class EnvironmentSnapshot(BaseModel):
    """State, tools, artifacts, and events exposed by a simulation environment."""

    tools: List[Dict[str, Any]] = Field(default_factory=list)
    artifacts: List[SimulationArtifact] = Field(default_factory=list)
    events: List[SimulationEvent] = Field(default_factory=list)
    state: Dict[str, Any] = Field(default_factory=dict)
    metadata: Dict[str, Any] = Field(default_factory=dict)


class ToolExecutionResult(BaseModel):
    """Result from executing a tool call inside a local environment."""

    tool_call_id: Optional[str] = None
    tool_name: str
    content: str
    result: Any = None
    success: bool = True
    error: Optional[str] = None
    state_updates: Dict[str, Any] = Field(default_factory=dict)
    artifacts: List[SimulationArtifact] = Field(default_factory=list)
    events: List[SimulationEvent] = Field(default_factory=list)
    metadata: Dict[str, Any] = Field(default_factory=dict)

    def to_tool_message(self) -> Dict[str, Any]:
        return {
            "role": "tool",
            "tool_call_id": self.tool_call_id or self.tool_name,
            "content": self.content,
        }


class EnvironmentAdapter(ABC):
    """Base class for local simulation environments."""

    name = "environment"

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        return EnvironmentSnapshot()

    def observe(self, **context: Any) -> EnvironmentSnapshot:
        return EnvironmentSnapshot()

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        return None


class ToolMockEnvironment(EnvironmentAdapter):
    """
    Local API/tool mock environment.

    Handlers can return plain values, dictionaries, or ToolExecutionResult. A
    dictionary can include `content`, `result`, `success`, `error`,
    `state_updates`, `artifacts`, and `events`.

    Canon correspondence (assessment §8 Gap D): this is the executor behind
    ``mock.level="static_fixture"`` (``contract.TOOL_MOCK_LEVELS``) — canned,
    deterministic responses. The higher tiers (``recorded_replay`` / ``emulated``
    / ``live``) are typed in the contract but not executed here.
    """

    name = "tool_mock"

    def __init__(
        self,
        tools: Mapping[str, Callable[[Dict[str, Any], Dict[str, Any]], Any] | Any],
        *,
        tool_schemas: Optional[Iterable[Dict[str, Any]]] = None,
        initial_state: Optional[Dict[str, Any]] = None,
    ) -> None:
        self.handlers = dict(tools)
        self.tool_schemas = list(tool_schemas or [])
        self.initial_state = copy.deepcopy(initial_state or {})
        self.state = copy.deepcopy(self.initial_state)

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.state = copy.deepcopy(self.initial_state)
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            state=copy.deepcopy(self.state),
            events=[
                SimulationEvent(
                    type="environment",
                    name="tool_mock_ready",
                    payload={"tools": sorted(self.handlers.keys())},
                )
            ],
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if not name:
            return None
        if name not in self.handlers:
            return None

        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)
        handler = self.handlers[name]
        try:
            raw = handler(arguments, context) if callable(handler) else handler
            result = _coerce_tool_result(raw, tool_name=name, tool_call_id=call_id)
        except Exception as exc:
            result = ToolExecutionResult(
                tool_call_id=call_id,
                tool_name=name,
                content=f"Tool {name} failed: {exc}",
                success=False,
                error=str(exc),
            )

        _deep_merge(self.state, result.state_updates)
        result.events.append(
            SimulationEvent(
                type="tool_execution",
                name=name,
                payload={
                    "tool": name,
                    "tool_name": name,
                    "tool_call_id": call_id,
                    "arguments": arguments,
                    "success": result.success,
                    "result": result.result,
                    "error": result.error,
                    "state_updates": copy.deepcopy(result.state_updates),
                },
            )
        )
        return result

    def _tool_specs(self) -> List[Dict[str, Any]]:
        if self.tool_schemas:
            return copy.deepcopy(self.tool_schemas)
        specs = []
        for name in sorted(self.handlers.keys()):
            specs.append(
                {
                    "name": name,
                    "description": f"Mocked tool '{name}' available in the local simulation.",
                    "parameters": {"type": "object", "properties": {}},
                }
            )
        return specs


class ToolFaultInjectionEnvironment(EnvironmentAdapter):
    """
    Controlled local tool/API fault injection.

    Put this adapter before the real tool environment. It intercepts the first
    N matching calls and returns a failed tool result, then lets later retries
    fall through to the next environment adapter.
    """

    name = "tool_fault_injection"

    def __init__(
        self,
        failures: Mapping[str, int | Mapping[str, Any]],
        *,
        default_error: str = "Injected transient tool failure.",
    ) -> None:
        self.failure_specs = {
            name: self._normalize_spec(spec, default_error=default_error)
            for name, spec in failures.items()
        }
        self.remaining: Dict[str, int] = {}

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.remaining = {
            name: int(spec["count"])
            for name, spec in self.failure_specs.items()
        }
        return EnvironmentSnapshot(
            events=[
                SimulationEvent(
                    type="environment",
                    name="tool_fault_injection_ready",
                    payload={"tools": sorted(self.failure_specs.keys())},
                )
            ],
            metadata={"tool_fault_injection": copy.deepcopy(self.failure_specs)},
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if not name or name not in self.failure_specs:
            return None
        if self.remaining.get(name, 0) <= 0:
            return None

        self.remaining[name] -= 1
        spec = self.failure_specs[name]
        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)
        error = str(spec.get("error") or "Injected transient tool failure.")
        result = spec.get("result", {"error": error, "fault_injected": True})
        payload = {
            "tool": name,
            "tool_name": name,
            "tool_call_id": call_id,
            "arguments": arguments,
            "success": False,
            "result": result,
            "error": error,
            "state_updates": {},
            "fault_injected": True,
            "remaining_failures": self.remaining[name],
        }
        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=name,
            content=str(spec.get("content") or f"Tool {name} failed: {error}"),
            result=result,
            success=False,
            error=error,
            events=[
                SimulationEvent(type="tool_fault", name=name, payload=copy.deepcopy(payload)),
                SimulationEvent(type="tool_execution", name=name, payload=copy.deepcopy(payload)),
            ],
            metadata={
                "fault_injected": True,
                "remaining_failures": self.remaining[name],
            },
        )

    @staticmethod
    def _normalize_spec(
        spec: int | Mapping[str, Any],
        *,
        default_error: str,
    ) -> Dict[str, Any]:
        if isinstance(spec, int):
            return {"count": max(0, spec), "error": default_error}
        data = dict(spec)
        count = data.get("count", data.get("failures", 1))
        data["count"] = max(0, int(count))
        data.setdefault("error", default_error)
        return data


class WorkflowHookEnvironment(EnvironmentAdapter):
    """HTTP workflow/tool hooks with redacted auth and execution traces."""

    name = "workflow_hook"

    def __init__(
        self,
        hooks: Mapping[str, Mapping[str, Any]],
        *,
        headers: Optional[Mapping[str, str]] = None,
        auth: Optional[Mapping[str, Any]] = None,
        timeout: float = 30.0,
        initial_state: Optional[Dict[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        if not hooks:
            raise ValueError("workflow hooks must contain at least one hook")
        self.hooks = {
            str(name): self._normalize_hook(str(name), spec)
            for name, spec in hooks.items()
        }
        self.headers = {str(k): str(v) for k, v in dict(headers or {}).items()}
        self.auth = dict(auth or {})
        self.timeout = float(timeout)
        self.initial_state = copy.deepcopy(initial_state or {})
        self.metadata = dict(metadata or {})
        self.state: Dict[str, Any] = {}

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.state = {
            **copy.deepcopy(self.initial_state),
            "workflow_hooks": {
                "configured_hooks": sorted(self.hooks),
                "calls": [],
                "summary": {
                    "configured_hook_count": len(self.hooks),
                    "call_count": 0,
                    "success_count": 0,
                    "failed_count": 0,
                },
            },
        }
        return EnvironmentSnapshot(
            tools=[self._tool_spec(name, spec) for name, spec in self.hooks.items()],
            state=copy.deepcopy(self.state),
            events=[
                SimulationEvent(
                    type="environment",
                    name="workflow_hook_ready",
                    payload={
                        "tools": sorted(self.hooks),
                        "auth_enabled": bool(self.auth)
                        or any(bool(spec.get("auth")) for spec in self.hooks.values()),
                    },
                )
            ],
            metadata={"workflow_hook": copy.deepcopy(self.metadata)},
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if not name or name not in self.hooks:
            return None

        spec = self.hooks[name]
        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)
        started = time.time()
        status_code = 0
        response_payload: Any = {}
        error: Optional[str] = None
        try:
            status_code, response_payload = self._post_hook(
                name=name,
                spec=spec,
                arguments=arguments,
                context=context,
            )
        except Exception as exc:
            error = str(exc)
            response_payload = {
                "content": f"Workflow hook {name} failed: {exc}",
                "success": False,
                "error": str(exc),
            }

        if status_code >= 400 and error is None:
            error = _workflow_error_text(response_payload) or (
                f"Workflow hook returned status {status_code}"
            )
        latency_ms = round((time.time() - started) * 1000, 4)
        trace = self._trace(
            name=name,
            spec=spec,
            status_code=status_code,
            latency_ms=latency_ms,
            success=error is None and 200 <= status_code < 300,
            error=error,
            argument_keys=sorted(arguments),
        )
        result = self._tool_result_from_payload(
            name=name,
            tool_call_id=call_id,
            payload=response_payload,
            trace=trace,
        )
        if error is not None:
            result.success = False
            result.error = error
            if not result.content:
                result.content = f"Workflow hook {name} failed: {error}"

        self._record_trace(trace)
        state_updates = dict(result.state_updates or {})
        _deep_merge(state_updates, copy.deepcopy(self.state))
        result.state_updates = state_updates
        result.events.append(
            SimulationEvent(
                type="workflow_hook",
                name=name,
                payload=copy.deepcopy(trace),
            )
        )
        result.artifacts.append(
            SimulationArtifact(
                type="trace",
                role="tool",
                data=copy.deepcopy(trace),
                metadata={"kind": "workflow_hook_trace", "tool": name},
            )
        )
        result.metadata = {
            **dict(result.metadata or {}),
            "workflow_hook_trace": copy.deepcopy(trace),
        }
        return result

    @staticmethod
    def _normalize_hook(name: str, spec: Mapping[str, Any]) -> Dict[str, Any]:
        hook = dict(spec)
        endpoint = hook.get("endpoint") or hook.get("url")
        if not endpoint:
            raise ValueError(f"workflow hook {name!r} requires endpoint or url")
        method = str(hook.get("method") or "POST").upper()
        if method not in {"POST", "PUT", "PATCH"}:
            raise ValueError("workflow hook method must be POST, PUT, or PATCH")
        hook["endpoint"] = str(endpoint)
        hook["method"] = method
        hook["headers"] = dict(hook.get("headers") or {})
        hook["auth"] = dict(hook.get("auth") or {})
        hook["timeout"] = float(hook.get("timeout", 0) or 0)
        return hook

    @staticmethod
    def _tool_spec(name: str, spec: Mapping[str, Any]) -> Dict[str, Any]:
        schema = dict(spec.get("schema") or {})
        schema.setdefault("name", name)
        schema.setdefault(
            "description",
            str(spec.get("description") or f"Call workflow hook {name}."),
        )
        schema.setdefault("parameters", {"type": "object", "properties": {}})
        return schema

    def _post_hook(
        self,
        *,
        name: str,
        spec: Mapping[str, Any],
        arguments: Mapping[str, Any],
        context: Mapping[str, Any],
    ) -> tuple[int, Any]:
        payload = {
            "tool": name,
            "arguments": dict(arguments),
            "thread_id": context.get("thread_id"),
            "turn_index": context.get("turn_index"),
        }
        headers = self._headers(spec)
        request = urllib.request.Request(
            str(spec["endpoint"]),
            data=json.dumps(payload, default=str).encode("utf-8"),
            headers=headers,
            method=str(spec.get("method") or "POST"),
        )
        timeout = float(spec.get("timeout") or self.timeout)
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                status = int(getattr(response, "status", 200))
                text = response.read().decode(
                    response.headers.get_content_charset() or "utf-8"
                )
        except urllib.error.HTTPError as exc:
            status = int(exc.code)
            text = exc.read().decode("utf-8")
        if not text:
            return status, {}
        try:
            return status, json.loads(text)
        except json.JSONDecodeError:
            return status, {"content": text, "result": text}

    def _headers(self, spec: Mapping[str, Any]) -> Dict[str, str]:
        headers = {
            "Content-Type": "application/json",
            **self.headers,
            **{str(k): str(v) for k, v in dict(spec.get("headers") or {}).items()},
        }
        auth_headers = _workflow_auth_headers(
            dict(self.auth or {}),
            dict(spec.get("auth") or {}),
        )
        for key, value in auth_headers.items():
            headers.setdefault(key, value)
        return headers

    def _trace(
        self,
        *,
        name: str,
        spec: Mapping[str, Any],
        status_code: int,
        latency_ms: float,
        success: bool,
        error: Optional[str],
        argument_keys: Sequence[str],
    ) -> Dict[str, Any]:
        headers = self._headers(spec)
        endpoint = str(spec["endpoint"])
        parsed = urlparse(endpoint)
        auth = dict(self.auth or {})
        auth.update(dict(spec.get("auth") or {}))
        return {
            "kind": "workflow_hook_trace",
            "tool": name,
            "endpoint": _workflow_redacted_url(endpoint),
            "endpoint_host": parsed.netloc,
            "method": str(spec.get("method") or "POST"),
            "status_code": int(status_code),
            "latency_ms": latency_ms,
            "success": bool(success),
            "error": error,
            "argument_keys": list(argument_keys),
            "request_header_names": sorted(headers),
            "auth": _workflow_auth_metadata(auth, headers),
            **copy.deepcopy(self.metadata),
            **copy.deepcopy(dict(spec.get("metadata") or {})),
        }

    @staticmethod
    def _tool_result_from_payload(
        *,
        name: str,
        tool_call_id: Optional[str],
        payload: Any,
        trace: Mapping[str, Any],
    ) -> ToolExecutionResult:
        if isinstance(payload, Mapping):
            data = copy.deepcopy(dict(payload))
        else:
            data = {"content": str(payload), "result": payload}
        data.setdefault("content", str(data.get("result") or "workflow hook executed"))
        data.setdefault("success", bool(trace.get("success")))
        metadata = dict(data.get("metadata") or {})
        metadata["workflow_hook_trace"] = copy.deepcopy(dict(trace))
        data["metadata"] = metadata
        return _coerce_tool_result(data, tool_name=name, tool_call_id=tool_call_id)

    def _record_trace(self, trace: Mapping[str, Any]) -> None:
        workflow_state = self.state.setdefault("workflow_hooks", {})
        calls = workflow_state.setdefault("calls", [])
        calls.append(copy.deepcopy(dict(trace)))
        workflow_state["last_call"] = copy.deepcopy(dict(trace))
        summary = workflow_state.setdefault("summary", {})
        summary["configured_hook_count"] = len(self.hooks)
        summary["call_count"] = len(calls)
        summary["success_count"] = len([call for call in calls if call.get("success")])
        summary["failed_count"] = len([call for call in calls if not call.get("success")])


class RetrievalHookEnvironment(EnvironmentAdapter):
    """HTTP retrieval/RAG hooks normalized into retrieval-memory trace evidence."""

    name = "retrieval_hook"

    def __init__(
        self,
        endpoint: str,
        *,
        tool_name: str = "retrieve_documents",
        headers: Optional[Mapping[str, str]] = None,
        auth: Optional[Mapping[str, Any]] = None,
        timeout: float = 30.0,
        top_k: int = 3,
        require_current: bool = True,
        initial_state: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        if not endpoint:
            raise ValueError("retrieval hook requires endpoint")
        self.endpoint = str(endpoint)
        self.tool_name = str(tool_name or "retrieve_documents")
        self.headers = {str(k): str(v) for k, v in dict(headers or {}).items()}
        self.auth = dict(auth or {})
        self.timeout = float(timeout)
        self.top_k = int(top_k)
        self.require_current = bool(require_current)
        self.initial_state = copy.deepcopy(dict(initial_state or {}))
        self.metadata = copy.deepcopy(dict(metadata or {}))
        self.documents: List[Dict[str, Any]] = []
        self.queries: List[Dict[str, Any]] = []
        self.document_reads: List[Dict[str, Any]] = []
        self.citations: List[Dict[str, Any]] = []
        self.hook_calls: List[Dict[str, Any]] = []
        self.state: Dict[str, Any] = {}

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.documents = []
        self.queries = []
        self.document_reads = []
        self.citations = []
        self.hook_calls = []
        self.state = {
            **copy.deepcopy(self.initial_state),
            "retrieval_memory": self._state_payload(),
            "retrieval_hooks": self._hook_state_payload(),
        }
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            artifacts=[self._trace_artifact()],
            state=copy.deepcopy(self.state),
            events=[
                SimulationEvent(
                    type="retrieval_memory",
                    name="retrieval_hook_ready",
                    payload={
                        "tool": self.tool_name,
                        "endpoint": _workflow_redacted_url(self.endpoint),
                        "auth_enabled": bool(self.auth),
                        "require_current": self.require_current,
                    },
                )
            ],
            metadata={
                "retrieval_hook": {
                    "tool": self.tool_name,
                    "endpoint": _workflow_redacted_url(self.endpoint),
                    "require_current": self.require_current,
                    **copy.deepcopy(self.metadata),
                }
            },
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if name not in {
            self.tool_name,
            "retrieve_documents",
            "search_knowledge_base",
            "query_knowledge",
            "read_document",
            "cite_sources",
            "record_attribution",
            "retrieval_memory_status",
        }:
            return None

        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)
        if name in {
            self.tool_name,
            "retrieve_documents",
            "search_knowledge_base",
            "query_knowledge",
        }:
            return self._handle_retrieve(
                tool_name=str(name),
                tool_call_id=call_id,
                arguments=arguments,
                context=context,
            )
        if name == "read_document":
            doc_id = str(arguments.get("id") or arguments.get("doc_id") or "")
            document = _find_retrieval_document(self.documents, doc_id)
            success = document is not None
            result = {"id": doc_id, "document": copy.deepcopy(document)}
            if success:
                self.document_reads.append(
                    {"id": doc_id, "document": copy.deepcopy(dict(document))}
                )
            return self._tool_result(
                tool_call_id=call_id,
                tool_name="read_document",
                content="Document read." if success else f"Document not found: {doc_id}",
                result=result,
                event_name="document_read" if success else "document_missing",
                success=success,
                error=None if success else "document_not_found",
            )
        if name in {"cite_sources", "record_attribution"}:
            citation = self._citation_from_arguments(arguments)
            self.citations.append(citation)
            return self._tool_result(
                tool_call_id=call_id,
                tool_name=str(name),
                content=json.dumps(citation, default=str),
                result=citation,
                event_name="attribution",
            )
        return self._tool_result(
            tool_call_id=call_id,
            tool_name="retrieval_memory_status",
            content="Retrieval hook status recorded.",
            result=self._trace_payload(),
            event_name="retrieval_memory_status",
        )

    def _handle_retrieve(
        self,
        *,
        tool_name: str,
        tool_call_id: Optional[str],
        arguments: Mapping[str, Any],
        context: Mapping[str, Any],
    ) -> ToolExecutionResult:
        query = str(arguments.get("query") or arguments.get("input") or arguments.get("question") or "")
        top_k = int(arguments.get("top_k", arguments.get("k", self.top_k)))
        started = time.time()
        status_code = 0
        response_payload: Any = {}
        error: Optional[str] = None
        try:
            status_code, response_payload = self._post_retrieval(
                query=query,
                top_k=top_k,
                arguments=arguments,
                context=context,
            )
        except Exception as exc:
            error = str(exc)
            response_payload = {
                "content": f"Retrieval hook failed: {exc}",
                "success": False,
                "error": str(exc),
            }
        if status_code >= 400 and error is None:
            error = _workflow_error_text(response_payload) or (
                f"Retrieval hook returned status {status_code}"
            )

        normalized = self._normalize_retrieval_response(
            response_payload,
            query=query,
            top_k=top_k,
        )
        latency_ms = round((time.time() - started) * 1000, 4)
        success = error is None and 200 <= status_code < 300
        trace = self._hook_trace(
            status_code=status_code,
            latency_ms=latency_ms,
            success=success,
            error=error,
            argument_keys=sorted(arguments),
            retrieved_doc_ids=[doc["id"] for doc in normalized["documents"]],
            top_k=top_k,
            query=query,
        )
        self._record_hook_trace(trace)
        if success:
            self._record_retrieval(query=query, top_k=top_k, normalized=normalized)

        result_payload = {
            "query": query,
            "documents": copy.deepcopy(normalized["documents"]),
            "citations": copy.deepcopy(normalized["citations"]),
            "retrieval_hook_trace": copy.deepcopy(trace),
        }
        content = str(
            _as_mapping(response_payload).get("content")
            or _as_mapping(response_payload).get("answer")
            or json.dumps(result_payload, default=str)
        )
        return self._tool_result(
            tool_call_id=tool_call_id,
            tool_name=tool_name,
            content=content,
            result=result_payload,
            event_name="query" if success else "retrieval_hook_failed",
            success=success,
            error=error,
            hook_trace=trace,
        )

    def _post_retrieval(
        self,
        *,
        query: str,
        top_k: int,
        arguments: Mapping[str, Any],
        context: Mapping[str, Any],
    ) -> tuple[int, Any]:
        payload = {
            "query": query,
            "top_k": top_k,
            "filters": copy.deepcopy(arguments.get("filters") or {}),
            "arguments": copy.deepcopy(dict(arguments)),
            "thread_id": context.get("thread_id"),
            "turn_index": context.get("turn_index"),
        }
        request = urllib.request.Request(
            self.endpoint,
            data=json.dumps(payload, default=str).encode("utf-8"),
            headers=self._headers(),
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                status = int(getattr(response, "status", 200))
                text = response.read().decode(
                    response.headers.get_content_charset() or "utf-8"
                )
        except urllib.error.HTTPError as exc:
            status = int(exc.code)
            text = exc.read().decode("utf-8")
        if not text:
            return status, {}
        try:
            return status, json.loads(text)
        except json.JSONDecodeError:
            return status, {"content": text, "result": text}

    def _headers(self) -> Dict[str, str]:
        headers = {"Content-Type": "application/json", **self.headers}
        for key, value in _workflow_auth_headers(self.auth).items():
            headers.setdefault(key, value)
        return headers

    def _normalize_retrieval_response(
        self,
        payload: Any,
        *,
        query: str,
        top_k: int,
    ) -> Dict[str, Any]:
        data = _as_mapping(payload)
        raw_docs = (
            data.get("documents")
            or data.get("docs")
            or data.get("results")
            or data.get("sources")
            or data.get("contexts")
            or []
        )
        if data.get("document"):
            raw_docs = [data["document"], *_as_iterable(raw_docs)]
        documents = _normalize_retrieval_documents(
            raw_docs if isinstance(raw_docs, Mapping) else _as_iterable(raw_docs)
        )
        documents = documents[:top_k]
        for index, document in enumerate(documents):
            document.setdefault("retrieval_rank", index + 1)
            document.setdefault(
                "retrieval_score",
                document.get("score", document.get("similarity", 0)),
            )
            if self.require_current and document.get("current") is None:
                document["current"] = True

        citations = [
            self._normalize_citation(item, documents=documents)
            for item in _as_iterable(data.get("citations") or data.get("attributions"))
        ]
        citations = [item for item in citations if item.get("doc_ids") or item.get("claim")]
        if not citations and documents and data.get("answer"):
            citations.append(
                {
                    "doc_ids": [str(doc["id"]) for doc in documents],
                    "memory_keys": [],
                    "claim": str(data.get("answer")),
                    "reason": data.get("reason"),
                    "freshness_checked": all(doc.get("current") is not False for doc in documents),
                }
            )
        return {"query": query, "documents": documents, "citations": citations}

    def _normalize_citation(
        self,
        raw: Any,
        *,
        documents: Sequence[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        item = _as_mapping(raw)
        doc_ids = [
            str(value)
            for value in _as_iterable(
                item.get("doc_ids")
                or item.get("document_ids")
                or item.get("documents")
                or item.get("sources")
            )
            if value not in (None, "")
        ]
        if item.get("doc_id") and str(item["doc_id"]) not in doc_ids:
            doc_ids.append(str(item["doc_id"]))
        if not doc_ids and documents:
            doc_ids = [str(doc["id"]) for doc in documents]
        return {
            "doc_ids": doc_ids,
            "memory_keys": [
                str(value)
                for value in _as_iterable(item.get("memory_keys"))
                if value not in (None, "")
            ],
            "claim": item.get("claim") or item.get("answer") or item.get("text"),
            "reason": item.get("reason"),
            "freshness_checked": bool(
                item.get(
                    "freshness_checked",
                    item.get(
                        "current",
                        all(doc.get("current") is not False for doc in documents),
                    ),
                )
            ),
        }

    def _citation_from_arguments(self, arguments: Mapping[str, Any]) -> Dict[str, Any]:
        return {
            "doc_ids": [
                str(item)
                for item in _as_iterable(
                    arguments.get("doc_ids", arguments.get("documents", []))
                )
                if item not in (None, "")
            ],
            "memory_keys": [
                str(item)
                for item in _as_iterable(arguments.get("memory_keys", []))
                if item not in (None, "")
            ],
            "claim": arguments.get("claim") or arguments.get("answer") or arguments.get("text"),
            "reason": arguments.get("reason"),
            "freshness_checked": bool(arguments.get("freshness_checked", arguments.get("current", False))),
        }

    def _record_retrieval(
        self,
        *,
        query: str,
        top_k: int,
        normalized: Mapping[str, Any],
    ) -> None:
        documents = [copy.deepcopy(dict(doc)) for doc in _as_iterable(normalized.get("documents"))]
        by_id = {str(doc.get("id")): doc for doc in self.documents}
        for document in documents:
            by_id[str(document.get("id"))] = document
        self.documents = list(by_id.values())
        self.queries.append(
            {
                "query": query,
                "top_k": top_k,
                "include_stale": not self.require_current,
                "documents": [str(doc.get("id")) for doc in documents],
                "ranked_documents": [
                    {
                        "id": str(doc.get("id")),
                        "rank": doc.get("retrieval_rank", index + 1),
                        "score": doc.get("retrieval_score", doc.get("score", 0)),
                        "current": doc.get("current"),
                        "source": doc.get("source"),
                    }
                    for index, doc in enumerate(documents)
                ],
            }
        )
        for citation in _as_iterable(normalized.get("citations")):
            self.citations.append(copy.deepcopy(dict(citation)))

    def _record_hook_trace(self, trace: Mapping[str, Any]) -> None:
        self.hook_calls.append(copy.deepcopy(dict(trace)))
        self.state["retrieval_hooks"] = self._hook_state_payload()
        self.state["retrieval_memory"] = self._state_payload()

    def _hook_trace(
        self,
        *,
        status_code: int,
        latency_ms: float,
        success: bool,
        error: Optional[str],
        argument_keys: Sequence[str],
        retrieved_doc_ids: Sequence[str],
        top_k: int,
        query: str,
    ) -> Dict[str, Any]:
        headers = self._headers()
        parsed = urlparse(self.endpoint)
        return {
            "kind": "retrieval_hook_trace",
            "tool": self.tool_name,
            "endpoint": _workflow_redacted_url(self.endpoint),
            "endpoint_host": parsed.netloc,
            "method": "POST",
            "status_code": int(status_code),
            "latency_ms": latency_ms,
            "success": bool(success),
            "error": error,
            "argument_keys": list(argument_keys),
            "request_header_names": sorted(headers),
            "auth": _workflow_auth_metadata(self.auth, headers),
            "query_present": bool(query),
            "query_length": len(query),
            "top_k": int(top_k),
            "retrieved_doc_ids": [str(doc_id) for doc_id in retrieved_doc_ids],
            **copy.deepcopy(self.metadata),
        }

    def _tool_specs(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": self.tool_name,
                "description": "Call the HTTP retriever and return ranked source documents with citations.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "query": {"type": "string"},
                        "top_k": {"type": "integer"},
                        "filters": {"type": "object"},
                    },
                    "required": ["query"],
                },
            },
            {
                "name": "read_document",
                "description": "Read one document returned by the retrieval hook.",
                "parameters": {"type": "object", "properties": {"id": {"type": "string"}}},
            },
            {
                "name": "cite_sources",
                "description": "Record source attribution for retrieved documents.",
                "parameters": {"type": "object", "properties": {"doc_ids": {"type": "array"}}},
            },
            {
                "name": "retrieval_memory_status",
                "description": "Inspect retrieval hook, citation, and trace state.",
                "parameters": {"type": "object", "properties": {}},
            },
        ]

    def _tool_result(
        self,
        *,
        tool_call_id: Optional[str],
        tool_name: str,
        content: str,
        result: Any,
        event_name: str,
        success: bool = True,
        error: Optional[str] = None,
        hook_trace: Optional[Mapping[str, Any]] = None,
    ) -> ToolExecutionResult:
        self.state["retrieval_memory"] = self._state_payload()
        self.state["retrieval_hooks"] = self._hook_state_payload()
        state_updates = {
            "retrieval_memory": self._state_payload(),
            "retrieval_hooks": self._hook_state_payload(),
        }
        artifacts = [self._trace_artifact()]
        if hook_trace is not None:
            artifacts.append(
                SimulationArtifact(
                    type="trace",
                    role="tool",
                    data=copy.deepcopy(dict(hook_trace)),
                    metadata={"kind": "retrieval_hook_trace", "tool": self.tool_name},
                )
            )
        events = [
            SimulationEvent(
                type="retrieval_memory",
                name=event_name,
                payload=result if isinstance(result, dict) else {"result": result},
            ),
            SimulationEvent(
                type="tool_execution",
                name=tool_name,
                payload={
                    "tool_name": tool_name,
                    "result": copy.deepcopy(result),
                    "success": success,
                    "error": error,
                    "state_updates": copy.deepcopy(state_updates),
                },
            ),
        ]
        if hook_trace is not None:
            events.append(
                SimulationEvent(
                    type="retrieval_hook",
                    name=self.tool_name,
                    payload=copy.deepcopy(dict(hook_trace)),
                )
            )
        return ToolExecutionResult(
            tool_call_id=tool_call_id,
            tool_name=tool_name,
            content=content,
            result=result,
            success=success,
            error=error,
            state_updates=state_updates,
            artifacts=artifacts,
            events=events,
            metadata={
                "retrieval_hook_trace": copy.deepcopy(dict(hook_trace))
                if hook_trace is not None
                else {}
            },
        )

    def _trace_artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            role="environment",
            data=self._trace_payload(),
            metadata={"kind": "retrieval_memory_trace"},
        )

    def _trace_payload(self) -> Dict[str, Any]:
        return {
            "kind": "retrieval_memory_trace",
            "documents": copy.deepcopy(self.documents),
            "queries": copy.deepcopy(self.queries),
            "document_reads": copy.deepcopy(self.document_reads),
            "memory_reads": [],
            "memory_writes": [],
            "citations": copy.deepcopy(self.citations),
            "memory": {},
            "require_current": self.require_current,
            "metadata": {
                **copy.deepcopy(self.metadata),
                "retrieval_hook": self._hook_state_payload(),
            },
        }

    def _state_payload(self) -> Dict[str, Any]:
        return self._trace_payload()

    def _hook_state_payload(self) -> Dict[str, Any]:
        successful = [call for call in self.hook_calls if call.get("success")]
        return {
            "configured_hooks": [self.tool_name],
            "calls": copy.deepcopy(self.hook_calls),
            "last_call": copy.deepcopy(self.hook_calls[-1]) if self.hook_calls else None,
            "summary": {
                "configured_hook_count": 1,
                "call_count": len(self.hook_calls),
                "success_count": len(successful),
                "failed_count": len(self.hook_calls) - len(successful),
                "retrieved_document_count": len(self.documents),
                "citation_count": len(self.citations),
            },
        }


class WorldContractEnvironment(EnvironmentAdapter):
    """
    Local state-machine world contract for arbitrary agent tasks.

    A world contract defines the actors, resources, allowed transitions,
    invariants, success conditions, policy gates, and adversarial surfaces that
    make a task valid. Use it when the important question is not which framework
    ran, but whether the agent moved the simulated world through the right
    states without violating domain rules.
    """

    name = "world_contract"

    def __init__(
        self,
        *,
        name: str = "world",
        actors: Optional[Iterable[str | Mapping[str, Any]]] = None,
        resources: Optional[Iterable[str | Mapping[str, Any]]] = None,
        transitions: Optional[Iterable[str | Mapping[str, Any]]] = None,
        invariants: Optional[Iterable[str | Mapping[str, Any]]] = None,
        success_conditions: Optional[Iterable[str | Mapping[str, Any]]] = None,
        policy_gates: Optional[Iterable[str | Mapping[str, Any]]] = None,
        adversarial_surfaces: Optional[Iterable[str | Mapping[str, Any]]] = None,
        initial_state: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        self.contract = normalize_world_contract(
            name=name,
            actors=actors or [],
            resources=resources or [],
            transitions=transitions or [],
            invariants=invariants or [],
            success_conditions=success_conditions or [],
            policy_gates=policy_gates or [],
            adversarial_surfaces=adversarial_surfaces or [],
            initial_state=initial_state or {},
            metadata=metadata or {},
        )
        self.initial_state = copy.deepcopy(self.contract["initial_state"])
        self.state: Dict[str, Any] = {}
        self.transition_log: List[Dict[str, Any]] = []
        self.invariant_results: List[Dict[str, Any]] = []
        self.success_results: List[Dict[str, Any]] = []

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.state = copy.deepcopy(self.initial_state)
        self.transition_log = []
        self.invariant_results = _world_contract_check_conditions(
            self.contract.get("invariants", []),
            self.state,
            condition_type="invariant",
        )
        self.success_results = _world_contract_check_conditions(
            self.contract.get("success_conditions", []),
            self.state,
            condition_type="success_condition",
        )
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            artifacts=[self._contract_artifact()],
            events=[
                SimulationEvent(
                    type="world_contract",
                    name="world_contract_ready",
                    payload={
                        "name": self.contract["name"],
                        "signals": sorted(self._observed_signals()),
                        "summary": self._summary(),
                    },
                )
            ],
            state={"world_contract": self._state_payload()},
            metadata={"world_contract": self._state_payload()},
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if name not in {
            "world_contract_status",
            "list_world_transitions",
            "inspect_world_invariant",
            "apply_world_transition",
        }:
            return None
        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)

        if name == "world_contract_status":
            result = self._state_payload()
            event_name = "world_contract_status"
            content = f"World contract {self.contract['name']} status recorded."
            success = True
            error = None
        elif name == "list_world_transitions":
            transitions = self._filtered_transitions(arguments)
            result = {
                "name": self.contract["name"],
                "transitions": copy.deepcopy(transitions),
            }
            event_name = "world_transitions_listed"
            content = f"Listed {len(transitions)} world transition(s)."
            success = True
            error = None
        elif name == "inspect_world_invariant":
            invariant_id = str(arguments.get("id") or arguments.get("name") or "")
            invariant = _world_contract_find_condition(
                self.contract.get("invariants", []),
                invariant_id,
            )
            result = {
                "name": self.contract["name"],
                "invariant": copy.deepcopy(invariant),
                "result": copy.deepcopy(_world_contract_find_condition_result(self.invariant_results, invariant_id)),
                "query": invariant_id,
            }
            event_name = "world_invariant_inspected" if invariant else "world_invariant_missing"
            success = invariant is not None
            error = None if success else "invariant_not_found"
            content = f"Inspected invariant {invariant_id}." if success else f"World invariant not found: {invariant_id}"
        else:
            transition_result = self._apply_transition(arguments)
            result = transition_result
            event_name = "world_transition_applied"
            success = transition_result["status"] == "success"
            error = None if success else transition_result["status"]
            content = (
                f"Applied world transition {transition_result['id']}."
                if success
                else f"World transition {transition_result['id']} failed: {transition_result['status']}."
            )

        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=name,
            content=content,
            result=result,
            success=success,
            error=error,
            state_updates={"world_contract": self._state_payload()},
            artifacts=[self._contract_artifact()],
            events=[
                SimulationEvent(
                    type="world_contract",
                    name=event_name,
                    payload=copy.deepcopy(result),
                )
            ],
        )

    def _tool_specs(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": "world_contract_status",
                "description": "Return the world contract, current state, transition log, invariant checks, success checks, and summary.",
                "parameters": {"type": "object", "properties": {}},
            },
            {
                "name": "list_world_transitions",
                "description": "List available world transitions, optionally filtered by actor, resource, action, signal, or required flag.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "actor": {"type": "string"},
                        "resource": {"type": "string"},
                        "action": {"type": "string"},
                        "signal": {"type": "string"},
                        "required": {"type": "boolean"},
                    },
                },
            },
            {
                "name": "inspect_world_invariant",
                "description": "Inspect one world invariant by id or name.",
                "parameters": {"type": "object", "properties": {"id": {"type": "string"}}},
            },
            {
                "name": "apply_world_transition",
                "description": "Apply an allowed world transition by id/name/action and update contract state.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "id": {"type": "string"},
                        "transition": {"type": "string"},
                        "action": {"type": "string"},
                    },
                },
            },
        ]

    def _apply_transition(self, arguments: Mapping[str, Any]) -> Dict[str, Any]:
        transition_id = str(
            arguments.get("id")
            or arguments.get("transition")
            or arguments.get("action")
            or ""
        )
        transition = _world_contract_find_transition(self.contract.get("transitions", []), transition_id)
        if transition is None:
            record = {
                "id": transition_id or "unknown",
                "status": "missing_transition",
                "arguments": copy.deepcopy(dict(arguments)),
            }
            self.transition_log.append(record)
            return record

        state_before = copy.deepcopy(self.state)
        violations: List[Dict[str, Any]] = []
        status = "success"
        if transition.get("forbidden") is True:
            status = "forbidden_transition"
            violations.append({"type": "forbidden_transition", "transition": transition["id"]})
        elif not _world_contract_condition_matches(self.state, _as_mapping(transition.get("preconditions"))):
            status = "precondition_failed"
            violations.append(
                {
                    "type": "precondition_failed",
                    "transition": transition["id"],
                    "expected": copy.deepcopy(_as_mapping(transition.get("preconditions"))),
                }
            )

        if status == "success":
            _deep_merge(self.state, _world_contract_effects(transition))
            if not _world_contract_condition_matches(self.state, _as_mapping(transition.get("postconditions"))):
                status = "postcondition_failed"
                violations.append(
                    {
                        "type": "postcondition_failed",
                        "transition": transition["id"],
                        "expected": copy.deepcopy(_as_mapping(transition.get("postconditions"))),
                    }
                )

        self.invariant_results = _world_contract_check_conditions(
            self.contract.get("invariants", []),
            self.state,
            condition_type="invariant",
        )
        self.success_results = _world_contract_check_conditions(
            self.contract.get("success_conditions", []),
            self.state,
            condition_type="success_condition",
        )
        for invariant in self.invariant_results:
            if invariant.get("pass") is False:
                violations.append({"type": "invariant_violation", **copy.deepcopy(invariant)})
        record = {
            "id": transition["id"],
            "name": transition.get("name"),
            "actor": transition.get("actor"),
            "action": transition.get("action"),
            "resource": transition.get("resource"),
            "required": bool(transition.get("required")),
            "status": status,
            "signals": copy.deepcopy(transition.get("signals", [])),
            "arguments": copy.deepcopy(dict(arguments)),
            "state_before": state_before,
            "state_after": copy.deepcopy(self.state),
            "violations": violations,
        }
        self.transition_log.append(record)
        return record

    def _filtered_transitions(self, arguments: Mapping[str, Any]) -> List[Dict[str, Any]]:
        transitions = [copy.deepcopy(transition) for transition in self.contract.get("transitions", [])]
        for field in ("actor", "resource", "action"):
            value = str(arguments.get(field) or "").strip().lower()
            if value:
                transitions = [
                    transition for transition in transitions if value == str(transition.get(field) or "").lower()
                ]
        signal = str(arguments.get("signal") or "").strip().lower()
        if signal:
            transitions = [
                transition
                for transition in transitions
                if signal in {str(item).lower() for item in transition.get("signals", [])}
            ]
        if arguments.get("required") is not None:
            required = bool(arguments.get("required"))
            transitions = [transition for transition in transitions if bool(transition.get("required")) is required]
        return transitions

    def _contract_artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            role="environment",
            data=self._state_payload(),
            metadata={"kind": "world_contract", "name": self.contract["name"]},
        )

    def _state_payload(self) -> Dict[str, Any]:
        return {
            "kind": "world_contract",
            "name": self.contract["name"],
            "actors": copy.deepcopy(self.contract.get("actors", [])),
            "resources": copy.deepcopy(self.contract.get("resources", [])),
            "transitions": copy.deepcopy(self.contract.get("transitions", [])),
            "invariants": copy.deepcopy(self.contract.get("invariants", [])),
            "success_conditions": copy.deepcopy(self.contract.get("success_conditions", [])),
            "policy_gates": copy.deepcopy(self.contract.get("policy_gates", [])),
            "adversarial_surfaces": copy.deepcopy(self.contract.get("adversarial_surfaces", [])),
            "state": copy.deepcopy(self.state),
            "transition_log": copy.deepcopy(self.transition_log),
            "invariant_results": copy.deepcopy(self.invariant_results),
            "success_results": copy.deepcopy(self.success_results),
            "signals": sorted(self._observed_signals()),
            "summary": self._summary(),
            "metadata": copy.deepcopy(self.contract.get("metadata", {})),
        }

    def _observed_signals(self) -> set[str]:
        signals = {"contract", "state"}
        if self.contract.get("actors"):
            signals.add("actor")
        if self.contract.get("resources"):
            signals.add("resource")
        if self.contract.get("transitions"):
            signals.add("transition")
        if self.contract.get("invariants"):
            signals.add("invariant")
        if self.contract.get("success_conditions"):
            signals.add("success_condition")
        if self.contract.get("policy_gates"):
            signals.add("policy")
        if self.contract.get("adversarial_surfaces"):
            signals.add("adversarial_surface")
        for transition in self.contract.get("transitions", []):
            signals.update(transition.get("signals", []))
        for record in self.transition_log:
            signals.add("transition_log")
            if record.get("status") == "success":
                signals.add("completed_transition")
            if record.get("status") == "forbidden_transition":
                signals.add("forbidden_transition")
            if record.get("violations"):
                signals.add("violation")
        if any(result.get("pass") is False for result in self.invariant_results):
            signals.add("invariant_violation")
        if all(result.get("pass") is True for result in self.success_results) and self.success_results:
            signals.add("success")
        return {_normalize_world_contract_key(signal) for signal in signals if signal}

    def _summary(self) -> Dict[str, Any]:
        completed = [record for record in self.transition_log if record.get("status") == "success"]
        forbidden = [record for record in self.transition_log if record.get("status") == "forbidden_transition"]
        violations = [violation for record in self.transition_log for violation in record.get("violations", [])]
        invariant_failures = [result for result in self.invariant_results if result.get("pass") is False]
        success_passed = [result for result in self.success_results if result.get("pass") is True]
        return {
            "actor_count": len(self.contract.get("actors", [])),
            "resource_count": len(self.contract.get("resources", [])),
            "transition_count": len(self.contract.get("transitions", [])),
            "completed_transition_count": len(completed),
            "required_transition_count": sum(1 for transition in self.contract.get("transitions", []) if transition.get("required")),
            "completed_required_transition_count": len(
                {
                    record.get("id")
                    for record in completed
                    if _world_contract_find_transition(self.contract.get("transitions", []), str(record.get("id"))) and _world_contract_find_transition(self.contract.get("transitions", []), str(record.get("id"))).get("required")
                }
            ),
            "forbidden_transition_count": len(forbidden),
            "violation_count": len(violations),
            "invariant_count": len(self.invariant_results),
            "invariant_violation_count": len(invariant_failures),
            "success_condition_count": len(self.success_results),
            "success_condition_pass_count": len(success_passed),
            "terminal_status": "success" if self.success_results and len(success_passed) == len(self.success_results) and not invariant_failures else "incomplete",
        }


class StatefulToolWorldEnvironment(EnvironmentAdapter):
    """
    Passive stateful tool-world benchmark evidence.

    The adapter observes the executed ``world_contract`` state after each turn
    and emits a normalized benchmark payload for long-horizon, tool-using
    agents: required state deltas, unsafe-action blocking, temporal takeover
    localization, cross-session persistence controls, and utility under attack.
    """

    name = "stateful_tool_world"

    def __init__(self, payload: Mapping[str, Any]) -> None:
        self.spec = normalize_stateful_tool_world_manifest(payload)
        self.latest_payload: Dict[str, Any] = {}

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.latest_payload = self._state_payload({})
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            artifacts=[self._artifact()],
            events=[
                SimulationEvent(
                    type="stateful_tool_world",
                    name="stateful_tool_world_ready",
                    payload={
                        "name": self.spec["name"],
                        "benchmark": self.spec.get("benchmark"),
                        "required_state_delta_count": len(
                            self.spec.get("required_state_deltas", [])
                        ),
                        "required_takeover_point_count": len(
                            self.spec.get("temporal_takeover_points", [])
                        ),
                    },
                )
            ],
            state={"stateful_tool_world": copy.deepcopy(self.latest_payload)},
            metadata={"stateful_tool_world": copy.deepcopy(self.latest_payload)},
        )

    def observe(self, **context: Any) -> EnvironmentSnapshot:
        environment_state = _as_mapping(context.get("environment_state"))
        self.latest_payload = self._state_payload(environment_state)
        return EnvironmentSnapshot(
            artifacts=[self._artifact()],
            events=[
                SimulationEvent(
                    type="stateful_tool_world",
                    name="stateful_tool_world_observed",
                    payload=copy.deepcopy(self.latest_payload.get("summary", {})),
                )
            ],
            state={"stateful_tool_world": copy.deepcopy(self.latest_payload)},
            metadata={"stateful_tool_world": copy.deepcopy(self.latest_payload)},
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if name not in {
            "stateful_tool_world_status",
            "localize_temporal_takeover",
        }:
            return None
        environment_state = _as_mapping(context.get("environment_state"))
        payload = self._state_payload(environment_state)
        self.latest_payload = payload
        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)
        if name == "localize_temporal_takeover":
            takeover_id = str(arguments.get("id") or arguments.get("point_id") or "")
            points = payload.get("temporal_takeover_points", [])
            if takeover_id:
                points = [
                    point
                    for point in points
                    if str(point.get("id") or point.get("name")) == takeover_id
                ]
            result: Any = {"points": copy.deepcopy(points)}
            event_name = "temporal_takeover_localized"
        else:
            result = copy.deepcopy(payload)
            event_name = "stateful_tool_world_status"
        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=name,
            content=json.dumps(result, default=str),
            result=result,
            state_updates={"stateful_tool_world": copy.deepcopy(payload)},
            artifacts=[self._artifact()],
            events=[
                SimulationEvent(
                    type="stateful_tool_world",
                    name=event_name,
                    payload=copy.deepcopy(result),
                )
            ],
        )

    def _tool_specs(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": "stateful_tool_world_status",
                "description": "Return benchmark state-delta, utility-under-attack, blocking, persistence, and takeover-localization evidence.",
                "parameters": {"type": "object", "properties": {}},
            },
            {
                "name": "localize_temporal_takeover",
                "description": "Return temporal takeover localization evidence for a tool-return boundary.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "id": {"type": "string"},
                        "point_id": {"type": "string"},
                    },
                },
            },
        ]

    def _artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            role="environment",
            data=copy.deepcopy(self.latest_payload or self.spec),
            metadata={"kind": "stateful_tool_world", "name": self.spec["name"]},
        )

    def _state_payload(self, environment_state: Mapping[str, Any]) -> Dict[str, Any]:
        world = _as_mapping(environment_state.get("world_contract"))
        world_state = _as_mapping(world.get("state"))
        transition_log = [
            _as_mapping(item)
            for item in _as_iterable(world.get("transition_log"))
            if isinstance(item, Mapping)
        ]
        completed = {
            str(item.get("id") or item.get("name") or item.get("action"))
            for item in transition_log
            if item.get("status") == "success"
        }
        blocked_log = {
            str(item.get("id") or item.get("name") or item.get("action"))
            for item in transition_log
            if str(item.get("status") or "") in {
                "blocked",
                "forbidden_transition",
                "policy_blocked",
            }
        }
        deltas = [
            self._state_delta_result(delta, completed=completed, world_state=world_state)
            for delta in self.spec.get("required_state_deltas", [])
        ]
        blocked_actions = [
            self._blocked_action_result(action, completed=completed, blocked_log=blocked_log)
            for action in self.spec.get("required_blocked_actions", [])
        ]
        takeover_points = [
            self._takeover_point_result(point)
            for point in self.spec.get("temporal_takeover_points", [])
        ]
        persistent_channels = [
            self._persistent_channel_result(channel)
            for channel in self.spec.get("persistent_channels", [])
        ]
        utility = self._utility_result()
        expected_state = _as_mapping(self.spec.get("expected_state"))
        expected_state_match = (
            True
            if not expected_state
            else _world_contract_condition_matches(world_state, expected_state)
        )
        summary = {
            "required_state_delta_count": len(deltas),
            "completed_state_delta_count": sum(1 for item in deltas if item["completed"]),
            "required_blocked_action_count": len(blocked_actions),
            "blocked_action_count": sum(1 for item in blocked_actions if item["blocked"]),
            "required_takeover_point_count": len(takeover_points),
            "localized_takeover_point_count": sum(
                1 for item in takeover_points if item["localized"]
            ),
            "purified_takeover_point_count": sum(
                1 for item in takeover_points if item["purified"]
            ),
            "persistent_channel_count": len(persistent_channels),
            "contained_persistent_channel_count": sum(
                1 for item in persistent_channels if item["contained"]
            ),
            "expected_state_matched": bool(expected_state_match),
            "utility_under_attack_score": utility["score"],
            "min_utility_under_attack": utility["min_score"],
            "world_terminal_status": _as_mapping(world.get("summary")).get(
                "terminal_status"
            ),
        }
        summary["terminal_status"] = (
            "success"
            if (
                (not deltas or summary["completed_state_delta_count"] == len(deltas))
                and (
                    not blocked_actions
                    or summary["blocked_action_count"] == len(blocked_actions)
                )
                and (
                    not takeover_points
                    or summary["localized_takeover_point_count"]
                    == len(takeover_points)
                )
                and (
                    not takeover_points
                    or summary["purified_takeover_point_count"]
                    == len(takeover_points)
                )
                and (
                    not persistent_channels
                    or summary["contained_persistent_channel_count"]
                    == len(persistent_channels)
                )
                and expected_state_match
                and utility["passed"]
            )
            else "incomplete"
        )
        return {
            "kind": "stateful_tool_world",
            "name": self.spec["name"],
            "benchmark": self.spec.get("benchmark"),
            "task": copy.deepcopy(self.spec.get("task", {})),
            "tool_registry": copy.deepcopy(self.spec.get("tool_registry", [])),
            "attack_surfaces": copy.deepcopy(self.spec.get("attack_surfaces", [])),
            "state_deltas": deltas,
            "required_blocked_actions": blocked_actions,
            "temporal_takeover_points": takeover_points,
            "persistent_channels": persistent_channels,
            "utility_under_attack": utility,
            "expected_state": copy.deepcopy(expected_state),
            "world_contract": {
                "name": world.get("name"),
                "summary": copy.deepcopy(world.get("summary", {})),
                "state": copy.deepcopy(world_state),
                "transition_log": copy.deepcopy(transition_log),
            },
            "summary": summary,
            "metadata": copy.deepcopy(self.spec.get("metadata", {})),
        }

    def _state_delta_result(
        self,
        delta: Mapping[str, Any],
        *,
        completed: set[str],
        world_state: Mapping[str, Any],
    ) -> Dict[str, Any]:
        delta_id = str(delta.get("id") or delta.get("transition") or delta.get("action") or "")
        expected = _as_mapping(delta.get("expected_state") or delta.get("must"))
        state_match = (
            True
            if not expected
            else _world_contract_condition_matches(world_state, expected)
        )
        return {
            **copy.deepcopy(dict(delta)),
            "id": delta_id,
            "completed": delta_id in completed and state_match,
            "state_matched": bool(state_match),
        }

    def _blocked_action_result(
        self,
        action: Mapping[str, Any],
        *,
        completed: set[str],
        blocked_log: set[str],
    ) -> Dict[str, Any]:
        action_id = str(action.get("id") or action.get("action") or action.get("transition") or "")
        evidence = _as_mapping(action.get("evidence"))
        blocked = bool(
            action.get("blocked")
            or evidence.get("blocked")
            or action_id in blocked_log
            or (
                action_id in completed
                and str(action.get("status") or "").lower() in {"blocked", "contained"}
            )
        )
        return {
            **copy.deepcopy(dict(action)),
            "id": action_id,
            "blocked": blocked,
        }

    def _takeover_point_result(self, point: Mapping[str, Any]) -> Dict[str, Any]:
        counterfactual_runs = int(point.get("counterfactual_runs") or 0)
        localized = bool(point.get("localized")) and counterfactual_runs >= int(
            point.get("min_counterfactual_runs") or 1
        )
        purified = bool(
            point.get("purified")
            or point.get("context_purified")
            or point.get("safe_continuation")
        )
        return {
            **copy.deepcopy(dict(point)),
            "counterfactual_runs": counterfactual_runs,
            "localized": localized,
            "purified": purified,
        }

    def _persistent_channel_result(self, channel: Mapping[str, Any]) -> Dict[str, Any]:
        write_status = str(channel.get("write_status") or channel.get("write") or "")
        activation_status = str(
            channel.get("activation_status") or channel.get("activation") or ""
        )
        contained = bool(channel.get("contained")) or (
            write_status in {"quarantined", "sanitized", "blocked"}
            and activation_status in {"contained", "blocked", "not_activated"}
        )
        return {
            **copy.deepcopy(dict(channel)),
            "contained": contained,
        }

    def _utility_result(self) -> Dict[str, Any]:
        utility = _as_mapping(self.spec.get("utility_under_attack"))
        min_score = float(utility.get("min_score") or utility.get("min_utility") or 0.0)
        attack_score = float(
            utility.get("attack_score")
            or utility.get("utility_under_attack")
            or utility.get("score")
            or 0.0
        )
        baseline_score = float(utility.get("baseline_score") or 1.0)
        normalized = attack_score / baseline_score if baseline_score > 0 else attack_score
        score = min(1.0, max(0.0, normalized))
        return {
            **copy.deepcopy(dict(utility)),
            "baseline_score": baseline_score,
            "attack_score": attack_score,
            "min_score": min_score,
            "score": round(score, 4),
            "passed": attack_score >= min_score,
        }


def normalize_stateful_tool_world_manifest(source: Mapping[str, Any]) -> Dict[str, Any]:
    """Normalize stateful tool-world benchmark evidence into a portable payload."""

    data = _coerce_plain_dict(source.get("stateful_tool_world") or source)
    metadata = _coerce_plain_dict(data.get("metadata"))
    return {
        "kind": "stateful_tool_world",
        "name": str(data.get("name") or data.get("id") or "stateful-tool-world"),
        "benchmark": str(data.get("benchmark") or data.get("source") or "custom"),
        "task": _coerce_plain_dict(data.get("task")),
        "tool_registry": [
            _coerce_plain_dict(item)
            for item in _as_iterable(data.get("tool_registry") or data.get("tools"))
        ],
        "attack_surfaces": [
            _coerce_plain_dict(item) if isinstance(item, Mapping) else {"id": str(item)}
            for item in _as_iterable(data.get("attack_surfaces") or data.get("surfaces"))
        ],
        "expected_state": _coerce_plain_dict(data.get("expected_state")),
        "required_state_deltas": [
            _coerce_plain_dict(item)
            for item in _as_iterable(
                data.get("required_state_deltas")
                or data.get("state_deltas")
                or data.get("required_transitions")
            )
        ],
        "required_blocked_actions": [
            _coerce_plain_dict(item)
            for item in _as_iterable(
                data.get("required_blocked_actions")
                or data.get("blocked_actions")
                or data.get("unsafe_actions")
            )
        ],
        "temporal_takeover_points": [
            _coerce_plain_dict(item)
            for item in _as_iterable(
                data.get("temporal_takeover_points")
                or data.get("takeover_points")
                or data.get("causal_takeover_points")
            )
        ],
        "persistent_channels": [
            _coerce_plain_dict(item)
            for item in _as_iterable(
                data.get("persistent_channels")
                or data.get("stored_prompt_injection_channels")
                or data.get("persistence_channels")
            )
        ],
        "utility_under_attack": _coerce_plain_dict(data.get("utility_under_attack")),
        "world_hooks_contract": _coerce_plain_dict(
            data.get("world_hooks_contract")
            or metadata.get("world_hooks_contract")
        ),
        "metadata": metadata,
    }


class OpenEnvEnvironment(EnvironmentAdapter):
    """Local-first OpenEnv/Gymnasium-style environment replay adapter."""

    name = "openenv"

    def __init__(self, payload: Mapping[str, Any]) -> None:
        self.spec = normalize_openenv_manifest(payload)
        self.current_observation: Any = None
        self.current_state: Dict[str, Any] = {}
        self.step_index = 0
        self.reset_count = 0
        self.trajectory: List[Dict[str, Any]] = []
        self.action_log: List[Dict[str, Any]] = []
        self.error_log: List[Dict[str, Any]] = []
        self.terminated = False
        self.truncated = False
        self.done = False
        self.reward_total = 0.0
        self.last_info: Dict[str, Any] = {}
        self._initialize_runtime()

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self._initialize_runtime()
        payload = self._state_payload()
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            artifacts=[self._artifact()],
            events=[
                SimulationEvent(
                    type="openenv",
                    name="openenv_ready",
                    payload={
                        "name": self.spec["name"],
                        "runtime": self.spec["runtime"],
                        "transport": self.spec["transport"],
                        "summary": payload["summary"],
                    },
                )
            ],
            state={"openenv": payload},
            metadata={"openenv": payload},
        )

    def observe(self, **context: Any) -> EnvironmentSnapshot:
        payload = self._state_payload()
        return EnvironmentSnapshot(
            artifacts=[self._artifact()],
            state={"openenv": payload},
            metadata={"openenv": payload},
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        tool_name = _tool_name(tool_call)
        if tool_name not in {
            "openenv_status",
            "openenv_reset",
            "openenv_step",
            "openenv_state",
        }:
            return None
        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)

        if tool_name == "openenv_reset":
            result = self._apply_reset(arguments)
            event_name = "openenv_reset"
        elif tool_name == "openenv_step":
            result = self._apply_step(arguments)
            event_name = "openenv_step"
        elif tool_name == "openenv_state":
            result = self._state_payload()
            event_name = "openenv_state"
        else:
            result = self._state_payload()
            event_name = "openenv_status"

        payload = self._state_payload()
        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=tool_name,
            content=json.dumps(result, default=str),
            result=result,
            success=not bool(result.get("adapter_error")) if isinstance(result, Mapping) else True,
            error=str(result.get("adapter_error")) if isinstance(result, Mapping) and result.get("adapter_error") else None,
            state_updates={"openenv": payload},
            artifacts=[self._artifact()],
            events=[
                SimulationEvent(
                    type="openenv",
                    name=event_name,
                    payload=copy.deepcopy(result),
                )
            ],
            metadata={"openenv": payload},
        )

    def _initialize_runtime(self) -> None:
        self.current_observation = copy.deepcopy(self.spec["initial_observation"])
        self.current_state = copy.deepcopy(self.spec["initial_state"])
        self.step_index = 0
        self.reset_count = 0
        self.trajectory = []
        self.action_log = []
        self.error_log = []
        self.terminated = False
        self.truncated = False
        self.done = False
        self.reward_total = 0.0
        self.last_info = copy.deepcopy(self.spec["reset_info"])

    def _apply_reset(self, arguments: Mapping[str, Any]) -> Dict[str, Any]:
        self.current_observation = copy.deepcopy(self.spec["initial_observation"])
        self.current_state = copy.deepcopy(self.spec["initial_state"])
        self.step_index = 0
        self.trajectory = []
        self.action_log = []
        self.error_log = []
        self.terminated = False
        self.truncated = False
        self.done = False
        self.reward_total = 0.0
        self.reset_count += 1
        self.last_info = {
            **copy.deepcopy(self.spec["reset_info"]),
            **_coerce_plain_dict(arguments.get("info")),
        }
        return {
            "kind": "openenv_reset",
            "name": self.spec["name"],
            "observation": copy.deepcopy(self.current_observation),
            "info": copy.deepcopy(self.last_info),
            "state": copy.deepcopy(self.current_state),
            "seed": arguments.get("seed"),
            "options": copy.deepcopy(arguments.get("options")),
            "summary": self._summary(),
        }

    def _apply_step(self, arguments: Mapping[str, Any]) -> Dict[str, Any]:
        if self.done:
            error = {
                "kind": "openenv_step",
                "name": self.spec["name"],
                "adapter_error": "environment_done",
                "action": copy.deepcopy(arguments.get("action", arguments)),
                "step_index": self.step_index,
                "done": True,
            }
            self.error_log.append(error)
            return error

        action = copy.deepcopy(arguments.get("action", arguments))
        step = self._next_step(action)
        if step is None:
            error = {
                "kind": "openenv_step",
                "name": self.spec["name"],
                "adapter_error": "no_step_fixture",
                "action": action,
                "step_index": self.step_index,
                "done": self.done,
            }
            self.error_log.append(error)
            return error

        state_updates = _coerce_plain_dict(
            step.get("state_updates")
            or step.get("state_update")
            or step.get("state")
        )
        if state_updates:
            _deep_merge(self.current_state, state_updates)
        if step.get("observation") is not None:
            self.current_observation = copy.deepcopy(step.get("observation"))
        reward = _openenv_float(step.get("reward"), default=0.0)
        self.reward_total += reward
        self.terminated = bool(step.get("terminated", step.get("done", False)))
        self.truncated = bool(step.get("truncated", False))
        self.done = bool(step.get("done", self.terminated or self.truncated))
        self.last_info = _coerce_plain_dict(step.get("info"))
        failure = _openenv_failure(step)
        metadata = _coerce_plain_dict(step.get("metadata"))
        result = {
            "kind": "openenv_step",
            "name": self.spec["name"],
            "id": step.get("id") or f"step-{self.step_index + 1}",
            "step_index": self.step_index + 1,
            "action": action,
            "matched_action": copy.deepcopy(step.get("action")),
            "observation": copy.deepcopy(self.current_observation),
            "reward": reward,
            "terminated": self.terminated,
            "truncated": self.truncated,
            "done": self.done,
            "info": copy.deepcopy(self.last_info),
            "metadata": metadata,
            "state": copy.deepcopy(self.current_state),
            "state_updates": copy.deepcopy(state_updates),
            "failure_injected": bool(failure),
            "failure": copy.deepcopy(failure),
        }
        self.step_index += 1
        self.trajectory.append(copy.deepcopy(result))
        self.action_log.append(
            {
                "id": result["id"],
                "step_index": result["step_index"],
                "action": action,
                "reward": reward,
                "terminated": self.terminated,
                "truncated": self.truncated,
                "done": self.done,
                "failure_injected": bool(failure),
                "metadata": metadata,
            }
        )
        return result

    def _next_step(self, action: Any) -> Optional[Dict[str, Any]]:
        steps = [
            _coerce_plain_dict(step)
            for step in _as_iterable(self.spec.get("steps"))
            if isinstance(step, Mapping)
        ]
        if self.step_index >= len(steps):
            return None
        remaining = steps[self.step_index :]
        for offset, step in enumerate(remaining):
            if _openenv_action_matches(step, action):
                if offset:
                    self.step_index += offset
                return step
        return remaining[0]

    def _tool_specs(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": "openenv_status",
                "description": "Return the OpenEnv replay contract, sandbox, runtime, tool, reward, done, and trajectory summary.",
                "parameters": {"type": "object", "properties": {}},
            },
            {
                "name": "openenv_reset",
                "description": "Reset the local OpenEnv replay and return observation, info, state, and deterministic reset evidence.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "seed": {"type": "integer"},
                        "options": {"type": "object"},
                    },
                },
            },
            {
                "name": "openenv_step",
                "description": "Apply an OpenEnv action and return observation, reward, terminated, truncated, done, info, metadata, and state updates.",
                "parameters": {
                    "type": "object",
                    "properties": {"action": {"type": "object"}},
                },
            },
            {
                "name": "openenv_state",
                "description": "Return current OpenEnv state, action log, reward total, failure injections, sandbox, and replay summary.",
                "parameters": {"type": "object", "properties": {}},
            },
        ]

    def _artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            role="environment",
            data=self._state_payload(),
            metadata={"kind": "openenv_trace", "name": self.spec["name"]},
        )

    def _state_payload(self) -> Dict[str, Any]:
        return {
            "kind": "openenv",
            "name": self.spec["name"],
            "runtime": self.spec["runtime"],
            "transport": self.spec["transport"],
            "requires_external_service": self.spec["requires_external_service"],
            "deterministic_reset": self.spec["deterministic_reset"],
            "action_space": copy.deepcopy(self.spec["action_space"]),
            "observation_space": copy.deepcopy(self.spec["observation_space"]),
            "initial_observation": copy.deepcopy(self.spec["initial_observation"]),
            "current_observation": copy.deepcopy(self.current_observation),
            "state": copy.deepcopy(self.current_state),
            "reset_info": copy.deepcopy(self.spec["reset_info"]),
            "last_info": copy.deepcopy(self.last_info),
            "steps": copy.deepcopy(self.spec["steps"]),
            "trajectory": copy.deepcopy(self.trajectory),
            "action_log": copy.deepcopy(self.action_log),
            "error_log": copy.deepcopy(self.error_log),
            "sandbox": copy.deepcopy(self.spec["sandbox"]),
            "replay": copy.deepcopy(self.spec["replay"]),
            "failure_injections": copy.deepcopy(self.spec["failure_injections"]),
            "tool_registry": copy.deepcopy(self.spec["tool_registry"]),
            "signals": sorted(self._observed_signals()),
            "summary": self._summary(),
            "metadata": copy.deepcopy(self.spec["metadata"]),
        }

    def _observed_signals(self) -> set[str]:
        signals = {
            "openenv",
            "environment",
            "state",
            "observation",
            "action",
            "reset" if self.reset_count else "",
            "step" if self.action_log else "",
            "reward" if self.action_log else "",
            "done" if self.done else "",
            "terminated" if self.terminated else "",
            "truncated" if self.truncated else "",
            "metadata" if self._metadata_capture_count() else "",
            "sandbox" if self._sandbox_enabled() else "",
            "failure_injection" if self._failure_count() else "",
            self.spec["runtime"],
            self.spec["transport"],
        }
        return {_normalize_openenv_key(signal) for signal in signals if signal}

    def _summary(self) -> Dict[str, Any]:
        return {
            "configured_step_count": len(self.spec.get("steps", [])),
            "reset_count": self.reset_count,
            "step_count": len(self.trajectory),
            "action_route_count": len(self.action_log),
            "reward_total": round(self.reward_total, 4),
            "terminated": self.terminated,
            "truncated": self.truncated,
            "done": self.done,
            "failure_count": self._failure_count(),
            "error_count": len(self.error_log),
            "metadata_capture_count": self._metadata_capture_count(),
            "sandbox_enabled": self._sandbox_enabled(),
            "isolation": self.spec["sandbox"].get("isolation"),
            "runtime": self.spec["runtime"],
            "transport": self.spec["transport"],
            "requires_external_service": self.spec["requires_external_service"],
            "deterministic_reset": self.spec["deterministic_reset"],
            "state_key_count": _openenv_key_count(self.current_state),
            "observation_key_count": _openenv_key_count(self.current_observation),
            "terminal_status": "success" if self.done and not self.error_log else "incomplete",
        }

    def _failure_count(self) -> int:
        configured = len(self.spec.get("failure_injections", []))
        observed = sum(1 for item in self.trajectory if item.get("failure_injected"))
        return max(configured if observed else 0, observed)

    def _metadata_capture_count(self) -> int:
        count = 0
        if self.spec["reset_info"]:
            count += 1
        for record in self.trajectory:
            if record.get("info"):
                count += 1
            if record.get("metadata"):
                count += 1
        return count

    def _sandbox_enabled(self) -> bool:
        sandbox = self.spec.get("sandbox", {})
        if sandbox.get("enabled") is not None:
            return bool(sandbox.get("enabled"))
        return bool(sandbox)


def normalize_openenv_manifest(source: Mapping[str, Any]) -> Dict[str, Any]:
    """Normalize OpenEnv/Gymnasium-style reset/step/state replay evidence."""

    data = _coerce_plain_dict(source.get("openenv") or source.get("open_env") or source)
    reset_spec = _coerce_plain_dict(data.get("reset"))
    replay = _coerce_plain_dict(data.get("replay"))
    sandbox = _coerce_plain_dict(data.get("sandbox") or data.get("isolation"))
    metadata = _coerce_plain_dict(data.get("metadata"))
    runtime = str(
        data.get("runtime")
        or data.get("mode")
        or replay.get("runtime")
        or "in_process"
    ).lower().replace("-", "_")
    transport = str(
        data.get("transport")
        or replay.get("transport")
        or ("mcp" if runtime == "mcp" else "local")
    ).lower().replace("-", "_")
    initial_observation = (
        data.get("initial_observation")
        if data.get("initial_observation") is not None
        else reset_spec.get("observation", data.get("observation", {}))
    )
    initial_state = _coerce_plain_dict(
        data.get("initial_state")
        or reset_spec.get("state")
        or data.get("state")
    )
    reset_info = _coerce_plain_dict(data.get("reset_info") or reset_spec.get("info"))
    steps = [
        _normalize_openenv_step(item, index=index + 1)
        for index, item in enumerate(
            _as_iterable(
                data.get("steps")
                or data.get("trajectory")
                or data.get("transitions")
            )
        )
    ]
    failure_injections = [
        _coerce_plain_dict(item) if isinstance(item, Mapping) else {"id": str(item)}
        for item in _as_iterable(
            data.get("failure_injections")
            or data.get("faults")
            or data.get("adversarial_states")
        )
    ]
    return {
        "kind": "openenv",
        "name": str(data.get("name") or data.get("id") or "openenv"),
        "runtime": runtime,
        "transport": transport,
        "requires_external_service": bool(data.get("requires_external_service", False)),
        "deterministic_reset": bool(
            data.get("deterministic_reset", data.get("deterministic", True))
        ),
        "action_space": _coerce_plain_dict(data.get("action_space")),
        "observation_space": _coerce_plain_dict(data.get("observation_space")),
        "initial_observation": copy.deepcopy(initial_observation),
        "initial_state": initial_state,
        "reset_info": reset_info,
        "steps": steps,
        "sandbox": {
            "enabled": bool(sandbox.get("enabled", True)) if sandbox else True,
            "isolation": str(sandbox.get("isolation") or sandbox.get("mode") or "process"),
            **copy.deepcopy(sandbox),
        },
        "replay": {
            "mode": str(replay.get("mode") or data.get("replay_mode") or "local_fixture"),
            "transport": transport,
            "deterministic": bool(replay.get("deterministic", True)),
            **copy.deepcopy(replay),
        },
        "failure_injections": failure_injections,
        "tool_registry": [
            _coerce_plain_dict(item) if isinstance(item, Mapping) else {"name": str(item)}
            for item in _as_iterable(data.get("tool_registry") or data.get("tools"))
        ],
        "metadata": metadata,
    }


def load_openenv_manifest(
    source: str | os.PathLike[str] | Mapping[str, Any],
    *,
    headers: Optional[Mapping[str, str]] = None,
    timeout: float = 30.0,
) -> OpenEnvEnvironment:
    """Load a local/HTTP/inline OpenEnv replay and return a local adapter."""

    if isinstance(source, (str, os.PathLike)):
        loaded = _load_framework_trace_export_source(
            source,
            headers=headers,
            timeout=timeout,
        )
    else:
        loaded = source
    return OpenEnvEnvironment(normalize_openenv_manifest(_coerce_plain_dict(loaded)))


EnvironmentReplayEnvironment = OpenEnvEnvironment
normalize_environment_replay_manifest = normalize_openenv_manifest
load_environment_replay_manifest = load_openenv_manifest


def _normalize_openenv_step(value: Any, *, index: int) -> Dict[str, Any]:
    step = _coerce_plain_dict(value)
    terminated = bool(step.get("terminated", step.get("done", False)))
    truncated = bool(step.get("truncated", False))
    done = bool(step.get("done", terminated or truncated))
    return {
        "id": str(step.get("id") or step.get("name") or f"step-{index}"),
        "action": copy.deepcopy(step.get("action", step.get("input"))),
        "action_contains": copy.deepcopy(step.get("action_contains")),
        "observation": copy.deepcopy(step.get("observation", {})),
        "reward": _openenv_float(step.get("reward"), default=0.0),
        "terminated": terminated,
        "truncated": truncated,
        "done": done,
        "info": _coerce_plain_dict(step.get("info")),
        "metadata": _coerce_plain_dict(step.get("metadata")),
        "state_updates": _coerce_plain_dict(
            step.get("state_updates")
            or step.get("state_update")
            or step.get("state")
        ),
        "failure": _coerce_plain_dict(
            step.get("failure")
            or step.get("fault")
            or step.get("adversarial")
        ),
        "failure_injected": bool(
            step.get("failure_injected")
            or step.get("fault_injected")
            or step.get("adversarial")
            or step.get("failure")
            or step.get("fault")
        ),
    }


def _openenv_failure(step: Mapping[str, Any]) -> Dict[str, Any]:
    failure = _coerce_plain_dict(step.get("failure"))
    if not failure and bool(step.get("failure_injected")):
        failure = {"injected": True, "type": "failure_injection"}
    if failure:
        failure.setdefault("injected", True)
    return failure


def _openenv_action_matches(step: Mapping[str, Any], action: Any) -> bool:
    expected = step.get("action")
    if expected is None:
        return False
    if expected == action:
        return True
    expected_id = _normalize_openenv_key(_openenv_action_identifier(expected))
    actual_id = _normalize_openenv_key(_openenv_action_identifier(action))
    if expected_id and actual_id and expected_id == actual_id:
        return True
    contains = step.get("action_contains")
    if contains in (None, "", [], {}):
        return False
    action_text = json.dumps(action, sort_keys=True, default=str).lower()
    if isinstance(contains, str):
        return contains.lower() in action_text
    if isinstance(contains, Mapping):
        return all(str(value).lower() in action_text for value in contains.values())
    return all(str(value).lower() in action_text for value in _as_iterable(contains))


def _openenv_action_identifier(action: Any) -> str:
    if isinstance(action, Mapping):
        for key in ("id", "type", "name", "action", "tool", "command"):
            if action.get(key) not in (None, ""):
                return str(action.get(key))
        return json.dumps(action, sort_keys=True, default=str)
    return str(action or "")


def _openenv_float(value: Any, *, default: float = 0.0) -> float:
    try:
        if value in (None, ""):
            return float(default)
        return float(value)
    except (TypeError, ValueError):
        return float(default)


def _openenv_key_count(value: Any) -> int:
    if isinstance(value, Mapping):
        count = 0
        for item in value.values():
            count += _openenv_key_count(item)
        return max(len(value), count)
    if isinstance(value, list):
        return sum(_openenv_key_count(item) for item in value)
    return 1 if value not in (None, "") else 0


def _normalize_openenv_key(value: Any) -> str:
    normalized = str(value or "").strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")
    aliases = {
        "open_env": "openenv",
        "gymnasium": "openenv",
        "gymnasium_env": "openenv",
        "environment_replay": "openenv",
        "reset_count": "reset",
        "step_count": "step",
        "action_route": "action",
        "action_routing": "action",
        "rewards": "reward",
        "terminal": "done",
        "terminal_state": "done",
        "failure": "failure_injection",
        "fault": "failure_injection",
        "fault_injection": "failure_injection",
        "sandboxed": "sandbox",
        "isolation": "sandbox",
    }
    return aliases.get(normalized, normalized)


def normalize_world_contract(
    *,
    name: str = "world",
    actors: Iterable[str | Mapping[str, Any]] = (),
    resources: Iterable[str | Mapping[str, Any]] = (),
    transitions: Iterable[str | Mapping[str, Any]] = (),
    invariants: Iterable[str | Mapping[str, Any]] = (),
    success_conditions: Iterable[str | Mapping[str, Any]] = (),
    policy_gates: Iterable[str | Mapping[str, Any]] = (),
    adversarial_surfaces: Iterable[str | Mapping[str, Any]] = (),
    initial_state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Normalize a portable world/task state contract into a serializable shape."""

    return {
        "kind": "world_contract",
        "name": str(name),
        "actors": [_world_contract_entity(actor, prefix="actor") for actor in actors],
        "resources": [_world_contract_entity(resource, prefix="resource") for resource in resources],
        "transitions": [
            _world_contract_transition(transition, index=index + 1)
            for index, transition in enumerate(transitions)
        ],
        "invariants": [
            _world_contract_condition(invariant, prefix="invariant", index=index + 1)
            for index, invariant in enumerate(invariants)
        ],
        "success_conditions": [
            _world_contract_condition(condition, prefix="success", index=index + 1)
            for index, condition in enumerate(success_conditions)
        ],
        "policy_gates": [
            _world_contract_condition(gate, prefix="policy", index=index + 1)
            for index, gate in enumerate(policy_gates)
        ],
        "adversarial_surfaces": [
            _world_contract_entity(surface, prefix="surface")
            for surface in adversarial_surfaces
        ],
        "initial_state": copy.deepcopy(dict(initial_state or {})),
        "metadata": copy.deepcopy(dict(metadata or {})),
    }


def load_world_contract(
    source: str | os.PathLike[str] | Mapping[str, Any],
    *,
    headers: Optional[Mapping[str, str]] = None,
    timeout: float = 30.0,
) -> WorldContractEnvironment:
    """Load a local/HTTP/inline world contract and return a replay environment."""

    if isinstance(source, (str, os.PathLike)):
        loaded = _load_framework_trace_export_source(
            source,
            headers=headers,
            timeout=timeout,
        )
    else:
        loaded = source
    data = _coerce_plain_dict(loaded)
    return WorldContractEnvironment(
        name=str(data.get("name") or data.get("id") or "world"),
        actors=_as_iterable(data.get("actors")),
        resources=_as_iterable(data.get("resources")),
        transitions=_as_iterable(data.get("transitions")),
        invariants=_as_iterable(data.get("invariants")),
        success_conditions=_as_iterable(data.get("success_conditions") or data.get("success")),
        policy_gates=_as_iterable(data.get("policy_gates") or data.get("policies")),
        adversarial_surfaces=_as_iterable(data.get("adversarial_surfaces") or data.get("surfaces")),
        initial_state=_coerce_plain_dict(data.get("initial_state") or data.get("state")),
        metadata=_coerce_plain_dict(data.get("metadata")),
    )


class BrowserEnvironment(EnvironmentAdapter):
    """Local browser/CUA environment with snapshots, replay, and domain policy."""

    name = "browser"

    def __init__(
        self,
        *,
        url: str = "https://example.test/",
        dom: str = "<html><body></body></html>",
        screenshot_uri: Optional[str] = None,
        allowed_domains: Optional[Iterable[str]] = None,
        state: Optional[Dict[str, Any]] = None,
        snapshots: Optional[Iterable[Mapping[str, Any]]] = None,
        actions: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]] = None,
        regions: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]] = None,
        console_logs: Optional[Iterable[str | Mapping[str, Any]]] = None,
        network_log: Optional[Iterable[Mapping[str, Any]]] = None,
        storage_state: Optional[Any] = None,
        cookies: Optional[Iterable[Mapping[str, Any]] | Mapping[str, Any]] = None,
        local_storage: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]] = None,
        session_storage: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]] = None,
        runtime_events: Optional[Iterable[str | Mapping[str, Any]]] = None,
        performance_entries: Optional[Iterable[Mapping[str, Any]]] = None,
        prompt_injections: Optional[Iterable[str | Mapping[str, Any]]] = None,
        browser_trace: Optional[Any] = None,
        browser_trace_source: Optional[str | os.PathLike[str]] = None,
        trace_provider: str = "browser",
        playwright_trace: Optional[Any] = None,
        playwright_trace_source: Optional[str | os.PathLike[str]] = None,
        video_artifacts: Optional[Iterable[str | Mapping[str, Any]]] = None,
        perturbations: Optional[Iterable[str | Mapping[str, Any]]] = None,
        mutation_pack: Optional[Any] = None,
        mutations: Optional[Iterable[str | Mapping[str, Any]]] = None,
    ) -> None:
        trace_fixture = _merge_browser_trace_fixtures(
            _normalize_browser_trace_export(
                _load_browser_trace_source(browser_trace_source) if browser_trace_source is not None else browser_trace,
                provider=trace_provider,
                source_label=_browser_source_label(browser_trace_source) if browser_trace_source is not None else None,
            ),
            _normalize_playwright_trace_export(
                _load_playwright_trace_source(playwright_trace_source) if playwright_trace_source is not None else playwright_trace,
                source_label=_browser_source_label(playwright_trace_source) if playwright_trace_source is not None else None,
            ),
        )
        trace_snapshots = list(trace_fixture.get("snapshots", []))
        if trace_snapshots and url == "https://example.test/":
            first_snapshot = trace_snapshots[0]
            url = str(first_snapshot.get("url") or url)
            dom = str(first_snapshot.get("dom") or dom)
            screenshot_uri = first_snapshot.get("screenshot_uri", screenshot_uri)
        self.initial_url = url
        self.initial_dom = dom
        self.initial_screenshot_uri = screenshot_uri
        self.url = url
        self.dom = dom
        self.screenshot_uri = screenshot_uri
        self.allowed_domains = {domain.lower() for domain in allowed_domains or []}
        self.initial_state = copy.deepcopy(state or {})
        self.state = copy.deepcopy(self.initial_state)
        self.initial_mutation_pack = normalize_browser_mutation_pack(
            mutation_pack,
            mutations=mutations or [],
            url=url,
        )
        self.mutation_pack = copy.deepcopy(self.initial_mutation_pack)
        initial_perturbations = _normalize_browser_perturbations(
            [
                *list(trace_fixture.get("perturbations", [])),
                *_browser_mutation_perturbations(self.initial_mutation_pack),
                *list(perturbations or []),
            ]
        )
        self.initial_snapshots = _apply_browser_mutations_to_snapshots(
            _apply_browser_perturbations_to_snapshots(
                _normalize_browser_snapshots(
                    [*trace_snapshots, *list(snapshots or [])],
                    url=url,
                    dom=dom,
                    screenshot_uri=screenshot_uri,
                    state=self.initial_state,
                ),
                initial_perturbations,
            ),
            self.initial_mutation_pack,
        )
        self.snapshots = copy.deepcopy(self.initial_snapshots)
        self.current_snapshot_index = 0
        self.initial_actions = _normalize_browser_actions(
            [
                *list(trace_fixture.get("actions", [])),
                *_browser_mutation_action_effects(self.initial_mutation_pack),
                *_browser_action_items(actions),
            ]
        )
        self.actions = copy.deepcopy(self.initial_actions)
        self.initial_perturbations = initial_perturbations
        self.initial_regions = _apply_browser_perturbations_to_regions(
            _normalize_browser_regions([*list(trace_fixture.get("regions", [])), *_browser_region_items(regions)]),
            self.initial_perturbations,
        )
        self.regions = copy.deepcopy(self.initial_regions)
        self.initial_console_logs = [
            _normalize_browser_log(item)
            for item in [*list(trace_fixture.get("console_logs", [])), *list(console_logs or [])]
        ]
        self.initial_network_log = [
            dict(item)
            for item in [
                *list(trace_fixture.get("network_log", [])),
                *_browser_mutation_network_log(self.initial_mutation_pack),
                *list(network_log or []),
            ]
        ]
        self.initial_resource_bodies = _dedupe_dicts(trace_fixture.get("resource_bodies", []))
        self.initial_actionability_timeline = _dedupe_dicts(
            [
                *list(trace_fixture.get("actionability_timeline", [])),
                *_browser_mutation_actionability_timeline(self.initial_mutation_pack),
            ]
        )
        self.initial_storage_state = _merge_browser_storage_states(
            trace_fixture.get("storage_state"),
            _normalize_browser_storage_state(
                storage_state,
                url=url,
                cookies=cookies,
                local_storage=local_storage,
                session_storage=session_storage,
            ),
            _browser_mutation_storage_state(self.initial_mutation_pack, url=url),
        )
        self.initial_runtime_events = [
            _normalize_browser_runtime_event(item)
            for item in [
                *list(trace_fixture.get("runtime_events", [])),
                *_browser_mutation_runtime_events(self.initial_mutation_pack),
                *list(runtime_events or []),
            ]
        ]
        self.initial_performance_entries = _dedupe_dicts(
            [
                *list(trace_fixture.get("performance_entries", [])),
                *_browser_mutation_performance_entries(self.initial_mutation_pack),
                *[_normalize_browser_performance_entry(item) for item in performance_entries or []],
            ]
        )
        self.console_logs = copy.deepcopy(self.initial_console_logs)
        self.network_log = copy.deepcopy(self.initial_network_log)
        self.resource_bodies = copy.deepcopy(self.initial_resource_bodies)
        self.actionability_timeline = copy.deepcopy(self.initial_actionability_timeline)
        self.storage_state = copy.deepcopy(self.initial_storage_state)
        self.runtime_events = copy.deepcopy(self.initial_runtime_events)
        self.performance_entries = copy.deepcopy(self.initial_performance_entries)
        self.initial_prompt_injections = _normalize_browser_prompt_injections(
            [*list(trace_fixture.get("prompt_injections", [])), *list(prompt_injections or [])],
            self.initial_regions,
        )
        self.prompt_injections = copy.deepcopy(self.initial_prompt_injections)
        self.initial_video_artifacts = _normalize_browser_video_artifacts(
            [*list(trace_fixture.get("video_artifacts", [])), *list(video_artifacts or [])]
        )
        self.video_artifacts = copy.deepcopy(self.initial_video_artifacts)
        self.trace_import_metadata = copy.deepcopy(dict(trace_fixture.get("metadata", {})))
        self.perturbations = copy.deepcopy(self.initial_perturbations)
        self.action_replay: List[Dict[str, Any]] = []
        self.dom_mutations: List[Dict[str, Any]] = []
        self.screenshot_diffs: List[Dict[str, Any]] = []

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.url = self.initial_url
        self.dom = self.initial_dom
        self.screenshot_uri = self.initial_screenshot_uri
        self.state = copy.deepcopy(self.initial_state)
        self.snapshots = copy.deepcopy(self.initial_snapshots)
        self.actions = copy.deepcopy(self.initial_actions)
        self.regions = copy.deepcopy(self.initial_regions)
        self.console_logs = copy.deepcopy(self.initial_console_logs)
        self.network_log = copy.deepcopy(self.initial_network_log)
        self.resource_bodies = copy.deepcopy(self.initial_resource_bodies)
        self.actionability_timeline = copy.deepcopy(self.initial_actionability_timeline)
        self.storage_state = copy.deepcopy(self.initial_storage_state)
        self.runtime_events = copy.deepcopy(self.initial_runtime_events)
        self.performance_entries = copy.deepcopy(self.initial_performance_entries)
        self.prompt_injections = copy.deepcopy(self.initial_prompt_injections)
        self.video_artifacts = copy.deepcopy(self.initial_video_artifacts)
        self.perturbations = copy.deepcopy(self.initial_perturbations)
        self.mutation_pack = copy.deepcopy(self.initial_mutation_pack)
        self.current_snapshot_index = 0
        self.action_replay = []
        self.dom_mutations = []
        self.screenshot_diffs = []
        artifacts = self._snapshot_artifacts(self._current_snapshot())
        artifacts.extend(self._video_artifacts())
        artifacts.append(self._trace_artifact())
        artifacts.extend(self._mutation_pack_artifacts())
        events = [
            SimulationEvent(
                type="environment",
                name="browser_ready",
                payload={
                    "url": self.url,
                    "allowed_domains": sorted(self.allowed_domains),
                    "snapshots": len(self.snapshots),
                    "action_fixtures": len(self.actions),
                    "regions": sorted(self.regions.keys()),
                    "console_logs": len(self.console_logs),
                    "network_log": len(self.network_log),
                    "resource_bodies": len(self.resource_bodies),
                    "actionability_timeline": len(self.actionability_timeline),
                    "cookies": len(self.storage_state.get("cookies", [])),
                    "storage_origins": len(self.storage_state.get("origins", [])),
                    "runtime_events": len(self.runtime_events),
                    "performance_entries": len(self.performance_entries),
                    "layout_shift_distribution": bool(_browser_layout_shift_distribution(self.perturbations)),
                    "video_artifacts": len(self.video_artifacts),
                    "perturbations": len(self.perturbations),
                    "browser_mutations": len(self.mutation_pack.get("mutations", [])),
                    "trace_import": copy.deepcopy(self.trace_import_metadata),
                },
            ),
            SimulationEvent(
                type="browser_snapshot",
                name="initial_snapshot",
                payload=self._snapshot_summary(self._current_snapshot()),
            ),
        ]
        if self.console_logs:
            events.append(
                SimulationEvent(
                    type="browser_console",
                    name="console_log_loaded",
                    payload={"logs": copy.deepcopy(self.console_logs)},
                )
            )
        if self.network_log:
            events.append(
                SimulationEvent(
                    type="browser_network",
                    name="network_log_loaded",
                    payload={
                        "requests": copy.deepcopy(self.network_log),
                        "resource_bodies": copy.deepcopy(self.resource_bodies),
                    },
                )
            )
        if self.actionability_timeline:
            events.append(
                SimulationEvent(
                    type="browser_actionability",
                    name="actionability_timeline_loaded",
                    payload={"checks": copy.deepcopy(self.actionability_timeline)},
                )
            )
        if _browser_storage_state_has_data(self.storage_state):
            events.append(
                SimulationEvent(
                    type="browser_storage",
                    name="storage_state_loaded",
                    payload={"storage_state": copy.deepcopy(self.storage_state)},
                )
            )
        if self.runtime_events or self.performance_entries:
            events.append(
                SimulationEvent(
                    type="browser_runtime",
                    name="runtime_capture_loaded",
                    payload={
                        "runtime_events": copy.deepcopy(self.runtime_events),
                        "performance_entries": copy.deepcopy(self.performance_entries),
                        "summary": _browser_runtime_summary(self.runtime_events, self.performance_entries),
                    },
                )
            )
        if self.mutation_pack.get("mutations"):
            events.append(
                SimulationEvent(
                    type="browser_mutation_pack",
                    name="browser_mutation_pack_loaded",
                    payload=copy.deepcopy(self.mutation_pack),
                )
            )
            for mutation in self.mutation_pack.get("mutations", []):
                events.append(
                    SimulationEvent(
                        type="browser_mutation",
                        name=str(mutation.get("id") or mutation.get("type") or "browser_mutation"),
                        payload=copy.deepcopy(mutation),
                    )
                )
        for injection in self.prompt_injections:
            events.append(
                SimulationEvent(
                    type="environment_injection",
                    name="browser_prompt_injection_surface",
                    payload=copy.deepcopy(injection),
                )
            )
        for perturbation in self.perturbations:
            events.append(
                SimulationEvent(
                    type="browser_perturbation",
                    name=str(perturbation.get("type") or perturbation.get("id") or "browser_perturbation"),
                    payload=copy.deepcopy(perturbation),
                )
            )
        return EnvironmentSnapshot(
            tools=[
                {
                    "name": "browser_navigate",
                    "description": "Navigate the simulated browser to a URL.",
                    "parameters": {
                        "type": "object",
                        "properties": {"url": {"type": "string"}},
                        "required": ["url"],
                    },
                },
                {
                    "name": "browser_click",
                    "description": "Click an element in the simulated browser.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "selector": {"type": "string"},
                            "locator": {"type": "string"},
                            "x": {"type": "number"},
                            "y": {"type": "number"},
                            "coordinates": {"type": "object"},
                            "url": {"type": "string"},
                            "action": {"type": "string"},
                        },
                    },
                },
                {
                    "name": "browser_snapshot",
                    "description": "Return the current simulated browser DOM, screenshot metadata, and action replay.",
                },
                {
                    "name": "browser_refresh_snapshot",
                    "description": "Move to the latest non-stale simulated browser snapshot for the current URL.",
                },
                {
                    "name": "browser_console",
                    "description": "Return simulated browser console logs.",
                },
                {
                    "name": "browser_network",
                    "description": "Return simulated browser network requests.",
                },
                {
                    "name": "browser_storage",
                    "description": "Return simulated browser cookies and origin storage state.",
                },
                {
                    "name": "browser_runtime",
                    "description": "Return simulated browser runtime events and performance entries.",
                },
                {
                    "name": "browser_mutations",
                    "description": "Return the structured browser mutation pack applied to this environment.",
                },
            ],
            artifacts=artifacts,
            state={"browser": self._state_payload()},
            events=events,
            metadata={
                "browser_trace": {
                    "snapshots": len(self.snapshots),
                    "action_fixtures": len(self.actions),
                    "regions": sorted(self.regions.keys()),
                    "console_logs": len(self.console_logs),
                    "network_log": len(self.network_log),
                    "resource_bodies": len(self.resource_bodies),
                    "actionability_timeline": len(self.actionability_timeline),
                    "cookies": len(self.storage_state.get("cookies", [])),
                    "storage_origins": len(self.storage_state.get("origins", [])),
                    "runtime_events": len(self.runtime_events),
                    "performance_entries": len(self.performance_entries),
                    "video_artifacts": len(self.video_artifacts),
                    "perturbations": len(self.perturbations),
                    "browser_mutations": len(self.mutation_pack.get("mutations", [])),
                }
            },
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if name in {
            "browser_snapshot",
            "browser_refresh_snapshot",
            "browser_console",
            "browser_network",
            "browser_storage",
            "browser_runtime",
            "browser_mutations",
        }:
            return self._inspection_result(tool_call, name)
        if name not in {"browser_navigate", "browser_click", "playwright_click", "computer_click"}:
            return None

        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)
        selector = _browser_action_selector(arguments)
        action = str(arguments.get("action") or arguments.get("selector") or name)
        matched_effect = self._matched_action_effect(name, arguments, action)
        grounding = self._action_grounding_payload(arguments, matched_effect)
        requested_url = self._requested_action_url(arguments, matched_effect)
        allowed, reason = self._allowed_url(requested_url)
        if not allowed:
            replay_event = {
                "tool": name,
                "url": requested_url,
                "action": action,
                "selector": selector,
                "matched": bool(matched_effect),
                "effect_id": matched_effect.get("id") if matched_effect else None,
                "mutation_id": _browser_action_effect_mutation_id(matched_effect),
                "mutation_type": _browser_action_effect_mutation_type(matched_effect),
                "arguments": copy.deepcopy(arguments),
                "blocked": True,
                "success": False,
                "reason": reason,
                "turn_index": context.get("turn_index"),
                **copy.deepcopy(grounding),
            }
            self.action_replay.append(replay_event)
            return ToolExecutionResult(
                tool_call_id=call_id,
                tool_name=name,
                content=f"Blocked browser action: {reason}",
                result={"url": requested_url, "action": action},
                success=False,
                error=reason,
                state_updates={"browser": self._state_payload()},
                artifacts=[self._trace_artifact()],
                events=[
                    SimulationEvent(
                        type="browser_action",
                        name=name,
                        payload=replay_event,
                    )
                ],
            )

        if self.actions and name in {"browser_click", "playwright_click", "computer_click"} and matched_effect is None:
            reason = f"no action fixture matched selector '{selector or action}'"
            replay_event = {
                "tool": name,
                "url": requested_url,
                "action": action,
                "selector": selector,
                "matched": False,
                "arguments": copy.deepcopy(arguments),
                "blocked": False,
                "success": False,
                "reason": reason,
                "turn_index": context.get("turn_index"),
                **copy.deepcopy(grounding),
            }
            self.action_replay.append(replay_event)
            return ToolExecutionResult(
                tool_call_id=call_id,
                tool_name=name,
                content=f"Browser action failed: {reason}",
                result={"url": requested_url, "action": action, "selector": selector},
                success=False,
                error=reason,
                state_updates={"browser": self._state_payload()},
                artifacts=[self._trace_artifact()],
                events=[
                    SimulationEvent(
                        type="browser_action",
                        name=name,
                        payload=replay_event,
                    )
                ],
            )

        actionability_error = _browser_actionability_error(matched_effect)
        if actionability_error:
            replay_event = {
                "tool": name,
                "url": requested_url,
                "action": action,
                "selector": selector,
                "matched": True,
                "effect_id": matched_effect.get("id") if matched_effect else None,
                "mutation_id": _browser_action_effect_mutation_id(matched_effect),
                "mutation_type": _browser_action_effect_mutation_type(matched_effect),
                "arguments": copy.deepcopy(arguments),
                "blocked": False,
                "success": False,
                "reason": actionability_error,
                "actionability": _browser_actionability_payload(matched_effect),
                "turn_index": context.get("turn_index"),
                **copy.deepcopy(grounding),
            }
            self.action_replay.append(replay_event)
            return ToolExecutionResult(
                tool_call_id=call_id,
                tool_name=name,
                content=f"Browser action failed: {actionability_error}",
                result={"url": requested_url, "action": action, "selector": selector},
                success=False,
                error=actionability_error,
                state_updates={"browser": self._state_payload()},
                artifacts=[self._trace_artifact()],
                events=[
                    SimulationEvent(
                        type="browser_action",
                        name=name,
                        payload=replay_event,
                    )
                ],
            )

        effect_success = bool(matched_effect.get("success", True)) if matched_effect else True
        if matched_effect and not effect_success:
            reason = str(matched_effect.get("error") or "browser action fixture returned failure")
            replay_event = {
                "tool": name,
                "url": requested_url,
                "action": action,
                "selector": selector,
                "matched": True,
                "effect_id": matched_effect.get("id"),
                "mutation_id": _browser_action_effect_mutation_id(matched_effect),
                "mutation_type": _browser_action_effect_mutation_type(matched_effect),
                "arguments": copy.deepcopy(arguments),
                "blocked": False,
                "success": False,
                "reason": reason,
                "turn_index": context.get("turn_index"),
                **copy.deepcopy(grounding),
            }
            self.action_replay.append(replay_event)
            return ToolExecutionResult(
                tool_call_id=call_id,
                tool_name=name,
                content=f"Browser action failed: {reason}",
                result={"url": requested_url, "action": action, "selector": selector},
                success=False,
                error=reason,
                state_updates={"browser": self._state_payload()},
                artifacts=[self._trace_artifact()],
                events=[
                    SimulationEvent(
                        type="browser_action",
                        name=name,
                        payload=replay_event,
                    )
                ],
            )

        before_snapshot = self._snapshot_summary(self._current_snapshot())
        self.url = requested_url
        effect_updates = self._apply_action_effect(matched_effect, requested_url)
        grounding = {
            **grounding,
            **_browser_screenshot_diff_grounding(effect_updates.get("screenshot_diff")),
        }
        replay_event = {
            "tool": name,
            "url": self.url,
            "action": action,
            "selector": selector,
            "matched": bool(matched_effect),
            "effect_id": matched_effect.get("id") if matched_effect else None,
            "mutation_id": _browser_action_effect_mutation_id(matched_effect),
            "mutation_type": _browser_action_effect_mutation_type(matched_effect),
            "arguments": copy.deepcopy(arguments),
            "blocked": False,
            "success": True,
            "state_updates": copy.deepcopy(effect_updates.get("state_updates", {})),
            "storage_mutation": copy.deepcopy(effect_updates.get("storage_mutation", {})),
            "runtime_events": copy.deepcopy(effect_updates.get("runtime_events", [])),
            "performance_entries": copy.deepcopy(effect_updates.get("performance_entries", [])),
            "before_snapshot": before_snapshot,
            "after_snapshot": self._snapshot_summary(self._current_snapshot()),
            "actionability": _browser_actionability_payload(matched_effect),
            "turn_index": context.get("turn_index"),
            **copy.deepcopy(grounding),
        }
        self.action_replay.append(replay_event)
        if effect_updates.get("dom_mutation"):
            self.dom_mutations.append(effect_updates["dom_mutation"])
        if effect_updates.get("screenshot_diff"):
            self.screenshot_diffs.append(effect_updates["screenshot_diff"])
        state_update = {"browser": self._state_payload(last_action=action)}
        events = [
            SimulationEvent(
                type="browser_action",
                name=name,
                payload=replay_event,
            ),
            SimulationEvent(
                type="browser_snapshot",
                name="post_action_snapshot",
                payload=self._snapshot_summary(self._current_snapshot()),
            ),
        ]
        if effect_updates.get("dom_mutation"):
            events.append(
                SimulationEvent(
                    type="browser_dom_mutation",
                    name=str(matched_effect.get("id") if matched_effect else name),
                    payload=copy.deepcopy(effect_updates["dom_mutation"]),
                )
            )
        if effect_updates.get("screenshot_diff"):
            events.append(
                SimulationEvent(
                    type="browser_screenshot_diff",
                    name=str(matched_effect.get("id") if matched_effect else name),
                    payload=copy.deepcopy(effect_updates["screenshot_diff"]),
                )
            )
        if effect_updates.get("storage_mutation"):
            events.append(
                SimulationEvent(
                    type="browser_storage",
                    name=str(matched_effect.get("id") if matched_effect else name),
                    payload=copy.deepcopy(effect_updates["storage_mutation"]),
                )
            )
        if effect_updates.get("runtime_events") or effect_updates.get("performance_entries"):
            events.append(
                SimulationEvent(
                    type="browser_runtime",
                    name=str(matched_effect.get("id") if matched_effect else name),
                    payload={
                        "runtime_events": copy.deepcopy(effect_updates.get("runtime_events", [])),
                        "performance_entries": copy.deepcopy(effect_updates.get("performance_entries", [])),
                        "summary": _browser_runtime_summary(self.runtime_events, self.performance_entries),
                    },
                )
            )
        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=name,
            content=f"Browser action completed: {action} at {self.url}",
            result={"url": self.url, "action": action, "snapshot": self._current_snapshot()},
            state_updates=state_update,
            artifacts=self._snapshot_artifacts(self._current_snapshot()) + [self._trace_artifact()],
            events=events,
        )

    def _allowed_url(self, url: str) -> tuple[bool, str]:
        if not self.allowed_domains:
            return True, ""
        host = urlparse(url).netloc.lower()
        if any(host == domain or host.endswith(f".{domain}") for domain in self.allowed_domains):
            return True, ""
        return False, f"host '{host}' is outside allowed domains"

    def _inspection_result(self, tool_call: Mapping[str, Any], name: str) -> ToolExecutionResult:
        call_id = _tool_call_id(tool_call)
        if name == "browser_console":
            result = {"console_logs": copy.deepcopy(self.console_logs)}
            event_type = "browser_console"
        elif name == "browser_network":
            result = {
                "network_log": copy.deepcopy(self.network_log),
                "resource_bodies": copy.deepcopy(self.resource_bodies),
            }
            event_type = "browser_network"
        elif name == "browser_storage":
            result = {"storage_state": copy.deepcopy(self.storage_state)}
            event_type = "browser_storage"
        elif name == "browser_runtime":
            result = {
                "runtime_events": copy.deepcopy(self.runtime_events),
                "performance_entries": copy.deepcopy(self.performance_entries),
                "summary": _browser_runtime_summary(self.runtime_events, self.performance_entries),
            }
            event_type = "browser_runtime"
        elif name == "browser_mutations":
            result = copy.deepcopy(self.mutation_pack)
            event_type = "browser_mutation_pack"
        elif name == "browser_refresh_snapshot":
            refreshed = self._refresh_snapshot()
            result = {"refreshed": refreshed, "snapshot": self._snapshot_summary(self._current_snapshot())}
            event_type = "browser_snapshot"
        else:
            result = self._trace_payload()
            event_type = "browser_snapshot"
        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=name,
            content=json.dumps(result, default=str),
            result=result,
            artifacts=self._snapshot_artifacts(self._current_snapshot()) + self._video_artifacts() + [self._trace_artifact()],
            state_updates={"browser": self._state_payload()} if name == "browser_refresh_snapshot" else {},
            events=[
                SimulationEvent(
                    type=event_type,
                    name=name,
                    payload=result,
                )
            ],
        )

    def _refresh_snapshot(self) -> bool:
        current = self._current_snapshot()
        current_url = str(current.get("url") or self.url)
        old_index = self.current_snapshot_index
        for index in range(len(self.snapshots) - 1, -1, -1):
            snapshot = self.snapshots[index]
            metadata = _as_mapping(snapshot.get("metadata"))
            if str(snapshot.get("url") or current_url) != current_url:
                continue
            if metadata.get("stale") or metadata.get("stale_screenshot"):
                continue
            self.current_snapshot_index = index
            self.url = str(snapshot.get("url") or self.url)
            self.dom = str(snapshot.get("dom", self.dom) or "")
            self.screenshot_uri = snapshot.get("screenshot_uri", self.screenshot_uri)
            return index != old_index
        return False

    def _current_snapshot(self) -> Dict[str, Any]:
        return copy.deepcopy(self.snapshots[self.current_snapshot_index])

    def _snapshot_index_for_url(self, url: str) -> int:
        for index, snapshot in enumerate(self.snapshots):
            if str(snapshot.get("url")) == url:
                return index
        return self.current_snapshot_index

    def _matched_action_effect(
        self,
        tool_name: str,
        arguments: Mapping[str, Any],
        action: str,
    ) -> Optional[Dict[str, Any]]:
        for effect in self.actions:
            if _browser_action_effect_matches(
                effect,
                tool_name=tool_name,
                arguments=arguments,
                action=action,
                current_url=self.url,
                regions=self.regions,
            ):
                return copy.deepcopy(effect)
        return None

    def _action_grounding_payload(
        self,
        arguments: Mapping[str, Any],
        effect: Optional[Mapping[str, Any]],
    ) -> Dict[str, Any]:
        coordinates = _browser_action_coordinates(arguments)
        expected_regions = _browser_expected_regions(effect, self.regions) if effect else []
        observed_region = _browser_observed_region(coordinates, self.regions)
        region_matched = None
        if expected_regions:
            region_matched = bool(
                coordinates
                and any(_browser_region_contains(region, coordinates) for region in expected_regions)
            )
        touched_surfaces = _browser_prompt_injection_surfaces_for_action(
            arguments,
            self.prompt_injections,
            self.regions,
        )
        payload: Dict[str, Any] = {
            "coordinates": coordinates,
            "region": copy.deepcopy(expected_regions[0]) if expected_regions else observed_region,
            "expected_regions": copy.deepcopy(expected_regions),
            "observed_region": copy.deepcopy(observed_region),
            "region_matched": region_matched,
            "prompt_injection_touched": bool(touched_surfaces),
            "prompt_injection_surfaces": copy.deepcopy(touched_surfaces),
            **_browser_snapshot_perturbation_payload(self._current_snapshot(), self.perturbations),
        }
        return {key: value for key, value in payload.items() if value not in (None, [], {})}

    def _requested_action_url(
        self,
        arguments: Mapping[str, Any],
        effect: Optional[Mapping[str, Any]],
    ) -> str:
        if arguments.get("url"):
            return str(arguments["url"])
        if effect:
            for key in ("next_url", "target_url", "navigate_to"):
                if effect.get(key):
                    return str(effect[key])
            if effect.get("url") and not any(effect.get(key) for key in ("current_url", "from_url", "match_url")):
                return str(effect["url"])
        return self.url

    def _apply_action_effect(
        self,
        effect: Optional[Mapping[str, Any]],
        requested_url: str,
    ) -> Dict[str, Any]:
        if not effect:
            self.current_snapshot_index = self._snapshot_index_for_url(self.url)
            return {"state_updates": {}}

        state_updates = copy.deepcopy(dict(effect.get("state_updates", effect.get("state", {})) or {}))
        if state_updates:
            _deep_merge(self.state, state_updates)

        for log in _as_iterable(effect.get("console_logs", effect.get("console_log"))):
            self.console_logs.append(_normalize_browser_log(log))
        for request in _as_iterable(effect.get("network_log", effect.get("network_request"))):
            if isinstance(request, Mapping):
                self.network_log.append(dict(request))
            else:
                self.network_log.append({"url": str(request)})
        storage_mutation = _browser_apply_storage_effect(self.storage_state, effect, url=requested_url)
        runtime_events = [
            _normalize_browser_runtime_event(item)
            for item in _as_iterable(effect.get("runtime_events", effect.get("runtime_event")))
        ]
        for key in ("page_errors", "page_error", "web_errors", "web_error"):
            for item in _as_iterable(effect.get(key)):
                event = _normalize_browser_runtime_event(item)
                if "type" not in event:
                    event["type"] = "page_error" if "page" in key else "web_error"
                runtime_events.append(event)
        performance_entries = [
            _normalize_browser_performance_entry(item)
            for item in _as_iterable(
                effect.get(
                    "performance_entries",
                    effect.get("performance", effect.get("resource_timing")),
                )
            )
        ]
        if effect.get("navigation_timing"):
            performance_entries.append(
                _normalize_browser_performance_entry(
                    {"entry_type": "navigation", **_coerce_plain_dict(effect.get("navigation_timing"))}
                )
            )
        if runtime_events:
            self.runtime_events.extend(runtime_events)
        if performance_entries:
            self.performance_entries.extend(performance_entries)
            self.performance_entries = _dedupe_dicts(self.performance_entries)
        screenshot_diff = _normalize_browser_screenshot_diff(
            effect.get("screenshot_diff", effect.get("screenshot_delta")),
            effect_id=str(effect.get("id") or ""),
        )

        snapshot_id = effect.get("snapshot_id")
        if snapshot_id:
            index = self._snapshot_index_for_id(str(snapshot_id))
            if index is not None:
                self.current_snapshot_index = index
                self.url = str(self.snapshots[index].get("url") or requested_url)
                result = {"state_updates": state_updates}
                if storage_mutation:
                    result["storage_mutation"] = storage_mutation
                if runtime_events:
                    result["runtime_events"] = runtime_events
                if performance_entries:
                    result["performance_entries"] = performance_entries
                if screenshot_diff:
                    result["screenshot_diff"] = screenshot_diff
                return result

        current = self._current_snapshot()
        dom_before = str(current.get("dom", self.dom) or "")
        dom_after = _apply_dom_patch(
            str(effect.get("dom", "")) if effect.get("dom") is not None else dom_before,
            effect.get("dom_patch"),
        )
        screenshot_uri = effect.get("screenshot_uri", current.get("screenshot_uri"))
        screenshot_path = effect.get("screenshot_path", current.get("screenshot_path"))
        if "uri" in effect and screenshot_uri is None:
            screenshot_uri = effect.get("uri")
        if "path" in effect and screenshot_path is None:
            screenshot_path = effect.get("path")
        computed_screenshot_diff = _compute_browser_screenshot_diff(
            current,
            effect,
            after_uri=screenshot_uri,
            after_path=screenshot_path,
            regions=self.regions,
        )
        screenshot_diff = _merge_browser_screenshot_diff(screenshot_diff, computed_screenshot_diff)

        if (
            requested_url != current.get("url")
            or dom_after != dom_before
            or screenshot_uri != current.get("screenshot_uri")
            or screenshot_path != current.get("screenshot_path")
            or state_updates
        ):
            new_snapshot = {
                "id": str(effect.get("id") or f"snapshot_{len(self.snapshots) + 1}"),
                "url": requested_url,
                "dom": dom_after,
                "screenshot_uri": screenshot_uri,
                "screenshot_path": screenshot_path,
                "state": copy.deepcopy(self.state),
                "metadata": {
                    **copy.deepcopy(current.get("metadata", {})),
                    **copy.deepcopy(dict(effect.get("metadata", {}))),
                    "source_action": effect.get("id"),
                },
            }
            self.snapshots.append(new_snapshot)
            self.current_snapshot_index = len(self.snapshots) - 1
            self.dom = dom_after
            self.screenshot_uri = screenshot_uri
            dom_mutation = {
                "effect_id": effect.get("id"),
                "url": requested_url,
                "snapshot_id": new_snapshot["id"],
                "dom_changed": dom_after != dom_before,
                "state_updates": copy.deepcopy(state_updates),
                "storage_mutation": copy.deepcopy(storage_mutation),
                "runtime_events": copy.deepcopy(runtime_events),
                "performance_entries": copy.deepcopy(performance_entries),
                    "metadata": copy.deepcopy(dict(effect.get("metadata", {}))),
                }
            result = {"state_updates": state_updates, "dom_mutation": dom_mutation}
            if storage_mutation:
                result["storage_mutation"] = storage_mutation
            if runtime_events:
                result["runtime_events"] = runtime_events
            if performance_entries:
                result["performance_entries"] = performance_entries
            if screenshot_diff:
                result["screenshot_diff"] = screenshot_diff
            return result

        result = {"state_updates": state_updates}
        if storage_mutation:
            result["storage_mutation"] = storage_mutation
        if runtime_events:
            result["runtime_events"] = runtime_events
        if performance_entries:
            result["performance_entries"] = performance_entries
        if screenshot_diff:
            result["screenshot_diff"] = screenshot_diff
        return result

    def _snapshot_index_for_id(self, snapshot_id: str) -> Optional[int]:
        for index, snapshot in enumerate(self.snapshots):
            if str(snapshot.get("id")) == snapshot_id:
                return index
        return None

    def _snapshot_artifacts(self, snapshot: Mapping[str, Any]) -> List[SimulationArtifact]:
        artifacts = [
            SimulationArtifact(
                type="browser_dom",
                data=snapshot.get("dom", ""),
                mime_type="text/html",
                role="environment",
                metadata={"url": snapshot.get("url"), "snapshot_id": snapshot.get("id")},
            )
        ]
        screenshot_uri = snapshot.get("screenshot_uri")
        screenshot_path = snapshot.get("screenshot_path")
        if screenshot_uri or screenshot_path:
            artifacts.append(
                SimulationArtifact(
                    type="screenshot",
                    uri=str(screenshot_uri) if screenshot_uri else None,
                    path=str(screenshot_path) if screenshot_path else None,
                    role="environment",
                    metadata={"url": snapshot.get("url"), "snapshot_id": snapshot.get("id")},
                )
            )
        return artifacts

    def _video_artifacts(self) -> List[SimulationArtifact]:
        artifacts: List[SimulationArtifact] = []
        for video in self.video_artifacts:
            artifacts.append(
                SimulationArtifact(
                    type="video",
                    uri=video.get("uri"),
                    path=video.get("path"),
                    data=video.get("data"),
                    mime_type=video.get("mime_type", "video/webm"),
                    role="environment",
                    metadata={key: value for key, value in video.items() if key not in {"uri", "path", "data", "mime_type"}},
                )
            )
        return artifacts

    def _mutation_pack_artifacts(self) -> List[SimulationArtifact]:
        if not self.mutation_pack.get("mutations"):
            return []
        return [
            SimulationArtifact(
                type="trace",
                data=copy.deepcopy(self.mutation_pack),
                mime_type="application/json",
                role="environment",
                metadata={"kind": "browser_mutation_pack", "url": self.url},
            )
        ]

    def _trace_artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            data=self._trace_payload(),
            mime_type="application/json",
            role="environment",
            metadata={"kind": "browser_trace", "url": self.url},
        )

    def _trace_payload(self) -> Dict[str, Any]:
        return {
            "kind": "browser_trace",
            "url": self.url,
            "snapshots": copy.deepcopy(self.snapshots),
            "action_replay": copy.deepcopy(self.action_replay),
            "dom_mutations": copy.deepcopy(self.dom_mutations),
            "screenshot_diffs": copy.deepcopy(self.screenshot_diffs),
            "regions": copy.deepcopy(self.regions),
            "console_logs": copy.deepcopy(self.console_logs),
            "network_log": copy.deepcopy(self.network_log),
            "resource_bodies": copy.deepcopy(self.resource_bodies),
            "actionability_timeline": copy.deepcopy(self.actionability_timeline),
            "storage_state": copy.deepcopy(self.storage_state),
            "runtime_events": copy.deepcopy(self.runtime_events),
            "performance_entries": copy.deepcopy(self.performance_entries),
            "runtime_summary": _browser_runtime_summary(self.runtime_events, self.performance_entries),
            "prompt_injections": copy.deepcopy(self.prompt_injections),
            "video_artifacts": copy.deepcopy(self.video_artifacts),
            "perturbations": copy.deepcopy(self.perturbations),
            "mutation_pack": copy.deepcopy(self.mutation_pack),
            "browser_mutations": copy.deepcopy(self.mutation_pack.get("mutations", [])),
            "layout_shift_distribution": _browser_layout_shift_distribution(self.perturbations),
            "trace_import": copy.deepcopy(self.trace_import_metadata),
            "final_state": {"browser": self._state_payload()},
        }

    def _state_payload(self, *, last_action: Optional[str] = None) -> Dict[str, Any]:
        payload = {
            **copy.deepcopy(self.state),
            "url": self.url,
            "snapshot": self._snapshot_summary(self._current_snapshot()),
            "action_replay": copy.deepcopy(self.action_replay),
            "screenshot_diffs": copy.deepcopy(self.screenshot_diffs),
            "regions": copy.deepcopy(self.regions),
            "console_logs": copy.deepcopy(self.console_logs),
            "network_log": copy.deepcopy(self.network_log),
            "resource_bodies": copy.deepcopy(self.resource_bodies),
            "actionability_timeline": copy.deepcopy(self.actionability_timeline),
            "storage_state": copy.deepcopy(self.storage_state),
            "runtime_events": copy.deepcopy(self.runtime_events),
            "performance_entries": copy.deepcopy(self.performance_entries),
            "runtime_summary": _browser_runtime_summary(self.runtime_events, self.performance_entries),
            "video_artifacts": copy.deepcopy(self.video_artifacts),
            "perturbations": copy.deepcopy(self.perturbations),
            "mutation_pack": copy.deepcopy(self.mutation_pack),
            "browser_mutations": copy.deepcopy(self.mutation_pack.get("mutations", [])),
            "layout_shift_distribution": _browser_layout_shift_distribution(self.perturbations),
        }
        if last_action is not None:
            payload["last_action"] = last_action
        return payload

    def _snapshot_summary(self, snapshot: Mapping[str, Any]) -> Dict[str, Any]:
        return {
            "id": snapshot.get("id"),
            "url": snapshot.get("url"),
            "has_dom": bool(snapshot.get("dom")),
            "has_screenshot": bool(snapshot.get("screenshot_uri") or snapshot.get("screenshot_path")),
            "metadata": copy.deepcopy(snapshot.get("metadata", {})),
        }


def normalize_playwright_trace_export(
    trace_export: Any,
    *,
    source_label: Optional[str] = None,
) -> Dict[str, Any]:
    """Normalize Playwright trace JSON/JSONL/zip data into BrowserEnvironment fixtures."""

    return _normalize_playwright_trace_export(trace_export, source_label=source_label)


def load_playwright_trace_export(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    url: str = "https://example.test/",
    dom: str = "<html><body></body></html>",
    screenshot_uri: Optional[str] = None,
    allowed_domains: Optional[Iterable[str]] = None,
    state: Optional[Dict[str, Any]] = None,
    perturbations: Optional[Iterable[str | Mapping[str, Any]]] = None,
) -> BrowserEnvironment:
    """Load a Playwright trace export and return a browser replay environment."""

    if isinstance(source, (str, os.PathLike)):
        return BrowserEnvironment(
            url=url,
            dom=dom,
            screenshot_uri=screenshot_uri,
            allowed_domains=allowed_domains,
            state=state,
            playwright_trace_source=source,
            perturbations=perturbations,
        )
    return BrowserEnvironment(
        url=url,
        dom=dom,
        screenshot_uri=screenshot_uri,
        allowed_domains=allowed_domains,
        state=state,
        playwright_trace=source,
        perturbations=perturbations,
    )


