    normalized = _normalize_agent_trust_boundary_key(value)
    aliases = {
        "yes": "present",
        "true": "present",
        "enabled": "present",
        "implemented": "present",
        "available": "present",
        "pass": "present",
        "passed": "present",
        "success": "present",
        "limited": "partial",
        "degraded": "partial",
        "planned": "partial",
        "partial_mitigation": "partial",
        "no": "missing",
        "false": "missing",
        "absent": "missing",
        "unsupported": "missing",
        "fail": "missing",
        "failed": "missing",
        "denied": "blocked",
        "forbidden": "blocked",
        "policy_blocked": "blocked",
    }
    normalized = aliases.get(normalized, normalized)
    return normalized if normalized in {"present", "partial", "missing", "blocked"} else ""


