def normalize_red_team_readiness_manifest(
    payload: Any = None,
    *,
    name: str = "red-team-readiness",
    target: Optional[Mapping[str, Any]] = None,
    framework_import: Optional[Mapping[str, Any]] = None,
    red_team_campaign: Optional[Mapping[str, Any]] = None,
    workspace_run: Optional[Mapping[str, Any]] = None,
    trust_boundary: Optional[Mapping[str, Any]] = None,
    control_plane: Optional[Mapping[str, Any]] = None,
    observability: Optional[Mapping[str, Any]] = None,
    artifacts: Optional[Iterable[Any]] = None,
    required_evidence: Optional[Iterable[str]] = None,
    required_signals: Optional[Iterable[str]] = None,
    persona_conditioned_campaign: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Normalize red-team preflight evidence into one readiness gate."""

    payload_dict = dict(payload) if isinstance(payload, Mapping) else {}
    manifest_name = str(payload_dict.get("name") or name)
    target_record = _red_team_readiness_mapping(target if target is not None else payload_dict.get("target"))
    framework_import_record = _red_team_readiness_mapping(
        framework_import
        if framework_import is not None
        else payload_dict.get("framework_import", payload_dict.get("framework_import_manifest"))
    )
    campaign_record = _red_team_readiness_mapping(
        red_team_campaign
        if red_team_campaign is not None
        else payload_dict.get("red_team_campaign", payload_dict.get("campaign"))
    )
    workspace_record = _red_team_readiness_mapping(
        workspace_run if workspace_run is not None else payload_dict.get("workspace_run")
    )
    trust_record = _red_team_readiness_mapping(
        trust_boundary
        if trust_boundary is not None
        else payload_dict.get("trust_boundary", payload_dict.get("agent_trust_boundary"))
    )
    control_record = _red_team_readiness_mapping(
        control_plane
        if control_plane is not None
        else payload_dict.get("control_plane", payload_dict.get("agent_control_plane"))
    )
    observability_record = _red_team_readiness_mapping(
        observability if observability is not None else payload_dict.get("observability")
    )
    artifact_records = _normalize_red_team_readiness_artifacts(
        artifacts if artifacts is not None else payload_dict.get("artifacts")
    )
    required_evidence_keys = _red_team_readiness_key_list(
        required_evidence if required_evidence is not None else payload_dict.get("required_evidence")
    )
    required_signal_keys = _red_team_readiness_key_list(
        required_signals if required_signals is not None else payload_dict.get("required_signals")
    )
    persona_campaign_record = (
        dict(persona_conditioned_campaign)
        if isinstance(persona_conditioned_campaign, Mapping)
        else dict(payload_dict.get("persona_conditioned_campaign") or {})
        if isinstance(payload_dict.get("persona_conditioned_campaign"), Mapping)
        else {}
    )
    summary = _red_team_readiness_summary(
        target=target_record,
        framework_import=framework_import_record,
        red_team_campaign=campaign_record,
        workspace_run=workspace_record,
        trust_boundary=trust_record,
        control_plane=control_record,
        observability=observability_record,
        artifacts=artifact_records,
        required_evidence=required_evidence_keys,
        required_signals=required_signal_keys,
        persona_conditioned_campaign=persona_campaign_record,
    )
    signals = _red_team_readiness_signals(
        target=target_record,
        framework_import=framework_import_record,
        red_team_campaign=campaign_record,
        workspace_run=workspace_record,
        trust_boundary=trust_record,
        control_plane=control_record,
        observability=observability_record,
        artifacts=artifact_records,
        summary=summary,
    )
    merged_metadata = {
        **dict(payload_dict.get("metadata") or {}),
        **dict(metadata or {}),
    }
    result = {
        "kind": "red_team_readiness",
        "name": manifest_name,
        "target": target_record,
        "framework_import": framework_import_record,
        "red_team_campaign": campaign_record,
        "workspace_run": workspace_record,
        "trust_boundary": trust_record,
        "control_plane": control_record,
        "observability": observability_record,
        "artifacts": artifact_records,
        "required_evidence": required_evidence_keys,
        "required_signals": required_signal_keys,
        "summary": summary,
        "signals": signals,
        "metadata": copy.deepcopy(merged_metadata),
    }
    if persona_campaign_record:
        # Phase 7 (§9.7): the persona-conditioned campaign rides on the
        # readiness manifest and is surfaced as its own top-level run state key.
        result["persona_conditioned_campaign"] = copy.deepcopy(persona_campaign_record)
    return result


def load_red_team_readiness_manifest(
    source: str | os.PathLike[str] | Mapping[str, Any],
    *,
    headers: Optional[Mapping[str, str]] = None,
    auth: Optional[Mapping[str, Any]] = None,
    pagination: Optional[Mapping[str, Any]] = None,
    max_pages: int = 20,
    timeout: float = 30.0,
    metadata: Optional[Mapping[str, Any]] = None,
    **kwargs: Any,
) -> RedTeamReadinessEnvironment:
    """Load a local/HTTP red-team readiness manifest and return an environment."""

    source_metadata: Dict[str, Any] = {}
    if isinstance(source, (str, os.PathLike)) or _is_export_source_spec(source):
        loaded, source_metadata = _load_framework_trace_export_source_with_metadata(
            source,
            headers=headers,
            auth=auth,
            pagination=pagination,
            max_pages=max_pages,
            timeout=timeout,
        )
    else:
        loaded = source
    if not isinstance(loaded, Mapping):
        raise TypeError("Red-team readiness export must be a mapping")
    return RedTeamReadinessEnvironment(
        loaded,
        metadata={**source_metadata, **dict(metadata or {})},
        **kwargs,
    )


def normalize_workspace_run_manifest(
    payload: Any = None,
    *,
    name: str = "workspace-run-manifest",
    platform: str = "futureagi",
    repository: Optional[Mapping[str, Any]] = None,
    checkout: Optional[Mapping[str, Any]] = None,
    commands: Optional[Iterable[Any]] = None,
    logs: Optional[Iterable[Any]] = None,
    artifacts: Optional[Iterable[Any]] = None,
    simulations: Optional[Iterable[Any]] = None,
    evals: Optional[Iterable[Any] | Mapping[str, Any]] = None,
    optimization_runs: Optional[Iterable[Any]] = None,
    red_team_runs: Optional[Iterable[Any]] = None,
    observability: Optional[Mapping[str, Any]] = None,
    ui_verification: Optional[Mapping[str, Any]] = None,
    credentials: Optional[Iterable[Any]] = None,
    security: Optional[Mapping[str, Any]] = None,
    required_evidence: Optional[Iterable[str]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Normalize autonomous checkout/run/log/eval/optimization evidence."""

    payload_dict = dict(payload) if isinstance(payload, Mapping) else {}
    manifest_name = str(payload_dict.get("name") or name)
    manifest_platform = _normalize_workspace_run_key(payload_dict.get("platform") or platform)
    repository_record = _normalize_workspace_repository(
        repository if repository is not None else payload_dict.get("repository", payload_dict.get("repo"))
    )
    checkout_record = _normalize_workspace_checkout(
        checkout if checkout is not None else payload_dict.get("checkout"),
        repository=repository_record,
    )
    command_records = _normalize_workspace_commands(
        commands if commands is not None else payload_dict.get("commands")
    )
    log_records = _normalize_workspace_logs(
        logs if logs is not None else payload_dict.get("logs"),
        command_records=command_records,
    )
    artifact_records = _normalize_workspace_artifacts(
        artifacts if artifacts is not None else payload_dict.get("artifacts"),
        command_records=command_records,
        log_records=log_records,
    )
    simulation_records = _normalize_workspace_named_runs(
        simulations if simulations is not None else payload_dict.get("simulations"),
        default_kind="simulation",
    )
    eval_records = _normalize_workspace_named_runs(
        evals if evals is not None else payload_dict.get("evals", payload_dict.get("evaluation")),
        default_kind="eval",
    )
    optimization_records = _normalize_workspace_named_runs(
        optimization_runs
        if optimization_runs is not None
        else payload_dict.get("optimization_runs", payload_dict.get("optimizations")),
        default_kind="optimization",
    )
    red_team_records = _normalize_workspace_red_team_runs(
        red_team_runs
        if red_team_runs is not None
        else payload_dict.get("red_team_runs", payload_dict.get("adversarial_runs"))
    )
    observability_record = _normalize_workspace_mapping(
        observability if observability is not None else payload_dict.get("observability")
    )
    ui_record = _normalize_workspace_mapping(
        ui_verification
        if ui_verification is not None
        else payload_dict.get("ui_verification", payload_dict.get("ui"))
    )
    credential_records = _normalize_workspace_credentials(
        credentials if credentials is not None else payload_dict.get("credentials")
    )
    security_record = _normalize_workspace_security(
        security if security is not None else payload_dict.get("security"),
        log_records=log_records,
    )
    required_keys = [
        _normalize_workspace_run_key(item)
        for item in _as_iterable(required_evidence if required_evidence is not None else payload_dict.get("required_evidence"))
    ]
    required_keys = [item for item in required_keys if item]
    summary = _workspace_run_summary(
        platform=manifest_platform,
        repository=repository_record,
        checkout=checkout_record,
        commands=command_records,
        logs=log_records,
        artifacts=artifact_records,
        simulations=simulation_records,
        evals=eval_records,
        optimization_runs=optimization_records,
        red_team_runs=red_team_records,
        observability=observability_record,
        ui_verification=ui_record,
        credentials=credential_records,
        security=security_record,
        required_evidence=required_keys,
    )
    signals = _workspace_run_signals(
        platform=manifest_platform,
        repository=repository_record,
        checkout=checkout_record,
        commands=command_records,
        logs=log_records,
        artifacts=artifact_records,
        simulations=simulation_records,
        evals=eval_records,
        optimization_runs=optimization_records,
        red_team_runs=red_team_records,
        observability=observability_record,
        ui_verification=ui_record,
        credentials=credential_records,
        security=security_record,
        summary=summary,
    )
    merged_metadata = {
        **dict(payload_dict.get("metadata") or {}),
        **dict(metadata or {}),
    }
    return {
        "kind": "workspace_run_manifest",
        "name": manifest_name,
        "platform": manifest_platform,
        "repository": repository_record,
        "checkout": checkout_record,
        "commands": command_records,
        "logs": log_records,
        "artifacts": artifact_records,
        "simulations": simulation_records,
        "evals": eval_records,
        "optimization_runs": optimization_records,
        "red_team_runs": red_team_records,
        "observability": observability_record,
        "ui_verification": ui_record,
        "credentials": credential_records,
        "security": security_record,
        "required_evidence": sorted(set(required_keys)),
        "summary": summary,
        "signals": signals,
        "metadata": copy.deepcopy(merged_metadata),
    }


def load_workspace_run_manifest(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    name: str = "workspace-run-manifest",
    platform: str = "futureagi",
    required_evidence: Optional[Iterable[str]] = None,
    headers: Optional[Mapping[str, str]] = None,
    auth: Optional[Mapping[str, Any]] = None,
    pagination: Optional[Mapping[str, Any]] = None,
    max_pages: int = 20,
    timeout: float = 30.0,
    metadata: Optional[Mapping[str, Any]] = None,
) -> WorkspaceRunEnvironment:
    """Load a local/HTTP autonomous workspace run manifest and return an environment."""

    source_metadata: Dict[str, Any] = {}
    if isinstance(source, (str, os.PathLike)) or _is_export_source_spec(source):
        loaded, source_metadata = _load_framework_trace_export_source_with_metadata(
            source,
            headers=headers,
            auth=auth,
            pagination=pagination,
            max_pages=max_pages,
            timeout=timeout,
        )
    else:
        loaded = source
    return WorkspaceRunEnvironment(
        loaded,
        name=name,
        platform=platform,
        required_evidence=required_evidence,
        metadata={**source_metadata, **dict(metadata or {})},
    )


def _normalize_workspace_repository(value: Any) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        return {}
    if isinstance(value, str):
        item: Dict[str, Any] = {"url": value}
    elif isinstance(value, Mapping):
        item = copy.deepcopy(dict(value))
    else:
        item = {"name": str(value)}
    url = str(item.get("url") or item.get("clone_url") or item.get("html_url") or "")
    provider = _normalize_workspace_run_key(item.get("provider") or ("github" if "github.com" in url else ""))
    item.update(
        {
            "provider": provider,
            "url": url,
            "owner": str(item.get("owner") or item.get("org") or ""),
            "name": str(item.get("name") or item.get("repo") or ""),
            "default_branch": str(item.get("default_branch") or item.get("branch") or ""),
            "commit_sha": str(item.get("commit_sha") or item.get("sha") or ""),
        }
    )
    return item


def _normalize_workspace_checkout(value: Any, *, repository: Mapping[str, Any]) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        value = {}
    item = copy.deepcopy(dict(value)) if isinstance(value, Mapping) else {"ref": str(value)}
    item.setdefault("ref", item.get("branch") or repository.get("default_branch") or "")
    item.setdefault("commit_sha", item.get("sha") or repository.get("commit_sha") or "")
    item.setdefault("repository_url", repository.get("url") or "")
    item["status"] = _normalize_workspace_run_status(item.get("status") or item.get("conclusion"))
    if not item["status"] and (item.get("commit_sha") or item.get("ref")):
        item["status"] = "passed"
    return item


def _normalize_workspace_commands(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"command": str(raw)}
        command = str(item.get("command") or item.get("cmd") or item.get("name") or "")
        exit_code = _workspace_int(item.get("exit_code", item.get("returncode")))
        status = _normalize_workspace_run_status(item.get("status") or item.get("conclusion"))
        if not status and exit_code is not None:
            status = "passed" if exit_code == 0 else "failed"
        signals = _workspace_text_signals(
            " ".join(
                str(part)
                for part in [
                    item.get("id"),
                    item.get("name"),
                    command,
                    item.get("kind"),
                    item.get("category"),
                ]
                if part
            )
        )
        if item.get("log_ref") or item.get("stdout") or item.get("stderr") or item.get("logs"):
            signals.add("log")
        if item.get("artifacts"):
            signals.add("artifact")
        item.update(
            {
                "id": str(item.get("id") or item.get("name") or f"command_{index}"),
                "name": str(item.get("name") or item.get("id") or f"command_{index}"),
                "command": command,
                "status": status or "unknown",
                "exit_code": exit_code,
                "signals": sorted(signal for signal in signals if signal),
            }
        )
        records.append(item)
    return records


def _normalize_workspace_logs(
    value: Any,
    *,
    command_records: Sequence[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        if isinstance(raw, str):
            item = {"content": raw}
        elif isinstance(raw, Mapping):
            item = copy.deepcopy(dict(raw))
        else:
            item = {"content": str(raw)}
        content = str(item.get("content") or item.get("text") or item.get("excerpt") or "")
        contains_secret = _workspace_contains_secret(content)
        item.update(
            {
                "id": str(item.get("id") or item.get("name") or f"log_{index}"),
                "path": str(item.get("path") or item.get("uri") or ""),
                "redacted": bool(item.get("redacted", item.get("secrets_redacted", False))),
                "contains_secret": bool(item.get("contains_secret", contains_secret)),
                "signals": sorted({"log", *_workspace_text_signals(content), *_as_iterable(item.get("signals"))}),
            }
        )
        records.append(item)
    for command in command_records:
        if not (command.get("stdout") or command.get("stderr") or command.get("log_ref")):
            continue
        content = "\n".join(str(command.get(key) or "") for key in ("stdout", "stderr"))
        records.append(
            {
                "id": f"{command.get('id')}_log",
                "path": str(command.get("log_ref") or ""),
                "command_id": command.get("id"),
                "redacted": bool(command.get("logs_redacted", command.get("redacted", False))),
                "contains_secret": _workspace_contains_secret(content),
                "signals": sorted({"log", *set(command.get("signals", []))}),
            }
        )
    return records


def _normalize_workspace_artifacts(
    value: Any,
    *,
    command_records: Sequence[Mapping[str, Any]],
    log_records: Sequence[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"path": str(raw)}
        artifact_type = _normalize_workspace_run_key(item.get("type") or item.get("kind") or "")
        path = str(item.get("path") or item.get("uri") or item.get("url") or "")
        signals = {"artifact", artifact_type, *_workspace_text_signals(path), *_as_iterable(item.get("signals"))}
        item.update(
            {
                "id": str(item.get("id") or item.get("name") or f"artifact_{index}"),
                "type": artifact_type or "artifact",
                "path": path,
                "status": _normalize_workspace_run_status(item.get("status")) or "available",
                "signals": sorted(str(signal) for signal in signals if signal),
            }
        )
        records.append(item)
    for log in log_records:
        path = str(log.get("path") or "")
        if path:
            records.append(
                {
                    "id": f"{log.get('id')}_artifact",
                    "type": "log",
                    "path": path,
                    "status": "available",
                    "signals": sorted({"artifact", "log", *set(log.get("signals", []))}),
                }
            )
    for command in command_records:
        for artifact in _as_iterable(command.get("artifacts")):
            item = copy.deepcopy(dict(artifact)) if isinstance(artifact, Mapping) else {"path": str(artifact)}
            item.setdefault("id", f"{command.get('id')}_artifact_{len(records) + 1}")
            item.setdefault("type", "artifact")
            item.setdefault("status", "available")
            item["signals"] = sorted({"artifact", *set(command.get("signals", [])), *_as_iterable(item.get("signals"))})
            records.append(item)
    return records


def _normalize_workspace_named_runs(value: Any, *, default_kind: str) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    if isinstance(value, Mapping) and default_kind == "eval":
        runs = value.get("runs") if "runs" in value else [value]
    else:
        runs = value
    for index, raw in enumerate(_as_iterable(runs), start=1):
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"name": str(raw)}
        status = _normalize_workspace_run_status(item.get("status") or item.get("conclusion"))
        passed = bool(item.get("passed", item.get("success", status == "passed")))
        if not status:
            status = "passed" if passed else "failed"
        signals = {
            default_kind,
            *_workspace_text_signals(str(item.get("name") or item.get("id") or item.get("command") or "")),
            *_as_iterable(item.get("signals")),
        }
        item.update(
            {
                "id": str(item.get("id") or item.get("run_id") or f"{default_kind}_{index}"),
                "kind": _normalize_workspace_run_key(item.get("kind") or default_kind),
                "status": status,
                "passed": passed and status == "passed",
                "signals": sorted(str(signal) for signal in signals if signal),
            }
        )
        records.append(item)
    return records


def _normalize_workspace_red_team_runs(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"name": str(raw)}
        status = _normalize_workspace_run_status(item.get("status") or item.get("conclusion"))
        findings = [_normalize_workspace_red_team_finding(finding) for finding in _as_iterable(item.get("findings"))]
        open_high = [
            finding
            for finding in findings
            if finding.get("status") not in {"closed", "fixed", "accepted"}
            and finding.get("severity") in {"critical", "high"}
        ]
        passed = bool(item.get("passed", item.get("success", not open_high)))
        if not status:
            status = "passed" if passed else "failed"
        taxonomies = sorted(
            {
                _normalize_workspace_run_key(taxonomy)
                for taxonomy in [
                    *_as_iterable(item.get("taxonomies")),
                    *_as_iterable(item.get("taxonomy")),
                    *_as_iterable(item.get("frameworks")),
                ]
                if _normalize_workspace_run_key(taxonomy)
            }
        )
        attack_types = sorted(
            {
                _normalize_workspace_run_key(attack)
                for attack in [
                    *_as_iterable(item.get("attack_types")),
                    *_as_iterable(item.get("attacks")),
                    *_as_iterable(item.get("probes")),
                ]
                if _normalize_workspace_run_key(attack)
            }
        )
        signals = {
            "red_team",
            "adversarial",
            "security",
            *taxonomies,
            *attack_types,
            *_workspace_text_signals(str(item.get("name") or item.get("framework") or "")),
            *_as_iterable(item.get("signals")),
        }
        item.update(
            {
                "id": str(item.get("id") or item.get("run_id") or f"red_team_{index}"),
                "status": status,
                "passed": passed and status == "passed",
                "findings": findings,
                "taxonomies": taxonomies,
                "attack_types": attack_types,
                "open_high_finding_count": len(open_high),
                "signals": sorted(str(signal) for signal in signals if signal),
            }
        )
        records.append(item)
    return records


def _normalize_workspace_red_team_finding(value: Any) -> Dict[str, Any]:
    item = copy.deepcopy(dict(value)) if isinstance(value, Mapping) else {"description": str(value)}
    item["severity"] = _normalize_workspace_run_key(item.get("severity") or item.get("level") or "medium")
    item["status"] = _normalize_workspace_run_key(item.get("status") or item.get("state") or "open")
    item["taxonomy"] = _normalize_workspace_run_key(item.get("taxonomy") or item.get("category") or "")
    return item


def _normalize_workspace_mapping(value: Any) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        return {}
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    return {"items": copy.deepcopy(_as_iterable(value))}


def _normalize_workspace_credentials(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        if isinstance(raw, str):
            item = {"ref": raw}
        elif isinstance(raw, Mapping):
            item = copy.deepcopy(dict(raw))
        else:
            item = {"ref": str(raw)}
        item.update(
            {
                "id": str(item.get("id") or item.get("ref") or f"credential_{index}"),
                "provider": _normalize_workspace_run_key(item.get("provider") or item.get("service")),
                "ref": str(item.get("ref") or item.get("env") or item.get("name") or ""),
                "status": _normalize_workspace_run_status(item.get("status") or item.get("credential_status")) or (
                    "configured" if item.get("ref") or item.get("env") else "missing"
                ),
            }
        )
        records.append(item)
    return records


def _normalize_workspace_security(value: Any, *, log_records: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    item = _normalize_workspace_mapping(value)
    secret_logs = [log.get("id") for log in log_records if log.get("contains_secret")]
    if "secret_leak_count" not in item:
        item["secret_leak_count"] = len(secret_logs)
    if "logs_with_secrets" not in item:
        item["logs_with_secrets"] = [str(log_id) for log_id in secret_logs if log_id]
    if "secrets_redacted" not in item and log_records:
        item["secrets_redacted"] = all(log.get("redacted") or not log.get("contains_secret") for log in log_records)
    return item


def _workspace_run_summary(
    *,
    platform: str,
    repository: Mapping[str, Any],
    checkout: Mapping[str, Any],
    commands: Sequence[Mapping[str, Any]],
    logs: Sequence[Mapping[str, Any]],
    artifacts: Sequence[Mapping[str, Any]],
    simulations: Sequence[Mapping[str, Any]],
    evals: Sequence[Mapping[str, Any]],
    optimization_runs: Sequence[Mapping[str, Any]],
    red_team_runs: Sequence[Mapping[str, Any]],
    observability: Mapping[str, Any],
    ui_verification: Mapping[str, Any],
    credentials: Sequence[Mapping[str, Any]],
    security: Mapping[str, Any],
    required_evidence: Sequence[str],
) -> Dict[str, Any]:
    failed_commands = [str(item.get("id")) for item in commands if item.get("status") == "failed"]
    open_findings = [
        str(finding.get("id") or finding.get("description") or f"{run.get('id')}:finding")
        for run in red_team_runs
        for finding in _as_iterable(run.get("findings"))
        if isinstance(finding, Mapping)
        and finding.get("status") not in {"closed", "fixed", "accepted"}
        and finding.get("severity") in {"critical", "high"}
    ]
    signals = _workspace_run_signals(
        platform=platform,
        repository=repository,
        checkout=checkout,
        commands=commands,
        logs=logs,
        artifacts=artifacts,
        simulations=simulations,
        evals=evals,
        optimization_runs=optimization_runs,
        red_team_runs=red_team_runs,
        observability=observability,
        ui_verification=ui_verification,
        credentials=credentials,
        security=security,
        summary={},
    )
    missing_required = sorted(set(required_evidence) - set(signals))
    observability_hook_count = sum(
        len(_as_iterable(observability.get(key)))
        for key in ("traces", "logs", "metrics", "dashboards", "webhooks", "events")
    )
    if observability and not observability_hook_count:
        observability_hook_count = 1
    ui_verified = bool(
        ui_verification
        and (
            ui_verification.get("opened")
            or ui_verification.get("screenshot")
            or ui_verification.get("playwright_trace")
            or ui_verification.get("status") in {"passed", "verified", "success"}
        )
    )
    unverified_credentials = [
        str(item.get("id") or item.get("ref"))
        for item in credentials
        if item.get("status") not in {"verified", "live_verified", "passed"}
    ]
    return {
        "has_repository": bool(repository),
        "has_checkout": bool(checkout) and checkout.get("status") == "passed",
        "has_commit_sha": bool(checkout.get("commit_sha") or repository.get("commit_sha")),
        "has_futureagi_platform": platform == "futureagi",
        "command_count": len(commands),
        "passed_command_count": sum(1 for item in commands if item.get("status") == "passed"),
        "failed_command_count": len(failed_commands),
        "failed_commands": failed_commands,
        "log_count": len(logs),
        "artifact_count": len(artifacts),
        "simulation_count": len(simulations),
        "passed_simulation_count": sum(1 for item in simulations if item.get("passed")),
        "eval_count": len(evals),
        "passed_eval_count": sum(1 for item in evals if item.get("passed")),
        "optimization_count": len(optimization_runs),
        "passed_optimization_count": sum(1 for item in optimization_runs if item.get("passed")),
        "red_team_count": len(red_team_runs),
        "passed_red_team_count": sum(1 for item in red_team_runs if item.get("passed")),
        "open_red_team_findings": open_findings,
        "open_red_team_finding_count": len(open_findings),
        "observability_hook_count": observability_hook_count,
        "ui_verification_count": 1 if ui_verified else 0,
        "verified_credential_count": sum(1 for item in credentials if item.get("status") in {"verified", "live_verified", "passed"}),
        "unverified_credentials": unverified_credentials,
        "secret_leak_count": _workspace_int(security.get("secret_leak_count")) or 0,
        "logs_with_secrets": copy.deepcopy(_as_iterable(security.get("logs_with_secrets"))),
        "has_sandbox": bool(security.get("sandbox") or security.get("sandboxed")),
        "has_secret_redaction": bool(security.get("secrets_redacted")),
        "has_policy_gate": bool(security.get("policy_gates") or security.get("approval_gates")),
        "missing_required_evidence": missing_required,
    }


def _workspace_run_signals(
    *,
    platform: str,
    repository: Mapping[str, Any],
    checkout: Mapping[str, Any],
    commands: Sequence[Mapping[str, Any]],
    logs: Sequence[Mapping[str, Any]],
    artifacts: Sequence[Mapping[str, Any]],
    simulations: Sequence[Mapping[str, Any]],
    evals: Sequence[Mapping[str, Any]],
    optimization_runs: Sequence[Mapping[str, Any]],
    red_team_runs: Sequence[Mapping[str, Any]],
    observability: Mapping[str, Any],
    ui_verification: Mapping[str, Any],
    credentials: Sequence[Mapping[str, Any]],
    security: Mapping[str, Any],
    summary: Mapping[str, Any],
) -> List[str]:
    signals = {"workspace_run"}
    if platform:
        signals.update({"platform", platform})
    if platform == "futureagi":
        signals.add("futureagi_platform")
    if repository:
        signals.add("repository")
        if repository.get("provider"):
            signals.add(str(repository.get("provider")))
    if checkout:
        signals.add("checkout")
        if checkout.get("commit_sha"):
            signals.add("commit_sha")
    for collection, signal in [
        (commands, "command"),
        (logs, "log"),
        (artifacts, "artifact"),
        (simulations, "simulation"),
        (evals, "eval"),
        (optimization_runs, "optimization"),
        (red_team_runs, "red_team"),
    ]:
        if collection:
            signals.add(signal)
        for item in collection:
            signals.update(str(value) for value in _as_iterable(item.get("signals")) if value)
    if observability:
        signals.add("observability")
    if ui_verification:
        signals.add("ui_verification")
        signals.update(_workspace_text_signals(str(ui_verification)))
    if credentials:
        signals.add("credential")
        for item in credentials:
            if item.get("provider"):
                signals.add(str(item.get("provider")))
    if security:
        signals.add("security")
        if security.get("sandbox") or security.get("sandboxed"):
            signals.add("sandbox")
        if security.get("secrets_redacted"):
            signals.add("secret_redaction")
        if security.get("policy_gates") or security.get("approval_gates"):
            signals.add("policy_gate")
    if summary.get("secret_leak_count"):
        signals.add("secret_leak")
    return sorted(_normalize_workspace_run_key(signal) for signal in signals if _normalize_workspace_run_key(signal))


def _normalize_workspace_run_status(value: Any) -> str:
    normalized = _normalize_workspace_run_key(value)
    if normalized in {"", "ok", "complete", "completed", "success", "succeeded", "passed", "available", "verified"}:
        return "passed"
    if normalized in {"fail", "failed", "error", "errored", "timeout", "timed_out", "cancelled", "canceled"}:
        return "failed"
    if normalized in {"queued", "pending", "running", "in_progress", "configured", "missing", "unknown"}:
        return normalized
    return normalized


def _workspace_text_signals(text: str) -> set[str]:
    normalized = _normalize_workspace_run_key(text)
    signals: set[str] = set()
    keyword_map = {
        "pytest": "test",
        "test": "test",
        "simulation": "simulation",
        "simulate": "simulation",
        "eval": "eval",
        "evaluation": "eval",
        "optimize": "optimization",
        "optimization": "optimization",
        "agentoptimizer": "optimization",
        "red_team": "red_team",
        "redteam": "red_team",
        "adversarial": "red_team",
        "jailbreak": "red_team",
        "pentest": "red_team",
        "garak": "garak",
        "pyrit": "pyrit",
        "owasp": "owasp",
        "inspect": "inspect",
        "playwright": "ui_verification",
        "browser": "ui_verification",
        "screenshot": "ui_verification",
        "github": "github",
        "otel": "observability",
        "opentelemetry": "observability",
        "trace": "observability",
        "log": "log",
    }
    for keyword, signal in keyword_map.items():
        if keyword in normalized:
            signals.add(signal)
    return signals


def _workspace_contains_secret(text: str) -> bool:
    return any(re.search(pattern, text or "", flags=re.IGNORECASE) for pattern in WORKSPACE_SECRET_PATTERNS)


def _normalize_workspace_run_key(value: Any) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")


def _workspace_int(value: Any) -> Optional[int]:
    if value in (None, ""):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _normalize_agent_integration_agent_definition(value: Any) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        return {}
    if hasattr(value, "model_dump"):
        value = value.model_dump()
    elif hasattr(value, "dict"):
        value = value.dict()
    if not isinstance(value, Mapping):
        return {"name": str(value)}
    item = copy.deepcopy(dict(value))
    if item.get("system_prompt") and "instructions" not in item:
        item["instructions"] = item.get("system_prompt")
    if item.get("agent_type") and "type" not in item:
        item["type"] = item.get("agent_type")
    return item


def _normalize_agent_integration_personas(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, persona in enumerate(_as_iterable(value), start=1):
        if hasattr(persona, "model_dump"):
            persona = persona.model_dump()
        elif hasattr(persona, "dict"):
            persona = persona.dict()
        if isinstance(persona, Mapping):
            item = copy.deepcopy(dict(persona))
        else:
            item = {"name": str(persona)}
        item.setdefault("id", item.get("name") or f"persona_{index}")
        records.append(item)
    return records


def _normalize_agent_integration_providers(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        if isinstance(raw, str):
            item = {"provider": raw}
        elif isinstance(raw, Mapping):
            item = copy.deepcopy(dict(raw))
        else:
            item = {"provider": str(raw)}
        provider = _normalize_agent_integration_provider_name(
            item.get("provider") or item.get("name") or item.get("framework") or item.get("vendor")
        )
        if not provider:
            provider = f"provider_{index}"
        channels = {
            _normalize_agent_integration_channel(channel)
            for channel in [
                *_as_iterable(item.get("channels")),
                *_as_iterable(item.get("modalities")),
                *_as_iterable(item.get("capabilities")),
                *AGENT_INTEGRATION_PROVIDER_CAPABILITIES.get(provider, []),
            ]
            if _normalize_agent_integration_channel(channel)
        }
        trace_framework = _normalize_agent_integration_provider_name(
            item.get("trace_framework") or item.get("framework")
        )
        if provider in TRACEAI_SUPPORTED_AGENT_FRAMEWORKS and not trace_framework:
            trace_framework = provider
        credential_status = _normalize_agent_integration_key(
            item.get("credential_status")
            or item.get("credentials_status")
            or ("verified" if item.get("credential_verified") is True else "")
        )
        credential_ref = item.get("credential_ref") or item.get("credentials_ref") or item.get("env")
        if not credential_status:
            credential_status = "configured" if credential_ref else "missing"
        item.update(
            {
                "id": str(item.get("id") or provider),
                "provider": provider,
                "name": str(item.get("name") or provider),
                "channels": sorted(channels),
                "trace_framework": trace_framework,
                "credential_ref": credential_ref,
                "credential_status": credential_status,
                "integration_points": sorted(
                    {
                        _normalize_agent_integration_key(point)
                        for point in [
                            *_as_iterable(item.get("integration_points")),
                            *_as_iterable(item.get("integrations")),
                            *_as_iterable(item.get("webhooks")),
                            *_as_iterable(item.get("tools")),
                        ]
                        if _normalize_agent_integration_key(point)
                    }
                ),
            }
        )
        records.append(item)
    return records


def _normalize_agent_integration_sessions(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"transcript": str(raw)}
        provider = _normalize_agent_integration_provider_name(item.get("provider") or item.get("framework"))
        channel = _normalize_agent_integration_channel(item.get("channel") or item.get("modality") or item.get("call_type"))
        if not channel:
            capabilities = set(AGENT_INTEGRATION_PROVIDER_CAPABILITIES.get(provider, []))
            has_phone = item.get("phone_number") or item.get("call_id")
            has_sip = item.get("sip_trunk") or item.get("sip_call_id")
            if has_sip and "sip" in capabilities:
                channel = "sip"
            elif has_phone and "phone" in capabilities:
                channel = "phone"
        if not channel:
            channel = "chat" if item.get("messages") else "voice" if item.get("audio") or item.get("transcript") else "session"
        signals = {
            provider,
            channel,
            *[
                _normalize_agent_integration_key(signal)
                for signal in _as_iterable(item.get("signals"))
                if _normalize_agent_integration_key(signal)
            ],
        }
        if item.get("trace_id") or item.get("spans") or item.get("events"):
            signals.add("trace")
        if item.get("transcript") or item.get("transcript_object") or item.get("messages"):
            signals.add("transcript")
        if item.get("webrtc_stats") or item.get("rtc_stats"):
            signals.add("webrtc")
        if item.get("sip_trunk") or item.get("sip_call_id"):
            signals.add("sip")
        if item.get("phone_number") or item.get("call_id"):
            signals.add("phone")
        if item.get("observability"):
            signals.add("observability")
        if item.get("evals") or item.get("evaluation") or item.get("metrics"):
            signals.add("eval")
        item.update(
            {
                "id": str(item.get("id") or item.get("session_id") or item.get("call_id") or f"session_{index}"),
                "provider": provider,
                "channel": channel,
                "status": _normalize_agent_integration_status(item.get("status") or item.get("call_status")),
                "signals": sorted(signal for signal in signals if signal),
            }
        )
        records.append(item)
    return records


def _normalize_agent_integration_simulations(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"scenario": str(raw)}
        item.update(
            {
                "id": str(item.get("id") or item.get("run_id") or f"simulation_{index}"),
                "provider": _normalize_agent_integration_provider_name(item.get("provider") or item.get("framework")),
                "channel": _normalize_agent_integration_channel(item.get("channel") or item.get("modality")),
                "passed": bool(item.get("passed", item.get("success", True))),
            }
        )
        records.append(item)
    return records


def _normalize_agent_integration_observability(value: Any) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        return {}
    if isinstance(value, Mapping):
        item = copy.deepcopy(dict(value))
    else:
        item = {"events": copy.deepcopy(_as_iterable(value))}
    item.setdefault("platform", item.get("source") or "futureagi")
    return item


def _normalize_agent_integration_evals(value: Any) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        return {}
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    return {"runs": copy.deepcopy(_as_iterable(value))}


def _agent_integration_summary(
    *,
    agent_definition: Mapping[str, Any],
    personas: Sequence[Mapping[str, Any]],
    providers: Sequence[Mapping[str, Any]],
    sessions: Sequence[Mapping[str, Any]],
    simulations: Sequence[Mapping[str, Any]],
    observability: Mapping[str, Any],
    evals: Mapping[str, Any],
    required_providers: Sequence[str],
    required_channels: Sequence[str],
    required_trace_frameworks: Sequence[str],
) -> Dict[str, Any]:
    observed_providers = {
        _normalize_agent_integration_provider_name(item.get("provider"))
        for item in [*providers, *sessions, *simulations]
    }
    observed_channels = {
        _normalize_agent_integration_channel(channel)
        for provider in providers
        for channel in _as_iterable(provider.get("channels"))
    }
    observed_channels.update(
        _normalize_agent_integration_channel(item.get("channel"))
        for item in [*sessions, *simulations]
    )
    trace_frameworks = {
        _normalize_agent_integration_provider_name(item.get("trace_framework"))
        for item in providers
        if item.get("trace_framework")
    }
    trace_frameworks.update(
        _normalize_agent_integration_provider_name(item.get("framework") or item.get("trace_framework"))
        for item in sessions
        if item.get("framework") or item.get("trace_framework")
    )
    missing_providers = sorted(set(required_providers) - {item for item in observed_providers if item})
    missing_channels = sorted(set(required_channels) - {item for item in observed_channels if item})
    missing_trace_frameworks = sorted(set(required_trace_frameworks) - {item for item in trace_frameworks if item})
    providers_without_verified_credentials = sorted(
        item.get("provider")
        for item in providers
        if item.get("provider") and item.get("credential_status") not in {"verified", "live_verified"}
    )
    failed_sessions = [
        item.get("id")
        for item in sessions
        if item.get("status") in {"failed", "error", "timeout", "dial_failed", "cancelled"}
    ]
    eval_metrics = set(_agent_integration_dict(evals.get("metrics")).keys())
    for run in _as_iterable(evals.get("runs")):
        if isinstance(run, Mapping):
            eval_metrics.update(str(metric) for metric in _agent_integration_dict(run.get("metrics")).keys())
    observability_hook_count = sum(
        len(_as_iterable(observability.get(key)))
        for key in ("traces", "webhooks", "alerts", "incidents", "dashboards", "runs")
    )
    if observability and not observability_hook_count:
        observability_hook_count = 1
    return {
        "has_agent_definition": bool(agent_definition),
        "persona_count": len(personas),
        "provider_count": len(providers),
        "session_count": len(sessions),
        "simulation_count": len(simulations),
        "passed_simulation_count": sum(1 for item in simulations if item.get("passed")),
        "failed_session_count": len(failed_sessions),
        "observability_hook_count": observability_hook_count,
        "eval_metric_count": len(eval_metrics),
        "observed_providers": sorted(item for item in observed_providers if item),
        "observed_channels": sorted(item for item in observed_channels if item),
        "trace_frameworks": sorted(item for item in trace_frameworks if item),
        "missing_required_providers": missing_providers,
        "missing_required_channels": missing_channels,
        "missing_required_trace_frameworks": missing_trace_frameworks,
        "verified_provider_count": sum(
            1 for item in providers if item.get("credential_status") in {"verified", "live_verified"}
        ),
        "providers_without_verified_credentials": providers_without_verified_credentials,
        "failed_sessions": failed_sessions,
        "transcript_session_count": sum(1 for item in sessions if "transcript" in set(item.get("signals", []))),
        "trace_session_count": sum(1 for item in sessions if "trace" in set(item.get("signals", []))),
        "eval_metrics": sorted(eval_metrics),
    }


def _agent_integration_signals(
    *,
    platform: str,
    agent_definition: Mapping[str, Any],
    personas: Sequence[Mapping[str, Any]],
    providers: Sequence[Mapping[str, Any]],
    sessions: Sequence[Mapping[str, Any]],
    simulations: Sequence[Mapping[str, Any]],
    observability: Mapping[str, Any],
    evals: Mapping[str, Any],
    summary: Mapping[str, Any],
) -> List[str]:
    signals = {"agent_integration", "provider", "channel"}
    if platform:
        signals.add(platform)
        signals.add("platform")
    if platform == "futureagi":
        signals.add("futureagi_platform")
    if agent_definition:
        signals.add("agent_definition")
    if personas:
        signals.add("persona")
    if sessions:
        signals.add("session")
    if simulations:
        signals.add("simulation")
    if observability:
        signals.add("observability")
    if evals:
        signals.add("eval")
    if summary.get("verified_provider_count", 0):
        signals.add("credential")
    for provider in providers:
        signals.add(_normalize_agent_integration_provider_name(provider.get("provider")))
        if provider.get("trace_framework"):
            signals.add("traceai_framework")
            signals.add(_normalize_agent_integration_provider_name(provider.get("trace_framework")))
        for channel in _as_iterable(provider.get("channels")):
            signals.add(_normalize_agent_integration_channel(channel))
    for session in sessions:
        signals.update(str(signal) for signal in _as_iterable(session.get("signals")) if signal)
    return sorted(signal for signal in signals if signal)


def _normalize_agent_integration_status(value: Any) -> str:
    normalized = _normalize_agent_integration_key(value)
    if normalized in {"", "registered", "completed", "complete", "ended", "success", "succeeded", "passed"}:
        return "passed"
    if normalized in {"fail", "failed", "error", "timeout", "cancelled", "canceled", "dial_failed"}:
        return "failed"
    return normalized


def _normalize_agent_integration_channel(value: Any) -> str:
    normalized = _normalize_agent_integration_key(value)
    aliases = {
        "web_call": "webrtc",
        "web": "webrtc",
        "rtc": "webrtc",
        "pstn": "phone",
        "telephony": "phone",
        "media_streams": "media_stream",
        "media_streaming": "media_stream",
        "conversation": "chat",
        "text": "chat",
        "audio": "voice",
    }
    return aliases.get(normalized, normalized)


def _normalize_agent_integration_provider_name(value: Any) -> str:
    normalized = _normalize_agent_integration_key(value)
    aliases = {
        "llama_index": "llamaindex",
        "openai-agents": "openai_agents",
        "openai_agents_sdk": "openai_agents",
        "pydantic-ai": "pydantic_ai",
        "google-adk": "google_adk",
        "google-genai": "google_genai",
        "mongodb": "mongodb_vector",
        "redis": "redis_vector",
        "eleven_labs": "elevenlabs",
        "11labs": "elevenlabs",
        "retell_ai": "retell",
        "bland_ai": "bland",
        "vapi_ai": "vapi",
        "trace_ai": "traceai",
    }
    return aliases.get(normalized, normalized)


def _normalize_agent_integration_key(value: Any) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")


def _agent_integration_dict(value: Any) -> Dict[str, Any]:
    return copy.deepcopy(dict(value)) if isinstance(value, Mapping) else {}


def _normalize_framework_import_sources(
    value: Any,
    *,
    default_framework: str = "",
    default_export_type: str = "",
) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        if raw in (None, "", [], {}):
            continue
        if isinstance(raw, str):
            item = {"name": raw, "path": raw}
        elif isinstance(raw, Mapping):
            item = copy.deepcopy(dict(raw))
        else:
            item = {"name": str(raw)}
        framework = _normalize_framework_import_framework(
            item.get("framework")
            or item.get("runtime")
            or item.get("source_framework")
            or default_framework
        )
        export_type = _normalize_framework_import_export_type(
            item.get("export_type")
            or item.get("type")
            or item.get("kind")
            or item.get("category")
            or default_export_type
        )
        source_id = _normalize_framework_import_key(
            item.get("id")
            or item.get("name")
            or item.get("source")
            or item.get("path")
            or item.get("url")
            or f"{framework or 'framework'}_{export_type or 'source'}_{index}"
        )
        status = _normalize_framework_import_status(item.get("status") or item.get("conclusion"))
        if not status:
            status = "failed" if item.get("error") else "passed" if _framework_import_source_has_evidence(item) else "unknown"
        signals = {
            framework,
            export_type,
            *_framework_import_key_list(item.get("signals")),
            *_framework_import_text_signals(
                " ".join(
                    str(part)
                    for part in [
                        source_id,
                        item.get("name"),
                        item.get("path"),
                        item.get("url"),
                        item.get("description"),
                        framework,
                        export_type,
                    ]
                    if part
                )
            ),
        }
        if item.get("spans") or item.get("resourceSpans") or item.get("resource_spans"):
            signals.add("trace_export")
            signals.add("span")
        if item.get("events") or item.get("stream_events") or item.get("messages"):
            signals.add("event_stream")
        if item.get("observability") or item.get("trace_id") or item.get("span_id"):
            signals.add("observability")
        if item.get("artifact") or item.get("artifact_ref") or item.get("path") or item.get("url"):
            signals.add("artifact")
        item.update(
            {
                "id": source_id,
                "name": str(item.get("name") or source_id),
                "framework": framework,
                "export_type": export_type,
                "status": status,
                "passed": status in {"passed", "success", "completed", "available", "verified", "live_verified"},
                "record_count": _framework_import_int(
                    item.get("record_count")
                    or item.get("event_count")
                    or item.get("span_count")
                    or len(_as_iterable(item.get("records") or item.get("events") or item.get("spans")))
                ),
                "signals": sorted(signal for signal in (_normalize_framework_import_key(s) for s in signals) if signal),
            }
        )
        records.append(item)
    return records


def _dedupe_framework_import_sources(sources: Sequence[Mapping[str, Any]]) -> List[Dict[str, Any]]:
    deduped: List[Dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for source in sources:
        item = copy.deepcopy(dict(source))
        key = (
            str(item.get("id") or ""),
            str(item.get("framework") or ""),
            str(item.get("export_type") or ""),
        )
        if key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return deduped


def _normalize_framework_import_artifacts(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        if raw in (None, "", [], {}):
            continue
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"path": str(raw)}
        artifact_type = _normalize_framework_import_export_type(item.get("type") or item.get("kind") or "artifact")
        item.update(
            {
                "id": str(item.get("id") or item.get("name") or f"artifact_{index}"),
                "type": artifact_type,
                "signals": sorted(
                    {
                        "artifact",
                        artifact_type,
                        *_framework_import_key_list(item.get("signals")),
                        *_framework_import_text_signals(str(item.get("path") or item.get("url") or item.get("name") or "")),
                    }
                ),
            }
        )
        records.append(item)
    return records


def _framework_import_summary(
    *,
    framework: str,
    adapter: Mapping[str, Any],
    target: Mapping[str, Any],
    sources: Sequence[Mapping[str, Any]],
    observability: Mapping[str, Any],
    artifacts: Sequence[Mapping[str, Any]],
    required_sources: Sequence[str],
    required_frameworks: Sequence[str],
    required_export_types: Sequence[str],
    required_signals: Sequence[str],
) -> Dict[str, Any]:
    observed_frameworks = {_normalize_framework_import_framework(framework)}
    observed_frameworks.update(
        _normalize_framework_import_framework(source.get("framework"))
        for source in sources
        if source.get("framework")
    )
    observed_export_types = {
        _normalize_framework_import_export_type(source.get("export_type"))
        for source in sources
        if source.get("export_type")
    }
    observed_signals = {
        _normalize_framework_import_key(signal)
        for source in sources
        for signal in _as_iterable(source.get("signals"))
        if _normalize_framework_import_key(signal)
    }
    observed_signals.update(
        _normalize_framework_import_key(signal)
        for artifact in artifacts
        for signal in _as_iterable(artifact.get("signals"))
        if _normalize_framework_import_key(signal)
    )
    if target:
        observed_signals.add("target")
    if adapter:
        observed_signals.add("adapter")
    observability_hook_count = sum(
        len(_as_iterable(observability.get(key)))
        for key in ("traces", "logs", "metrics", "dashboards", "webhooks", "events", "runs")
    )
    if observability and not observability_hook_count:
        observability_hook_count = 1
    if observability_hook_count:
        observed_signals.add("observability")
    if artifacts:
        observed_signals.add("artifact")

    source_keys = {
        _normalize_framework_import_key(value)
        for source in sources
        for value in [
            source.get("id"),
            source.get("name"),
            source.get("framework"),
            source.get("export_type"),
            *_as_iterable(source.get("signals")),
        ]
        if _normalize_framework_import_key(value)
    }
    failed_sources = [
        str(source.get("id"))
        for source in sources
        if source.get("status") in {"failed", "error", "timeout", "cancelled", "canceled"}
    ]
    def has_export(*names: str) -> bool:
        return bool(observed_export_types.intersection(names))

    return {
        "has_target": bool(target),
        "has_adapter": bool(adapter),
        "source_count": len(sources),
        "passed_source_count": sum(1 for source in sources if source.get("passed")),
        "failed_source_count": len([item for item in failed_sources if item]),
        "failed_sources": [item for item in failed_sources if item],
        "artifact_count": len(artifacts),
        "observability_hook_count": observability_hook_count,
        "has_trace_export": has_export("trace_export", "otlp_trace", "framework_trace"),
        "has_event_stream": has_export("event_stream", "stream_events"),
        "has_lifecycle": has_export("lifecycle", "lifecycle_trace"),
        "has_capability_matrix": has_export("capability_matrix"),
        "has_probe_suite": has_export("probe_suite"),
        "has_portability_matrix": has_export("portability_matrix"),
        "has_observability": observability_hook_count > 0,
        "has_artifacts": bool(artifacts),
        "observed_frameworks": sorted(item for item in observed_frameworks if item),
        "observed_export_types": sorted(item for item in observed_export_types if item),
        "observed_signals": sorted(item for item in observed_signals if item),
        "source_keys": sorted(item for item in source_keys if item),
        "missing_required_sources": sorted(set(required_sources) - source_keys),
        "missing_required_frameworks": sorted(set(required_frameworks) - {item for item in observed_frameworks if item}),
        "missing_required_export_types": sorted(set(required_export_types) - {item for item in observed_export_types if item}),
        "missing_required_signals": sorted(set(required_signals) - {item for item in observed_signals if item}),
    }


def _framework_import_signals(
    *,
    framework: str,
    adapter: Mapping[str, Any],
    target: Mapping[str, Any],
    sources: Sequence[Mapping[str, Any]],
    observability: Mapping[str, Any],
    artifacts: Sequence[Mapping[str, Any]],
    summary: Mapping[str, Any],
) -> List[str]:
    signals = {"framework_import", "framework_import_manifest"}
    if framework:
        signals.update({"framework", framework})
    if adapter:
        signals.add("adapter")
    if target:
        signals.add("target")
    for source in sources:
        signals.add("source")
        signals.add(_normalize_framework_import_framework(source.get("framework")))
        signals.add(_normalize_framework_import_export_type(source.get("export_type")))
        signals.update(_normalize_framework_import_key(signal) for signal in _as_iterable(source.get("signals")) if _normalize_framework_import_key(signal))
    if observability:
        signals.add("observability")
    if artifacts:
        signals.add("artifact")
    for key in ("observed_frameworks", "observed_export_types", "observed_signals"):
        signals.update(str(item) for item in _as_iterable(summary.get(key)) if str(item))
    return sorted(_normalize_framework_import_key(signal) for signal in signals if _normalize_framework_import_key(signal))


def _framework_import_mapping(value: Any) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        return {}
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    return {"name": str(value)}


def _framework_import_source_has_evidence(item: Mapping[str, Any]) -> bool:
    return any(
        item.get(key) not in (None, "", [], {})
        for key in ("path", "url", "records", "events", "spans", "data", "artifact", "artifact_ref")
    )


def _normalize_framework_import_status(value: Any) -> str:
    normalized = _normalize_framework_import_key(value)
    if normalized in {"ok", "complete", "completed", "success", "succeeded", "passed", "available", "verified", "live_verified"}:
        return "passed"
    if normalized in {"fail", "failed", "error", "errored", "timeout", "timed_out", "cancelled", "canceled"}:
        return "failed"
    return normalized


def _normalize_framework_import_framework(value: Any) -> str:
    normalized = _normalize_framework_import_key(value)
    aliases = {
        "llama_index": "llamaindex",
        "openai_ag": "openai_agents",
        "openai_agent": "openai_agents",
        "openai_agents_sdk": "openai_agents",
        "openai_responses": "openai_agents",
        "openai": "openai_agents",
        "pydantic_ai": "pydantic_ai",
        "pydanticai": "pydantic_ai",
        "auto_gen": "autogen",
        "trace_ai": "traceai",
        "opentelemetry": "otel",
    }
    return aliases.get(normalized, normalized)


def _normalize_framework_import_export_type(value: Any) -> str:
    normalized = _normalize_framework_import_key(value)
    aliases = {
        "trace": "trace_export",
        "traces": "trace_export",
        "framework_trace": "trace_export",
        "span_export": "trace_export",
        "spans": "trace_export",
        "otlp": "trace_export",
        "otel": "trace_export",
        "event": "event_stream",
        "events": "event_stream",
        "stream": "event_stream",
        "stream_event": "event_stream",
        "stream_events": "event_stream",
        "capability": "capability_matrix",
        "capabilities": "capability_matrix",
        "capability_map": "capability_matrix",
        "probe": "probe_suite",
        "probes": "probe_suite",
        "probe_matrix": "probe_suite",
        "portability": "portability_matrix",
        "portability_map": "portability_matrix",
        "transcripts": "transcript",
    }
    return aliases.get(normalized, normalized)


def _framework_import_key_list(value: Any) -> List[str]:
    return sorted({_normalize_framework_import_key(item) for item in _as_iterable(value) if _normalize_framework_import_key(item)})


def _framework_import_text_signals(text: str) -> set[str]:
    normalized = _normalize_framework_import_key(text)
    keyword_map = {
        "langgraph": "langgraph",
        "langchain": "langchain",
        "autogen": "autogen",
        "crewai": "crewai",
        "openai": "openai_agents",
        "traceai": "traceai",
        "otel": "otel",
        "opentelemetry": "otel",
        "span": "trace_export",
        "trace": "trace_export",
        "event": "event_stream",
        "stream": "event_stream",
        "lifecycle": "lifecycle",
        "capability": "capability_matrix",
        "probe": "probe_suite",
        "portability": "portability_matrix",
        "transcript": "transcript",
        "model": "model",
        "tool": "tool",
        "state": "state",
        "checkpoint": "checkpoint",
        "handoff": "handoff",
        "memory": "memory",
        "security": "security",
        "observability": "observability",
        "latency": "latency",
        "cost": "cost",
    }
    return {signal for keyword, signal in keyword_map.items() if keyword in normalized}


def _normalize_framework_import_key(value: Any) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")


def _framework_import_int(value: Any) -> Optional[int]:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        try:
            return int(value.strip())
        except ValueError:
            return None
    return None


def _red_team_readiness_mapping(value: Any) -> Dict[str, Any]:
    if value in (None, "", [], {}):
        return {}
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    return {"name": str(value)}


def _normalize_red_team_readiness_artifacts(value: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    for index, raw in enumerate(_as_iterable(value), start=1):
        if raw in (None, "", [], {}):
            continue
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"path": str(raw)}
        artifact_type = _red_team_readiness_key(item.get("type") or item.get("kind") or "artifact")
        item.update(
            {
                "id": str(item.get("id") or item.get("name") or f"artifact_{index}"),
                "type": artifact_type,
                "signals": sorted(
                    {
                        "artifact",
                        artifact_type,
                        *_red_team_readiness_key_list(item.get("signals")),
                    }
                ),
            }
        )
        records.append(item)
    return records


def _red_team_readiness_persona_conditioning_ready(
    persona_conditioned_campaign: Optional[Mapping[str, Any]],
) -> bool:
    """Phase 7 (§9.7): a persona-conditioned campaign is ready when it carries
    at least one in-character attack (a per-attack fidelity verdict held)."""
    if not isinstance(persona_conditioned_campaign, Mapping) or not persona_conditioned_campaign:
        return False
    summary = persona_conditioned_campaign.get("summary")
    if not isinstance(summary, Mapping):
        return False
    in_character = _red_team_readiness_int(summary.get("persona_in_character_attack_count")) or 0
    conditioned = _red_team_readiness_int(summary.get("persona_conditioned_attack_count")) or 0
    return in_character >= 1 and conditioned >= 1


def _red_team_readiness_summary(
    *,
    target: Mapping[str, Any],
    framework_import: Mapping[str, Any],
    red_team_campaign: Mapping[str, Any],
    workspace_run: Mapping[str, Any],
    trust_boundary: Mapping[str, Any],
    control_plane: Mapping[str, Any],
    observability: Mapping[str, Any],
    artifacts: Sequence[Mapping[str, Any]],
    required_evidence: Sequence[str],
    required_signals: Sequence[str],
    persona_conditioned_campaign: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    component_ready = {
        "framework_import": _red_team_readiness_framework_import_ready(framework_import),
        "red_team_campaign": _red_team_readiness_campaign_ready(red_team_campaign),
        "workspace_run": _red_team_readiness_workspace_ready(workspace_run),
        "trust_boundary": _red_team_readiness_trust_boundary_ready(trust_boundary),
        "control_plane": _red_team_readiness_control_plane_ready(control_plane),
    }
    # Phase 7 (§9.7): persona_conditioning becomes a ready component ONLY when a
    # persona-conditioned campaign block is present AND at least one attack held
    # character (per-attack fidelity verdict pass). Absent block => unchanged
    # 5-component readiness summary (back-compat).
    if _red_team_readiness_persona_conditioning_ready(persona_conditioned_campaign):
        component_ready["persona_conditioning"] = True
    component_present = {
        "target": bool(target),
        "framework_import": bool(framework_import),
        "red_team_campaign": bool(red_team_campaign),
        "workspace_run": bool(workspace_run),
        "trust_boundary": bool(trust_boundary),
        "control_plane": bool(control_plane),
        "observability": bool(observability),
        "artifacts": bool(artifacts),
    }
    observed_signals = _red_team_readiness_observed_signals(
        target=target,
        framework_import=framework_import,
        red_team_campaign=red_team_campaign,
        workspace_run=workspace_run,
        trust_boundary=trust_boundary,
        control_plane=control_plane,
        observability=observability,
        artifacts=artifacts,
    )
    observed_evidence = {
        key
        for key, present in component_present.items()
        if present
    }
    observed_evidence.update(
        f"{key}_ready"
        for key, ready in component_ready.items()
        if ready
    )
    observed_evidence.update(observed_signals)
    artifact_count = len(artifacts) + sum(
        _red_team_readiness_int(_red_team_readiness_summary_of(child).get("artifact_count")) or 0
        for child in (framework_import, red_team_campaign, workspace_run)
    )
    observability_hook_count = _red_team_readiness_observability_hook_count(observability) + sum(
        _red_team_readiness_int(_red_team_readiness_summary_of(child).get("observability_hook_count")) or 0
        for child in (framework_import, red_team_campaign, workspace_run)
    )
    blocking_gaps: List[str] = []
    if not target:
        blocking_gaps.append("target_missing")
    for component, present in component_present.items():
        if component in {"target", "observability", "artifacts"}:
            continue
        if not present:
            blocking_gaps.append(f"{component}_missing")
    for component, ready in component_ready.items():
        if component_present.get(component) and not ready:
            blocking_gaps.append(f"{component}_not_ready")
    if not observability_hook_count:
        blocking_gaps.append("observability_missing")
    if not artifact_count:
        blocking_gaps.append("artifacts_missing")
    missing_required_evidence = sorted(set(required_evidence) - observed_evidence)
    missing_required_signals = sorted(set(required_signals) - observed_signals)
    blocking_gaps.extend(f"missing_evidence:{item}" for item in missing_required_evidence)
    blocking_gaps.extend(f"missing_signal:{item}" for item in missing_required_signals)
    ready_components = sorted(component for component, ready in component_ready.items() if ready)
    failed_components = sorted(component for component, ready in component_ready.items() if component_present.get(component) and not ready)
    return {
        "has_target": bool(target),
        "has_framework_import": bool(framework_import),
        "has_red_team_campaign": bool(red_team_campaign),
        "has_workspace_run": bool(workspace_run),
        "has_trust_boundary": bool(trust_boundary),
        "has_control_plane": bool(control_plane),
        "has_observability": observability_hook_count > 0,
        "has_artifacts": artifact_count > 0,
        "framework_import_ready": component_ready["framework_import"],
        "red_team_campaign_ready": component_ready["red_team_campaign"],
        "workspace_run_ready": component_ready["workspace_run"],
        "trust_boundary_ready": component_ready["trust_boundary"],
        "control_plane_ready": component_ready["control_plane"],
        "ready_component_count": len(ready_components),
        "ready_components": ready_components,
        "failed_components": failed_components,
        "artifact_count": artifact_count,
        "observability_hook_count": observability_hook_count,
        "blocking_gap_count": len(blocking_gaps),
        "blocking_gaps": sorted(set(blocking_gaps)),
        "observed_evidence": sorted(observed_evidence),
        "observed_signals": sorted(observed_signals),
        "missing_required_evidence": missing_required_evidence,
        "missing_required_signals": missing_required_signals,
    }


def _red_team_readiness_signals(
    *,
    target: Mapping[str, Any],
    framework_import: Mapping[str, Any],
    red_team_campaign: Mapping[str, Any],
    workspace_run: Mapping[str, Any],
    trust_boundary: Mapping[str, Any],
    control_plane: Mapping[str, Any],
    observability: Mapping[str, Any],
    artifacts: Sequence[Mapping[str, Any]],
    summary: Mapping[str, Any],
) -> List[str]:
    signals = _red_team_readiness_observed_signals(
        target=target,
        framework_import=framework_import,
        red_team_campaign=red_team_campaign,
        workspace_run=workspace_run,
        trust_boundary=trust_boundary,
        control_plane=control_plane,
        observability=observability,
        artifacts=artifacts,
    )
    signals.update(
        _red_team_readiness_key(item)
        for item in _as_iterable(summary.get("ready_components"))
        if _red_team_readiness_key(item)
    )
    signals.update(
        _red_team_readiness_key(item)
        for item in _as_iterable(summary.get("observed_evidence"))
        if _red_team_readiness_key(item)
    )
    return sorted(signal for signal in signals if signal)


def _red_team_readiness_observed_signals(
    *,
    target: Mapping[str, Any],
    framework_import: Mapping[str, Any],
    red_team_campaign: Mapping[str, Any],
    workspace_run: Mapping[str, Any],
    trust_boundary: Mapping[str, Any],
    control_plane: Mapping[str, Any],
    observability: Mapping[str, Any],
    artifacts: Sequence[Mapping[str, Any]],
) -> set[str]:
    signals = {"red_team_readiness", "readiness", "preflight", "gate"}
    if target:
        signals.add("target")
    for name, payload in [
        ("framework_import", framework_import),
        ("red_team_campaign", red_team_campaign),
        ("workspace_run", workspace_run),
        ("trust_boundary", trust_boundary),
        ("control_plane", control_plane),
    ]:
        if payload:
            signals.add(name)
            signals.update(_red_team_readiness_child_signals(payload))
    if observability:
        signals.add("observability")
    if artifacts:
        signals.add("artifact")
    for artifact in artifacts:
        signals.update(_red_team_readiness_key(item) for item in _as_iterable(artifact.get("signals")) if _red_team_readiness_key(item))
        signals.add(_red_team_readiness_key(artifact.get("type")))
    return {signal for signal in (_red_team_readiness_key(item) for item in signals) if signal}


def _red_team_readiness_child_signals(payload: Mapping[str, Any]) -> set[str]:
    summary = _red_team_readiness_summary_of(payload)
    signals = {
        _red_team_readiness_key(signal)
        for signal in _as_iterable(payload.get("signals"))
        if _red_team_readiness_key(signal)
    }
    for key in (
        "observed_frameworks",
        "observed_export_types",
        "observed_signals",
        "observed_taxonomies",
        "observed_attack_types",
        "observed_surfaces",
        "observed_channels",
        "observed_providers",
        "frameworks",
        "red_team_taxonomies",
        "controls",
        "present_controls",
        "present_categories",
    ):
        signals.update(_red_team_readiness_key(item) for item in _as_iterable(summary.get(key)) if _red_team_readiness_key(item))
    kind = _red_team_readiness_key(payload.get("kind"))
    if kind:
        signals.add(kind)
    return {signal for signal in signals if signal}


def _red_team_readiness_framework_import_ready(payload: Mapping[str, Any]) -> bool:
    summary = _red_team_readiness_summary_of(payload)
    if not summary:
        return False
    return all(
        bool(summary.get(key))
        for key in (
            "has_target",
            "has_adapter",
            "has_trace_export",
            "has_event_stream",
            "has_lifecycle",
            "has_capability_matrix",
            "has_probe_suite",
            "has_portability_matrix",
            "has_observability",
            "has_artifacts",
        )
    ) and not any(
        summary.get(key)
        for key in (
            "missing_required_sources",
            "missing_required_frameworks",
            "missing_required_export_types",
            "missing_required_signals",
            "failed_sources",
        )
    ) and (_red_team_readiness_int(summary.get("failed_source_count")) or 0) == 0


def _red_team_readiness_campaign_ready(payload: Mapping[str, Any]) -> bool:
    summary = _red_team_readiness_summary_of(payload)
    if not summary:
        return False
    return (
        bool(summary.get("has_target"))
        and (_red_team_readiness_int(summary.get("attack_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("scenario_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("run_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("passed_run_count")) or 0) >= (_red_team_readiness_int(summary.get("run_count")) or 0)
        and (_red_team_readiness_int(summary.get("multi_turn_scenario_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("artifact_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("mitigation_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("observability_hook_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("failed_run_count")) or 0) == 0
        and (_red_team_readiness_int(summary.get("open_high_finding_count")) or 0) == 0
        and not any(
            summary.get(key)
            for key in (
                "missing_required_taxonomies",
                "missing_required_attack_types",
                "missing_required_surfaces",
                "missing_required_channels",
                "missing_required_providers",
                "missing_coverage_cells",
                "missing_run_artifact_cells",
                "missing_mitigation_cells",
            )
        )
    )


def _red_team_readiness_workspace_ready(payload: Mapping[str, Any]) -> bool:
    summary = _red_team_readiness_summary_of(payload)
    if not summary:
        return False
    return (
        bool(summary.get("has_repository"))
        and bool(summary.get("has_checkout"))
        and bool(summary.get("has_commit_sha"))
        and (_red_team_readiness_int(summary.get("command_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("failed_command_count")) or 0) == 0
        and (_red_team_readiness_int(summary.get("log_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("artifact_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("eval_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("red_team_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("open_red_team_finding_count")) or 0) == 0
        and (_red_team_readiness_int(summary.get("secret_leak_count")) or 0) == 0
        and bool(summary.get("has_sandbox"))
        and bool(summary.get("has_secret_redaction"))
        and bool(summary.get("has_policy_gate"))
        and (_red_team_readiness_int(summary.get("observability_hook_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("ui_verification_count")) or 0) > 0
        and not summary.get("missing_required_evidence")
    )


def _red_team_readiness_trust_boundary_ready(payload: Mapping[str, Any]) -> bool:
    summary = _red_team_readiness_summary_of(payload)
    if not summary:
        return False
    return (
        (_red_team_readiness_int(summary.get("control_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("threat_count")) or 0) > 0
        and float(summary.get("required_control_rate", 0.0) or 0.0) >= 1.0
        and (_red_team_readiness_int(summary.get("high_risk_unmitigated_count")) or 0) == 0
        and bool(summary.get("has_identity"))
        and bool(summary.get("has_permissions"))
        and bool(summary.get("has_sandbox"))
        and bool(summary.get("has_audit"))
        and bool(summary.get("has_canaries"))
        and bool(summary.get("has_memory_isolation"))
        and bool(summary.get("has_network_egress_controls"))
        and bool(summary.get("has_tool_allowlist"))
        and bool(summary.get("has_data_boundary"))
        and bool(summary.get("has_secret_handling"))
    )


def _red_team_readiness_control_plane_ready(payload: Mapping[str, Any]) -> bool:
    summary = _red_team_readiness_summary_of(payload)
    if not summary:
        return False
    return (
        (_red_team_readiness_int(summary.get("control_count")) or 0) > 0
        and (_red_team_readiness_int(summary.get("action_count")) or 0) > 0
        and float(summary.get("required_control_rate", 0.0) or 0.0) >= 1.0
        and (_red_team_readiness_int(summary.get("exceeded_budget_count")) or 0) == 0
        and (_red_team_readiness_int(summary.get("missing_budget_count")) or 0) == 0
        and (_red_team_readiness_int(summary.get("uncontained_incident_count")) or 0) == 0
        and (_red_team_readiness_int(summary.get("high_risk_uncontained_count")) or 0) == 0
        and bool(summary.get("has_risk_scoring"))
        and bool(summary.get("has_action_policy"))
        and bool(summary.get("has_approval_gates"))
        and bool(summary.get("has_rollback"))
        and bool(summary.get("has_kill_switch"))
        and bool(summary.get("has_circuit_breakers"))
        and bool(summary.get("has_rate_limits"))
        and bool(summary.get("has_budgets"))
        and bool(summary.get("has_audit"))
        and bool(summary.get("has_containment"))
        and bool(summary.get("has_drift_detection"))
    )


def _red_team_readiness_summary_of(payload: Mapping[str, Any]) -> Dict[str, Any]:
    return copy.deepcopy(dict(payload.get("summary") or {})) if isinstance(payload, Mapping) else {}


def _red_team_readiness_observability_hook_count(observability: Mapping[str, Any]) -> int:
    count = sum(
        len(_as_iterable(observability.get(key)))
        for key in ("traces", "logs", "metrics", "dashboards", "webhooks", "events", "runs")
    )
    return count or (1 if observability else 0)


def _red_team_readiness_key_list(value: Any) -> List[str]:
    return sorted({_red_team_readiness_key(item) for item in _as_iterable(value) if _red_team_readiness_key(item)})


def _red_team_readiness_key(value: Any) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")


def _red_team_readiness_int(value: Any) -> Optional[int]:
    if isinstance(value, bool):
        return None
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        try:
            return int(value.strip())
        except ValueError:
            return None
    return None


def _observability_replay_records(payload: Any) -> List[Any]:
    if payload in (None, "", [], {}):
        return []
    if isinstance(payload, Mapping):
        for key in ("cases", "rows", "records", "runs", "data", "items"):
            value = payload.get(key)
            if isinstance(value, (list, tuple)):
                return list(value)
        return [payload]
    if isinstance(payload, (list, tuple)):
        return list(payload)
    return [payload]


def _normalize_observability_replay_case(
    raw_case: Any,
    *,
    index: int,
    source: str,
    framework: str,
    required_metrics: Mapping[str, float],
    required_trace_signals: Sequence[str],
) -> Dict[str, Any]:
    case = _coerce_plain_dict(raw_case)
    input_payload = _coerce_plain_dict(case.get("input"))
    expected = _coerce_plain_dict(case.get("expected") or case.get("expected_response"))
    observability = _coerce_plain_dict(
        case.get("observability")
        or input_payload.get("observability")
        or case.get("agent_observability_feedback")
    )
    if not observability:
        observability = copy.deepcopy(case)
    raw = _coerce_plain_dict(observability.get("raw"))
    metrics = _observability_replay_metrics(case, observability, raw)
    thresholds = {
        **dict(required_metrics),
        **{
            str(metric): float(threshold)
            for metric, threshold in _coerce_plain_dict(
                expected.get("required_metrics")
                or case.get("required_metrics")
                or observability.get("required_metrics")
            ).items()
        },
    }
    trace_signals = sorted(
        {
            _normalize_replay_signal(signal)
            for signal in [
                *_as_iterable(observability.get("trace_signals")),
                *_as_iterable(observability.get("signals")),
                *_as_iterable(case.get("trace_signals")),
            ]
            if _normalize_replay_signal(signal)
        }
    )
    expected_signals = sorted(
        {
            *required_trace_signals,
            *[
                _normalize_replay_signal(signal)
                for signal in _as_iterable(
                    expected.get("required_trace_signals")
                    or case.get("required_trace_signals")
                    or observability.get("required_trace_signals")
                )
                if _normalize_replay_signal(signal)
            ],
        }
    )
    missing_trace_signals = sorted(set(expected_signals) - set(trace_signals))
    failed_metrics = sorted(
        metric
        for metric, threshold in thresholds.items()
        if _observability_float(metrics.get(metric), default=-1.0) < threshold
    )
    failures = [
        str(item)
        for item in [
            *_as_iterable(observability.get("failures")),
            *_as_iterable(case.get("failures")),
            *[f"metric '{metric}' below {thresholds[metric]}" for metric in failed_metrics],
            *[f"missing trace signal '{signal}'" for signal in missing_trace_signals],
        ]
        if str(item)
    ]
    score = _observability_float(observability.get("score"))
    if score is None:
        score = min(metrics.values()) if metrics else (0.0 if failures else 1.0)
    passed_value = observability.get("passed")
    passed = bool(passed_value) if isinstance(passed_value, bool) else not failures
    case_id = str(
        case.get("id")
        or case.get("case_id")
        or observability.get("case_id")
        or observability.get("run_id")
        or case.get("run_id")
        or f"observability_case_{index}"
    )
    tags = sorted(
        {
            str(tag)
            for tag in [
                *_as_iterable(case.get("tags")),
                *_as_iterable(observability.get("tags")),
                *[f"metric:{metric}" for metric in failed_metrics],
                *[f"missing_signal:{signal}" for signal in missing_trace_signals],
            ]
            if str(tag)
        }
    )
    return {
        "id": case_id,
        "run_id": str(observability.get("run_id") or case.get("run_id") or case_id),
        "source": str(observability.get("source") or case.get("source") or source),
        "framework": str(observability.get("framework") or case.get("framework") or framework),
        "score": round(float(score), 4),
        "passed": bool(passed) and not failed_metrics and not missing_trace_signals,
        "metrics": metrics,
        "required_metrics": thresholds,
        "failed_metrics": failed_metrics,
        "trace_signals": trace_signals,
        "required_trace_signals": expected_signals,
        "missing_trace_signals": missing_trace_signals,
        "failures": list(dict.fromkeys(failures)),
        "tags": tags,
        "raw": copy.deepcopy(raw),
        "metadata": copy.deepcopy(_coerce_plain_dict(case.get("metadata"))),
    }


def _observability_replay_metrics(
    case: Mapping[str, Any],
    observability: Mapping[str, Any],
    raw: Mapping[str, Any],
) -> Dict[str, float]:
    metrics: Dict[str, float] = {}
    for source in (
        _coerce_plain_dict(observability.get("metrics")),
        _coerce_plain_dict(case.get("metrics")),
    ):
        for metric, value in source.items():
            score = _observability_float(value)
            if score is not None:
                metrics[str(metric)] = score
    for item in _as_iterable(observability.get("feedback") or case.get("feedback")):
        item_dict = _coerce_plain_dict(item)
        name = item_dict.get("key") or item_dict.get("name") or item_dict.get("metric")
        score = _observability_float(item_dict.get("score") or item_dict.get("value") or item_dict.get("output"))
        if name and score is not None:
            metrics[str(name)] = score
    evaluation = _coerce_plain_dict(
        raw.get("agent_report_evaluation")
        or raw.get("evaluation")
        or observability.get("agent_report_evaluation")
        or case.get("agent_report_evaluation")
    )
    summary_metrics = _coerce_plain_dict(_coerce_plain_dict(evaluation.get("summary")).get("metric_averages"))
    for metric, value in summary_metrics.items():
        score = _observability_float(value)
        if score is not None:
            metrics[str(metric)] = score
    return metrics


def _observability_replay_summary(
    cases: Sequence[Mapping[str, Any]],
    *,
    required_metrics: Mapping[str, float],
    required_trace_signals: Sequence[str],
) -> Dict[str, Any]:
    observed_metrics = sorted({metric for case in cases for metric in _coerce_plain_dict(case.get("metrics")).keys()})
    failed_metrics = sorted({metric for case in cases for metric in _as_iterable(case.get("failed_metrics"))})
    trace_signals = sorted({signal for case in cases for signal in _as_iterable(case.get("trace_signals"))})
    missing_trace_signals = sorted({signal for case in cases for signal in _as_iterable(case.get("missing_trace_signals"))})
    tags = sorted({tag for case in cases for tag in _as_iterable(case.get("tags"))})
    failed_case_count = sum(1 for case in cases if not case.get("passed"))
    return {
        "case_count": len(cases),
        "failed_case_count": failed_case_count,
        "passed_case_count": len(cases) - failed_case_count,
        "required_metrics": dict(required_metrics),
        "observed_metrics": observed_metrics,
        "failed_metrics": failed_metrics,
        "required_trace_signals": sorted(set(required_trace_signals)),
        "trace_signals": trace_signals,
        "missing_trace_signals": missing_trace_signals,
        "tags": tags,
    }


def _observability_float(value: Any, default: Optional[float] = None) -> Optional[float]:
    if isinstance(value, bool):
        return 1.0 if value else 0.0
    try:
        if value in (None, "", [], {}):
            return default
        return float(value)
    except (TypeError, ValueError):
        return default


def _normalize_replay_signal(value: Any) -> str:
    return str(value).strip().lower().replace("-", "_").replace(" ", "_")


def normalize_framework_trace_export(
    trace_export: Any,
    *,
    framework: str = "traceai",
) -> List[Dict[str, Any]]:
    """
    Normalize TraceAI/Future AGI/OpenTelemetry trace exports into framework spans.

    Supported shapes include OTLP JSON `resourceSpans`/`scopeSpans`, wrapped
    Future AGI-style payloads with `data`, `traces`, `records`, or `spans`, and
    JSONL sequences of span records.
    """

    records = _framework_trace_export_records(trace_export)
    return normalize_framework_trace_events(framework, records, category="span")


def load_framework_trace_export(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    framework: str = "traceai",
    headers: Optional[Mapping[str, str]] = None,
    auth: Optional[Mapping[str, Any]] = None,
    pagination: Optional[Mapping[str, Any]] = None,
    max_pages: int = 20,
    timeout: float = 30.0,
    state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> FrameworkTraceEnvironment:
    """Load a local/HTTP trace export and return a replay environment."""

    if isinstance(source, (str, os.PathLike)) or _is_export_source_spec(source):
        return FrameworkTraceEnvironment.from_export(
            framework=framework,
            source=source,
            headers=headers,
            auth=auth,
            pagination=pagination,
            max_pages=max_pages,
            timeout=timeout,
            state=state,
            metadata=metadata,
        )
    return FrameworkTraceEnvironment.from_export(
        framework=framework,
        export=source,
        state=state,
        metadata=metadata,
    )


def normalize_mcp_tool_session_export(
    session_export: Any,
    *,
    framework: str = "mcp",
    server_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Normalize MCP tools/list and tools/call session exports into framework spans.

    Accepted shapes include MCP JSON-RPC records, `{tools, calls}` fixture
    payloads, session wrappers, and Future AGI-style exported payloads. The
    returned spans retain tool schemas, call arguments, results, and errors so
    agent-report evaluators can score trace coverage, schema conformance, and
    tool outcomes without calling the MCP server again.
    """

    records = _mcp_tool_session_export_records(session_export, server_name=server_name)
    return normalize_framework_trace_events(framework, records, category="span")


def load_mcp_tool_session_export(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    framework: str = "mcp",
    server_name: Optional[str] = None,
    headers: Optional[Mapping[str, str]] = None,
    auth: Optional[Mapping[str, Any]] = None,
    pagination: Optional[Mapping[str, Any]] = None,
    max_pages: int = 20,
    timeout: float = 30.0,
    state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> FrameworkTraceEnvironment:
    """Load a local/HTTP MCP tool session export and return a replay environment."""

    source_metadata: Dict[str, Any] = {}
    if isinstance(source, (str, os.PathLike)) or _is_export_source_spec(source):
        loaded, source_metadata = _load_framework_trace_export_source_with_metadata(
            source,
            headers=headers,
            auth=auth,
            pagination=pagination,
            max_pages=max_pages,
            timeout=timeout,
        )
    else:
        loaded = source

    spans = normalize_mcp_tool_session_export(
        loaded,
        framework=framework,
        server_name=server_name,
    )
    combined_metadata = copy.deepcopy(dict(metadata or {}))
    combined_metadata.setdefault("mcp_tool_session", {}).update(
        _mcp_tool_session_metadata(spans, source_metadata)
    )
    if source_metadata:
        combined_metadata.setdefault("trace_export", {}).update(source_metadata)
    return FrameworkTraceEnvironment(
        framework=framework,
        spans=spans,
        state=state,
        metadata=combined_metadata,
    )


