class OrchestrationTraceEnvironment(EnvironmentAdapter):
    """
    Replay normalized workflow graph evidence from arbitrary agent frameworks.

    Framework traces preserve native spans and events. This adapter projects
    those records into a portable graph contract: nodes, edges, execution steps,
    retries, recovery, latency, cost, and final state.
    """

    name = "orchestration_trace"

    def __init__(
        self,
        *,
        framework: str,
        records: Optional[Iterable[str | Mapping[str, Any]]] = None,
        trace_export: Optional[Any] = None,
        export_source: Optional[str | os.PathLike[str]] = None,
        export_headers: Optional[Mapping[str, str]] = None,
        export_timeout: float = 30.0,
        nodes: Optional[Iterable[Mapping[str, Any]]] = None,
        edges: Optional[Iterable[Mapping[str, Any]]] = None,
        steps: Optional[Iterable[Mapping[str, Any]]] = None,
        state: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        self.framework = str(framework)
        export_records: List[Any] = []
        export_metadata: Dict[str, Any] = {}
        if export_source is not None:
            loaded_export = _load_framework_trace_export_source(
                export_source,
                headers=export_headers,
                timeout=export_timeout,
            )
            export_records.extend(_framework_trace_export_records(loaded_export))
            export_metadata["export_source"] = _framework_trace_source_label(export_source)
        if trace_export is not None:
            export_records.extend(_framework_trace_export_records(trace_export))

        trace = normalize_orchestration_trace_events(
            self.framework,
            [*(records or []), *export_records],
            nodes=nodes,
            edges=edges,
            steps=steps,
            state=state,
            metadata=metadata,
        )
        if export_metadata:
            trace.setdefault("metadata", {}).setdefault("trace_export", {}).update(export_metadata)
        self.initial_trace = trace
        self.trace: Dict[str, Any] = {}

    @classmethod
    def from_export(
        cls,
        *,
        framework: str = "traceai",
        export: Optional[Any] = None,
        source: Optional[str | os.PathLike[str]] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: float = 30.0,
        state: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> "OrchestrationTraceEnvironment":
        return cls(
            framework=framework,
            trace_export=export,
            export_source=source,
            export_headers=headers,
            export_timeout=timeout,
            state=state,
            metadata=metadata,
        )

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.trace = copy.deepcopy(self.initial_trace)
        events = [
            SimulationEvent(
                type="orchestration_trace",
                name="orchestration_trace_ready",
                payload={
                    "framework": self.framework,
                    "node_count": len(self.trace.get("nodes", [])),
                    "edge_count": len(self.trace.get("edges", [])),
                    "step_count": len(self.trace.get("steps", [])),
                    "signals": copy.deepcopy(self.trace.get("signals", [])),
                    "summary": copy.deepcopy(self.trace.get("summary", {})),
                },
            )
        ]
        events.extend(_orchestration_step_event(step, self.framework) for step in self.trace.get("steps", []))
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            artifacts=[self._trace_artifact()],
            events=events,
            state={"orchestration_trace": self._state_payload()},
            metadata={
                "orchestration_trace": {
                    "framework": self.framework,
                    "node_count": len(self.trace.get("nodes", [])),
                    "edge_count": len(self.trace.get("edges", [])),
                    "step_count": len(self.trace.get("steps", [])),
                    "signals": copy.deepcopy(self.trace.get("signals", [])),
                    "summary": copy.deepcopy(self.trace.get("summary", {})),
                }
            },
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if name not in {
            "orchestration_trace_status",
            "list_orchestration_steps",
            "inspect_orchestration_node",
            "inspect_orchestration_edge",
        }:
            return None
        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)

        if name == "orchestration_trace_status":
            result = self._trace_payload()
            event_name = "orchestration_trace_status"
            content = f"{self.framework} orchestration trace status recorded."
            success = True
            error = None
        elif name == "list_orchestration_steps":
            signal = _normalize_orchestration_trace_key(arguments.get("signal") or arguments.get("kind") or "")
            node = _normalize_orchestration_name(arguments.get("node") or arguments.get("name") or "")
            steps = [copy.deepcopy(dict(step)) for step in self.trace.get("steps", [])]
            if signal:
                steps = [step for step in steps if signal in set(step.get("signals", []))]
            if node:
                steps = [
                    step
                    for step in steps
                    if _normalize_orchestration_name(step.get("node") or step.get("name")) == node
                ]
            result = {"framework": self.framework, "steps": steps, "query": {"signal": signal, "node": node}}
            event_name = "orchestration_steps_listed"
            content = f"Listed {len(steps)} orchestration step(s)."
            success = True
            error = None
        elif name == "inspect_orchestration_node":
            node_id = str(arguments.get("id") or arguments.get("node") or arguments.get("name") or "")
            node_record = _find_orchestration_record(self.trace.get("nodes", []), node_id)
            success = node_record is not None
            result = {"framework": self.framework, "node": copy.deepcopy(node_record), "query": node_id}
            event_name = "orchestration_node_inspected" if success else "orchestration_node_missing"
            content = f"Inspected orchestration node {node_id}." if success else f"Orchestration node not found: {node_id}"
            error = None if success else "node_not_found"
        else:
            edge_id = str(arguments.get("id") or arguments.get("edge") or "")
            from_node = arguments.get("from") or arguments.get("source")
            to_node = arguments.get("to") or arguments.get("target")
            edge_record = _find_orchestration_edge(
                self.trace.get("edges", []),
                edge_id=edge_id,
                from_node=from_node,
                to_node=to_node,
            )
            success = edge_record is not None
            result = {
                "framework": self.framework,
                "edge": copy.deepcopy(edge_record),
                "query": {"id": edge_id, "from": from_node, "to": to_node},
            }
            event_name = "orchestration_edge_inspected" if success else "orchestration_edge_missing"
            content = "Inspected orchestration edge." if success else "Orchestration edge not found."
            error = None if success else "edge_not_found"

        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=name,
            content=content,
            result=result,
            success=success,
            error=error,
            state_updates={"orchestration_trace": self._state_payload()},
            artifacts=[self._trace_artifact()],
            events=[
                SimulationEvent(
                    type="orchestration_trace",
                    name=event_name,
                    payload=result,
                    metadata={"framework": self.framework},
                )
            ],
        )

    def _tool_specs(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": "orchestration_trace_status",
                "description": "Return normalized workflow graph trace state, nodes, edges, steps, signals, and summary.",
                "parameters": {"type": "object", "properties": {}},
            },
            {
                "name": "list_orchestration_steps",
                "description": "List workflow execution steps, optionally filtered by signal or node.",
                "parameters": {
                    "type": "object",
                    "properties": {"signal": {"type": "string"}, "node": {"type": "string"}},
                },
            },
            {
                "name": "inspect_orchestration_node",
                "description": "Inspect one workflow node by id or name.",
                "parameters": {"type": "object", "properties": {"id": {"type": "string"}}},
            },
            {
                "name": "inspect_orchestration_edge",
                "description": "Inspect one workflow route/edge by id or from/to node pair.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "id": {"type": "string"},
                        "from": {"type": "string"},
                        "to": {"type": "string"},
                    },
                },
            },
        ]

    def _trace_artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            role="environment",
            data=self._trace_payload(),
            metadata={"kind": "orchestration_trace", "framework": self.framework},
        )

    def _trace_payload(self) -> Dict[str, Any]:
        return copy.deepcopy(self.trace)

    def _state_payload(self) -> Dict[str, Any]:
        return self._trace_payload()


def normalize_orchestration_trace_events(
    framework: str,
    records: Iterable[Any],
    *,
    nodes: Optional[Iterable[Mapping[str, Any]]] = None,
    edges: Optional[Iterable[Mapping[str, Any]]] = None,
    steps: Optional[Iterable[Mapping[str, Any]]] = None,
    state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Normalize native workflow/runtime records into a portable graph trace."""

    normalized_steps = [
        _normalize_orchestration_step(record, framework=str(framework), index=index)
        for index, record in enumerate(records or [])
    ]
    normalized_steps.extend(
        _normalize_orchestration_step(step, framework=str(framework), index=len(normalized_steps) + index)
        for index, step in enumerate(steps or [])
    )
    normalized_nodes = [
        _normalize_orchestration_node(node, framework=str(framework))
        for node in nodes or []
    ]
    normalized_edges = [
        _normalize_orchestration_edge(edge, framework=str(framework))
        for edge in edges or []
    ]
    projected_nodes, projected_edges = _orchestration_graph_from_steps(normalized_steps, framework=str(framework))
    normalized_nodes = _dedupe_orchestration_records([*normalized_nodes, *projected_nodes])
    normalized_edges = _dedupe_orchestration_records([*normalized_edges, *projected_edges])
    signals = _orchestration_trace_signals(normalized_nodes, normalized_edges, normalized_steps, state)
    summary = _orchestration_trace_summary(normalized_steps, normalized_edges)
    return {
        "kind": "orchestration_trace",
        "framework": str(framework),
        "nodes": normalized_nodes,
        "edges": normalized_edges,
        "steps": normalized_steps,
        "signals": sorted(signals),
        "summary": summary,
        "state": copy.deepcopy(dict(state or {})),
        "metadata": copy.deepcopy(dict(metadata or {})),
    }


def normalize_orchestration_trace_export(
    trace_export: Any,
    *,
    framework: str = "traceai",
    state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Normalize TraceAI/OpenTelemetry/framework exports into an orchestration graph trace."""

    records = _framework_trace_export_records(trace_export)
    return normalize_orchestration_trace_events(
        framework,
        records,
        state=state,
        metadata=metadata,
    )


def load_orchestration_trace_export(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    framework: str = "traceai",
    headers: Optional[Mapping[str, str]] = None,
    timeout: float = 30.0,
    state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> OrchestrationTraceEnvironment:
    """Load local/HTTP/inline workflow trace evidence into a graph replay environment."""

    if isinstance(source, (str, os.PathLike)):
        return OrchestrationTraceEnvironment.from_export(
            framework=framework,
            source=source,
            headers=headers,
            timeout=timeout,
            state=state,
            metadata=metadata,
        )
    return OrchestrationTraceEnvironment.from_export(
        framework=framework,
        export=source,
        state=state,
        metadata=metadata,
    )


class StreamingTraceEnvironment(EnvironmentAdapter):
    """
    Replay framework-neutral streaming/session events as simulation evidence.

    Use this for LangChain/LangGraph stream chunks, OpenAI Agents streaming
    events, LiveKit AgentSession events, Pipecat frames, OpenTelemetry GenAI
    streaming attributes, or custom runtimes that emit incremental output.
    """

    name = "streaming_trace"

    def __init__(
        self,
        *,
        framework: str,
        events: Optional[Iterable[str | Mapping[str, Any]]] = None,
        trace_export: Optional[Any] = None,
        export_source: Optional[str | os.PathLike[str]] = None,
        export_headers: Optional[Mapping[str, str]] = None,
        export_timeout: float = 30.0,
        state: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> None:
        self.framework = str(framework)
        export_events: List[Dict[str, Any]] = []
        export_metadata: Dict[str, Any] = {}
        if export_source is not None:
            loaded_export = _load_framework_trace_export_source(
                export_source,
                headers=export_headers,
                timeout=export_timeout,
            )
            export_trace = normalize_streaming_trace_export(loaded_export, framework=self.framework)
            export_events.extend(_as_iterable(export_trace.get("events")))
            export_metadata["export_source"] = _framework_trace_source_label(export_source)
        if trace_export is not None:
            export_trace = normalize_streaming_trace_export(trace_export, framework=self.framework)
            export_events.extend(_as_iterable(export_trace.get("events")))
        inline_trace = normalize_streaming_trace_events(
            self.framework,
            events or [],
        )
        self.initial_events = export_events + _as_iterable(inline_trace.get("events"))
        self.initial_state = copy.deepcopy(dict(state or {}))
        self.metadata = copy.deepcopy(dict(metadata or {}))
        if export_metadata:
            self.metadata.setdefault("streaming_export", {}).update(export_metadata)
        self.events: List[Dict[str, Any]] = []
        self.state = copy.deepcopy(self.initial_state)

    @classmethod
    def from_export(
        cls,
        *,
        framework: str = "streaming",
        export: Optional[Any] = None,
        source: Optional[str | os.PathLike[str]] = None,
        headers: Optional[Mapping[str, str]] = None,
        timeout: float = 30.0,
        state: Optional[Mapping[str, Any]] = None,
        metadata: Optional[Mapping[str, Any]] = None,
    ) -> "StreamingTraceEnvironment":
        return cls(
            framework=framework,
            trace_export=export,
            export_source=source,
            export_headers=headers,
            export_timeout=timeout,
            state=state,
            metadata=metadata,
        )

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.events = copy.deepcopy(self.initial_events)
        self.state = copy.deepcopy(self.initial_state)
        trace_events = [
            SimulationEvent(
                type="streaming_trace_event",
                name=str(event.get("type") or "stream_event"),
                payload=copy.deepcopy(event),
            )
            for event in self.events
        ]
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            artifacts=[self._trace_artifact()],
            events=[
                SimulationEvent(
                    type="streaming_trace",
                    name="streaming_trace_ready",
                    payload={
                        "framework": self.framework,
                        "event_count": len(self.events),
                        "signals": sorted(self._observed_signals()),
                        "summary": _streaming_trace_summary(self.events),
                    },
                ),
                *trace_events,
            ],
            state={"streaming_trace": self._state_payload()},
            metadata={
                "streaming_trace": {
                    "framework": self.framework,
                    "event_count": len(self.events),
                    "signals": sorted(self._observed_signals()),
                    "summary": _streaming_trace_summary(self.events),
                }
            },
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        if name not in {"streaming_trace_status", "list_stream_events", "inspect_stream_event"}:
            return None
        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)

        if name == "streaming_trace_status":
            result = self._trace_payload()
            event_name = "streaming_trace_status"
            content = f"{self.framework} streaming trace status recorded."
        elif name == "list_stream_events":
            signal = _normalize_streaming_trace_key(arguments.get("signal") or arguments.get("kind") or "")
            event_type = _normalize_streaming_trace_key(arguments.get("type") or "")
            source = str(arguments.get("source") or "").strip().lower()
            role = str(arguments.get("role") or "").strip().lower()
            events = [*self.events]
            if signal:
                events = [event for event in events if signal in set(event.get("signals", []))]
            if event_type:
                events = [
                    event
                    for event in events
                    if event_type == _normalize_streaming_trace_key(event.get("type"))
                ]
            if source:
                events = [
                    event
                    for event in events
                    if source in str(event.get("source") or "").lower()
                ]
            if role:
                events = [
                    event
                    for event in events
                    if role == str(event.get("role") or "").lower()
                ]
            result = {"framework": self.framework, "events": copy.deepcopy(events)}
            event_name = "streaming_events_listed"
            content = f"Listed {len(events)} {self.framework} streaming event(s)."
        else:
            event_id = str(
                arguments.get("id")
                or arguments.get("event_id")
                or arguments.get("sequence")
                or arguments.get("type")
                or ""
            )
            event = _find_streaming_event(self.events, event_id)
            success = event is not None
            result = {"framework": self.framework, "event": copy.deepcopy(event), "query": event_id}
            event_name = "streaming_event_inspected" if success else "streaming_event_missing"
            content = f"Inspected streaming event {event_id}." if success else f"Streaming event not found: {event_id}"
            return ToolExecutionResult(
                tool_call_id=call_id,
                tool_name=name,
                content=content,
                result=result,
                success=success,
                error=None if success else "event_not_found",
                state_updates={"streaming_trace": self._state_payload()},
                artifacts=[self._trace_artifact()],
                events=[
                    SimulationEvent(
                        type="streaming_trace",
                        name=event_name,
                        payload=result,
                    )
                ],
            )

        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=name,
            content=content,
            result=result,
            state_updates={"streaming_trace": self._state_payload()},
            artifacts=[self._trace_artifact()],
            events=[
                SimulationEvent(
                    type="streaming_trace",
                    name=event_name,
                    payload=result,
                )
            ],
        )

    def _tool_specs(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": "streaming_trace_status",
                "description": "Return normalized streaming trace events, summary, and observed signals.",
                "parameters": {"type": "object", "properties": {}},
            },
            {
                "name": "list_stream_events",
                "description": "List normalized streaming events, optionally filtered by signal, type, source, or role.",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "signal": {"type": "string"},
                        "type": {"type": "string"},
                        "source": {"type": "string"},
                        "role": {"type": "string"},
                    },
                },
            },
            {
                "name": "inspect_stream_event",
                "description": "Inspect one streaming event by id, event_id, sequence, or type.",
                "parameters": {"type": "object", "properties": {"id": {"type": "string"}}},
            },
        ]

    def _trace_artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            role="environment",
            data=self._trace_payload(),
            metadata={"kind": "streaming_trace", "framework": self.framework},
        )

    def _trace_payload(self) -> Dict[str, Any]:
        trace = normalize_streaming_trace_events(
            self.framework,
            self.events,
            state=self.state,
            metadata=self.metadata,
        )
        trace["metadata"] = copy.deepcopy(self.metadata)
        return trace

    def _state_payload(self) -> Dict[str, Any]:
        return self._trace_payload()

    def _observed_signals(self) -> set[str]:
        signals: set[str] = set()
        for event in self.events:
            signals.update(event.get("signals", []))
        return signals


def normalize_streaming_trace_events(
    framework: str,
    records: Iterable[Any],
    *,
    state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """
    Normalize incremental streaming/session records into one replayable trace.

    Supported inputs include token chunks, tool-call deltas, LiveKit session
    events, Pipecat frames, OpenAI Agents stream events, LangChain/LangGraph
    stream modes, OpenTelemetry span/event dictionaries, and custom records.
    """

    normalized_events = [
        _normalize_streaming_event(record, framework=str(framework), sequence=index + 1)
        for index, record in enumerate(records)
    ]
    signals = _streaming_trace_signals(normalized_events)
    summary = _streaming_trace_summary(normalized_events)
    return {
        "kind": "streaming_trace",
        "framework": str(framework),
        "events": normalized_events,
        "chunks": [
            copy.deepcopy(event)
            for event in normalized_events
            if "chunk" in set(event.get("signals", []))
        ],
        "tool_deltas": [
            copy.deepcopy(event)
            for event in normalized_events
            if "tool_delta" in set(event.get("signals", []))
        ],
        "interruptions": [
            copy.deepcopy(event)
            for event in normalized_events
            if "interruption" in set(event.get("signals", []))
        ],
        "signals": sorted(signals),
        "summary": summary,
        "state": copy.deepcopy(dict(state or {})),
        "metadata": copy.deepcopy(dict(metadata or {})),
    }


def normalize_streaming_trace_export(
    trace_export: Any,
    *,
    framework: str = "streaming",
) -> Dict[str, Any]:
    """Normalize a wrapped JSON/JSONL streaming export into a streaming trace."""

    export_dict = _coerce_plain_dict(trace_export)
    export_framework = str(export_dict.get("framework") or export_dict.get("provider") or framework)
    state = _coerce_plain_dict(export_dict.get("state"))
    metadata = _coerce_plain_dict(export_dict.get("metadata"))
    if not metadata and export_dict:
        metadata = {
            key: copy.deepcopy(value)
            for key, value in export_dict.items()
            if key not in {"events", "stream_events", "records", "items", "chunks", "frames", "data", "state"}
            and value not in (None, "", [], {})
        }
    return normalize_streaming_trace_events(
        export_framework,
        _streaming_trace_export_records(trace_export),
        state=state,
        metadata=metadata,
    )


def load_streaming_trace_export(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    framework: str = "streaming",
    headers: Optional[Mapping[str, str]] = None,
    timeout: float = 30.0,
    state: Optional[Mapping[str, Any]] = None,
    metadata: Optional[Mapping[str, Any]] = None,
) -> StreamingTraceEnvironment:
    """Load a local/HTTP streaming export and return a replay environment."""

    if isinstance(source, (str, os.PathLike)):
        return StreamingTraceEnvironment.from_export(
            framework=framework,
            source=source,
            headers=headers,
            timeout=timeout,
            state=state,
            metadata=metadata,
        )
    return StreamingTraceEnvironment.from_export(
        framework=framework,
        export=source,
        state=state,
        metadata=metadata,
    )


class AutonomyLoopEnvironment(EnvironmentAdapter):
    """
    Local autonomy-loop harness for observe/orient/plan/act/verify/reflect traces.

    The adapter exposes deterministic tools an agent can call to make its control
    loop observable. It is intended for testing the scaffold around an agent:
    planning, feedback use, reflection, memory writes, and skill-library updates.
    """

    name = "autonomy_loop"

    def __init__(
        self,
        *,
        goal: Optional[str] = None,
        required_stages: Optional[Iterable[str]] = None,
        feedback: Optional[Mapping[str, Any]] = None,
        prior_memory: Optional[Mapping[str, Any]] = None,
        skill_library: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]] = None,
        policy: Optional[Mapping[str, Any]] = None,
        expected_plan: Optional[Mapping[str, Any]] = None,
        expected_verification: Optional[Mapping[str, Any]] = None,
        expected_reflection: Optional[Mapping[str, Any]] = None,
        expected_memory: Optional[Mapping[str, Any]] = None,
        expected_skills: Optional[Iterable[str | Mapping[str, Any]]] = None,
        expected_stop: Optional[Mapping[str, Any] | bool] = None,
        state: Optional[Mapping[str, Any]] = None,
    ) -> None:
        self.goal = goal
        self.required_stages = [
            _normalize_autonomy_stage(stage)
            for stage in (required_stages or DEFAULT_AUTONOMY_STAGES)
        ]
        self.required_stages = [stage for stage in self.required_stages if stage]
        self.feedback = copy.deepcopy(dict(feedback or {}))
        self.prior_memory = copy.deepcopy(dict(prior_memory or {}))
        self.initial_skills = _normalize_skill_library(skill_library)
        self.policy = copy.deepcopy(dict(policy or {}))
        self.expected_plan = copy.deepcopy(dict(expected_plan or {}))
        self.expected_verification = copy.deepcopy(dict(expected_verification or {}))
        self.expected_reflection = copy.deepcopy(dict(expected_reflection or {}))
        self.expected_memory = copy.deepcopy(dict(expected_memory or {}))
        self.expected_skills = _normalize_expected_skills(expected_skills)
        self.expected_stop = _normalize_expected_stop(expected_stop)
        self.initial_state = copy.deepcopy(dict(state or {}))
        self.entries: List[Dict[str, Any]] = []
        self.memory_updates: List[Dict[str, Any]] = []
        self.skills: Dict[str, Any] = copy.deepcopy(self.initial_skills)
        self.state = copy.deepcopy(self.initial_state)

    def reset(self, **context: Any) -> EnvironmentSnapshot:
        self.entries = []
        self.memory_updates = []
        self.skills = copy.deepcopy(self.initial_skills)
        self.state = copy.deepcopy(self.initial_state)
        return EnvironmentSnapshot(
            tools=self._tool_specs(),
            artifacts=[self._trace_artifact()],
            state={"autonomy_loop": self._state_payload()},
            events=[
                SimulationEvent(
                    type="autonomy_loop",
                    name="loop_ready",
                    payload={
                        "goal": self.goal,
                        "required_stages": self.required_stages,
                        "feedback_keys": sorted(self.feedback.keys()),
                        "memory_keys": sorted(self.prior_memory.keys()),
                        "skill_count": len(self.skills),
                        "policy_keys": sorted(self.policy.keys()),
                        "expected_quality_checks": self._expected_quality_count(),
                    },
                )
            ],
            metadata={
                "autonomy_loop": {
                    "required_stages": self.required_stages,
                    "feedback_keys": sorted(self.feedback.keys()),
                    "expected_quality_checks": self._expected_quality_count(),
                }
            },
        )

    def handle_tool_call(
        self,
        tool_call: Mapping[str, Any],
        **context: Any,
    ) -> Optional[ToolExecutionResult]:
        name = _tool_name(tool_call)
        stage = _autonomy_stage_for_tool(name)
        if not stage:
            return None

        arguments = _tool_arguments(tool_call)
        call_id = _tool_call_id(tool_call)
        entry = {
            "stage": stage,
            "tool": name,
            "arguments": copy.deepcopy(arguments),
            "turn_index": context.get("turn_index"),
        }
        feedback = copy.deepcopy(
            self.feedback.get(stage, self.feedback.get(str(name), self.feedback.get("default", {})))
        )
        if feedback:
            entry["feedback"] = feedback
        if self.policy:
            entry["policy"] = copy.deepcopy(self.policy)
        self.entries.append(entry)

        if stage == "memory":
            self.memory_updates.append(copy.deepcopy(arguments))
        if stage == "skill":
            skill_name = str(arguments.get("name") or arguments.get("skill") or f"skill_{len(self.skills) + 1}")
            self.skills[skill_name] = copy.deepcopy(arguments)
        if stage == "act":
            self.state["last_action"] = copy.deepcopy(arguments)
        if stage == "verify":
            self.state["last_verification"] = copy.deepcopy(arguments)
            if any(key in arguments for key in ("stop", "should_stop", "continue", "should_continue", "decision")):
                self.state["last_stop_decision"] = copy.deepcopy(arguments)
        if stage == "reflect" and any(key in arguments for key in ("stop", "should_stop", "continue", "should_continue", "decision")):
            self.state["last_stop_decision"] = copy.deepcopy(arguments)

        payload = {
            "stage": stage,
            "tool": name,
            "arguments": arguments,
            "feedback": feedback,
            "observed_stages": self._observed_stages(),
            "quality_checks": self._quality_checks(),
        }
        return ToolExecutionResult(
            tool_call_id=call_id,
            tool_name=str(name),
            content=f"Recorded autonomy loop stage '{stage}'.",
            result=payload,
            state_updates={"autonomy_loop": self._state_payload()},
            artifacts=[self._trace_artifact()],
            events=[
                SimulationEvent(
                    type="autonomy_loop",
                    name=stage,
                    payload=payload,
                )
            ],
            metadata={"autonomy_loop": {"stage": stage}},
        )

    def _tool_specs(self) -> List[Dict[str, Any]]:
        return [
            {
                "name": "record_observation",
                "description": "Record observed task, environment, user, or state signals.",
                "parameters": {"type": "object", "properties": {"signals": {"type": "array"}}},
            },
            {
                "name": "orient_strategy",
                "description": "Record the strategy, constraints, uncertainty, or policy orientation.",
                "parameters": {"type": "object", "properties": {"strategy": {"type": "string"}}},
            },
            {
                "name": "propose_plan",
                "description": "Record a decomposed plan or candidate next steps.",
                "parameters": {"type": "object", "properties": {"steps": {"type": "array"}}},
            },
            {
                "name": "record_action",
                "description": "Record the selected action and why it was chosen.",
                "parameters": {"type": "object", "properties": {"action": {"type": "string"}}},
            },
            {
                "name": "verify_outcome",
                "description": "Record self-check, critic, test, or external verification evidence.",
                "parameters": {"type": "object", "properties": {"passed": {"type": "boolean"}}},
            },
            {
                "name": "reflect",
                "description": "Record reflection or self-refinement notes from feedback.",
                "parameters": {"type": "object", "properties": {"lesson": {"type": "string"}}},
            },
            {
                "name": "write_memory",
                "description": "Record an episodic memory update produced by the agent.",
                "parameters": {"type": "object", "properties": {}},
            },
            {
                "name": "store_skill",
                "description": "Record a reusable skill, macro, or procedure learned by the agent.",
                "parameters": {"type": "object", "properties": {"name": {"type": "string"}}},
            },
            {
                "name": "autonomy_status",
                "description": "Inspect observed autonomy loop stages, memory, skills, and feedback.",
                "parameters": {"type": "object", "properties": {}},
            },
        ]

    def _trace_artifact(self) -> SimulationArtifact:
        return SimulationArtifact(
            type="trace",
            role="environment",
            data=self._trace_payload(),
            metadata={"kind": "autonomy_loop_trace", "required_stages": self.required_stages},
        )

    def _trace_payload(self) -> Dict[str, Any]:
        return {
            "kind": "autonomy_loop_trace",
            "goal": self.goal,
            "required_stages": list(self.required_stages),
            "stages_observed": self._observed_stages(),
            "entries": copy.deepcopy(self.entries),
            "feedback": copy.deepcopy(self.feedback),
            "prior_memory": copy.deepcopy(self.prior_memory),
            "memory_updates": copy.deepcopy(self.memory_updates),
            "skills": copy.deepcopy(self.skills),
            "policy": copy.deepcopy(self.policy),
            "expected_plan": copy.deepcopy(self.expected_plan),
            "expected_verification": copy.deepcopy(self.expected_verification),
            "expected_reflection": copy.deepcopy(self.expected_reflection),
            "expected_memory": copy.deepcopy(self.expected_memory),
            "expected_skills": copy.deepcopy(self.expected_skills),
            "expected_stop": copy.deepcopy(self.expected_stop),
            "quality_checks": self._quality_checks(),
        }

    def _state_payload(self) -> Dict[str, Any]:
        return {
            "goal": self.goal,
            "required_stages": list(self.required_stages),
            "stages_observed": self._observed_stages(),
            "entries": copy.deepcopy(self.entries),
            "prior_memory": copy.deepcopy(self.prior_memory),
            "memory_updates": copy.deepcopy(self.memory_updates),
            "skills": copy.deepcopy(self.skills),
            "policy": copy.deepcopy(self.policy),
            "expected_plan": copy.deepcopy(self.expected_plan),
            "expected_verification": copy.deepcopy(self.expected_verification),
            "expected_reflection": copy.deepcopy(self.expected_reflection),
            "expected_memory": copy.deepcopy(self.expected_memory),
            "expected_skills": copy.deepcopy(self.expected_skills),
            "expected_stop": copy.deepcopy(self.expected_stop),
            "quality_checks": self._quality_checks(),
            "state": copy.deepcopy(self.state),
        }

    def _observed_stages(self) -> List[str]:
        return sorted({entry["stage"] for entry in self.entries})

    def _quality_checks(self) -> List[Dict[str, Any]]:
        return _autonomy_quality_checks(
            entries=self.entries,
            memory_updates=self.memory_updates,
            skills=self.skills,
            expected_plan=self.expected_plan,
            expected_verification=self.expected_verification,
            expected_reflection=self.expected_reflection,
            expected_memory=self.expected_memory,
            expected_skills=self.expected_skills,
            expected_stop=self.expected_stop,
        )

    def _expected_quality_count(self) -> int:
        return sum(
            1
            for item in (
                self.expected_plan,
                self.expected_verification,
                self.expected_reflection,
                self.expected_memory,
                self.expected_skills,
                self.expected_stop,
            )
            if item
        )


def coerce_environment_adapters(
    environment: EnvironmentAdapter | Iterable[EnvironmentAdapter] | None,
) -> List[EnvironmentAdapter]:
    if environment is None:
        return []
    if isinstance(environment, EnvironmentAdapter):
        return [environment]
    return list(environment)


def _merge_environment_snapshots(*snapshots: EnvironmentSnapshot) -> EnvironmentSnapshot:
    tools: List[Dict[str, Any]] = []
    artifacts: List[SimulationArtifact] = []
    events: List[SimulationEvent] = []
    state: Dict[str, Any] = {}
    metadata: Dict[str, Any] = {}
    for snapshot in snapshots:
        tools.extend(copy.deepcopy(snapshot.tools))
        artifacts.extend(copy.deepcopy(snapshot.artifacts))
        events.extend(copy.deepcopy(snapshot.events))
        _deep_merge(state, snapshot.state)
        _deep_merge(metadata, snapshot.metadata)
    return EnvironmentSnapshot(
        tools=tools,
        artifacts=artifacts,
        events=events,
        state=state,
        metadata=metadata,
    )


def _coerce_tool_result(
    value: Any,
    *,
    tool_name: str,
    tool_call_id: Optional[str],
) -> ToolExecutionResult:
    if isinstance(value, ToolExecutionResult):
        if value.tool_call_id is None:
            value.tool_call_id = tool_call_id
        return value
    if isinstance(value, dict):
        return ToolExecutionResult(
            tool_call_id=tool_call_id,
            tool_name=tool_name,
            content=str(value.get("content", value.get("result", ""))),
            result=value.get("result", value),
            success=bool(value.get("success", True)),
            error=value.get("error"),
            state_updates=dict(value.get("state_updates", {})),
            artifacts=[_coerce_artifact(item) for item in value.get("artifacts", [])],
            events=[_coerce_event(item) for item in value.get("events", [])],
            metadata=dict(value.get("metadata", {})),
        )
    return ToolExecutionResult(
        tool_call_id=tool_call_id,
        tool_name=tool_name,
        content=str(value),
        result=value,
    )


def _tool_name(tool_call: Mapping[str, Any]) -> Optional[str]:
    function = tool_call.get("function")
    if isinstance(function, dict):
        return tool_call.get("name") or function.get("name")
    return tool_call.get("name") or tool_call.get("tool") or tool_call.get("action")


def _tool_arguments(tool_call: Mapping[str, Any]) -> Dict[str, Any]:
    function = tool_call.get("function")
    value: Any = tool_call.get("arguments", tool_call.get("args", tool_call.get("input", {})))
    if isinstance(function, dict) and "arguments" in function:
        value = function["arguments"]
    if isinstance(value, dict):
        return value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return parsed if isinstance(parsed, dict) else {"value": parsed}
        except json.JSONDecodeError:
            return {"value": value}
    return {"value": value}


def _tool_call_id(tool_call: Mapping[str, Any]) -> Optional[str]:
    value = tool_call.get("id") or tool_call.get("tool_call_id") or tool_call.get("call_id")
    return str(value) if value is not None else None


def _coerce_artifact(value: SimulationArtifact | Dict[str, Any]) -> SimulationArtifact:
    if isinstance(value, SimulationArtifact):
        return value
    return SimulationArtifact(**value)


def _coerce_event(value: SimulationEvent | Dict[str, Any]) -> SimulationEvent:
    if isinstance(value, SimulationEvent):
        return value
    return SimulationEvent(**value)


def _normalize_workflow_trace_manifest(
    trace: Mapping[str, Any],
    *,
    framework: str,
    workflow_id: str,
    thread_id: str,
    run_id: str,
    nodes: Optional[Iterable[Mapping[str, Any]]],
    edges: Optional[Iterable[Mapping[str, Any]]],
    steps: Optional[Iterable[Mapping[str, Any]]],
    checkpoints: Optional[Iterable[Mapping[str, Any]]],
    route_decisions: Optional[Iterable[Mapping[str, Any]]],
    interrupts: Optional[Iterable[Mapping[str, Any]]],
    replay: Optional[Iterable[Mapping[str, Any]]],
    writes: Optional[Iterable[Mapping[str, Any]]],
    state_snapshots: Optional[Iterable[Mapping[str, Any]]],
    final_state: Optional[Mapping[str, Any]],
    metadata: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    wrapper_payload = _coerce_plain_dict(trace)
    payload = (
        _coerce_plain_dict(wrapper_payload.get("trace"))
        or _coerce_plain_dict(wrapper_payload.get("workflow_trace"))
        or wrapper_payload
    )
    normalized_nodes = _workflow_trace_records(
        nodes if nodes is not None else payload.get("nodes") or payload.get("workflow_nodes")
    )
    normalized_edges = _workflow_trace_records(
        edges if edges is not None else payload.get("edges") or payload.get("workflow_edges")
    )
    normalized_steps = _workflow_trace_records(
        steps if steps is not None else payload.get("steps") or payload.get("workflow_steps")
    )
    normalized_checkpoints = _workflow_trace_records(
        checkpoints
        if checkpoints is not None
        else payload.get("checkpoints") or payload.get("workflow_checkpoints")
    )
    normalized_routes = _workflow_trace_records(
        route_decisions
        if route_decisions is not None
        else payload.get("route_decisions") or payload.get("routes")
    )
    normalized_interrupts = _workflow_trace_records(
        interrupts
        if interrupts is not None
        else payload.get("interrupts") or payload.get("workflow_interrupts")
    )
    normalized_replay = _workflow_trace_records(
        replay if replay is not None else payload.get("replay") or payload.get("workflow_replay")
    )
    normalized_writes = _workflow_trace_records(
        writes if writes is not None else payload.get("writes") or payload.get("pending_writes")
    )
    normalized_state_snapshots = _workflow_trace_records(
        state_snapshots
        if state_snapshots is not None
        else payload.get("state_snapshots") or payload.get("state_history")
    )
    normalized_final_state = _coerce_plain_dict(
        final_state
        if final_state is not None
        else payload.get("final_state") or payload.get("workflow_state")
    )
    tool_names: List[str] = []
    for step in normalized_steps:
        for raw_call in _as_iterable(step.get("tool_calls")):
            call = _coerce_plain_dict(raw_call)
            name = str(call.get("name") or call.get("tool") or "")
            if name:
                tool_names.append(name)
    tool_names = sorted(set(tool_names))
    step_statuses = sorted(
        {
            _normalize_workflow_trace_name(step.get("status"))
            for step in normalized_steps
            if _normalize_workflow_trace_name(step.get("status"))
        }
    )
    topology = _workflow_trace_topology_payload(
        normalized_nodes,
        normalized_edges,
        _coerce_plain_dict(payload.get("topology")),
    )
    normalized_metadata = {
        **_coerce_plain_dict(wrapper_payload.get("metadata")),
        **_coerce_plain_dict(payload.get("metadata")),
        **copy.deepcopy(dict(metadata or {})),
    }
    primary_framework = str(payload.get("framework") or framework)
    source_frameworks = _workflow_trace_frameworks(
        payload.get("source_frameworks") or payload.get("frameworks"),
        normalized_metadata.get("source_frameworks")
        or normalized_metadata.get("frameworks"),
    )
    if not source_frameworks and primary_framework:
        source_frameworks = [_normalize_workflow_trace_name(primary_framework)]
    observed_frameworks = sorted(
        {
            item
            for item in [
                _normalize_workflow_trace_name(primary_framework),
                *source_frameworks,
            ]
            if item
        }
    )
    return {
        "kind": "workflow_trace",
        "framework": primary_framework,
        "source_frameworks": source_frameworks,
        "workflow_id": str(payload.get("workflow_id") or workflow_id),
        "thread_id": str(payload.get("thread_id") or thread_id),
        "run_id": str(payload.get("run_id") or run_id),
        "nodes": normalized_nodes,
        "edges": normalized_edges,
        "steps": normalized_steps,
        "checkpoints": normalized_checkpoints,
        "route_decisions": normalized_routes,
        "interrupts": normalized_interrupts,
        "replay": normalized_replay,
        "writes": normalized_writes,
        "state_snapshots": normalized_state_snapshots,
        "final_state": normalized_final_state,
        "topology": topology,
        "node_count": len(normalized_nodes),
        "edge_count": len(normalized_edges),
        "step_count": len(normalized_steps),
        "checkpoint_count": len(normalized_checkpoints),
        "route_decision_count": len(normalized_routes),
        "interrupt_count": len(normalized_interrupts),
        "replay_count": len(normalized_replay),
        "write_count": len(normalized_writes),
        "state_snapshot_count": len(normalized_state_snapshots),
        "tool_call_count": len(tool_names),
        "tool_names": tool_names,
        "step_statuses": step_statuses,
        "final_state_keys": sorted(str(key) for key in normalized_final_state),
        "has_replay": bool(normalized_replay),
        "has_interrupts": bool(normalized_interrupts),
        "has_routes": bool(normalized_routes),
        "summary": {
            "node_count": len(normalized_nodes),
            "edge_count": len(normalized_edges),
            "step_count": len(normalized_steps),
            "checkpoint_count": len(normalized_checkpoints),
            "route_decision_count": len(normalized_routes),
            "interrupt_count": len(normalized_interrupts),
            "replay_count": len(normalized_replay),
            "write_count": len(normalized_writes),
            "state_snapshot_count": len(normalized_state_snapshots),
            "tool_call_count": len(tool_names),
            "tool_names": tool_names,
            "step_statuses": step_statuses,
            "final_state_keys": sorted(str(key) for key in normalized_final_state),
            "frameworks": observed_frameworks,
            "source_frameworks": source_frameworks,
            "entry_nodes": list(topology.get("entry_nodes") or []),
            "terminal_nodes": list(topology.get("terminal_nodes") or []),
        },
        "metadata": normalized_metadata,
    }


def _workflow_trace_records(values: Any) -> List[Dict[str, Any]]:
    return [
        _coerce_plain_dict(value)
        for value in _as_iterable(values)
        if _coerce_plain_dict(value)
    ]


def _workflow_trace_frameworks(*values: Any) -> List[str]:
    frameworks: set[str] = set()
    for value in values:
        for item in _as_iterable(value):
            if isinstance(item, Mapping):
                candidates = (
                    item.get("framework"),
                    item.get("name"),
                    item.get("id"),
                )
            else:
                candidates = (item,)
            for candidate in candidates:
                normalized = _normalize_workflow_trace_name(candidate)
                if normalized:
                    frameworks.add(normalized)
    return sorted(frameworks)


def _workflow_trace_topology_payload(
    nodes: Sequence[Mapping[str, Any]],
    edges: Sequence[Mapping[str, Any]],
    explicit: Mapping[str, Any],
) -> Dict[str, Any]:
    if explicit:
        return copy.deepcopy(dict(explicit))
    node_ids = {
        str(node.get("id") or node.get("name"))
        for node in nodes
        if node.get("id") or node.get("name")
    }
    targets = {str(edge.get("target")) for edge in edges if edge.get("target")}
    sources = {str(edge.get("source")) for edge in edges if edge.get("source")}
    entry_nodes = sorted(node_ids - targets)
    terminal_nodes = sorted(node_ids - sources)
    return {
        "entry_nodes": entry_nodes,
        "terminal_nodes": terminal_nodes,
    }


def _workflow_trace_events_from_payload(payload: Mapping[str, Any]) -> List[SimulationEvent]:
    events: List[SimulationEvent] = []
    for step in payload.get("steps", []):
        events.append(
            SimulationEvent(
                type="workflow_step",
                name=str(step.get("name") or step.get("id") or "workflow_step"),
                payload=copy.deepcopy(dict(step)),
                metadata={"kind": "workflow_trace"},
            )
        )
    for route in payload.get("route_decisions", []):
        events.append(
            SimulationEvent(
                type="workflow_route",
                name=str(route.get("selected") or route.get("target") or "workflow_route"),
                payload=copy.deepcopy(dict(route)),
                metadata={"kind": "workflow_trace"},
            )
        )
    for checkpoint in payload.get("checkpoints", []):
        events.append(
            SimulationEvent(
                type="workflow_checkpoint",
                name=str(
                    checkpoint.get("checkpoint_id")
                    or checkpoint.get("id")
                    or "workflow_checkpoint"
                ),
                payload=copy.deepcopy(dict(checkpoint)),
                metadata={"kind": "workflow_trace"},
            )
        )
    for item in payload.get("interrupts", []):
        events.append(
            SimulationEvent(
                type="workflow_interrupt",
                name=str(item.get("id") or item.get("node") or "workflow_interrupt"),
                payload=copy.deepcopy(dict(item)),
                metadata={"kind": "workflow_trace"},
            )
        )
    for item in payload.get("replay", []):
        events.append(
            SimulationEvent(
                type="workflow_replay",
                name=str(item.get("id") or "workflow_replay"),
                payload=copy.deepcopy(dict(item)),
                metadata={"kind": "workflow_trace"},
            )
        )
    events.append(
        SimulationEvent(
            type="workflow_trace",
            name="workflow_trace",
            payload=copy.deepcopy(dict(payload)),
            metadata={"kind": "workflow_trace"},
        )
    )
    return events


def _normalize_workflow_trace_name(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", "_", str(value or "").strip().lower()).strip("_")


def _normalize_participants(
    participants: Iterable[str | Mapping[str, Any]] | Mapping[str, Any],
) -> Dict[str, Dict[str, Any]]:
    if isinstance(participants, Mapping):
        normalized = {}
        for name, spec in participants.items():
            role = copy.deepcopy(dict(spec)) if isinstance(spec, Mapping) else {"description": spec}
            role.setdefault("name", str(name))
            normalized[str(name)] = role
        return normalized

    normalized: Dict[str, Dict[str, Any]] = {}
    for index, participant in enumerate(participants):
        if isinstance(participant, Mapping):
            role = copy.deepcopy(dict(participant))
            name = str(role.get("name") or role.get("role") or f"agent_{index + 1}")
            role.setdefault("name", name)
            normalized[name] = role
        else:
            name = str(participant)
            normalized[name] = {"name": name}
    return normalized


def _normalize_handoff_contracts(
    contracts: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]],
) -> Dict[str, Dict[str, Any]]:
    if contracts is None:
        return {}
    if isinstance(contracts, Mapping):
        normalized = {}
        for name, spec in contracts.items():
            normalized[str(name)] = copy.deepcopy(dict(spec)) if isinstance(spec, Mapping) else {"description": spec}
        return normalized
    normalized = {}
    for index, contract in enumerate(contracts):
        item = copy.deepcopy(dict(contract))
        name = str(item.get("to") or item.get("role") or item.get("agent") or item.get("name") or f"contract_{index + 1}")
        normalized[name] = item
    return normalized


def _multi_agent_contract_status(
    handoff: Mapping[str, Any],
    contract: Mapping[str, Any],
) -> Dict[str, Any]:
    checks: List[Dict[str, Any]] = []
    if not contract:
        return {"matched": True, "checks": checks}

    if contract.get("require_reason"):
        checks.append(
            {
                "check": "reason",
                "expected": "present",
                "actual": bool(handoff.get("reason")),
                "match": bool(handoff.get("reason")),
            }
        )

    required_context_keys = _multi_agent_string_list(
        contract.get("required_context_keys") or contract.get("context_keys")
    )
    if required_context_keys:
        context = handoff.get("context")
        actual_keys = sorted(context.keys()) if isinstance(context, Mapping) else []
        missing = sorted(set(required_context_keys) - set(actual_keys))
        checks.append(
            {
                "check": "context_keys",
                "expected": required_context_keys,
                "actual": actual_keys,
                "match": not missing,
                "missing": missing,
            }
        )

    required_task_terms = _multi_agent_string_list(
        contract.get("required_task_terms") or contract.get("task_contains")
    )
    if required_task_terms:
        text = _multi_agent_record_text(handoff)
        missing = [term for term in required_task_terms if term.lower() not in text]
        checks.append(
            {
                "check": "task_contains",
                "expected": required_task_terms,
                "actual": handoff.get("task"),
                "match": not missing,
                "missing": missing,
            }
        )

    forbidden_terms = _multi_agent_string_list(contract.get("forbidden_terms"))
    if forbidden_terms:
        text = _multi_agent_record_text(handoff)
        present = [term for term in forbidden_terms if term.lower() in text]
        checks.append(
            {
                "check": "forbidden_terms",
                "expected": [],
                "actual": present,
                "match": not present,
            }
        )

    return {
        "matched": all(check["match"] for check in checks),
        "checks": checks,
    }


def _multi_agent_coordination_checks(
    *,
    participants: Mapping[str, Any],
    handoffs: Iterable[Mapping[str, Any]],
    reviews: Iterable[Mapping[str, Any]],
    reconciliations: Iterable[Mapping[str, Any]],
    expected_handoffs: Iterable[Mapping[str, Any]],
    expected_reviews: Iterable[Mapping[str, Any]],
    expected_reconciliation: Mapping[str, Any],
) -> List[Dict[str, Any]]:
    handoff_list = [dict(item) for item in handoffs]
    review_list = [dict(item) for item in reviews]
    reconciliation_list = [dict(item) for item in reconciliations]
    checks: List[Dict[str, Any]] = []

    for handoff in handoff_list:
        checks.append(
            {
                "check": "known_handoff_role",
                "expected": sorted(participants.keys()),
                "actual": handoff.get("to"),
                "match": bool(handoff.get("known_role", handoff.get("to") in participants)),
            }
        )
        contract_status = dict(handoff.get("contract_status", {}))
        if contract_status.get("checks"):
            checks.append(
                {
                    "check": "handoff_contract",
                    "expected": handoff.get("contract", {}),
                    "actual": contract_status,
                    "match": bool(contract_status.get("matched")),
                    "to": handoff.get("to"),
                }
            )

    for review in review_list:
        checks.append(
            {
                "check": "known_review_role",
                "expected": sorted(participants.keys()),
                "actual": review.get("reviewer"),
                "match": bool(review.get("known_role", review.get("reviewer") in participants)),
            }
        )

    for index, expected in enumerate(expected_handoffs):
        expected_dict = dict(expected)
        matched = any(_multi_agent_handoff_matches(handoff, expected_dict) for handoff in handoff_list)
        checks.append(
            {
                "check": "expected_handoff",
                "index": index,
                "expected": copy.deepcopy(expected_dict),
                "actual": copy.deepcopy(handoff_list),
                "match": matched,
            }
        )

    for index, expected in enumerate(expected_reviews):
        expected_dict = dict(expected)
        matched = any(_multi_agent_review_matches(review, expected_dict) for review in review_list)
        checks.append(
            {
                "check": "expected_review",
                "index": index,
                "expected": copy.deepcopy(expected_dict),
                "actual": copy.deepcopy(review_list),
                "match": matched,
            }
        )

    if expected_reconciliation:
        matched = any(
            _multi_agent_reconciliation_matches(item, expected_reconciliation)
            for item in reconciliation_list
        )
        checks.append(
            {
                "check": "expected_reconciliation",
                "expected": copy.deepcopy(dict(expected_reconciliation)),
                "actual": copy.deepcopy(reconciliation_list),
                "match": matched,
            }
        )

    return checks


def _multi_agent_handoff_matches(record: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    if expected.get("to") and str(record.get("to")) != str(expected.get("to")):
        return False
    if expected.get("known_role") is not None and bool(record.get("known_role")) != bool(expected.get("known_role")):
        return False
    if not _multi_agent_text_contains(record.get("task"), expected.get("task_contains")):
        return False
    if not _multi_agent_text_contains(record.get("reason"), expected.get("reason_contains")):
        return False
    if not _multi_agent_context_matches(record.get("context"), expected.get("context_keys")):
        return False
    if expected.get("contract_matched") is not None:
        status = dict(record.get("contract_status", {}))
        if bool(status.get("matched")) != bool(expected.get("contract_matched")):
            return False
    return True


def _multi_agent_review_matches(record: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    if expected.get("reviewer") and str(record.get("reviewer")) != str(expected.get("reviewer")):
        return False
    if not _multi_agent_text_contains(record.get("target"), expected.get("target_contains")):
        return False
    expected_criteria = set(_multi_agent_string_list(expected.get("criteria")))
    actual_criteria = set(_multi_agent_string_list(record.get("criteria")))
    if expected_criteria and not expected_criteria <= actual_criteria:
        return False
    return True


def _multi_agent_reconciliation_matches(record: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    if expected.get("accepted_source") and str(record.get("accepted_source")) != str(expected.get("accepted_source")):
        return False
    if not _multi_agent_text_contains(record.get("summary") or record.get("decision"), expected.get("summary_contains")):
        return False
    if expected.get("conflicts_empty") is not None:
        conflicts = record.get("conflicts", [])
        if bool(conflicts) == bool(expected.get("conflicts_empty")):
            return False
    return True


def _multi_agent_context_matches(context: Any, expected_keys: Any) -> bool:
    keys = _multi_agent_string_list(expected_keys)
    if not keys:
        return True
    if not isinstance(context, Mapping):
        return False
    return set(keys) <= {str(key) for key in context.keys()}


def _multi_agent_text_contains(value: Any, expected_terms: Any) -> bool:
    terms = _multi_agent_string_list(expected_terms)
    if not terms:
        return True
    text = str(value or "").lower()
    return all(term.lower() in text for term in terms)


def _multi_agent_record_text(record: Mapping[str, Any]) -> str:
    return " ".join(
        [
            str(record.get("task") or ""),
            str(record.get("reason") or ""),
            _stringify_dict(record.get("context") or {}),
        ]
    ).lower()


def _multi_agent_string_list(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, Iterable) and not isinstance(value, (bytes, bytearray, Mapping)):
        return [str(item) for item in value if item not in (None, "")]
    return [str(value)]


def _normalize_retrieval_documents(
    documents: Mapping[str, Any] | Iterable[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    raw_documents: List[Mapping[str, Any]] = []
    if isinstance(documents, Mapping):
        for doc_id, value in documents.items():
            if isinstance(value, Mapping):
                item = dict(value)
            else:
                item = {"content": str(value)}
            item.setdefault("id", str(doc_id))
            raw_documents.append(item)
    else:
        raw_documents = [dict(document) for document in documents]

    normalized = []
    for index, document in enumerate(raw_documents):
        item = copy.deepcopy(dict(document))
        item.setdefault("id", f"doc_{index + 1}")
        item.setdefault("title", item.get("source", item["id"]))
        item.setdefault("content", item.get("text", ""))
        item.setdefault("source", item.get("uri", item.get("path", item["id"])))
        item.setdefault("metadata", {})
        item.setdefault("current", item.get("status", "current") not in {"stale", "superseded", "archived"})
        if "version" not in item and isinstance(item.get("metadata"), Mapping):
            item["version"] = item["metadata"].get("version")
        normalized.append(item)
    return normalized


def _find_retrieval_document(
    documents: Iterable[Mapping[str, Any]],
    doc_id: str,
) -> Optional[Mapping[str, Any]]:
    if not doc_id:
        return None
    for document in documents:
        if doc_id in {str(document.get("id")), str(document.get("source")), str(document.get("title"))}:
            return document
    return None


def _token_set(text: str) -> set[str]:
    return {
        token.strip(".,:;!?()[]{}\"'").lower()
        for token in str(text).split()
        if len(token.strip(".,:;!?()[]{}\"'")) > 2
    }


def _as_iterable(value: Any) -> List[Any]:
    if value is None:
        return []
    if isinstance(value, (list, tuple, set)):
        return list(value)
    return [value]


def _load_framework_trace_export_source(
    source: Any,
    *,
    headers: Optional[Mapping[str, str]] = None,
    auth: Optional[Mapping[str, Any]] = None,
    pagination: Optional[Mapping[str, Any]] = None,
    max_pages: int = 20,
    timeout: float = 30.0,
) -> Any:
    payload, _ = _load_framework_trace_export_source_with_metadata(
        source,
        headers=headers,
        auth=auth,
        pagination=pagination,
        max_pages=max_pages,
        timeout=timeout,
    )
    return payload


def _load_framework_trace_export_source_with_metadata(
    source: Any,
    *,
    headers: Optional[Mapping[str, str]] = None,
    auth: Optional[Mapping[str, Any]] = None,
    pagination: Optional[Mapping[str, Any]] = None,
    max_pages: int = 20,
    timeout: float = 30.0,
) -> tuple[Any, Dict[str, Any]]:
    if _is_export_source_spec(source):
        spec = copy.deepcopy(dict(source))
        spec_headers = {**dict(headers or {}), **dict(spec.get("headers", {}))}
        spec_auth = _as_mapping(spec.get("auth")) or auth
        spec_pagination = _as_mapping(spec.get("pagination")) or pagination
        spec_max_pages = _voice_int(spec.get("max_pages")) or max_pages
        if "pages" in spec:
            pages = [
                _load_export_page_payload(
                    page,
                    headers=spec_headers,
                    auth=spec_auth,
                    timeout=timeout,
                )
                for page in _as_iterable(spec.get("pages"))
            ]
            metadata = _export_source_metadata(
                source,
                headers=spec_headers,
                auth=spec_auth,
                page_count=len(pages),
                pagination_enabled=True,
                pagination=spec_pagination,
            )
            return pages, metadata
        nested_source = spec.get("url") or spec.get("source") or spec.get("path")
        if nested_source is None:
            return spec, _export_source_metadata(
                source,
                headers=spec_headers,
                auth=spec_auth,
                page_count=1,
                pagination_enabled=bool(spec_pagination),
                pagination=spec_pagination,
            )
        return _load_framework_trace_export_source_with_metadata(
            nested_source,
            headers=spec_headers,
            auth=spec_auth,
            pagination=spec_pagination,
            max_pages=spec_max_pages,
            timeout=timeout,
        )

    effective_headers = _export_request_headers(headers, auth)
    source_text = os.fspath(source)
    parsed = urlparse(source_text)
    if parsed.scheme in {"http", "https"} and _pagination_enabled(pagination):
        pages: List[Any] = []
        next_url: Optional[str] = source_text
        cursor: Optional[str] = None
        for _ in range(max(1, max_pages)):
            if not next_url:
                break
            page_payload, response_headers = _load_http_export_page(
                next_url,
                headers=effective_headers,
                timeout=timeout,
            )
            pages.append(page_payload)
            next_url = _next_export_page_url(
                page_payload,
                response_headers=response_headers,
                current_url=next_url,
                pagination=pagination,
            )
            if not next_url:
                cursor = _next_export_cursor(page_payload, pagination=pagination)
                if cursor:
                    next_url = _url_with_cursor(
                        source_text,
                        cursor=cursor,
                        pagination=pagination,
                    )
        metadata = _export_source_metadata(
            source,
            headers=effective_headers,
            auth=auth,
            page_count=len(pages),
            pagination_enabled=True,
            pagination=pagination,
        )
        metadata["truncated"] = bool(next_url)
        return pages, metadata

    source_text = os.fspath(source)
    parsed = urlparse(source_text)
    if parsed.scheme in {"http", "https"}:
        payload, _ = _load_http_export_page(
            source_text,
            headers=effective_headers,
            timeout=timeout,
        )
        return payload, _export_source_metadata(
            source,
            headers=effective_headers,
            auth=auth,
            page_count=1,
            pagination_enabled=False,
            pagination=pagination,
        )
    if os.path.exists(source_text):
        with open(source_text, "r", encoding="utf-8") as file:
            payload = _parse_framework_trace_export_text(file.read())
        return payload, _export_source_metadata(
            source,
            headers=effective_headers,
            auth=auth,
            page_count=1,
            pagination_enabled=False,
            pagination=pagination,
        )
    return _parse_framework_trace_export_text(source_text), _export_source_metadata(
        source,
        headers=effective_headers,
        auth=auth,
        page_count=1,
        pagination_enabled=False,
        pagination=pagination,
    )


def _is_export_source_spec(value: Any) -> bool:
    return isinstance(value, Mapping) and any(key in value for key in ("url", "source", "path", "pages", "auth", "pagination"))


def _load_export_page_payload(
    page: Any,
    *,
    headers: Mapping[str, str],
    auth: Optional[Mapping[str, Any]],
    timeout: float,
) -> Any:
    if _is_export_source_spec(page):
        payload, _ = _load_framework_trace_export_source_with_metadata(
            page,
            headers=headers,
            auth=auth,
            timeout=timeout,
        )
        return payload
    if isinstance(page, (str, os.PathLike)):
        return _load_framework_trace_export_source(
            page,
            headers=headers,
            auth=auth,
            timeout=timeout,
        )
    return copy.deepcopy(page)


def _load_http_export_page(
    url: str,
    *,
    headers: Mapping[str, str],
    timeout: float,
) -> tuple[Any, Mapping[str, str]]:
    request = urllib.request.Request(url, headers=dict(headers))
    with urllib.request.urlopen(request, timeout=timeout) as response:
        encoding = response.headers.get_content_charset() or "utf-8"
        body = response.read().decode(encoding)
        response_headers = {key.lower(): value for key, value in response.headers.items()}
    return _parse_framework_trace_export_text(body), response_headers


def _export_request_headers(
    headers: Optional[Mapping[str, str]],
    auth: Optional[Mapping[str, Any]],
) -> Dict[str, str]:
    result = dict(headers or {})
    auth_map = _as_mapping(auth)
    if not auth_map:
        return result
    auth_type = str(auth_map.get("type") or auth_map.get("scheme") or "").lower()
    token = auth_map.get("token") or auth_map.get("bearer_token") or auth_map.get("api_key")
    if auth_type in {"bearer", "token"} and token:
        result.setdefault("Authorization", f"Bearer {token}")
    elif auth_type in {"api_key", "apikey"} and token:
        header_name = str(auth_map.get("header") or auth_map.get("header_name") or "X-API-Key")
        result.setdefault(header_name, str(token))
    elif auth_map.get("authorization"):
        result.setdefault("Authorization", str(auth_map["authorization"]))
    return result


def _workflow_auth_headers(*auth_specs: Mapping[str, Any]) -> Dict[str, str]:
    result: Dict[str, str] = {}
    for auth in auth_specs:
        auth_map = _as_mapping(auth)
        if not auth_map:
            continue
        auth_type = str(auth_map.get("type") or auth_map.get("scheme") or "").lower()
        token = (
            auth_map.get("token")
            or auth_map.get("bearer_token")
            or auth_map.get("api_key")
        )
        token_env = (
            auth_map.get("token_env")
            or auth_map.get("api_key_env")
            or auth_map.get("env")
        )
        if not token and token_env:
            token = os.environ.get(str(token_env), "")
        if auth_type in {"bearer", "token"} and token:
            result.setdefault("Authorization", f"Bearer {token}")
        elif auth_type in {"api_key", "apikey"} and token:
            header_name = str(
                auth_map.get("header") or auth_map.get("header_name") or "X-API-Key"
            )
            result.setdefault(header_name, str(token))
        elif auth_map.get("authorization"):
            result.setdefault("Authorization", str(auth_map["authorization"]))
    return result


def _workflow_auth_metadata(
    auth: Mapping[str, Any],
    headers: Mapping[str, str],
) -> Dict[str, Any]:
    auth_map = _as_mapping(auth)
    header_names = sorted(str(key) for key in headers)
    auth_header_names = [
        name
        for name in header_names
        if name.lower()
        in {
            "authorization",
            "x-api-key",
            str(auth_map.get("header", "")).lower(),
        }
    ]
    return {
        "enabled": bool(auth_map or auth_header_names),
        "type": str(auth_map.get("type") or auth_map.get("scheme") or ""),
        "token_env": (
            auth_map.get("token_env")
            or auth_map.get("api_key_env")
            or auth_map.get("env")
        ),
        "header_names": sorted(set(auth_header_names)),
        "redacted": bool(auth_map or auth_header_names),
    }


def _workflow_redacted_url(endpoint: str) -> str:
    parsed = urlparse(endpoint)
    if parsed.query:
        parsed = parsed._replace(query="<redacted>")
    return parsed.geturl()


def _workflow_error_text(payload: Any) -> str:
    if isinstance(payload, Mapping):
        error = payload.get("error")
        if isinstance(error, Mapping):
            return str(error.get("message") or error.get("detail") or error)
        if error not in (None, ""):
            return str(error)
        for key in ("message", "detail", "content"):
            if payload.get(key) not in (None, ""):
                return str(payload.get(key))
    return "" if payload in (None, "") else str(payload)


def _export_source_metadata(
    source: Any,
    *,
    headers: Optional[Mapping[str, str]],
    auth: Optional[Mapping[str, Any]],
    page_count: int,
    pagination_enabled: bool,
    pagination: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    header_names = sorted(str(key) for key in (headers or {}).keys())
    auth_map = _as_mapping(auth)
    auth_header_names = [
        name
        for name in header_names
        if name.lower() in {"authorization", "x-api-key", str(auth_map.get("header", "")).lower()}
    ]
    metadata = {
        "export_source": _framework_trace_source_label(source),
        "page_count": int(page_count),
        "pagination_enabled": bool(pagination_enabled),
        "auth_enabled": bool(auth_map or auth_header_names),
        "header_names": header_names,
        "auth_header_names": sorted(set(auth_header_names)),
    }
    if pagination:
        metadata["pagination"] = {
            key: value
            for key, value in dict(pagination).items()
            if key not in {"token", "api_key", "authorization"}
        }
    return metadata


def _pagination_enabled(pagination: Optional[Mapping[str, Any]]) -> bool:
    if pagination is None:
        return False
    if not pagination:
        return True
    return bool(pagination.get("enabled", True))


def _next_export_page_url(
    payload: Any,
    *,
    response_headers: Mapping[str, str],
    current_url: str,
    pagination: Optional[Mapping[str, Any]],
) -> Optional[str]:
    link_header = response_headers.get("link")
    if link_header:
        for part in link_header.split(","):
            if 'rel="next"' in part or "rel=next" in part:
                start = part.find("<")
                end = part.find(">")
                if start >= 0 and end > start:
                    return urljoin(current_url, part[start + 1 : end])
    item = _as_mapping(payload)
    paths = _as_iterable(_as_mapping(pagination).get("next_url_path")) or [
        "next",
        "next_url",
        "nextPageUrl",
        "pagination.next",
        "pagination.next_url",
        "links.next",
        "meta.next",
    ]
    for path in paths:
        value = _mapping_path(item, str(path))
        if value:
            return urljoin(current_url, str(value))
    return None


def _next_export_cursor(payload: Any, *, pagination: Optional[Mapping[str, Any]]) -> Optional[str]:
    item = _as_mapping(payload)
    paths = _as_iterable(_as_mapping(pagination).get("cursor_path")) or [
        "next_cursor",
        "nextCursor",
        "pagination.next_cursor",
        "pagination.cursor",
        "meta.next_cursor",
    ]
    for path in paths:
        value = _mapping_path(item, str(path))
        if value:
            return str(value)
    return None


def _url_with_cursor(
    url: str,
    *,
    cursor: str,
    pagination: Optional[Mapping[str, Any]],
) -> str:
    cursor_param = str(_as_mapping(pagination).get("cursor_param") or "cursor")
    separator = "&" if "?" in url else "?"
    return f"{url}{separator}{urlencode({cursor_param: cursor})}"


def _mapping_path(value: Mapping[str, Any], path: str) -> Any:
    current: Any = value
    for part in path.split("."):
        if not isinstance(current, Mapping):
            return None
        current = current.get(part)
    return current


def _parse_framework_trace_export_text(text: str) -> Any:
    stripped = text.strip()
    if not stripped:
        return []
    try:
        return json.loads(stripped)
    except json.JSONDecodeError as exc:
        records: List[Any] = []
        for line_number, line in enumerate(stripped.splitlines(), start=1):
            line = line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError as line_exc:
                raise ValueError(f"Invalid trace export JSON/JSONL at line {line_number}") from line_exc
        if records:
            return records
        raise ValueError("Invalid trace export JSON/JSONL") from exc


def _framework_trace_source_label(source: Any) -> str:
    if isinstance(source, Mapping):
        if source.get("url") or source.get("source") or source.get("path"):
            return _framework_trace_source_label(source.get("url") or source.get("source") or source.get("path"))
        if source.get("pages") is not None:
            return "inline_paginated_export"
        return "inline_export_spec"
    source_text = os.fspath(source)
    parsed = urlparse(source_text)
    if parsed.scheme in {"http", "https"}:
        return f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
    return source_text


def _framework_trace_export_records(trace_export: Any) -> List[Any]:
    if trace_export is None:
        return []
    if isinstance(trace_export, str):
        text = trace_export.strip()
        if text.startswith(("{", "[")) or "\n" in text:
            return _framework_trace_export_records(_parse_framework_trace_export_text(text))
        return [{"name": trace_export}]
    if hasattr(trace_export, "model_dump"):
        return _framework_trace_export_records(trace_export.model_dump())
    if hasattr(trace_export, "dict"):
        return _framework_trace_export_records(trace_export.dict())
    if isinstance(trace_export, Mapping):
        export = copy.deepcopy(dict(trace_export))
        otlp_records = _flatten_otlp_resource_spans(export)
        if otlp_records:
            return otlp_records
        if _looks_like_framework_export_record(export):
            return [export]

        records: List[Any] = []
        for key in (
            "traces",
            "spans",
            "events",
            "records",
            "items",
            "results",
            "resource_spans",
            "scope_spans",
        ):
            if key in export:
                records.extend(_framework_trace_export_records(export[key]))
        if records:
            return records

        for key in ("data", "result", "payload", "response", "body"):
            nested = export.get(key)
            if isinstance(nested, (Mapping, list, tuple)):
                nested_records = _framework_trace_export_records(nested)
                if nested_records:
                    return nested_records
        return [export]
    if isinstance(trace_export, Iterable):
        records = []
        for item in trace_export:
            records.extend(_framework_trace_export_records(item))
        return records
    return [trace_export]


def _looks_like_framework_export_record(export: Mapping[str, Any]) -> bool:
    if "spans" in export and not any(key in export for key in ("spanId", "span_id", "id", "run_id")):
        return False
    if "method" in export and "params" in export:
        return True
    if any(key in export for key in ("spanId", "span_id", "id", "run_id", "parentSpanId", "parent_span_id")):
        return True
    if any(key in export for key in ("event", "frame_type", "span_data")):
        return True
    if "name" in export and any(key in export for key in ("attributes", "attrs", "type", "kind", "events", "status")):
        return True
    if "attributes" in export and any(key in export for key in ("type", "kind", "traceId", "trace_id")):
        return True
    return False


def _mcp_tool_session_export_records(
    session_export: Any,
    *,
    server_name: Optional[str] = None,
    session_id: Optional[str] = None,
) -> List[Dict[str, Any]]:
    if session_export is None:
        return []
    if isinstance(session_export, str):
        text = session_export.strip()
        if not text:
            return []
        if text.startswith(("{", "[")) or "\n" in text:
            return _mcp_tool_session_export_records(
                _parse_framework_trace_export_text(text),
                server_name=server_name,
                session_id=session_id,
            )
        return [_mcp_server_record(str(server_name or text), {}, session_id=session_id)]
    if hasattr(session_export, "model_dump"):
        return _mcp_tool_session_export_records(
            session_export.model_dump(),
            server_name=server_name,
            session_id=session_id,
        )
    if hasattr(session_export, "dict"):
        return _mcp_tool_session_export_records(
            session_export.dict(),
            server_name=server_name,
            session_id=session_id,
        )
    if isinstance(session_export, Mapping):
        payload = copy.deepcopy(dict(session_export))
        server = _mcp_server_name(payload, default=server_name)
        current_session_id = str(
            payload.get("session_id")
            or payload.get("sessionId")
            or payload.get("session")
            or session_id
            or ""
        )
        records: List[Dict[str, Any]] = []
        if server:
            records.append(_mcp_server_record(server, payload, session_id=current_session_id))

        for nested_key in ("sessions", "runs"):
            for nested in _as_iterable(payload.get(nested_key)):
                records.extend(
                    _mcp_tool_session_export_records(
                        nested,
                        server_name=server,
                        session_id=current_session_id,
                    )
                )

        for spec in _mcp_tool_specs_from_payload(payload):
            record = _mcp_tool_schema_record(spec, server_name=server, session_id=current_session_id)
            if record:
                records.append(record)

        for index, call in enumerate(_mcp_direct_tool_calls_from_payload(payload), start=1):
            record = _mcp_tool_call_record(
                call,
                server_name=server,
                session_id=current_session_id,
                index=index,
            )
            if record:
                records.append(record)

        for event_key in ("events", "records", "messages", "requests", "responses", "items"):
            events = _as_iterable(payload.get(event_key))
            if events:
                records.extend(
                    _mcp_records_from_event_sequence(
                        events,
                        server_name=server,
                        session_id=current_session_id,
                    )
                )

        for resource in _mcp_resources_from_payload(payload):
            records.append(_mcp_resource_record(resource, server_name=server, session_id=current_session_id))

        if _looks_like_mcp_jsonrpc_record(payload):
            records.extend(
                _mcp_records_from_event_sequence(
                    [payload],
                    server_name=server,
                    session_id=current_session_id,
                )
            )
        return _dedupe_mcp_records(records)
    if isinstance(session_export, Iterable):
        return _mcp_records_from_event_sequence(
            list(session_export),
            server_name=server_name or "mcp",
            session_id=session_id,
        )
    return []


def _mcp_records_from_event_sequence(
    events: Sequence[Any],
    *,
    server_name: Optional[str],
    session_id: Optional[str],
) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    pending_calls: Dict[str, Dict[str, Any]] = {}
    for index, raw_event in enumerate(events, start=1):
        event = _coerce_plain_dict(raw_event)
        if not event:
            continue
        server = _mcp_server_name(event, default=server_name)
        current_session_id = str(
            event.get("session_id")
            or event.get("sessionId")
            or event.get("session")
            or session_id
            or ""
        )
        for spec in _mcp_tool_specs_from_payload(event):
            record = _mcp_tool_schema_record(spec, server_name=server, session_id=current_session_id)
            if record:
                records.append(record)
        call = _mcp_tool_call_payload(event)
        if call:
            call_id = str(call.get("call_id") or "")
            if call_id:
                pending_calls[call_id] = copy.deepcopy(call)
            record = _mcp_tool_call_record(
                call,
                server_name=server,
                session_id=current_session_id,
                index=index,
            )
            if record:
                records.append(record)
            continue
        result = _mcp_tool_result_payload(event, pending_calls)
        if result:
            record = _mcp_tool_call_record(
                result,
                server_name=server,
                session_id=current_session_id,
                index=index,
            )
            if record:
                records.append(record)
            continue
        if _is_mcp_session_wrapper(event):
            records.extend(
                _mcp_tool_session_export_records(
                    event,
                    server_name=server,
                    session_id=current_session_id,
                )
            )
    return _dedupe_mcp_records(records)


def _mcp_tool_specs_from_payload(payload: Mapping[str, Any]) -> List[Dict[str, Any]]:
    specs: List[Dict[str, Any]] = []
    sources = [
        payload,
        _coerce_plain_dict(payload.get("result")),
        _coerce_plain_dict(payload.get("payload")),
        _coerce_plain_dict(payload.get("data")),
        _coerce_plain_dict(payload.get("response")),
        _coerce_plain_dict(payload.get("body")),
    ]
    for source in sources:
        if not source:
            continue
        for key in ("tools", "tool_specs", "toolSchemas", "tool_schemas", "schemas", "available_tools"):
            if key not in source:
                continue
            for spec in _mcp_tool_specs_from_value(source.get(key)):
                if spec:
                    specs.append(spec)
    return _dedupe_mcp_specs(specs)


def _mcp_tool_specs_from_value(value: Any) -> List[Dict[str, Any]]:
    if value is None:
        return []
    if isinstance(value, str):
        return [{"name": value}]
    if isinstance(value, Mapping):
        if _mcp_tool_spec_name(value):
            return [copy.deepcopy(dict(value))]
        specs: List[Dict[str, Any]] = []
        for name, raw_spec in value.items():
            spec = _coerce_plain_dict(raw_spec)
            if not spec and isinstance(raw_spec, str):
                spec = {"description": raw_spec}
            spec.setdefault("name", name)
            specs.append(spec)
        return specs
    specs: List[Dict[str, Any]] = []
    for item in _as_iterable(value):
        specs.extend(_mcp_tool_specs_from_value(item))
    return specs


def _mcp_direct_tool_calls_from_payload(payload: Mapping[str, Any]) -> List[Dict[str, Any]]:
    calls: List[Dict[str, Any]] = []
    sources = [
        payload,
        _coerce_plain_dict(payload.get("result")),
        _coerce_plain_dict(payload.get("payload")),
        _coerce_plain_dict(payload.get("data")),
        _coerce_plain_dict(payload.get("response")),
        _coerce_plain_dict(payload.get("body")),
    ]
    for source in sources:
        for key in ("tool_calls", "calls", "invocations", "executions", "tool_invocations"):
            for item in _as_iterable(source.get(key)):
                call = _mcp_tool_call_payload(item) or _coerce_plain_dict(item)
                if _mcp_tool_name_from_call(call):
                    calls.append(call)
    return calls


def _mcp_resources_from_payload(payload: Mapping[str, Any]) -> List[Dict[str, Any]]:
    resources: List[Dict[str, Any]] = []
    for source in (payload, _coerce_plain_dict(payload.get("result")), _coerce_plain_dict(payload.get("payload"))):
        for key in ("resources", "resource_templates"):
            for item in _as_iterable(source.get(key)):
                item_dict = _coerce_plain_dict(item)
                if item_dict:
                    resources.append(item_dict)
    return resources


def _mcp_server_name(payload: Mapping[str, Any], *, default: Optional[str]) -> str:
    nested = _coerce_plain_dict(payload.get("server"))
    value = payload.get("server_name") or payload.get("serverName") or payload.get("server")
    if not value and str(payload.get("type") or "").lower() in {"server", "mcp_server"}:
        value = payload.get("name")
    if isinstance(value, Mapping):
        value = value.get("name")
    return str(value or nested.get("name") or default or "mcp")


def _mcp_server_record(
    server_name: str,
    payload: Mapping[str, Any],
    *,
    session_id: Optional[str],
) -> Dict[str, Any]:
    attributes = {
        "mcp.server.name": server_name,
        "mcp.session.id": session_id,
    }
    if payload.get("protocol_version") or payload.get("protocolVersion"):
        attributes["mcp.protocol.version"] = payload.get("protocol_version") or payload.get("protocolVersion")
    return {
        "id": f"mcp_server_{_safe_trace_id(server_name)}",
        "span_id": f"mcp_server_{_safe_trace_id(server_name)}",
        "name": f"MCP server {server_name}",
        "type": "mcp_server",
        "framework": "mcp",
        "signals": ["framework", "mcp", "mcp_server"],
        "attributes": {key: value for key, value in attributes.items() if value not in (None, "", [], {})},
    }


def _mcp_tool_schema_record(
    raw_spec: Mapping[str, Any],
    *,
    server_name: str,
    session_id: Optional[str],
) -> Optional[Dict[str, Any]]:
    spec = copy.deepcopy(dict(raw_spec))
    name = _mcp_tool_spec_name(spec)
    if not name:
        return None
    schema = _mcp_tool_schema_from_spec(spec)
    description = spec.get("description") or _coerce_plain_dict(spec.get("function")).get("description")
    attributes = {
        "mcp.server.name": server_name,
        "mcp.session.id": session_id,
        "mcp.tool.name": name,
        "mcp.tool.description": description,
        "mcp.tool.input_schema": schema,
        "parameters": schema,
    }
    return {
        "id": f"mcp_schema_{_safe_trace_id(name)}",
        "span_id": f"mcp_schema_{_safe_trace_id(name)}",
        "name": f"MCP tool schema {name}",
        "type": "mcp_tool_schema",
        "framework": "mcp",
        "tool_name": name,
        "input": schema,
        "signals": ["mcp", "mcp_tool_schema", "tool", "tool_schema"],
        "attributes": {key: copy.deepcopy(value) for key, value in attributes.items() if value not in (None, "", [], {})},
    }


def _mcp_resource_record(
    raw_resource: Mapping[str, Any],
    *,
    server_name: str,
    session_id: Optional[str],
) -> Dict[str, Any]:
    name = str(raw_resource.get("name") or raw_resource.get("uri") or raw_resource.get("template") or "resource")
    attributes = {
        "mcp.server.name": server_name,
        "mcp.session.id": session_id,
        "mcp.resource.name": name,
        "mcp.resource.uri": raw_resource.get("uri"),
        "mcp.resource.mime_type": raw_resource.get("mimeType") or raw_resource.get("mime_type"),
    }
    return {
        "id": f"mcp_resource_{_safe_trace_id(name)}",
        "span_id": f"mcp_resource_{_safe_trace_id(name)}",
        "name": f"MCP resource {name}",
        "type": "mcp_resource",
        "framework": "mcp",
        "signals": ["mcp", "mcp_resource", "retrieval"],
        "attributes": {key: copy.deepcopy(value) for key, value in attributes.items() if value not in (None, "", [], {})},
    }


def _mcp_tool_call_payload(raw: Any) -> Dict[str, Any]:
    event = _coerce_plain_dict(raw)
    if not event:
        return {}
    method = str(event.get("method") or "").lower()
    params = _coerce_plain_dict(event.get("params"))
    function = _coerce_plain_dict(event.get("function"))
    if method and "tools/call" not in method and method not in {"tool_call", "call_tool"}:
        return {}
    if _mcp_tool_spec_name(event) and _mcp_tool_schema_from_spec(event) and not any(
        key in event for key in ("arguments", "args", "input", "result", "output", "content", "error")
    ):
        return {}
    name = (
        event.get("tool_name")
        or event.get("tool")
        or event.get("name")
        or params.get("name")
        or function.get("name")
    )
    if not name:
        return {}
    arguments = (
        event.get("arguments")
        if "arguments" in event
        else event.get("args", event.get("input", params.get("arguments", params.get("input", function.get("arguments", {})))))
    )
    return {
        "call_id": event.get("id") or event.get("call_id") or event.get("tool_call_id") or params.get("id"),
        "name": str(name),
        "arguments": _mcp_parse_arguments(arguments),
        "result": event.get("result", event.get("output", event.get("content"))),
        "error": event.get("error") or event.get("exception"),
        "status": event.get("status"),
        "latency_ms": event.get("latency_ms") or event.get("duration_ms") or event.get("elapsed_ms"),
        "state_updates": event.get("state_updates") or event.get("stateUpdates"),
    }


def _mcp_tool_result_payload(
    raw: Any,
    pending_calls: Mapping[str, Mapping[str, Any]],
) -> Dict[str, Any]:
    event = _coerce_plain_dict(raw)
    if not event:
        return {}
    call_id = str(event.get("id") or event.get("call_id") or event.get("tool_call_id") or "")
    if not call_id or call_id not in pending_calls:
        return {}
    if "result" not in event and "error" not in event and "output" not in event and "content" not in event:
        return {}
    result = copy.deepcopy(dict(pending_calls[call_id]))
    result["result"] = event.get("result", event.get("output", event.get("content")))
    result["error"] = event.get("error") or event.get("exception")
    result["status"] = event.get("status")
    result["latency_ms"] = event.get("latency_ms") or event.get("duration_ms") or event.get("elapsed_ms")
    return result


def _mcp_tool_call_record(
    call: Mapping[str, Any],
    *,
    server_name: str,
    session_id: Optional[str],
    index: int,
) -> Optional[Dict[str, Any]]:
    tool_name = _mcp_tool_name_from_call(call)
    if not tool_name:
        return None
    arguments = _mcp_parse_arguments(call.get("arguments", {}))
    error = _mcp_error_value(call.get("error"))
    output = _mcp_result_value(call.get("result"))
    status = str(call.get("status") or "").lower()
    if status in {"error", "failed", "failure", "exception"} and error is None:
        error = status
    record_type = "mcp_tool_error" if error else "mcp_tool_result" if output is not None else "mcp_tool_call"
    signals = ["mcp", "mcp_tool_call", "tool"]
    if output is not None:
        signals.extend(["mcp_tool_result", "tool_result"])
    if error:
        signals.extend(["error", "mcp_tool_error", "tool_error"])
    call_id = call.get("call_id") or f"{tool_name}_{index}"
    attributes = {
        "mcp.server.name": server_name,
        "mcp.session.id": session_id,
        "mcp.tool.name": tool_name,
        "mcp.request.id": call_id,
        "arguments": arguments,
        "mcp.tool.arguments": arguments,
        "result": output,
        "mcp.tool.result": output,
        "success": not bool(error),
        "state_updates": call.get("state_updates"),
    }
    record = {
        "id": f"mcp_call_{_safe_trace_id(call_id)}",
        "span_id": f"mcp_call_{_safe_trace_id(call_id)}",
        "name": f"MCP tool {'error' if error else 'result' if output is not None else 'call'} {tool_name}",
        "type": record_type,
        "framework": "mcp",
        "tool_name": tool_name,
        "input": arguments,
        "output": output,
        "error": error,
        "latency_ms": _voice_int(call.get("latency_ms")),
        "signals": signals,
        "attributes": {key: copy.deepcopy(value) for key, value in attributes.items() if value not in (None, "", [], {})},
    }
    return {key: copy.deepcopy(value) for key, value in record.items() if value not in (None, "", [], {})}


def _mcp_tool_spec_name(spec: Mapping[str, Any]) -> str:
    function = _coerce_plain_dict(spec.get("function"))
    return str(spec.get("name") or spec.get("tool_name") or spec.get("tool") or function.get("name") or "")


def _mcp_tool_schema_from_spec(spec: Mapping[str, Any]) -> Dict[str, Any]:
    function = _coerce_plain_dict(spec.get("function"))
    schema = (
        spec.get("inputSchema")
        or spec.get("input_schema")
        or spec.get("parameters")
        or spec.get("schema")
        or function.get("parameters")
    )
    if isinstance(schema, str):
        try:
            parsed = json.loads(schema)
            return _coerce_plain_dict(parsed)
        except json.JSONDecodeError:
            return {}
    return _coerce_plain_dict(schema)


def _mcp_tool_name_from_call(call: Mapping[str, Any]) -> str:
    return str(call.get("name") or call.get("tool_name") or call.get("tool") or "")


def _mcp_parse_arguments(value: Any) -> Dict[str, Any]:
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {"value": value}
        return _coerce_plain_dict(parsed)
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    return _coerce_plain_dict(value)


def _mcp_result_value(value: Any) -> Any:
    result = _coerce_plain_dict(value)
    if result:
        if result.get("structuredContent") is not None:
            return copy.deepcopy(result.get("structuredContent"))
        if result.get("structured_content") is not None:
            return copy.deepcopy(result.get("structured_content"))
        content = _as_iterable(result.get("content"))
        if content:
            return _mcp_content_value(content)
        return result
    return copy.deepcopy(value)


def _mcp_content_value(content: Sequence[Any]) -> Any:
    parsed_items: List[Any] = []
    for item in content:
        item_dict = _coerce_plain_dict(item)
        if item_dict.get("json") is not None:
            parsed_items.append(copy.deepcopy(item_dict["json"]))
            continue
        text = item_dict.get("text")
        if isinstance(text, str):
            try:
                parsed_items.append(json.loads(text))
            except json.JSONDecodeError:
                parsed_items.append(text)
            continue
        parsed_items.append(copy.deepcopy(item))
    if len(parsed_items) == 1:
        return parsed_items[0]
    return parsed_items


def _mcp_error_value(value: Any) -> Any:
    error = _coerce_plain_dict(value)
    if error:
        return error.get("message") or error.get("code") or error
    return value


def _looks_like_mcp_jsonrpc_record(value: Mapping[str, Any]) -> bool:
    method = str(value.get("method") or "").lower()
    params = _coerce_plain_dict(value.get("params"))
    result = _coerce_plain_dict(value.get("result"))
    return (
        method.startswith("tools/")
        or bool(params.get("name") and "arguments" in params)
        or bool(result.get("tools"))
        or bool(value.get("jsonrpc") and ("result" in value or "error" in value))
    )


def _is_mcp_session_wrapper(value: Mapping[str, Any]) -> bool:
    return any(key in value for key in ("sessions", "tools", "calls", "tool_calls", "resources"))


def _mcp_tool_session_metadata(
    spans: Sequence[Mapping[str, Any]],
    source_metadata: Mapping[str, Any],
) -> Dict[str, Any]:
    tool_names = sorted({str(span.get("tool_name")) for span in spans if span.get("tool_name")})
    signals = {str(signal) for span in spans for signal in _as_iterable(span.get("signals"))}
    metadata = {
        "span_count": len(spans),
        "tool_count": len(tool_names),
        "tool_names": tool_names,
        "schema_count": sum(1 for span in spans if "mcp_tool_schema" in _as_iterable(span.get("signals"))),
        "call_count": sum(1 for span in spans if "mcp_tool_call" in _as_iterable(span.get("signals"))),
        "result_count": sum(1 for span in spans if "mcp_tool_result" in _as_iterable(span.get("signals"))),
        "error_count": sum(1 for span in spans if "mcp_tool_error" in _as_iterable(span.get("signals"))),
        "signals": sorted(signals),
    }
    if source_metadata:
        metadata["source"] = copy.deepcopy(dict(source_metadata))
    return metadata


def _dedupe_mcp_specs(specs: Sequence[Mapping[str, Any]]) -> List[Dict[str, Any]]:
    deduped: List[Dict[str, Any]] = []
    seen = set()
    for spec in specs:
        name = _mcp_tool_spec_name(spec)
        signature = json.dumps({"name": name, "schema": _mcp_tool_schema_from_spec(spec)}, sort_keys=True, default=str)
        if signature in seen:
            continue
        seen.add(signature)
        deduped.append(copy.deepcopy(dict(spec)))
    return deduped


def _dedupe_mcp_records(records: Sequence[Mapping[str, Any]]) -> List[Dict[str, Any]]:
    deduped: List[Dict[str, Any]] = []
    seen = set()
    for record in records:
        signature = json.dumps(record, sort_keys=True, default=str)
        if signature in seen:
            continue
        seen.add(signature)
        deduped.append(copy.deepcopy(dict(record)))
    return deduped


def _safe_trace_id(value: Any) -> str:
    text = str(value or "").strip().lower()
    cleaned = [character if character.isalnum() else "_" for character in text]
    return "_".join("".join(cleaned).split("_")) or "item"


def _load_framework_event_stream_records(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    headers: Optional[Mapping[str, str]] = None,
    timeout: float = 30.0,
) -> tuple[List[Any], Dict[str, Any]]:
    metadata: Dict[str, Any] = {}
    if isinstance(source, (str, os.PathLike)):
        loaded = _load_framework_trace_export_source(
            source,
            headers=headers,
            timeout=timeout,
        )
        metadata["source"] = _framework_trace_source_label(source)
    else:
        loaded = source
        metadata["source"] = "inline"
    return _framework_trace_export_records(loaded), metadata


def _load_openai_responses_trace_records(
    source: str | os.PathLike[str] | Mapping[str, Any] | Iterable[Any],
    *,
    headers: Optional[Mapping[str, str]] = None,
    timeout: float = 30.0,
) -> tuple[List[Dict[str, Any]], Dict[str, Any]]:
    metadata: Dict[str, Any] = {}
    if isinstance(source, (str, os.PathLike)):
        source_text = os.fspath(source)
        stripped = source_text.strip() if isinstance(source, str) else ""
        if stripped.startswith(("{", "[")) or "\n" in stripped:
            loaded = _parse_framework_trace_export_text(stripped)
            metadata["source"] = "inline_json"
        else:
            loaded = _load_framework_trace_export_source(
                source,
                headers=headers,
                timeout=timeout,
            )
            metadata["source"] = _framework_trace_source_label(source)
    else:
        loaded = source
        metadata["source"] = "inline"

    records = _openai_responses_trace_records(loaded)
    metadata["record_count"] = len(records)
    response_ids = sorted({str(record.get("response_id")) for record in records if record.get("response_id")})
    if response_ids:
        metadata["response_ids"] = response_ids
    return records, metadata


def _openai_responses_trace_records(source: Any) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    call_names: Dict[str, str] = {}

    def walk(value: Any, context: Mapping[str, Any]) -> None:
        value = _openai_plain_value(value)
        if value is None:
            return
        if isinstance(value, str):
            stripped = value.strip()
            if not stripped:
                return
            if stripped.startswith(("{", "[")):
                try:
                    walk(json.loads(stripped), context)
                    return
                except json.JSONDecodeError:
                    pass
            records.append(_openai_responses_message_record({"text": value}, context))
            return
        if isinstance(value, Mapping):
            raw = copy.deepcopy(dict(value))
            if _looks_like_openai_responses_response(raw):
                response_context = _openai_response_context(raw, context)
                output_text = _openai_response_text(raw)
                records.append(
                    {
                        "id": response_context.get("response_id") or raw.get("id") or "response",
                        "name": "response.completed",
                        "type": raw.get("object") or raw.get("type") or "response",
                        "framework": "openai_responses",
                        "response_id": response_context.get("response_id"),
                        "trace_id": response_context.get("response_id"),
                        "model": response_context.get("model"),
                        "usage": _openai_response_usage(raw),
                        "status": raw.get("status"),
                        "output": output_text,
                        "message_text": output_text,
                        "payload": {
                            key: value
                            for key, value in {
                                "response_id": response_context.get("response_id"),
                                "model": response_context.get("model"),
                                "status": raw.get("status"),
                                "usage": _openai_response_usage(raw),
                            }.items()
                            if value not in (None, "", {}, [])
                        },
                    }
                )
                for item in _as_iterable(raw.get("output")):
                    walk(item, response_context)
                return

            event_type = str(raw.get("type") or raw.get("event") or "")
            if event_type in {"response.output_item.added", "response.function_call_arguments.done"}:
                event_context = _openai_response_context(raw, context)
                event_context["output_index"] = raw.get("output_index")
                event_context["stream_event_type"] = event_type
                walk(raw.get("item"), event_context)
                return
            if event_type == "response.function_call_arguments.delta":
                records.append(_openai_responses_argument_delta_record(raw, context))
                return
            if _looks_like_openai_responses_output_item(raw):
                item_record = _openai_responses_output_item_record(raw, context, call_names)
                if item_record:
                    records.append(item_record)
                return

            nested_keys = ("responses", "output", "items", "events", "records", "input", "data", "result", "payload")
            nested_found = False
            for key in nested_keys:
                nested = raw.get(key)
                if isinstance(nested, (Mapping, list, tuple)):
                    nested_found = True
                    walk(nested, _openai_response_context(raw, context))
            if nested_found:
                return
            records.append(_openai_responses_message_record(raw, context))
            return
        if isinstance(value, Iterable):
            for item in value:
                walk(item, context)
            return
        records.append(_openai_responses_message_record({"text": str(value)}, context))

    walk(source, {})
    return [record for record in records if record]


def _openai_plain_value(value: Any) -> Any:
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, (str, Mapping)):
        return value
    if hasattr(value, "model_dump"):
        return value.model_dump()
    if hasattr(value, "dict"):
        return value.dict()
    if isinstance(value, Iterable):
        return value
    if hasattr(value, "__dict__"):
        return vars(value)
    return value


def _looks_like_openai_responses_response(value: Mapping[str, Any]) -> bool:
    if "output" not in value:
        return False
    object_type = str(value.get("object") or value.get("type") or "").lower()
    if object_type in {"response", "responses.response"}:
        return True
    response_id = str(value.get("id") or "")
    return response_id.startswith("resp_") or bool(value.get("model"))


def _looks_like_openai_responses_output_item(value: Mapping[str, Any]) -> bool:
    item_type = str(value.get("type") or "").lower()
    if item_type in {"message", "function_call", "function_call_output"}:
        return True
    if value.get("call_id") and (value.get("name") or value.get("output") is not None):
        return True
    if "content" in value and (value.get("role") or value.get("id")):
        return True
    return False


def _openai_response_context(
    raw: Mapping[str, Any],
    parent: Mapping[str, Any],
) -> Dict[str, Any]:
    context = copy.deepcopy(dict(parent or {}))
    for source_key, target_key in (
        ("response_id", "response_id"),
        ("id", "response_id"),
        ("model", "model"),
        ("created_at", "created_at"),
        ("created", "created_at"),
        ("output_index", "output_index"),
        ("sequence", "sequence"),
        ("index", "sequence"),
        ("stream_event_type", "stream_event_type"),
    ):
        value = raw.get(source_key)
        if value not in (None, "", {}, []):
            context.setdefault(target_key, value)
    return context


def _openai_responses_output_item_record(
    raw: Mapping[str, Any],
    context: Mapping[str, Any],
    call_names: Dict[str, str],
) -> Dict[str, Any]:
    item_type = str(raw.get("type") or "").lower()
    if item_type == "function_call" or (raw.get("call_id") and raw.get("name")):
        return _openai_responses_function_call_record(raw, context, call_names)
    if item_type == "function_call_output" or (raw.get("call_id") and raw.get("output") is not None):
        return _openai_responses_function_output_record(raw, context, call_names)
    return _openai_responses_message_record(raw, context)


def _openai_responses_function_call_record(
    raw: Mapping[str, Any],
    context: Mapping[str, Any],
    call_names: Dict[str, str],
) -> Dict[str, Any]:
    tool_name = str(raw.get("name") or raw.get("tool_name") or "")
    call_id = str(raw.get("call_id") or raw.get("id") or "")
    if call_id and tool_name:
        call_names[call_id] = tool_name
    arguments = _openai_jsonish(raw.get("arguments"), object_default=True)
    payload = _openai_response_context_payload(context)
    payload.update(
        {
            key: value
            for key, value in {
                "tool_name": tool_name,
                "call_id": call_id,
                "arguments": arguments,
                "raw_arguments": raw.get("arguments"),
                "status": raw.get("status"),
                "stream_event_type": context.get("stream_event_type"),
                "output_index": context.get("output_index"),
            }.items()
            if value not in (None, "", {}, [])
        }
    )
    return {
        "id": raw.get("id") or call_id or f"{context.get('response_id', 'response')}:function_call",
        "name": f"function_call {tool_name}".strip(),
        "type": "function_call",
        "framework": "openai_responses",
        "response_id": context.get("response_id"),
        "trace_id": context.get("response_id"),
        "parent_id": context.get("response_id"),
        "tool_name": tool_name,
        "input": arguments,
        "model": context.get("model"),
        "status": raw.get("status"),
        "payload": payload,
    }


def _openai_responses_function_output_record(
    raw: Mapping[str, Any],
    context: Mapping[str, Any],
    call_names: Mapping[str, str],
) -> Dict[str, Any]:
    call_id = str(raw.get("call_id") or raw.get("id") or "")
    tool_name = str(raw.get("name") or raw.get("tool_name") or call_names.get(call_id, ""))
    output = _openai_jsonish(raw.get("output"), object_default=False)
    payload = _openai_response_context_payload(context)
    payload.update(
        {
            key: value
            for key, value in {
                "tool_name": tool_name,
                "call_id": call_id,
                "output": output,
                "status": raw.get("status"),
                "stream_event_type": context.get("stream_event_type"),
                "output_index": context.get("output_index"),
            }.items()
            if value not in (None, "", {}, [])
        }
    )
    record_id = (
        raw.get("id")
        or (f"{call_id}:output" if call_id else f"{context.get('response_id', 'response')}:function_call_output")
    )
    return {
        "id": record_id,
        "name": f"function_call_output {tool_name}".strip(),
        "type": "function_call_output",
        "framework": "openai_responses",
        "response_id": context.get("response_id"),
        "trace_id": context.get("response_id"),
        "parent_id": context.get("response_id"),
        "tool_name": tool_name,
        "output": output,
        "model": context.get("model"),
        "status": raw.get("status"),
        "payload": payload,
    }


def _openai_responses_message_record(
    raw: Mapping[str, Any],
    context: Mapping[str, Any],
) -> Dict[str, Any]:
    text = _openai_response_text(raw)
    role = raw.get("role")
    payload = _openai_response_context_payload(context)
    payload.update(
        {
            key: value
            for key, value in {
                "role": role,
                "message_text": text,
                "status": raw.get("status"),
                "output_index": context.get("output_index"),
            }.items()
            if value not in (None, "", {}, [])
        }
    )
    return {
        "id": raw.get("id") or f"{context.get('response_id', 'response')}:message",
        "name": f"message {role or 'assistant'}",
        "type": raw.get("type") or "message",
        "framework": "openai_responses",
        "response_id": context.get("response_id"),
        "trace_id": context.get("response_id"),
        "parent_id": context.get("response_id"),
        "model": context.get("model"),
        "message_text": text,
        "output": text,
        "status": raw.get("status"),
        "payload": payload,
    }


def _openai_responses_argument_delta_record(
    raw: Mapping[str, Any],
    context: Mapping[str, Any],
) -> Dict[str, Any]:
    event_context = _openai_response_context(raw, context)
    payload = _openai_response_context_payload(event_context)
    payload.update(
        {
            key: value
            for key, value in {
                "item_id": raw.get("item_id"),
                "delta": raw.get("delta"),
                "output_index": raw.get("output_index"),
            }.items()
            if value not in (None, "", {}, [])
        }
    )
    return {
        "id": raw.get("item_id") or f"{event_context.get('response_id', 'response')}:arguments_delta",
        "name": "response.function_call_arguments.delta",
        "type": "function_call_arguments_delta",
        "framework": "openai_responses",
        "response_id": event_context.get("response_id"),
        "trace_id": event_context.get("response_id"),
        "parent_id": event_context.get("response_id"),
        "message_text": str(raw.get("delta") or ""),
        "payload": payload,
    }


def _openai_response_context_payload(context: Mapping[str, Any]) -> Dict[str, Any]:
    return {
        key: copy.deepcopy(value)
        for key, value in {
            "response_id": context.get("response_id"),
            "model": context.get("model"),
            "created_at": context.get("created_at"),
            "sequence": context.get("sequence"),
            "stream_event_type": context.get("stream_event_type"),
        }.items()
        if value not in (None, "", {}, [])
    }


def _openai_response_text(raw: Mapping[str, Any]) -> str:
    output_text = raw.get("output_text")
    if isinstance(output_text, str) and output_text:
        return output_text
    for key in ("text", "message_text", "delta"):
        value = raw.get(key)
        if isinstance(value, str) and value:
            return value
    content = raw.get("content")
    if isinstance(content, str):
        return content
    chunks: List[str] = []
    for item in _as_iterable(content):
        item_dict = _coerce_plain_dict(item)
        if not item_dict:
            if isinstance(item, str):
                chunks.append(item)
            continue
        for key in ("text", "content", "message_text", "delta"):
            value = item_dict.get(key)
            if isinstance(value, str) and value:
                chunks.append(value)
                break
    if chunks:
        return "".join(chunks)

    output = raw.get("output")
    for item in _as_iterable(output):
        item_dict = _coerce_plain_dict(item)
        if item_dict.get("type") == "message":
            text = _openai_response_text(item_dict)
            if text:
                chunks.append(text)
    return "\n".join(chunks)


def _openai_response_usage(raw: Mapping[str, Any]) -> Any:
    usage = raw.get("usage")
    if usage is None:
        return None
    if hasattr(usage, "model_dump"):
        return usage.model_dump()
    if hasattr(usage, "dict"):
        return usage.dict()
    if isinstance(usage, Mapping):
        return copy.deepcopy(dict(usage))
    return usage


def _openai_jsonish(value: Any, *, object_default: bool) -> Any:
    if value in (None, ""):
        return {} if object_default else value
    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError:
            return {"value": value} if object_default else value
        if object_default and not isinstance(parsed, Mapping):
            return {"value": parsed}
        return parsed
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    if isinstance(value, (list, tuple)):
        return copy.deepcopy(list(value))
    return {"value": value} if object_default else value


def _flatten_otlp_resource_spans(export: Mapping[str, Any]) -> List[Dict[str, Any]]:
    resource_spans = export.get("resourceSpans") or export.get("resource_spans")
    if not resource_spans:
        return []

    records: List[Dict[str, Any]] = []
    for resource_span in _as_iterable(resource_spans):
        resource_span_dict = _coerce_plain_dict(resource_span)
        resource = _coerce_plain_dict(resource_span_dict.get("resource"))
        resource_attrs = _otel_attributes_to_dict(resource.get("attributes"))
        schema_url = resource_span_dict.get("schemaUrl") or resource_span_dict.get("schema_url")
        if schema_url:
            resource_attrs.setdefault("otel.resource.schema_url", schema_url)

        scope_spans = (
            resource_span_dict.get("scopeSpans")
            or resource_span_dict.get("scope_spans")
            or resource_span_dict.get("instrumentationLibrarySpans")
            or resource_span_dict.get("instrumentation_library_spans")
        )
        if not scope_spans and resource_span_dict.get("spans"):
            scope_spans = [{"spans": resource_span_dict.get("spans")}]
        for scope_span in _as_iterable(scope_spans):
            scope_span_dict = _coerce_plain_dict(scope_span)
            scope = _coerce_plain_dict(
                scope_span_dict.get("scope")
                or scope_span_dict.get("instrumentationLibrary")
                or scope_span_dict.get("instrumentation_library")
            )
            scope_attrs = _otel_attributes_to_dict(scope.get("attributes"))
            scope_info = {
                key: value
                for key, value in {
                    "name": scope.get("name"),
                    "version": scope.get("version"),
                    "attributes": scope_attrs,
                }.items()
                if value
            }
            for span in _as_iterable(scope_span_dict.get("spans")):
                span_dict = _coerce_plain_dict(span)
                if span_dict:
                    records.append(
                        _flatten_otlp_span(
                            span_dict,
                            resource_attrs=resource_attrs,
                            scope_info=scope_info,
                        )
                    )
    return records


def _flatten_otlp_span(
    span: Mapping[str, Any],
    *,
    resource_attrs: Mapping[str, Any],
    scope_info: Mapping[str, Any],
) -> Dict[str, Any]:
    span_attrs = _otel_attributes_to_dict(span.get("attributes"))
    scope_attrs = _coerce_plain_dict(scope_info.get("attributes"))
    attributes: Dict[str, Any] = {}
    attributes.update(copy.deepcopy(dict(resource_attrs)))
    attributes.update(copy.deepcopy(scope_attrs))
    attributes.update(span_attrs)
    if scope_info.get("name"):
        attributes.setdefault("otel.scope.name", scope_info.get("name"))
    if scope_info.get("version"):
        attributes.setdefault("otel.scope.version", scope_info.get("version"))

    event_payloads: List[Dict[str, Any]] = []
    event_names: List[str] = []
    for event in _as_iterable(span.get("events")):
        event_dict = _coerce_plain_dict(event)
        if not event_dict:
            continue
        event_attrs = _otel_attributes_to_dict(event_dict.get("attributes"))
        event_name = str(event_dict.get("name") or "")
        if event_name:
            event_names.append(event_name)
        event_payloads.append(
            {
                key: value
                for key, value in {
                    "name": event_name,
                    "time_unix_nano": event_dict.get("timeUnixNano") or event_dict.get("time_unix_nano"),
                    "attributes": event_attrs,
                }.items()
                if value not in (None, "", {})
            }
        )
    if event_names:
        attributes.setdefault("otel.event.names", " ".join(event_names))

    status = _coerce_plain_dict(span.get("status"))
    start_nano = _otel_int(span.get("startTimeUnixNano") or span.get("start_time_unix_nano"))
    end_nano = _otel_int(span.get("endTimeUnixNano") or span.get("end_time_unix_nano"))
    record: Dict[str, Any] = {
        "name": span.get("name"),
        "kind": span.get("kind"),
        "trace_id": span.get("traceId") or span.get("trace_id"),
        "span_id": span.get("spanId") or span.get("span_id"),
        "parent_span_id": span.get("parentSpanId") or span.get("parent_span_id"),
        "start_time_unix_nano": start_nano,
        "end_time_unix_nano": end_nano,
        "attributes": attributes,
        "resource": dict(resource_attrs),
        "scope": {key: value for key, value in scope_info.items() if key != "attributes"},
        "status": status,
        "events": event_payloads,
    }
    if start_nano is not None:
        record["timestamp_ms"] = start_nano // 1_000_000
    if start_nano is not None and end_nano is not None and end_nano >= start_nano:
        record["latency_ms"] = (end_nano - start_nano) // 1_000_000
    status_code = str(status.get("code") or "").upper()
    if status_code in {"2", "ERROR", "STATUS_CODE_ERROR"}:
        record["error"] = status.get("message") or status.get("description") or status_code
    return {key: value for key, value in record.items() if value not in (None, "", [], {})}


def _otel_attributes_to_dict(attributes: Any) -> Dict[str, Any]:
    if isinstance(attributes, Mapping):
        if "key" in attributes and "value" in attributes:
            return {str(attributes.get("key")): _otel_value(attributes.get("value"))}
        return {str(key): _otel_value(value) for key, value in attributes.items()}
    result: Dict[str, Any] = {}
    for item in _as_iterable(attributes):
        item_dict = _coerce_plain_dict(item)
        key = item_dict.get("key")
        if key is None:
            continue
        result[str(key)] = _otel_value(item_dict.get("value"))
    return result


def _otel_value(value: Any) -> Any:
    if not isinstance(value, Mapping):
        return value
    if "stringValue" in value:
        return value.get("stringValue")
    if "intValue" in value:
        return _otel_int(value.get("intValue"))
    if "doubleValue" in value:
        try:
            return float(value.get("doubleValue"))
        except (TypeError, ValueError):
            return value.get("doubleValue")
    if "boolValue" in value:
        return bool(value.get("boolValue"))
    if "bytesValue" in value:
        return value.get("bytesValue")
    if "arrayValue" in value:
        array_value = _coerce_plain_dict(value.get("arrayValue"))
        return [_otel_value(item) for item in _as_iterable(array_value.get("values"))]
    if "kvlistValue" in value:
        kvlist_value = _coerce_plain_dict(value.get("kvlistValue"))
        return _otel_attributes_to_dict(kvlist_value.get("values"))
    if set(value.keys()) == {"value"}:
        return _otel_value(value.get("value"))
    return {str(key): _otel_value(item) for key, item in value.items()}


def _otel_int(value: Any) -> Optional[int]:
    if value is None:
        return None
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, (int, float)):
        return int(value)
    try:
        return int(str(value))
    except (TypeError, ValueError):
        return None


