def _normalize_framework_trace_key(value: Any) -> str:
    normalized = str(value).strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")
    return FRAMEWORK_TRACE_ALIASES.get(normalized, normalized)


def _normalize_framework_span(
    value: Any,
    *,
    framework: str,
    category: str = "span",
) -> Dict[str, Any]:
    raw = _framework_record_to_dict(value)
    raw.setdefault("framework", framework)
    span_data = _coerce_plain_dict(raw.get("span_data") or raw.get("span"))
    data = _coerce_plain_dict(raw.get("data"))
    payload = _coerce_plain_dict(raw.get("payload"))
    attributes = _nested_dict(raw, ("attributes", "attrs", "metadata", "data", "payload", "span_data", "resource"))
    attributes.setdefault("source_category", category)
    if raw.get("ns") is not None:
        attributes.setdefault("namespace", raw.get("ns"))
    status = _coerce_plain_dict(raw.get("status"))
    if status.get("code") is not None:
        attributes.setdefault("otel.status.code", status.get("code"))
    if status.get("message") is not None:
        attributes.setdefault("otel.status.message", status.get("message"))

    name = _framework_record_name(raw, span_data=span_data, data=data, payload=payload)
    if name == "framework_event":
        name = str(
            attributes.get("gen_ai.operation.name")
            or attributes.get("gen_ai.tool.name")
            or attributes.get("mcp.tool.name")
            or attributes.get("fi.span.kind")
            or attributes.get("gen_ai.span.kind")
            or name
        )
    native_span_id = (
        raw.get("span_id")
        or raw.get("spanId")
        or data.get("span_id")
        or data.get("spanId")
    )
    trace_id = raw.get("trace_id") or raw.get("traceId") or data.get("trace_id") or data.get("traceId")
    parent_id = _framework_parent_id(raw, data=data)
    span_id = str(
        raw.get("id")
        or native_span_id
        or raw.get("run_id")
        or trace_id
        or data.get("run_id")
        or name
    )
    signals = _framework_signals(raw, attributes, name, span_data=span_data, data=data, payload=payload)
    protocol_event = _framework_protocol_event(raw, data=data, payload=payload, attributes=attributes)
    if protocol_event.get("memory"):
        signals.add("memory")
    if protocol_event.get("skill"):
        signals.add("skill")
    if protocol_event.get("checkpoint"):
        signals.update({"checkpoint", "state", "memory"})
    if protocol_event.get("session"):
        signals.add("session")
    latency_ms = _first_number(
        raw,
        attributes,
        ("latency_ms", "duration_ms", "elapsed_ms", "duration"),
    )
    if latency_ms is None:
        latency_ms = _duration_ms_from_span(raw, attributes)
    output = _first_present(
        (raw, span_data, data, payload, attributes),
        (
            "output",
            "output.value",
            "chunk",
            "gen_ai.completion",
            "gen_ai.output",
            "gen_ai.output.messages",
            "llm.completions",
        ),
    )
    if output is None:
        output = protocol_event.get("message_text") or protocol_event.get("final_output")
    normalized = {
        "id": span_id,
        "name": name,
        "framework": str(raw.get("framework") or framework),
        "type": str(
            raw.get("type")
            or raw.get("kind")
            or raw.get("span_type")
            or raw.get("event")
            or span_data.get("type")
            or category
        ),
        "signals": sorted(signals),
        "trace_id": trace_id,
        "span_id": native_span_id,
        "parent_id": parent_id,
        "parent_span_id": parent_id,
        "input": _first_present(
            (raw, span_data, data, payload, attributes),
            (
                "input",
                "input.value",
                "gen_ai.prompt",
                "gen_ai.input",
                "gen_ai.input.messages",
                "llm.prompts",
            ),
        ),
        "output": output,
        "error": _framework_error(raw, data=data, payload=payload, attributes=attributes),
        "latency_ms": latency_ms,
        "cost": _framework_usage(raw, span_data=span_data, data=data, attributes=attributes),
        "attributes": attributes,
    }
    if protocol_event:
        normalized["framework_event"] = protocol_event
        for source_key, target_key in (
            ("method", "method"),
            ("namespace", "namespace"),
            ("node", "node"),
            ("subgraph", "subgraph"),
            ("speaker", "speaker"),
            ("recipient", "recipient"),
            ("message_type", "message_type"),
            ("tool_name", "tool_name"),
            ("handoff_from", "handoff_from"),
            ("handoff_to", "handoff_to"),
            ("task", "task"),
            ("termination", "termination"),
            ("message_text", "message_text"),
            ("state", "state"),
            ("final_output", "final_output"),
            ("memory", "memory"),
            ("skill", "skill"),
            ("checkpoint", "checkpoint"),
            ("session", "session"),
            ("sequence", "sequence"),
        ):
            value = protocol_event.get(source_key)
            if value not in (None, "", [], {}):
                normalized[target_key] = copy.deepcopy(value)
    for key in (
        "start_time",
        "end_time",
        "timestamp_ms",
        "started_at",
        "ended_at",
        "start_time_unix_nano",
        "end_time_unix_nano",
        "startTimeUnixNano",
        "endTimeUnixNano",
    ):
        if raw.get(key) is not None:
            normalized[key] = raw.get(key)
    for key in ("resource", "scope", "status", "events"):
        if raw.get(key) not in (None, "", [], {}):
            normalized[key] = copy.deepcopy(raw.get(key))
    return {key: value for key, value in normalized.items() if value is not None and value != ""}


def _framework_record_to_dict(value: Any) -> Dict[str, Any]:
    if isinstance(value, str):
        return {"name": value}
    if isinstance(value, Mapping):
        raw = copy.deepcopy(dict(value))
    elif hasattr(value, "model_dump"):
        raw = copy.deepcopy(dict(value.model_dump()))
    elif hasattr(value, "dict"):
        raw = copy.deepcopy(dict(value.dict()))
    elif hasattr(value, "__dict__"):
        raw = copy.deepcopy(dict(vars(value)))
    else:
        raw = {"name": value.__class__.__name__, "value": str(value)}
    if not isinstance(value, Mapping):
        raw.setdefault("class_name", value.__class__.__name__)
    return raw


def _coerce_plain_dict(value: Any) -> Dict[str, Any]:
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    if hasattr(value, "model_dump"):
        return copy.deepcopy(dict(value.model_dump()))
    if hasattr(value, "dict"):
        return copy.deepcopy(dict(value.dict()))
    if hasattr(value, "__dict__"):
        return copy.deepcopy(dict(vars(value)))
    return {}


def _framework_protocol_event(
    raw: Mapping[str, Any],
    *,
    data: Mapping[str, Any],
    payload: Mapping[str, Any],
    attributes: Mapping[str, Any],
) -> Dict[str, Any]:
    span_data = _coerce_plain_dict(raw.get("span_data") or raw.get("span"))
    params = _coerce_plain_dict(raw.get("params") or data.get("params") or payload.get("params"))
    params_data = _coerce_plain_dict(params.get("data"))
    if not params_data:
        params_data = _coerce_plain_dict(data.get("data") or payload.get("data"))

    method = raw.get("method") or params.get("method") or data.get("method") or payload.get("method")
    namespace = (
        params.get("namespace")
        or raw.get("namespace")
        or raw.get("ns")
        or data.get("namespace")
        or attributes.get("namespace")
    )
    node = (
        raw.get("node")
        or params_data.get("node")
        or params_data.get("langgraph_node")
        or attributes.get("node")
        or attributes.get("langgraph_node")
    )
    segments = _framework_namespace_segments(namespace)
    if not node and segments:
        node = segments[-1]
    subgraph = (
        raw.get("subgraph")
        or raw.get("graph_name")
        or params_data.get("subgraph")
        or params_data.get("graph_name")
        or attributes.get("subgraph")
        or attributes.get("graph_name")
    )
    if not subgraph and len(segments) > 1:
        subgraph = segments[-2]
    speaker = _framework_agent_name_from_sources(
        raw,
        params,
        params_data,
        data,
        payload,
        span_data,
        attributes,
    )
    if not node and speaker:
        node = speaker
    message_type = _framework_message_type_from_sources(raw, params_data, data, payload, span_data)
    tool_name = (
        _framework_tool_name_from_payload(params_data)
        or _framework_tool_name_from_payload(raw)
        or _framework_tool_name_from_payload(data)
        or _framework_tool_name_from_payload(payload)
        or _framework_tool_name_from_payload(span_data)
        or _framework_tool_name_from_payload(attributes)
    )
    message_text = (
        _framework_text_from_payload(params_data)
        or _framework_text_from_payload(raw)
        or _framework_text_from_payload(data)
        or _framework_text_from_payload(payload)
        or _framework_text_from_payload(span_data)
    )
    handoff_from, handoff_to = _framework_handoff_agents_from_sources(
        raw,
        params_data,
        data,
        payload,
        span_data,
        attributes,
        fallback_speaker=speaker,
    )
    recipient = _first_present(
        (params_data, data, payload, span_data, raw, attributes),
        ("recipient", "target", "to", "to_agent", "handoff_to"),
    )
    if handoff_to and not recipient:
        recipient = handoff_to
    task = _first_present(
        (params_data, data, payload, span_data, raw, attributes),
        ("task", "task_description", "description", "handoff_task", "assignment"),
    )
    termination = _framework_termination_from_sources(
        raw,
        params_data,
        data,
        payload,
        span_data,
        attributes,
        text=message_text,
    )
    memory = _framework_memory_payload_from_sources(
        raw,
        params,
        params_data,
        data,
        payload,
        span_data,
        attributes,
    )
    skill = _framework_skill_payload_from_sources(
        raw,
        params,
        params_data,
        data,
        payload,
        span_data,
        attributes,
    )
    checkpoint = _framework_checkpoint_payload_from_sources(
        raw,
        params,
        params_data,
        data,
        payload,
        span_data,
        attributes,
    )
    session = _framework_session_payload_from_sources(
        raw,
        params,
        params_data,
        data,
        payload,
        span_data,
        attributes,
        checkpoint=checkpoint,
    )
    final_output = _first_present(
        (params_data, data, payload, raw),
        ("final_output", "output", "result"),
    )
    state: Any = None
    normalized_method = str(method or "").lower()
    if normalized_method in {"values", "updates", "state", "checkpoints", "tasks"}:
        state = params_data or data or payload
    elif params_data.get("state") is not None:
        state = params_data.get("state")

    event = {
        "sequence": raw.get("seq") or raw.get("sequence") or raw.get("index"),
        "method": method,
        "namespace": namespace,
        "node": node,
        "subgraph": subgraph,
        "speaker": speaker,
        "recipient": recipient,
        "message_type": message_type,
        "tool_name": tool_name,
        "handoff_from": handoff_from,
        "handoff_to": handoff_to,
        "task": task,
        "termination": termination,
        "message_text": message_text,
        "state": state,
        "final_output": final_output,
        "memory": memory,
        "skill": skill,
        "checkpoint": checkpoint,
        "session": session,
        "data": params_data,
    }
    return {key: copy.deepcopy(value) for key, value in event.items() if value not in (None, "", [], {})}


def _framework_namespace_segments(value: Any) -> List[str]:
    if isinstance(value, (list, tuple)):
        raw_segments = [str(item) for item in value]
    elif isinstance(value, str):
        raw_segments = value.replace(">", "/").replace(".", "/").split("/")
    else:
        return []
    segments: List[str] = []
    for segment in raw_segments:
        segment = segment.strip()
        if not segment:
            continue
        if ":" in segment:
            segment = segment.split(":", 1)[0]
        segments.append(segment)
    return segments


def _framework_tool_name_from_payload(value: Mapping[str, Any]) -> str:
    for key in ("tool_name", "tool", "name"):
        if value.get(key):
            return str(value.get(key))
    for key in ("tool_call", "call"):
        nested = _coerce_plain_dict(value.get(key))
        if nested.get("name") or nested.get("tool_name"):
            return str(nested.get("name") or nested.get("tool_name"))
    for key in ("content", "tool_calls", "function_calls", "calls"):
        for item in _as_iterable(value.get(key)):
            item_dict = _coerce_plain_dict(item)
            if item_dict.get("name") or item_dict.get("tool_name"):
                return str(item_dict.get("name") or item_dict.get("tool_name"))
            function = _coerce_plain_dict(item_dict.get("function"))
            if function.get("name"):
                return str(function.get("name"))
    return ""


def _framework_text_from_payload(value: Mapping[str, Any]) -> str:
    for key in ("text", "content", "message_text", "delta"):
        if isinstance(value.get(key), str) and value.get(key):
            return str(value.get(key))
    chunk = value.get("chunk")
    if isinstance(chunk, str):
        return chunk
    chunk_dict = _coerce_plain_dict(chunk)
    for key in ("content", "text", "message_text"):
        if chunk_dict.get(key):
            return str(chunk_dict.get(key))
    return ""


def _framework_agent_name_from_sources(*sources: Mapping[str, Any]) -> str:
    keys = (
        "speaker",
        "source",
        "sender",
        "agent",
        "agent_name",
        "agent_role",
        "role",
        "from_agent",
        "gen_ai.agent.name",
        "agent.name",
        "autogen.agent.name",
        "crewai.agent.role",
        "crewai.agent.name",
        "openai.agent.name",
    )
    for source in sources:
        if not isinstance(source, Mapping):
            continue
        for key in keys:
            value = source.get(key)
            if value not in (None, "", [], {}):
                return str(value)
    return ""


def _framework_message_type_from_sources(*sources: Mapping[str, Any]) -> str:
    for source in sources:
        if not isinstance(source, Mapping):
            continue
        for key in ("message_type", "type", "event", "class_name", "kind"):
            value = source.get(key)
            if value not in (None, "", [], {}):
                return str(value)
    return ""


def _framework_handoff_agents_from_sources(
    *sources: Mapping[str, Any],
    fallback_speaker: str = "",
) -> tuple[str, str]:
    from_agent = ""
    to_agent = ""
    for source in sources:
        if not isinstance(source, Mapping):
            continue
        from_agent = from_agent or str(
            source.get("from_agent")
            or source.get("handoff_from")
            or source.get("source_agent")
            or source.get("source")
            or ""
        )
        to_agent = to_agent or str(
            source.get("to_agent")
            or source.get("handoff_to")
            or source.get("target_agent")
            or source.get("recipient")
            or source.get("target")
            or source.get("to")
            or ""
        )
    text = " ".join(
        str(source.get(key, ""))
        for source in sources
        if isinstance(source, Mapping)
        for key in ("event", "type", "name", "class_name")
    ).lower()
    if "handoff" not in text and "transfer" not in text and not to_agent:
        return "", ""
    return from_agent or fallback_speaker, to_agent


def _framework_termination_from_sources(
    *sources: Mapping[str, Any],
    text: str = "",
) -> str:
    for source in sources:
        if not isinstance(source, Mapping):
            continue
        for key in ("termination", "stop_reason", "finish_reason", "finish", "terminated"):
            value = source.get(key)
            if value not in (None, "", [], {}):
                return str(value)
    combined = " ".join(
        [
            text,
            *[
                str(source.get(key, ""))
                for source in sources
                if isinstance(source, Mapping)
                for key in ("event", "type", "name", "class_name", "status")
            ],
        ]
    )
    lowered = combined.lower()
    if "terminate" in lowered or "termination" in lowered or "completed" in lowered or "final_answer" in lowered:
        return combined.strip()
    return ""


def _framework_memory_payload_from_sources(*sources: Mapping[str, Any]) -> Dict[str, Any]:
    text = _framework_sources_text(*sources)
    if not any(token in text for token in ("memory", "checkpoint", "session")):
        return {}
    operation = _framework_value_from_sources(
        sources,
        ("memory_operation", "operation", "op", "memory.operation", "checkpoint.operation", "session.operation"),
    )
    key = _framework_value_from_sources(
        sources,
        ("memory_key", "key", "memory.key", "checkpoint_key", "checkpoint.key", "session_key", "session.key"),
    )
    value = _framework_value_from_sources(
        sources,
        ("memory_value", "value", "memory.value", "checkpoint_value", "checkpoint.value", "session_value", "session.value"),
    )
    nested = _framework_mapping_from_sources(sources, ("memory", "checkpoint", "session"))
    payload: Dict[str, Any] = {}
    if operation not in (None, "", [], {}):
        payload["operation"] = operation
    if key not in (None, "", [], {}):
        payload["key"] = key
    if value not in (None, "", [], {}):
        payload["value"] = value
    if nested:
        semantic_keys = {"operation", "op", "key", "value"}
        if not payload and not semantic_keys.intersection(nested.keys()):
            payload["values"] = copy.deepcopy(nested)
        elif not payload.get("value") and not payload.get("key"):
            payload["values"] = copy.deepcopy(nested)
    return {key: copy.deepcopy(value) for key, value in payload.items() if value not in (None, "", [], {})}


def _framework_skill_payload_from_sources(*sources: Mapping[str, Any]) -> Dict[str, Any]:
    text = _framework_sources_text(*sources)
    if "skill" not in text:
        return {}
    name = _framework_value_from_sources(
        sources,
        ("skill_name", "skill.name", "name"),
    )
    steps = _framework_value_from_sources(
        sources,
        ("skill_steps", "steps", "skill.steps"),
    )
    payload: Dict[str, Any] = {}
    if name not in (None, "", [], {}):
        payload["name"] = name
    if steps not in (None, "", [], {}):
        payload["steps"] = copy.deepcopy(steps)
    nested = _framework_mapping_from_sources(sources, ("skill", "skill_library"))
    if nested:
        for key, value in nested.items():
            payload.setdefault(str(key), copy.deepcopy(value))
    return {key: copy.deepcopy(value) for key, value in payload.items() if value not in (None, "", [], {})}


def _framework_checkpoint_payload_from_sources(*sources: Mapping[str, Any]) -> Dict[str, Any]:
    text = _framework_sources_text(*sources)
    method = str(
        _framework_value_from_sources(sources, ("method", "type", "event"))
        or ""
    ).lower()
    checkpoint_hint = (
        "checkpoint" in text
        or method in {"checkpoint", "checkpoints"}
        or _framework_value_from_sources(
            sources,
            (
                "checkpoint_id",
                "checkpoint.id",
                "checkpoint.checkpoint_id",
                "config.configurable.checkpoint_id",
                "metadata.checkpoint_id",
            ),
        )
        not in (None, "", [], {})
    )
    if not checkpoint_hint:
        return {}

    checkpoint = _framework_mapping_from_sources(
        sources,
        (
            "checkpoint",
            "checkpoint_state",
            "langgraph.checkpoint",
            "langgraph_checkpoint",
        ),
    )
    config = _framework_mapping_from_sources(sources, ("config", "checkpoint_config"))
    parent_config = _framework_mapping_from_sources(
        sources,
        ("parent_config", "parentConfig", "parent_checkpoint_config", "parentCheckpointConfig"),
    )
    metadata = _framework_mapping_from_sources(sources, ("checkpoint_metadata", "metadata"))
    configurable = _coerce_plain_dict(config.get("configurable"))
    parent_configurable = _coerce_plain_dict(parent_config.get("configurable"))

    checkpoint_id = _first_framework_value(
        checkpoint.get("id"),
        checkpoint.get("checkpoint_id"),
        checkpoint.get("checkpointId"),
        configurable.get("checkpoint_id"),
        configurable.get("checkpointId"),
        metadata.get("checkpoint_id"),
        _framework_value_from_sources(
            sources,
            ("checkpoint_id", "checkpointId", "checkpoint.id", "checkpoint.checkpoint_id"),
        ),
    )
    parent_checkpoint_id = _first_framework_value(
        checkpoint.get("parent_checkpoint_id"),
        checkpoint.get("parentCheckpointId"),
        parent_configurable.get("checkpoint_id"),
        parent_configurable.get("checkpointId"),
        _framework_value_from_sources(
            sources,
            (
                "parent_checkpoint_id",
                "parentCheckpointId",
                "parent_config.configurable.checkpoint_id",
                "parentConfig.configurable.checkpointId",
            ),
        ),
    )
    thread_id = _first_framework_value(
        checkpoint.get("thread_id"),
        checkpoint.get("threadId"),
        configurable.get("thread_id"),
        configurable.get("threadId"),
        metadata.get("thread_id"),
        _framework_value_from_sources(
            sources,
            ("thread_id", "threadId", "session_id", "sessionId", "config.configurable.thread_id"),
        ),
    )
    namespace = _first_framework_value(
        checkpoint.get("checkpoint_ns"),
        checkpoint.get("checkpoint_namespace"),
        checkpoint.get("namespace"),
        configurable.get("checkpoint_ns"),
        configurable.get("checkpointNamespace"),
        _framework_value_from_sources(
            sources,
            ("checkpoint_ns", "checkpoint_namespace", "checkpoint.namespace", "namespace", "ns"),
        ),
    )
    values = _first_framework_value(
        checkpoint.get("values"),
        checkpoint.get("channel_values"),
        checkpoint.get("channelValues"),
        checkpoint.get("state"),
        _framework_value_from_sources(
            sources,
            ("values", "channel_values", "channelValues", "state", "checkpoint.values", "checkpoint.channel_values"),
        ),
    )
    updates = _first_framework_value(
        checkpoint.get("updates"),
        checkpoint.get("writes"),
        checkpoint.get("updated_channels"),
        checkpoint.get("updatedChannels"),
        _framework_value_from_sources(
            sources,
            ("updates", "writes", "updated_channels", "updatedChannels", "checkpoint.updates"),
        ),
    )
    payload: Dict[str, Any] = {}
    for key, value in (
        ("id", checkpoint_id),
        ("thread_id", thread_id),
        ("namespace", namespace),
        ("parent_checkpoint_id", parent_checkpoint_id),
        ("values", values),
        ("updates", updates),
        ("metadata", metadata),
        ("config", config),
        ("parent_config", parent_config),
    ):
        if value not in (None, "", [], {}):
            payload[key] = copy.deepcopy(value)
    return payload


def _framework_session_payload_from_sources(
    *sources: Mapping[str, Any],
    checkpoint: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    checkpoint = checkpoint or {}
    text = _framework_sources_text(*sources)
    thread_id = _first_framework_value(
        checkpoint.get("thread_id"),
        _framework_value_from_sources(
            sources,
            (
                "thread_id",
                "threadId",
                "session_id",
                "sessionId",
                "conversation_id",
                "conversationId",
                "config.configurable.thread_id",
            ),
        ),
    )
    session_id = _first_framework_value(
        _framework_value_from_sources(
            sources,
            ("session_id", "sessionId", "conversation_id", "conversationId"),
        ),
        thread_id,
    )
    if session_id in (None, "", [], {}) and "session" not in text and not checkpoint:
        return {}

    namespace = _first_framework_value(
        checkpoint.get("namespace"),
        _framework_value_from_sources(
            sources,
            ("checkpoint_ns", "checkpoint_namespace", "namespace", "ns", "config.configurable.checkpoint_ns"),
        ),
    )
    checkpoint_id = _first_framework_value(
        checkpoint.get("id"),
        _framework_value_from_sources(
            sources,
            ("checkpoint_id", "checkpointId", "config.configurable.checkpoint_id"),
        ),
    )
    payload: Dict[str, Any] = {}
    for key, value in (
        ("id", session_id),
        ("thread_id", thread_id),
        ("namespace", namespace),
        ("checkpoint_id", checkpoint_id),
    ):
        if value not in (None, "", [], {}):
            payload[key] = copy.deepcopy(value)
    return payload


def _first_framework_value(*values: Any) -> Any:
    for value in values:
        if value not in (None, "", [], {}):
            return value
    return None


def _framework_value_from_sources(
    sources: Iterable[Mapping[str, Any]],
    keys: Iterable[str],
) -> Any:
    for source in sources:
        if not isinstance(source, Mapping):
            continue
        for key in keys:
            value = _framework_value_from_source(source, key)
            if value not in (None, "", [], {}):
                return value
    return None


def _framework_mapping_from_sources(
    sources: Iterable[Mapping[str, Any]],
    keys: Iterable[str],
) -> Dict[str, Any]:
    value = _framework_value_from_sources(sources, keys)
    return _coerce_plain_dict(value)


def _framework_value_from_source(source: Mapping[str, Any], path: str) -> Any:
    if path in source:
        return source.get(path)
    current: Any = source
    for part in path.split("."):
        if isinstance(current, Mapping) and part in current:
            current = current.get(part)
        else:
            return None
    return current


def _framework_sources_text(*sources: Mapping[str, Any]) -> str:
    parts: List[str] = []
    for source in sources:
        if not isinstance(source, Mapping):
            continue
        parts.extend(str(key) for key in source.keys())
        parts.extend(
            str(value)
            for value in source.values()
            if isinstance(value, (str, int, float, bool))
        )
    return " ".join(parts).lower()


def _framework_record_name(
    raw: Mapping[str, Any],
    *,
    span_data: Mapping[str, Any],
    data: Mapping[str, Any],
    payload: Mapping[str, Any],
) -> str:
    event = raw.get("event") or data.get("event") or payload.get("event")
    base = (
        raw.get("name")
        or raw.get("span_name")
        or raw.get("operation")
        or raw.get("frame_type")
        or raw.get("frame")
        or span_data.get("name")
        or span_data.get("type")
        or data.get("name")
        or payload.get("name")
        or raw.get("type")
        or raw.get("class_name")
    )
    if not base and event:
        return str(event)
    base = base or "framework_event"
    if event and str(event) not in str(base):
        return f"{event} {base}"
    return str(base)


def _framework_parent_id(raw: Mapping[str, Any], *, data: Mapping[str, Any]) -> Any:
    parent_ids = raw.get("parent_ids") or data.get("parent_ids")
    if isinstance(parent_ids, (list, tuple)) and parent_ids:
        return parent_ids[-1]
    return (
        raw.get("parent_id")
        or raw.get("parent_span_id")
        or raw.get("parentSpanId")
        or raw.get("parent_run_id")
        or data.get("parent_id")
        or data.get("parent_span_id")
        or data.get("parentSpanId")
    )


def _framework_signals(
    raw: Mapping[str, Any],
    attributes: Mapping[str, Any],
    name: str,
    *,
    span_data: Optional[Mapping[str, Any]] = None,
    data: Optional[Mapping[str, Any]] = None,
    payload: Optional[Mapping[str, Any]] = None,
) -> set[str]:
    span_data = span_data or {}
    data = data or {}
    payload = payload or {}
    text = " ".join(
        [
            name,
            str(raw.get("type", "")),
            str(raw.get("kind", "")),
            str(raw.get("span_type", "")),
            str(raw.get("event", "")),
            str(raw.get("frame_type", "")),
            str(raw.get("class_name", "")),
            str(span_data.get("type", "")),
            str(data.get("type", "")),
            str(payload.get("type", "")),
            " ".join(str(key) for key in raw.keys()),
            " ".join(
                str(item)
                for item in raw.values()
                if isinstance(item, (str, int, float, bool))
            ),
            " ".join(str(key) for key in attributes.keys()),
            " ".join(
                str(value)
                for value in attributes.values()
                if isinstance(value, (str, int, float, bool))
            ),
            " ".join(str(key) for key in span_data.keys()),
            " ".join(str(key) for key in data.keys()),
            " ".join(str(key) for key in payload.keys()),
            " ".join(
                str(event.get("name", ""))
                for event in _as_iterable(raw.get("events"))
                if isinstance(event, Mapping)
            ),
        ]
    ).lower()
    signals = {"span"}
    for source in (raw, data, payload, attributes):
        for signal in _as_iterable(source.get("signals")):
            if signal not in (None, "", [], {}):
                signals.add(str(signal))
    if raw.get("framework"):
        signals.add("framework")
    keyword_signals = {
        "agent": "agent",
        "chain": "agent",
        "graph": "agent",
        "node": "agent",
        "messages": "model",
        "llm": "model",
        "model": "model",
        "generation": "model",
        "tool": "tool",
        "function": "tool",
        "mcp": "tool",
        "autogen": "agent",
        "llamaindex": "retrieval",
        "llama_index": "retrieval",
        "query_engine": "retrieval",
        "dspy": "agent",
        "predict": "model",
        "module": "agent",
        "task": "agent",
        "crew": "agent",
        "flow": "agent",
        "handoff": "handoff",
        "transfer": "handoff",
        "guardrail": "guardrail",
        "retriev": "retrieval",
        "rag": "retrieval",
        "vector": "retrieval",
        "memory": "memory",
        "skill": "skill",
        "skill_library": "skill",
        "browser": "browser",
        "computer": "browser",
        "cua": "browser",
        "voice": "voice",
        "livekit": "voice",
        "pipecat": "voice",
        "audio": "voice",
        "speech": "voice",
        "transcri": "voice",
        "tts": "voice",
        "stt": "voice",
        "image": "image",
        "vision": "image",
        "state": "state",
        "checkpoint": "state",
        "updates": "state",
        "values": "state",
        "interrupt": "interrupt",
        "barge": "interrupt",
        "frame": "frame",
        "error": "error",
        "exception": "error",
        "latency": "latency",
        "duration": "latency",
        "token": "cost",
        "cost": "cost",
        "usage": "cost",
        "span_kind": "span",
        "retriever": "retrieval",
        "retrieval_documents": "retrieval",
    }
    for token, signal in keyword_signals.items():
        if token in text:
            signals.add(signal)

    span_kind = str(
        _first_present(
            (attributes,),
            ("gen_ai.span.kind", "fi.span.kind", "openinference.span.kind", "span.kind"),
        )
        or ""
    ).lower()
    operation = str(
        _first_present(
            (attributes,),
            ("gen_ai.operation.name", "llm.operation", "operation.name", "otel.operation"),
        )
        or ""
    ).lower()
    explicit_signal_groups = {
        "agent": ("agent", "chain", "workflow", "graph", "task", "crew", "flow"),
        "model": ("llm", "model", "chat", "generation", "embedding", "embedder", "predict"),
        "tool": ("tool", "function", "execute_tool", "tool_call", "mcp_tool"),
        "retrieval": ("retriev", "rag", "vector", "query", "search"),
        "guardrail": ("guardrail", "safety"),
        "memory": ("memory",),
        "skill": ("skill",),
        "browser": ("browser", "computer", "cua"),
        "voice": ("voice", "audio", "speech", "transcri", "tts", "stt"),
        "image": ("image", "vision"),
    }
    for signal, tokens in explicit_signal_groups.items():
        if any(token in span_kind or token in operation for token in tokens):
            signals.add(signal)
    if "checkpoint" in text:
        signals.update({"checkpoint", "state"})
    if "session" in text:
        signals.add("session")
    if any(token in text for token in ("checkpoint", "session")):
        signals.add("memory")
    if any(str(key).startswith("mcp.resource") for key in attributes.keys()):
        signals.add("retrieval")
    if _first_number(raw, attributes, ("latency_ms", "duration_ms", "elapsed_ms")) is not None:
        signals.add("latency")
    if _duration_ms_from_span(raw, attributes) is not None:
        signals.add("latency")
    if raw.get("error") or raw.get("exception") or attributes.get("error"):
        signals.add("error")
    status_code = str(attributes.get("otel.status.code") or "").upper()
    if status_code in {"2", "ERROR", "STATUS_CODE_ERROR"}:
        signals.add("error")
    if (
        raw.get("cost")
        or attributes.get("cost")
        or attributes.get("usage")
        or attributes.get("gen_ai.usage")
        or data.get("usage")
        or data.get("usage_metadata")
        or any(str(key).startswith("gen_ai.usage.") for key in attributes.keys())
        or any(str(key).startswith("llm.token_count.") for key in attributes.keys())
    ):
        signals.add("cost")
    return {_normalize_framework_trace_key(signal) for signal in signals if signal}


def _nested_dict(value: Mapping[str, Any], keys: Iterable[str]) -> Dict[str, Any]:
    merged: Dict[str, Any] = {}
    for key in keys:
        candidate = value.get(key)
        if isinstance(candidate, Mapping):
            merged.update(copy.deepcopy(dict(candidate)))
    return merged


def _first_present(
    sources: Iterable[Mapping[str, Any]],
    keys: Iterable[str],
) -> Any:
    for source in sources:
        for key in keys:
            if key in source and source.get(key) not in (None, ""):
                return source.get(key)
    return None


def _first_number(
    raw: Mapping[str, Any],
    attributes: Mapping[str, Any],
    keys: Iterable[str],
) -> Optional[int]:
    for source in (raw, attributes):
        for key in keys:
            value = source.get(key)
            if isinstance(value, (int, float)):
                return int(value)
            if isinstance(value, str):
                try:
                    return int(float(value))
                except ValueError:
                    continue
    return None


def _duration_ms_from_span(
    raw: Mapping[str, Any],
    attributes: Mapping[str, Any],
) -> Optional[int]:
    start_nano = _first_number(raw, attributes, ("start_time_unix_nano", "startTimeUnixNano"))
    end_nano = _first_number(raw, attributes, ("end_time_unix_nano", "endTimeUnixNano"))
    if start_nano is None or end_nano is None or end_nano < start_nano:
        return None
    return (end_nano - start_nano) // 1_000_000


def _framework_error(
    raw: Mapping[str, Any],
    *,
    data: Mapping[str, Any],
    payload: Mapping[str, Any],
    attributes: Mapping[str, Any],
) -> Any:
    error = raw.get("error") or raw.get("exception") or data.get("error") or payload.get("error") or attributes.get("error")
    if error:
        return error
    status = _coerce_plain_dict(raw.get("status"))
    status_code = str(status.get("code") or attributes.get("otel.status.code") or "").upper()
    if status_code in {"2", "ERROR", "STATUS_CODE_ERROR"}:
        return status.get("message") or attributes.get("otel.status.message") or status_code
    return None


def _framework_usage(
    raw: Mapping[str, Any],
    *,
    span_data: Mapping[str, Any],
    data: Mapping[str, Any],
    attributes: Mapping[str, Any],
) -> Any:
    direct = (
        raw.get("cost")
        or raw.get("usage")
        or raw.get("usage_metadata")
        or span_data.get("usage")
        or data.get("usage")
        or data.get("usage_metadata")
        or attributes.get("cost")
        or attributes.get("usage")
        or attributes.get("gen_ai.usage")
    )
    if direct:
        return direct
    usage_keys = {
        "gen_ai.usage.input_tokens": "input_tokens",
        "gen_ai.usage.output_tokens": "output_tokens",
        "gen_ai.usage.total_tokens": "total_tokens",
        "llm.token_count.prompt": "input_tokens",
        "llm.token_count.completion": "output_tokens",
        "llm.token_count.total": "total_tokens",
        "input_token_count": "input_tokens",
        "output_token_count": "output_tokens",
        "total_token_count": "total_tokens",
    }
    usage = {
        normalized_key: value
        for key, normalized_key in usage_keys.items()
        if (value := attributes.get(key)) is not None
    }
    return usage or None


def _framework_span_event(span: Mapping[str, Any], framework: str) -> SimulationEvent:
    return SimulationEvent(
        type="framework_span",
        name=str(span.get("name") or "framework_span"),
        payload=copy.deepcopy(dict(span)),
        timestamp_ms=span.get("timestamp_ms"),
        metadata={
            "framework": str(span.get("framework") or framework),
            "signals": list(span.get("signals", [])),
        },
    )


def _find_framework_span(
    spans: Iterable[Mapping[str, Any]],
    span_id: str,
) -> Optional[Mapping[str, Any]]:
    if not span_id:
        return None
    for span in spans:
        if span_id in {str(span.get("id")), str(span.get("span_id")), str(span.get("name"))}:
            return span
    return None


def _streaming_trace_export_records(trace_export: Any) -> List[Any]:
    if trace_export is None:
        return []
    if isinstance(trace_export, str):
        stripped = trace_export.strip()
        if not stripped:
            return []
        try:
            parsed = json.loads(stripped)
            return _streaming_trace_export_records(parsed)
        except json.JSONDecodeError:
            return [{"type": "chunk", "delta": trace_export}]
    if isinstance(trace_export, Mapping):
        export = _coerce_plain_dict(trace_export)
        if export.get("kind") == "streaming_trace" and isinstance(export.get("events"), list):
            return list(export.get("events") or [])
        records: List[Any] = []
        for key in ("events", "stream_events", "records", "items", "chunks", "frames"):
            if key in export:
                records.extend(_streaming_trace_export_records(export.get(key)))
        if records:
            return records
        if _looks_like_streaming_record(export):
            return [export]
        data = export.get("data")
        if data is not None and data is not export:
            records.extend(_streaming_trace_export_records(data))
        if records:
            return records
        return [export]
    if isinstance(trace_export, Iterable):
        records = []
        for item in trace_export:
            records.extend(_streaming_trace_export_records(item))
        return records
    return [trace_export]


def _looks_like_streaming_record(export: Mapping[str, Any]) -> bool:
    return any(
        key in export
        for key in (
            "id",
            "event_id",
            "type",
            "event",
            "kind",
            "frame_type",
            "frame",
            "delta",
            "content",
            "text",
            "tool_call",
            "tool_calls",
            "tool_call_chunks",
            "timestamp_ms",
            "timestamp",
            "latency_ms",
            "gap_ms",
        )
    )


def _normalize_streaming_event(record: Any, *, framework: str, sequence: int) -> Dict[str, Any]:
    if isinstance(record, str):
        raw: Dict[str, Any] = {"type": "chunk", "delta": record}
    else:
        raw = _coerce_plain_dict(record)
        if not raw:
            raw = {"type": "event", "value": copy.deepcopy(record)}

    data = _coerce_plain_dict(raw.get("data"))
    payload = _coerce_plain_dict(raw.get("payload"))
    metadata = _coerce_plain_dict(raw.get("metadata"))
    attributes = _coerce_plain_dict(raw.get("attributes") or raw.get("attrs"))
    chunk = _coerce_plain_dict(raw.get("chunk") or data.get("chunk") or payload.get("chunk"))
    delta_payload = _coerce_plain_dict(raw.get("delta") or data.get("delta") or payload.get("delta"))
    sources = (raw, data, payload, chunk, delta_payload, attributes, metadata)

    event_type = _streaming_event_type(raw, data, payload, chunk, delta_payload)
    role = _streaming_value_from_sources(sources, ("role", "message.role", "delta.role", "chunk.role"))
    source = _streaming_value_from_sources(
        sources,
        ("source", "processor", "node", "agent", "provider", "model", "name", "span_name"),
    )
    timestamp_ms = _streaming_timestamp_ms(sources)
    latency_ms = _streaming_latency_ms(sources)
    gap_ms = _streaming_numeric_value(sources, ("gap_ms", "inter_chunk_gap_ms", "chunk_gap_ms"))
    usage = _streaming_mapping_from_sources(
        sources,
        ("usage", "usage_metadata", "response.usage", "gen_ai.usage"),
    )
    tool_call = _streaming_tool_call(raw, data, payload, chunk, delta_payload)
    text_delta = _streaming_text_delta(raw, data, payload, chunk, delta_payload)
    status = _streaming_value_from_sources(
        sources,
        ("status", "finish_reason", "response.status", "state", "agent_state", "user_state"),
    )
    error = _streaming_value_from_sources(
        sources,
        ("error", "exception", "error.type", "error_type", "error.message"),
    )
    dropped = _streaming_value_from_sources(
        sources,
        ("dropped", "drop_count", "dropped_count", "discarded", "discarded_count"),
    )
    buffer_size = _streaming_numeric_value(
        sources,
        ("buffer_size", "queue_size", "pending_frames", "pending_events"),
    )

    event: Dict[str, Any] = {
        "id": str(
            _streaming_value_from_sources(
                sources,
                ("id", "event_id", "span_id", "spanId", "run_id", "item_id"),
            )
            or f"stream_event_{sequence}"
        ),
        "type": event_type,
        "sequence": sequence,
        "framework": framework,
        "raw": copy.deepcopy(raw),
    }
    if role not in (None, "", [], {}):
        event["role"] = str(role)
    if source not in (None, "", [], {}):
        event["source"] = str(source)
    if text_delta:
        event["delta"] = text_delta
    if tool_call:
        event["tool_call"] = tool_call
    if timestamp_ms is not None:
        event["timestamp_ms"] = timestamp_ms
    if latency_ms is not None:
        event["latency_ms"] = latency_ms
    if gap_ms is not None:
        event["gap_ms"] = gap_ms
    if usage:
        event["usage"] = usage
    if status not in (None, "", [], {}):
        event["status"] = str(status)
    if error not in (None, "", [], {}):
        event["error"] = error
    if dropped not in (None, "", [], {}):
        event["dropped"] = dropped
    if buffer_size is not None:
        event["buffer_size"] = buffer_size
    event["signals"] = sorted(_streaming_event_signals(event, raw, data, payload, attributes, framework))
    return event


def _streaming_event_type(
    raw: Mapping[str, Any],
    data: Mapping[str, Any],
    payload: Mapping[str, Any],
    chunk: Mapping[str, Any],
    delta_payload: Mapping[str, Any],
) -> str:
    raw_type = str(
        raw.get("type")
        or raw.get("event")
        or raw.get("kind")
        or data.get("type")
        or payload.get("type")
        or raw.get("frame_type")
        or raw.get("frame")
        or raw.get("name")
        or ""
    )
    normalized = _normalize_streaming_trace_key(raw_type)
    text = " ".join([raw_type, _framework_sources_text(raw, data, payload, chunk, delta_payload)])
    lowered = text.lower()
    if any(token in lowered for token in ("tool_call_delta", "function_call_arguments.delta")):
        return "tool_delta"
    if any(token in lowered for token in ("response.output_text.delta", "text_delta", "message_delta")):
        return "chunk"
    if any(
        source.get(key) not in (None, "", [], {})
        for source in (raw, data, payload, chunk, delta_payload)
        for key in ("tool_call_chunks", "tool_calls")
    ):
        return "tool_delta"
    if any(token in lowered for token in ("final", "completed", "complete", "message_end", "response.done", "fullresponseend")):
        return "final"
    if any(token in lowered for token in ("interrupt", "barge", "cancel")):
        return "interruption"
    if any(token in lowered for token in ("drop", "discard")):
        return "drop"
    if any(token in lowered for token in ("usage", "metrics")):
        return "usage"
    if any(token in lowered for token in ("error", "exception")):
        return "error"
    if normalized in {"tool_delta", "final", "interruption", "drop", "usage", "error", "start", "message"}:
        return normalized
    if any(
        source.get(key) not in (None, "", [], {})
        for source in (raw, data, payload, chunk, delta_payload)
        for key in ("delta", "content", "text")
    ):
        return "chunk"
    return normalized or "event"


def _streaming_event_signals(
    event: Mapping[str, Any],
    raw: Mapping[str, Any],
    data: Mapping[str, Any],
    payload: Mapping[str, Any],
    attributes: Mapping[str, Any],
    framework: str,
) -> set[str]:
    signals = {_normalize_streaming_trace_key(event.get("type"))}
    text = " ".join(
        [
            framework,
            str(event.get("type", "")),
            str(event.get("status", "")),
            _framework_sources_text(raw, data, payload, attributes),
        ]
    ).lower()
    keyword_signals = {
        "stream": "stream",
        "chunk": "chunk",
        "delta": "chunk",
        "token": "chunk",
        "message": "message",
        "text": "chunk",
        "tool": "tool_delta",
        "function": "tool_delta",
        "final": "final",
        "completed": "final",
        "complete": "final",
        "finish": "final",
        "usage": "usage",
        "metric": "usage",
        "latency": "latency",
        "duration": "latency",
        "time_to_first_chunk": "latency",
        "gap": "gap",
        "inter_chunk": "gap",
        "drop": "drop",
        "discard": "drop",
        "interrupt": "interruption",
        "barge": "interruption",
        "cancel": "interruption",
        "recover": "recovered",
        "resume": "recovered",
        "error": "error",
        "exception": "error",
        "buffer": "backpressure",
        "queue": "backpressure",
        "backpressure": "backpressure",
        "livekit": "livekit",
        "pipecat": "pipecat",
        "langchain": "langchain",
        "langgraph": "langgraph",
        "openai": "openai_agents",
        "otel": "otel",
        "opentelemetry": "otel",
    }
    for token, signal in keyword_signals.items():
        if token in text:
            signals.add(signal)
    if event.get("delta"):
        signals.add("chunk")
    if event.get("tool_call"):
        signals.add("tool_delta")
    if event.get("latency_ms") is not None:
        signals.add("latency")
    if event.get("gap_ms") is not None:
        signals.add("gap")
    if event.get("usage"):
        signals.add("usage")
    if event.get("error") not in (None, "", [], {}):
        signals.add("error")
    if event.get("dropped") not in (None, "", [], {}, False, 0):
        signals.add("drop")
    if event.get("buffer_size") not in (None, "", [], {}):
        signals.add("backpressure")
    if _normalize_streaming_trace_key(event.get("type")) == "tool_delta":
        signals.discard("chunk")
    return {_normalize_streaming_trace_key(signal) for signal in signals if signal}


def _streaming_trace_summary(events: Iterable[Mapping[str, Any]]) -> Dict[str, Any]:
    records = [_coerce_plain_dict(event) for event in events]
    chunk_events = [event for event in records if "chunk" in set(event.get("signals", []))]
    tool_delta_events = [event for event in records if "tool_delta" in set(event.get("signals", []))]
    interruption_events = [event for event in records if "interruption" in set(event.get("signals", []))]
    dropped_events = [
        event
        for event in records
        if "drop" in set(event.get("signals", [])) or event.get("dropped") not in (None, "", [], {}, False, 0)
    ]
    error_events = [event for event in records if "error" in set(event.get("signals", []))]
    timestamps = [
        float(event["timestamp_ms"])
        for event in records
        if isinstance(event.get("timestamp_ms"), (int, float))
    ]
    explicit_gaps = [
        float(event["gap_ms"])
        for event in records
        if isinstance(event.get("gap_ms"), (int, float))
    ]
    ordered_timestamps = [
        float(event["timestamp_ms"])
        for event in sorted(chunk_events, key=lambda item: item.get("sequence", 0))
        if isinstance(event.get("timestamp_ms"), (int, float))
    ]
    computed_gaps = [
        max(0.0, ordered_timestamps[index] - ordered_timestamps[index - 1])
        for index in range(1, len(ordered_timestamps))
    ]
    first_token_latency = _streaming_first_token_latency(records, chunk_events)
    completion_status = _streaming_completion_status(records)
    usage = _streaming_usage_summary(records)
    summary: Dict[str, Any] = {
        "event_count": len(records),
        "chunk_count": len(chunk_events),
        "tool_delta_count": len(tool_delta_events),
        "interruption_count": len(interruption_events),
        "dropped_event_count": len(dropped_events),
        "error_count": len(error_events),
        "assembled_text": "".join(str(event.get("delta") or "") for event in chunk_events),
        "completion_status": completion_status,
    }
    if first_token_latency is not None:
        summary["first_token_latency_ms"] = round(first_token_latency, 4)
    if explicit_gaps:
        summary["max_gap_ms"] = round(max(explicit_gaps), 4)
    elif computed_gaps:
        summary["max_gap_ms"] = round(max(computed_gaps), 4)
    if timestamps:
        summary["total_latency_ms"] = round(max(timestamps) - min(timestamps), 4)
    if usage:
        summary["usage"] = usage
    if any("recovered" in set(event.get("signals", [])) for event in records):
        summary["recovered_interruption_count"] = sum(
            1 for event in records if "recovered" in set(event.get("signals", []))
        )
    return summary


def _streaming_trace_signals(events: Iterable[Mapping[str, Any]]) -> set[str]:
    signals: set[str] = set()
    for event in events:
        signals.update(event.get("signals", []))
    return signals


def _streaming_first_token_latency(
    records: Sequence[Mapping[str, Any]],
    chunk_events: Sequence[Mapping[str, Any]],
) -> Optional[float]:
    for event in chunk_events:
        value = event.get("latency_ms")
        if isinstance(value, (int, float)):
            return float(value)
    request_timestamps = [
        float(event["timestamp_ms"])
        for event in records
        if isinstance(event.get("timestamp_ms"), (int, float))
        and any(signal in set(event.get("signals", [])) for signal in ("start", "stream"))
    ]
    all_timestamps = [
        float(event["timestamp_ms"])
        for event in records
        if isinstance(event.get("timestamp_ms"), (int, float))
    ]
    chunk_timestamps = [
        float(event["timestamp_ms"])
        for event in chunk_events
        if isinstance(event.get("timestamp_ms"), (int, float))
    ]
    if chunk_timestamps and (request_timestamps or all_timestamps):
        return min(chunk_timestamps) - min(request_timestamps or all_timestamps)
    return None


def _streaming_completion_status(records: Sequence[Mapping[str, Any]]) -> str:
    for event in reversed(records):
        status = str(event.get("status") or "").strip()
        signals = set(event.get("signals", []))
        if "final" in signals:
            return status or "completed"
        if status.lower() in {"complete", "completed", "success", "succeeded", "done", "closed"}:
            return status
    if any("error" in set(event.get("signals", [])) for event in records):
        return "error"
    return "unknown"


def _streaming_usage_summary(records: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    merged: Dict[str, Any] = {}
    for event in records:
        usage = _coerce_plain_dict(event.get("usage"))
        for key, value in usage.items():
            if isinstance(value, (int, float)):
                merged[key] = merged.get(key, 0) + value
            elif key not in merged:
                merged[key] = copy.deepcopy(value)
    return merged


def _find_streaming_event(
    events: Iterable[Mapping[str, Any]],
    event_id: str,
) -> Optional[Dict[str, Any]]:
    normalized_query = str(event_id or "").strip().lower()
    if not normalized_query:
        return None
    for event in events:
        event_dict = _coerce_plain_dict(event)
        candidates = {
            str(event_dict.get("id") or "").lower(),
            str(event_dict.get("event_id") or "").lower(),
            str(event_dict.get("sequence") or "").lower(),
            str(event_dict.get("type") or "").lower(),
            _normalize_streaming_trace_key(event_dict.get("type")),
        }
        if normalized_query in candidates:
            return event_dict
    return None


def _streaming_text_delta(
    raw: Mapping[str, Any],
    data: Mapping[str, Any],
    payload: Mapping[str, Any],
    chunk: Mapping[str, Any],
    delta_payload: Mapping[str, Any],
) -> str:
    for source in (raw, data, payload, chunk, delta_payload):
        value = _streaming_value_from_sources(
            (source,),
            (
                "delta",
                "text",
                "content",
                "transcript",
                "output_text",
                "message.content",
                "chunk.content",
                "delta.content",
            ),
        )
        text = _streaming_text_from_value(value)
        if text:
            return text
    return ""


def _streaming_text_from_value(value: Any) -> str:
    if value in (None, "", [], {}):
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float, bool)):
        return str(value)
    if isinstance(value, Mapping):
        parts: List[str] = []
        for key in ("text", "content", "delta", "transcript", "value"):
            text = _streaming_text_from_value(value.get(key))
            if text:
                parts.append(text)
        if not parts and value.get("type") in {"text", "output_text"}:
            parts.append(_streaming_text_from_value(value.get("value")))
        return "".join(parts)
    if isinstance(value, Iterable):
        return "".join(_streaming_text_from_value(item) for item in value)
    return str(value)


def _streaming_tool_call(
    raw: Mapping[str, Any],
    data: Mapping[str, Any],
    payload: Mapping[str, Any],
    chunk: Mapping[str, Any],
    delta_payload: Mapping[str, Any],
) -> Dict[str, Any]:
    for source in (raw, data, payload, chunk, delta_payload):
        for key in ("tool_call", "tool_calls", "tool_call_chunks", "function_call", "function"):
            value = source.get(key)
            if value not in (None, "", [], {}):
                return {"field": key, "value": copy.deepcopy(value)}
    return {}


def _streaming_value_from_sources(
    sources: Iterable[Mapping[str, Any]],
    keys: Iterable[str],
) -> Any:
    for source in sources:
        if not isinstance(source, Mapping):
            continue
        for key in keys:
            if key in source and source.get(key) not in (None, ""):
                return source.get(key)
            current: Any = source
            for part in key.split("."):
                if isinstance(current, Mapping) and part in current:
                    current = current.get(part)
                else:
                    current = None
                    break
            if current not in (None, ""):
                return current
    return None


def _streaming_mapping_from_sources(
    sources: Iterable[Mapping[str, Any]],
    keys: Iterable[str],
) -> Dict[str, Any]:
    value = _streaming_value_from_sources(sources, keys)
    return _coerce_plain_dict(value)


def _streaming_numeric_value(
    sources: Iterable[Mapping[str, Any]],
    keys: Iterable[str],
) -> Optional[float]:
    value = _streaming_value_from_sources(sources, keys)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            return None
    return None


def _streaming_timestamp_ms(sources: Iterable[Mapping[str, Any]]) -> Optional[float]:
    value = _streaming_value_from_sources(
        sources,
        ("timestamp_ms", "ts_ms", "time_ms", "created_at_ms", "start_time_ms"),
    )
    if isinstance(value, (int, float)):
        return float(value)
    value = _streaming_value_from_sources(sources, ("timestamp", "time", "created_at"))
    if isinstance(value, (int, float)):
        return float(value * 1000 if value < 10_000_000_000 else value)
    if isinstance(value, str):
        try:
            numeric = float(value)
            return numeric * 1000 if numeric < 10_000_000_000 else numeric
        except ValueError:
            return None
    return None


def _streaming_latency_ms(sources: Iterable[Mapping[str, Any]]) -> Optional[float]:
    value = _streaming_numeric_value(
        sources,
        (
            "latency_ms",
            "duration_ms",
            "elapsed_ms",
            "first_token_latency_ms",
            "time_to_first_chunk_ms",
            "gen_ai.response.time_to_first_chunk_ms",
        ),
    )
    if value is not None:
        return value
    seconds = _streaming_numeric_value(
        sources,
        ("time_to_first_chunk", "gen_ai.response.time_to_first_chunk"),
    )
    if seconds is not None:
        return seconds * 1000
    return None


