def _autonomy_stage_for_tool(name: Optional[str]) -> Optional[str]:
    if not name:
        return None
    if str(name) in AUTONOMY_TOOL_STAGES:
        return AUTONOMY_TOOL_STAGES[str(name)]
    normalized = _normalize_autonomy_stage(str(name))
    if normalized in set(DEFAULT_AUTONOMY_STAGES + ["skill", "status"]):
        return normalized
    return None


def _normalize_autonomy_stage(stage: Any) -> str:
    normalized = str(stage).strip().lower().replace("-", "_").replace(" ", "_")
    return AUTONOMY_STAGE_ALIASES.get(normalized, normalized)


def _autonomy_quality_checks(
    *,
    entries: Iterable[Mapping[str, Any]],
    memory_updates: Iterable[Mapping[str, Any]],
    skills: Mapping[str, Any],
    expected_plan: Mapping[str, Any],
    expected_verification: Mapping[str, Any],
    expected_reflection: Mapping[str, Any],
    expected_memory: Mapping[str, Any],
    expected_skills: Iterable[Mapping[str, Any]],
    expected_stop: Mapping[str, Any],
) -> List[Dict[str, Any]]:
    entries_by_stage = _autonomy_entries_by_stage(entries)
    checks: List[Dict[str, Any]] = []

    plan_entries = entries_by_stage.get("plan", [])
    plan_steps = _autonomy_plan_steps(plan_entries)
    if expected_plan:
        required_steps = _autonomy_string_list(
            expected_plan.get("required_steps") or expected_plan.get("steps")
        )
        if required_steps:
            missing = [step for step in required_steps if not _autonomy_terms_present(plan_steps, step)]
            checks.append(
                {
                    "check": "plan_steps",
                    "expected": required_steps,
                    "actual": plan_steps,
                    "match": not missing,
                    "missing": missing,
                }
            )
        min_steps = expected_plan.get("min_steps")
        if min_steps is not None:
            checks.append(
                {
                    "check": "plan_min_steps",
                    "expected": int(min_steps),
                    "actual": len(plan_steps),
                    "match": len(plan_steps) >= int(min_steps),
                }
            )
        forbidden_steps = _autonomy_string_list(expected_plan.get("forbidden_steps"))
        if forbidden_steps:
            present = [step for step in forbidden_steps if _autonomy_terms_present(plan_steps, step)]
            checks.append(
                {
                    "check": "plan_forbidden_steps",
                    "expected": [],
                    "actual": present,
                    "match": not present,
                }
            )

    verify_entries = entries_by_stage.get("verify", [])
    verify_text = _autonomy_entries_text(verify_entries)
    if expected_verification:
        required_checks = _autonomy_string_list(
            expected_verification.get("required_checks") or expected_verification.get("checks")
        )
        if required_checks:
            missing = [term for term in required_checks if term.lower() not in verify_text]
            checks.append(
                {
                    "check": "verification_checks",
                    "expected": required_checks,
                    "actual": _autonomy_verification_checks(verify_entries),
                    "match": not missing,
                    "missing": missing,
                }
            )
        if expected_verification.get("passed_required") is not None:
            passed = any(_autonomy_entry_passed(entry) for entry in verify_entries)
            checks.append(
                {
                    "check": "verification_passed",
                    "expected": bool(expected_verification.get("passed_required")),
                    "actual": passed,
                    "match": passed == bool(expected_verification.get("passed_required")),
                }
            )
        if expected_verification.get("min_score") is not None:
            scores = _autonomy_entry_scores(verify_entries)
            max_score = max(scores) if scores else None
            checks.append(
                {
                    "check": "verification_score",
                    "expected": f">= {expected_verification.get('min_score')}",
                    "actual": max_score,
                    "match": max_score is not None and max_score >= float(expected_verification.get("min_score")),
                }
            )

    reflect_entries = entries_by_stage.get("reflect", [])
    reflect_text = _autonomy_entries_text(reflect_entries)
    if expected_reflection:
        required_terms = _autonomy_string_list(
            expected_reflection.get("required_terms") or expected_reflection.get("lesson_contains")
        )
        if required_terms:
            missing = [term for term in required_terms if term.lower() not in reflect_text]
            checks.append(
                {
                    "check": "reflection_terms",
                    "expected": required_terms,
                    "actual": reflect_text,
                    "match": not missing,
                    "missing": missing,
                }
            )
        min_length = expected_reflection.get("min_length")
        if min_length is not None:
            checks.append(
                {
                    "check": "reflection_length",
                    "expected": int(min_length),
                    "actual": len(reflect_text),
                    "match": len(reflect_text) >= int(min_length),
                }
            )

    memory_list = [dict(item) for item in memory_updates]
    if expected_memory:
        required_keys = _autonomy_string_list(
            expected_memory.get("required_keys") or expected_memory.get("keys")
        )
        if required_keys:
            actual_keys = sorted({str(key) for item in memory_list for key in item.keys()})
            missing = sorted(set(required_keys) - set(actual_keys))
            checks.append(
                {
                    "check": "memory_keys",
                    "expected": required_keys,
                    "actual": actual_keys,
                    "match": not missing,
                    "missing": missing,
                }
            )
        forbidden_keys = _autonomy_string_list(expected_memory.get("forbidden_keys"))
        if forbidden_keys:
            actual_keys = sorted({str(key) for item in memory_list for key in item.keys()})
            present = sorted(set(forbidden_keys) & set(actual_keys))
            checks.append(
                {
                    "check": "memory_forbidden_keys",
                    "expected": [],
                    "actual": present,
                    "match": not present,
                }
            )

    for expected_skill in expected_skills:
        expected = dict(expected_skill)
        name = str(expected.get("name") or expected.get("skill") or "")
        skill = dict(skills.get(name, {})) if name else {}
        skill_steps = _autonomy_string_list(skill.get("steps"))
        required_steps = _autonomy_string_list(expected.get("required_steps") or expected.get("steps"))
        step_missing = [step for step in required_steps if not _autonomy_terms_present(skill_steps, step)]
        checks.append(
            {
                "check": "skill_reuse",
                "expected": expected,
                "actual": skill,
                "match": bool(skill) and not step_missing,
                "missing": step_missing,
            }
        )

    if expected_stop:
        stop_records = [
            _as_mapping(entry.get("arguments"))
            for entry in entries_by_stage.get("verify", []) + entries_by_stage.get("reflect", [])
            if any(key in _as_mapping(entry.get("arguments")) for key in ("stop", "should_stop", "continue", "should_continue", "decision"))
        ]
        actual = stop_records[-1] if stop_records else {}
        should_stop = expected_stop.get("should_stop")
        if should_stop is not None:
            actual_stop = _autonomy_stop_value(actual)
            checks.append(
                {
                    "check": "stop_decision",
                    "expected": bool(should_stop),
                    "actual": actual,
                    "match": actual_stop is not None and actual_stop == bool(should_stop),
                }
            )
    return checks


def _normalize_expected_skills(
    expected_skills: Optional[Iterable[str | Mapping[str, Any]]],
) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for item in expected_skills or []:
        if isinstance(item, Mapping):
            normalized.append(copy.deepcopy(dict(item)))
        else:
            normalized.append({"name": str(item)})
    return normalized


def _normalize_expected_stop(expected_stop: Optional[Mapping[str, Any] | bool]) -> Dict[str, Any]:
    if expected_stop is None:
        return {}
    if isinstance(expected_stop, Mapping):
        return copy.deepcopy(dict(expected_stop))
    return {"should_stop": bool(expected_stop)}


def _autonomy_entries_by_stage(entries: Iterable[Mapping[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
    grouped: Dict[str, List[Dict[str, Any]]] = {}
    for entry in entries:
        entry_dict = dict(entry)
        stage = _normalize_autonomy_stage(entry_dict.get("stage") or entry_dict.get("name") or "")
        if not stage:
            continue
        grouped.setdefault(stage, []).append(entry_dict)
    return grouped


def _autonomy_plan_steps(entries: Iterable[Mapping[str, Any]]) -> List[str]:
    steps: List[str] = []
    for entry in entries:
        arguments = _as_mapping(entry.get("arguments"))
        raw_steps = arguments.get("steps") or arguments.get("plan") or arguments.get("tasks")
        steps.extend(_autonomy_string_list(raw_steps))
    return steps


def _autonomy_verification_checks(entries: Iterable[Mapping[str, Any]]) -> List[str]:
    checks: List[str] = []
    for entry in entries:
        arguments = _as_mapping(entry.get("arguments"))
        checks.extend(_autonomy_string_list(arguments.get("checks") or arguments.get("evidence")))
    return checks


def _autonomy_entry_passed(entry: Mapping[str, Any]) -> bool:
    arguments = _as_mapping(entry.get("arguments"))
    if "passed" in arguments:
        return bool(arguments.get("passed"))
    feedback = _as_mapping(entry.get("feedback"))
    if "passed" in feedback:
        return bool(feedback.get("passed"))
    score = feedback.get("score", arguments.get("score"))
    return isinstance(score, (int, float)) and score >= 1.0


def _autonomy_entry_scores(entries: Iterable[Mapping[str, Any]]) -> List[float]:
    scores: List[float] = []
    for entry in entries:
        arguments = _as_mapping(entry.get("arguments"))
        feedback = _as_mapping(entry.get("feedback"))
        for raw in (arguments.get("score"), feedback.get("score")):
            if isinstance(raw, bool) or raw is None:
                continue
            try:
                scores.append(float(raw))
            except (TypeError, ValueError):
                continue
    return scores


def _autonomy_entries_text(entries: Iterable[Mapping[str, Any]]) -> str:
    parts: List[str] = []
    for entry in entries:
        parts.append(_stringify_dict(entry))
    return " ".join(parts).lower()


def _autonomy_terms_present(values: Iterable[str], expected: str) -> bool:
    expected_text = str(expected).lower()
    return any(expected_text in str(value).lower() for value in values)


def _autonomy_string_list(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [value]
    if isinstance(value, Mapping):
        return [str(key) for key in value.keys()]
    if isinstance(value, Iterable) and not isinstance(value, (bytes, bytearray)):
        return [str(item) for item in value if item not in (None, "")]
    return [str(value)]


def _autonomy_stop_value(record: Mapping[str, Any]) -> Optional[bool]:
    if "should_stop" in record:
        return bool(record.get("should_stop"))
    if "stop" in record:
        return bool(record.get("stop"))
    if "should_continue" in record:
        return not bool(record.get("should_continue"))
    if "continue" in record:
        return not bool(record.get("continue"))
    decision = str(record.get("decision") or "").strip().lower()
    if decision in {"stop", "done", "final", "finish"}:
        return True
    if decision in {"continue", "retry", "iterate"}:
        return False
    return None


def _as_mapping(value: Any) -> Dict[str, Any]:
    return dict(value) if isinstance(value, Mapping) else {}


def _normalize_skill_library(
    skill_library: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]],
) -> Dict[str, Any]:
    if skill_library is None:
        return {}
    if isinstance(skill_library, Mapping):
        return copy.deepcopy(dict(skill_library))
    normalized: Dict[str, Any] = {}
    for index, skill in enumerate(skill_library):
        item = dict(skill)
        name = str(item.get("name") or item.get("skill") or f"skill_{index + 1}")
        normalized[name] = item
    return normalized


def _browser_action_items(
    actions: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]],
) -> List[Dict[str, Any]]:
    if actions is None:
        return []
    if isinstance(actions, Mapping):
        return [
            {"selector": str(key), **copy.deepcopy(dict(value))}
            if isinstance(value, Mapping)
            else {"selector": str(key), "next_url": value}
            for key, value in actions.items()
        ]
    return [copy.deepcopy(dict(item)) for item in actions]


def _browser_region_items(
    regions: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]],
) -> List[Dict[str, Any]]:
    if regions is None:
        return []
    if isinstance(regions, Mapping):
        items: List[Dict[str, Any]] = []
        for name, value in regions.items():
            item = copy.deepcopy(dict(value)) if isinstance(value, Mapping) else {"bounds": value}
            item.setdefault("name", str(name))
            items.append(item)
        return items
    return [copy.deepcopy(dict(item)) for item in regions]


def _empty_browser_trace_fixture(
    *,
    source_label: Optional[str] = None,
    source_type: str = "browser_trace",
) -> Dict[str, Any]:
    return {
        "snapshots": [],
        "actions": [],
        "regions": [],
        "console_logs": [],
        "network_log": [],
        "resource_bodies": [],
        "actionability_timeline": [],
        "storage_state": {"cookies": [], "origins": []},
        "runtime_events": [],
        "performance_entries": [],
        "video_artifacts": [],
        "prompt_injections": [],
        "perturbations": [],
        "metadata": {
            **({"source": source_label} if source_label else {}),
            "source_type": source_type,
        },
    }


def _merge_browser_trace_fixtures(*fixtures: Mapping[str, Any]) -> Dict[str, Any]:
    merged = _empty_browser_trace_fixture(source_type="browser_trace")
    merged["metadata"] = {}
    for fixture in fixtures:
        if not fixture:
            continue
        merged["metadata"].update(copy.deepcopy(dict(fixture.get("metadata", {}))))
        merged["storage_state"] = _merge_browser_storage_states(
            merged.get("storage_state"),
            fixture.get("storage_state"),
        )
        for key in (
            "snapshots",
            "actions",
            "regions",
            "console_logs",
            "network_log",
            "resource_bodies",
            "actionability_timeline",
            "runtime_events",
            "performance_entries",
            "video_artifacts",
            "prompt_injections",
            "perturbations",
        ):
            merged[key].extend(copy.deepcopy(list(fixture.get(key, []))))
    for key in (
        "snapshots",
        "actions",
        "regions",
        "console_logs",
        "network_log",
        "resource_bodies",
        "actionability_timeline",
        "runtime_events",
        "performance_entries",
        "video_artifacts",
        "prompt_injections",
        "perturbations",
    ):
        merged[key] = _dedupe_dicts(merged[key])
    return merged


def _normalize_browser_trace_provider(provider: Any) -> str:
    normalized = str(provider or "browser").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "openai": "openai_cua",
        "openai_computer": "openai_cua",
        "computer_use": "openai_cua",
        "computer_use_preview": "openai_cua",
        "cua": "openai_cua",
        "browseruse": "browser_use",
        "browser_use_cloud": "browser_use",
        "playwright_har": "har",
        "http_archive": "har",
    }
    return aliases.get(normalized, normalized or "browser")


def _load_browser_trace_source(source: str | os.PathLike[str]) -> Dict[str, Any]:
    source_text = os.fspath(source)
    metadata = {"source": _browser_source_label(source), "source_type": "browser_trace"}
    if zipfile.is_zipfile(source_text):
        records: List[Any] = []
        resources: Dict[str, str] = {}
        videos: List[Dict[str, Any]] = []
        with zipfile.ZipFile(source_text) as archive:
            for name in archive.namelist():
                lower = name.lower()
                uri = f"zip://{source_text}#{name}"
                if lower.endswith((".png", ".jpg", ".jpeg", ".webp", ".html", ".css", ".js", ".json", ".txt")):
                    resources[name] = uri
                    resources[os.path.basename(name)] = uri
                if lower.endswith((".webm", ".mp4", ".mov")):
                    videos.append(
                        {
                            "uri": uri,
                            "id": os.path.basename(name),
                            "source": "browser_trace_zip",
                            "mime_type": _browser_video_mime_type(name),
                        }
                    )
                    continue
                if not lower.endswith((".trace", ".har", ".json", ".jsonl")):
                    continue
                try:
                    text = archive.read(name).decode("utf-8")
                except UnicodeDecodeError:
                    continue
                parsed = _parse_framework_trace_export_text(text)
                records.extend(_as_iterable(parsed))
                if lower.endswith(".har"):
                    metadata["source_type"] = "har"
        return {"records": records, "resources": resources, "video_artifacts": videos, "metadata": metadata}

    parsed = _load_framework_trace_export_source(source_text)
    if str(source_text).lower().endswith(".har"):
        metadata["source_type"] = "har"
    return {"records": _as_iterable(parsed), "metadata": metadata}


def _normalize_browser_trace_export(
    trace_export: Any,
    *,
    provider: str = "browser",
    source_label: Optional[str] = None,
) -> Dict[str, Any]:
    metadata_hint = _get_mapping_value(_get_mapping_value(trace_export, "metadata"), "source_type")
    provider_name = _normalize_browser_trace_provider(
        _get_mapping_value(trace_export, "provider")
        or _get_mapping_value(trace_export, "framework")
        or metadata_hint
        or provider
    )
    fixture = _empty_browser_trace_fixture(source_label=source_label, source_type=provider_name)
    if trace_export is None:
        return fixture

    export = trace_export
    resources: Dict[str, str] = {}
    if isinstance(export, Mapping) and any(key in export for key in ("records", "resources", "video_artifacts", "metadata")):
        wrapper = copy.deepcopy(dict(export))
        resources = {str(key): str(value) for key, value in dict(wrapper.get("resources", {})).items()}
        fixture["video_artifacts"].extend(_as_iterable(wrapper.get("video_artifacts", [])))
        fixture["metadata"].update(copy.deepcopy(dict(wrapper.get("metadata", {}))))
        export = wrapper.get("records", wrapper)

    playwright_fixture = _normalize_playwright_trace_export(export, source_label=source_label)
    fixture = _merge_browser_trace_fixtures(fixture, playwright_fixture)
    fixture["metadata"]["source_type"] = provider_name
    if source_label:
        fixture["metadata"]["source"] = source_label

    direct = _coerce_plain_dict(export) if isinstance(export, Mapping) else {}
    fixture["resource_bodies"].extend(_as_iterable(direct.get("resource_bodies", [])))
    fixture["actionability_timeline"].extend(_as_iterable(direct.get("actionability_timeline", [])))
    fixture["storage_state"] = _merge_browser_storage_states(
        fixture.get("storage_state"),
        _normalize_browser_storage_state(
            direct.get("storage_state", direct.get("storageState")),
            url=direct.get("url") or direct.get("current_url"),
            cookies=direct.get("cookies"),
            local_storage=direct.get("local_storage", direct.get("localStorage")),
            session_storage=direct.get("session_storage", direct.get("sessionStorage")),
        ),
    )
    fixture["runtime_events"].extend(
        _normalize_browser_runtime_event(item)
        for item in _as_iterable(direct.get("runtime_events", direct.get("runtime", [])))
    )
    fixture["performance_entries"].extend(
        _normalize_browser_performance_entry(item)
        for item in _as_iterable(direct.get("performance_entries", direct.get("performance", [])))
    )

    har_fixture = _browser_har_fixture(export, resources=resources)
    if har_fixture["network_log"] or har_fixture["resource_bodies"]:
        fixture = _merge_browser_trace_fixtures(fixture, har_fixture)
        fixture["metadata"]["source_type"] = "har" if provider_name == "har" else provider_name

    browser_use_fixture = _browser_use_fixture(export)
    if any(browser_use_fixture[key] for key in ("snapshots", "actions", "actionability_timeline")):
        fixture = _merge_browser_trace_fixtures(fixture, browser_use_fixture)
        fixture["metadata"]["source_type"] = "browser_use" if provider_name in {"browser", "browser_use"} else provider_name

    actions_by_id: Dict[str, Dict[str, Any]] = {}
    actionability: List[Dict[str, Any]] = []
    for index, record in enumerate(_browser_trace_records(export)):
        record_dict = _coerce_plain_dict(record)
        if not record_dict:
            continue
        for snapshot in _browser_snapshots_from_record(record_dict, index=index):
            fixture["snapshots"].append(snapshot)
        for action in _browser_actions_from_record(record_dict, index=index):
            call_id = str(action.get("id"))
            actions_by_id[call_id] = {**actions_by_id.get(call_id, {}), **action}
            region = action.get("region")
            if isinstance(region, Mapping):
                fixture["regions"].append(region)
        actionability.extend(_browser_actionability_from_record(record_dict, index=index))
        network = _browser_network_from_record(record_dict)
        if network:
            fixture["network_log"].append(network)
        resource = _browser_resource_body_from_record(record_dict)
        if resource:
            fixture["resource_bodies"].append(resource)
        fixture["storage_state"] = _merge_browser_storage_states(
            fixture.get("storage_state"),
            _browser_storage_state_from_record(record_dict),
        )
        fixture["runtime_events"].extend(_browser_runtime_events_from_record(record_dict, index=index))
        fixture["performance_entries"].extend(_browser_performance_entries_from_record(record_dict, index=index))
        fixture["prompt_injections"].extend(_browser_prompt_injections_from_record(record_dict))
    fixture["actions"].extend(actions_by_id.values())
    fixture["actionability_timeline"].extend(actionability)

    for key in (
        "snapshots",
        "actions",
        "regions",
        "console_logs",
        "network_log",
        "resource_bodies",
        "actionability_timeline",
        "runtime_events",
        "performance_entries",
        "video_artifacts",
        "prompt_injections",
        "perturbations",
    ):
        fixture[key] = _dedupe_dicts(fixture[key])
    return fixture


def _browser_trace_records(export: Any) -> List[Any]:
    if export is None:
        return []
    if isinstance(export, str):
        text = export.strip()
        if text.startswith(("{", "[")) or "\n" in text:
            return _browser_trace_records(_parse_framework_trace_export_text(text))
        return []
    if hasattr(export, "model_dump"):
        return _browser_trace_records(export.model_dump())
    if hasattr(export, "dict"):
        return _browser_trace_records(export.dict())
    if isinstance(export, Mapping):
        data = copy.deepcopy(dict(export))
        if _looks_like_browser_trace_record(data):
            return [data]
        records: List[Any] = []
        for key in (
            "records",
            "events",
            "items",
            "output",
            "input",
            "steps",
            "history",
            "action_history",
            "model_actions",
            "model_outputs",
            "action_results",
            "screenshots",
            "snapshots",
            "actions",
        ):
            if key in data:
                records.extend(_browser_trace_records(data[key]))
        if records:
            return records
        for key in ("data", "payload", "result", "response", "body"):
            if isinstance(data.get(key), (Mapping, list, tuple)):
                nested = _browser_trace_records(data[key])
                if nested:
                    return nested
        return []
    if isinstance(export, Iterable):
        records: List[Any] = []
        for item in export:
            records.extend(_browser_trace_records(item))
        return records
    return []


def _looks_like_browser_trace_record(record: Mapping[str, Any]) -> bool:
    record_type = str(record.get("type") or record.get("event") or record.get("kind") or "").lower()
    if record_type in {"computer_call", "computer_call_output", "computer_screenshot", "browser_state", "action_result"}:
        return True
    if any(
        key in record
        for key in (
            "action",
            "actions",
            "current_url",
            "screenshot",
            "screenshot_path",
            "image_url",
            "browser_state",
            "storage_state",
            "storageState",
            "cookies",
            "localStorage",
            "sessionStorage",
            "runtime_events",
            "page_errors",
            "performance_entries",
        )
    ):
        return True
    return False


def _browser_snapshots_from_record(record: Mapping[str, Any], *, index: int) -> List[Dict[str, Any]]:
    snapshots: List[Dict[str, Any]] = []
    record_type = str(record.get("type") or record.get("event") or "").lower()
    output = _coerce_plain_dict(record.get("output"))
    browser_state = _coerce_plain_dict(record.get("browser_state") or record.get("state"))
    screenshot_uri = (
        record.get("screenshot_uri")
        or record.get("image_url")
        or output.get("image_url")
        or browser_state.get("screenshot_uri")
        or _browser_screenshot_uri_from_value(record.get("screenshot") or browser_state.get("screenshot"))
    )
    screenshot_path = record.get("screenshot_path") or browser_state.get("screenshot_path")
    url = record.get("current_url") or record.get("url") or browser_state.get("url")
    dom = record.get("dom") or record.get("html") or browser_state.get("dom") or browser_state.get("html")
    if record_type == "computer_call_output" or screenshot_uri or screenshot_path or dom:
        snapshots.append(
            {
                "id": str(record.get("id") or record.get("call_id") or f"browser_trace_snapshot_{index + 1}"),
                "url": url,
                "dom": dom,
                "screenshot_uri": screenshot_uri,
                "screenshot_path": screenshot_path,
                "metadata": {
                    "source": _browser_record_source(record),
                    "record_type": record_type or "browser_snapshot",
                    "call_id": record.get("call_id"),
                    "status": record.get("status"),
                },
            }
        )
    return [{key: value for key, value in snapshot.items() if value not in (None, "", {}, [])} for snapshot in snapshots]


def _browser_actions_from_record(record: Mapping[str, Any], *, index: int) -> List[Dict[str, Any]]:
    actions: List[Dict[str, Any]] = []
    raw_actions = _as_iterable(record.get("actions", record.get("action")))
    if not raw_actions and _looks_like_browser_action_mapping(record):
        raw_actions = [record]
    for action_index, raw in enumerate(raw_actions):
        action_dict = _coerce_plain_dict(raw)
        if not action_dict:
            continue
        action_type = str(
            action_dict.get("type")
            or action_dict.get("name")
            or action_dict.get("action")
            or next(iter(action_dict.keys()), "")
        )
        if len(action_dict) == 1 and isinstance(action_dict.get(action_type), Mapping):
            nested = _coerce_plain_dict(action_dict[action_type])
            nested.setdefault("type", action_type)
            action_dict = nested
        action_type = str(action_dict.get("type") or action_dict.get("name") or action_type)
        if not action_type:
            continue
        base_id = str(record.get("call_id") or record.get("id") or f"browser_trace_action_{index + 1}")
        normalized = {
            "id": f"{base_id}_{action_index + 1}" if len(raw_actions) > 1 else base_id,
            "action": action_type,
            "actions": [action_type],
            "current_url": record.get("current_url") or record.get("url"),
            "metadata": {
                "source": _browser_record_source(record),
                "record_type": record.get("type") or record.get("event"),
                "status": record.get("status"),
            },
        }
        selector = action_dict.get("selector") or action_dict.get("locator") or action_dict.get("target") or action_dict.get("element")
        if selector:
            normalized["selector"] = str(selector)
            normalized["selectors"] = [str(selector)]
        coordinates = _browser_action_coordinates({**action_dict, **record})
        if coordinates:
            normalized["coordinates"] = coordinates
            normalized["x"] = coordinates["x"]
            normalized["y"] = coordinates["y"]
        url = action_dict.get("url") or action_dict.get("target_url") or record.get("target_url")
        if url:
            normalized["next_url"] = str(url)
        region = _browser_region_from_action(action_dict, default_name=f"{normalized['id']}_target")
        if region:
            normalized["region"] = region
        tool_names = _browser_tool_names_for_action(action_type)
        if tool_names:
            normalized["tool_names"] = tool_names
        actionability = _browser_actionability_mapping(record, action_dict)
        if actionability:
            normalized["actionability"] = actionability
        if record.get("error") or action_dict.get("error"):
            normalized["success"] = False
            normalized["error"] = str(record.get("error") or action_dict.get("error"))
        actions.append({key: value for key, value in normalized.items() if value not in (None, "", [], {})})
    return actions


def _looks_like_browser_action_mapping(record: Mapping[str, Any]) -> bool:
    action_type = str(record.get("type") or record.get("action") or record.get("name") or "").lower()
    return action_type in {"click", "double_click", "scroll", "type", "wait", "keypress", "drag", "move", "screenshot", "navigate", "goto", "done"}


def _browser_tool_names_for_action(action_type: str) -> List[str]:
    lowered = action_type.lower()
    if any(token in lowered for token in ("click", "double_click", "tap", "drag", "move", "scroll", "hover")):
        return ["computer_click", "browser_click", "playwright_click"]
    if any(token in lowered for token in ("navigate", "goto", "open_url")):
        return ["browser_navigate"]
    return []


def _browser_region_from_action(action: Mapping[str, Any], *, default_name: str) -> Optional[Dict[str, Any]]:
    box = action.get("boundingBox") or action.get("bounding_box") or action.get("bbox") or action.get("bounds")
    if not box:
        return None
    region = _normalize_browser_region({"bounds": box, "name": default_name}, default_name=default_name)
    selector = action.get("selector") or action.get("locator")
    if selector:
        region["selectors"] = [str(selector)]
    return region


def _browser_actionability_from_record(record: Mapping[str, Any], *, index: int) -> List[Dict[str, Any]]:
    checks: List[Dict[str, Any]] = []
    for action_index, action in enumerate(_browser_actions_from_record(record, index=index)):
        actionability = _coerce_plain_dict(action.get("actionability"))
        if not actionability:
            continue
        checks.append(
            {
                "id": f"{action.get('id')}_actionability_{action_index + 1}",
                "action_id": action.get("id"),
                "source": action.get("metadata", {}).get("source"),
                "checks": actionability,
                "passed": all(value is not False for value in actionability.values()),
            }
        )
    safety_checks = _as_iterable(record.get("pending_safety_checks") or record.get("acknowledged_safety_checks"))
    for safety_index, safety_check in enumerate(safety_checks):
        item = _coerce_plain_dict(safety_check)
        if not item:
            continue
        checks.append(
            {
                "id": str(item.get("id") or f"safety_check_{index + 1}_{safety_index + 1}"),
                "action_id": record.get("call_id") or record.get("id"),
                "source": _browser_record_source(record),
                "checks": {"safety_check": True, str(item.get("code") or "safety_check"): True},
                "passed": True,
                "message": item.get("message"),
            }
        )
    return checks


def _browser_actionability_mapping(record: Mapping[str, Any], action: Mapping[str, Any]) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    for source in (record, action):
        actionability = _coerce_plain_dict(source.get("actionability"))
        result.update(actionability)
        for key in ("attached", "visible", "enabled", "stable", "receives_events", "editable", "actionable"):
            if key in source:
                result[key] = bool(source[key])
    if record.get("pending_safety_checks"):
        result["safety_checks_present"] = True
    return result


def _browser_network_from_record(record: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
    if not any(key in record for key in ("request", "response", "url", "method", "status", "resource_type")):
        return None
    request = _coerce_plain_dict(record.get("request"))
    response = _coerce_plain_dict(record.get("response"))
    url = record.get("url") or request.get("url") or response.get("url")
    if not url:
        return None
    return {
        "url": str(url),
        "method": record.get("method") or request.get("method"),
        "status": record.get("status") or response.get("status"),
        "resource_type": record.get("resource_type") or record.get("resourceType"),
        "source": _browser_record_source(record),
    }


def _browser_resource_body_from_record(record: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
    content = _coerce_plain_dict(record.get("content") or _coerce_plain_dict(record.get("response")).get("content"))
    body = record.get("body") or record.get("text") or content.get("text")
    if body is None:
        return None
    return {
        "id": str(record.get("id") or record.get("url") or "resource_body"),
        "url": record.get("url") or _coerce_plain_dict(record.get("request")).get("url"),
        "body": body,
        "mime_type": record.get("mime_type") or content.get("mimeType") or content.get("mime_type"),
        "encoding": content.get("encoding"),
        "source": _browser_record_source(record),
    }


def _browser_prompt_injections_from_record(record: Mapping[str, Any]) -> List[Dict[str, Any]]:
    checks = _as_iterable(record.get("pending_safety_checks") or record.get("safety_checks"))
    surfaces: List[Dict[str, Any]] = []
    for index, check in enumerate(checks):
        item = _coerce_plain_dict(check)
        code = str(item.get("code") or "").lower()
        if "malicious" not in code and "injection" not in code:
            continue
        surfaces.append(
            {
                "id": str(item.get("id") or f"browser_safety_prompt_injection_{index + 1}"),
                "surface_type": "prompt_injection",
                "content": item.get("message") or code,
                "source": _browser_record_source(record),
            }
        )
    return surfaces


def _browser_record_source(record: Mapping[str, Any]) -> str:
    text = json.dumps(record, default=str).lower()
    record_type = str(record.get("type") or record.get("event") or "").lower()
    if "computer_call" in record_type or "computer_screenshot" in text:
        return "openai_cua"
    if "browser_use" in text or "actionresult" in text or "agenthistory" in text:
        return "browser_use"
    return "browser_trace"


def _browser_screenshot_uri_from_value(value: Any) -> Optional[str]:
    if not value:
        return None
    text = str(value)
    if text.startswith(("http://", "https://", "file://", "data:")):
        return text
    if len(text) > 64 and all(ch.isalnum() or ch in "+/=\n\r" for ch in text[:128]):
        return f"data:image/png;base64,{text}"
    return None


def _browser_har_fixture(export: Any, *, resources: Mapping[str, str]) -> Dict[str, Any]:
    fixture = _empty_browser_trace_fixture(source_type="har")
    entries = _browser_har_entries(export)
    for index, entry in enumerate(entries):
        request = _coerce_plain_dict(entry.get("request"))
        response = _coerce_plain_dict(entry.get("response"))
        content = _coerce_plain_dict(response.get("content"))
        url = request.get("url") or entry.get("url")
        if not url:
            continue
        method = request.get("method")
        status = response.get("status")
        mime_type = content.get("mimeType") or content.get("mime_type")
        fixture["network_log"].append(
            {
                "id": str(entry.get("pageref") or entry.get("id") or f"har_entry_{index + 1}"),
                "url": str(url),
                "method": method,
                "status": status,
                "resource_type": _browser_resource_type_from_mime(mime_type),
                "started_at": entry.get("startedDateTime"),
                "time_ms": entry.get("time"),
                "source": "har",
            }
        )
        body = content.get("text")
        attached_file = content.get("_file") or content.get("fileName") or content.get("path")
        attached_uri = resources.get(str(attached_file)) or resources.get(os.path.basename(str(attached_file))) if attached_file else None
        if body is not None or attached_uri:
            fixture["resource_bodies"].append(
                {
                    "id": f"har_resource_{index + 1}",
                    "url": str(url),
                    "body": body,
                    "uri": attached_uri,
                    "mime_type": mime_type,
                    "encoding": content.get("encoding"),
                    "size": content.get("size"),
                    "source": "har",
                }
            )
        if body and "html" in str(mime_type or "").lower():
            fixture["snapshots"].append(
                {
                    "id": f"har_snapshot_{index + 1}",
                    "url": str(url),
                    "dom": body,
                    "metadata": {"source": "har", "status": status, "mime_type": mime_type},
                }
            )
    return fixture


def _browser_har_entries(export: Any) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    if isinstance(export, Mapping):
        data = copy.deepcopy(dict(export))
        log = _coerce_plain_dict(data.get("log"))
        raw_entries = log.get("entries") if log else data.get("entries")
        if raw_entries:
            return [_coerce_plain_dict(item) for item in _as_iterable(raw_entries) if _coerce_plain_dict(item)]
        for key in ("records", "events", "items", "data", "payload"):
            entries.extend(_browser_har_entries(data.get(key)))
    elif isinstance(export, Iterable) and not isinstance(export, (str, bytes)):
        for item in export:
            entries.extend(_browser_har_entries(item))
    return entries


def _browser_resource_type_from_mime(mime_type: Any) -> Optional[str]:
    text = str(mime_type or "").lower()
    if "html" in text:
        return "document"
    if "json" in text:
        return "xhr"
    if "javascript" in text or "ecmascript" in text:
        return "script"
    if "css" in text:
        return "stylesheet"
    if "image" in text:
        return "image"
    return None


def _browser_use_fixture(export: Any) -> Dict[str, Any]:
    fixture = _empty_browser_trace_fixture(source_type="browser_use")
    if not isinstance(export, Mapping):
        return fixture
    data = copy.deepcopy(dict(export))
    urls = _as_iterable(data.get("urls", []))
    screenshot_paths = _as_iterable(data.get("screenshot_paths", []))
    screenshots = _as_iterable(data.get("screenshots", []))
    steps = max(len(urls), len(screenshot_paths), len(screenshots))
    for index in range(steps):
        screenshot_uri = None
        screenshot_path = screenshot_paths[index] if index < len(screenshot_paths) else None
        if index < len(screenshots):
            screenshot_uri = _browser_screenshot_uri_from_value(screenshots[index])
        fixture["snapshots"].append(
            {
                "id": f"browser_use_snapshot_{index + 1}",
                "url": urls[index] if index < len(urls) else None,
                "screenshot_uri": screenshot_uri,
                "screenshot_path": screenshot_path,
                "metadata": {"source": "browser_use", "step": index + 1},
            }
        )
    action_names = _as_iterable(data.get("action_names", []))
    model_actions = _as_iterable(data.get("model_actions", data.get("actions", [])))
    action_results = _as_iterable(data.get("action_results", []))
    for index, raw_action in enumerate(model_actions):
        action_dict = _coerce_plain_dict(raw_action)
        if not action_dict and index < len(action_names):
            action_dict = {"type": action_names[index]}
        if not action_dict:
            continue
        action_dict.setdefault("type", action_names[index] if index < len(action_names) else action_dict.get("name"))
        result = _coerce_plain_dict(action_results[index]) if index < len(action_results) else {}
        record = {
            "type": action_dict.get("type") or action_dict.get("name") or "browser_use_action",
            "action": action_dict,
            "current_url": urls[index] if index < len(urls) else None,
            "status": "completed",
            "error": result.get("error"),
            "browser_use": True,
        }
        actions = _browser_actions_from_record(record, index=index)
        fixture["actions"].extend(actions)
        action_id = actions[-1].get("id") if actions else f"browser_trace_action_{index + 1}_1"
        if result:
            fixture["actionability_timeline"].append(
                {
                    "id": f"browser_use_actionability_{index + 1}",
                    "action_id": action_id,
                    "source": "browser_use",
                    "checks": {"tool_result_success": result.get("success", result.get("error") is None)},
                    "passed": result.get("success", result.get("error") is None) is not False,
                    "message": result.get("error"),
                }
            )
    return fixture


def _load_playwright_trace_source(source: str | os.PathLike[str]) -> Dict[str, Any]:
    source_text = os.fspath(source)
    metadata = {"source": _browser_source_label(source), "source_type": "playwright_trace"}
    if zipfile.is_zipfile(source_text):
        records: List[Any] = []
        resources: Dict[str, str] = {}
        videos: List[Dict[str, Any]] = []
        with zipfile.ZipFile(source_text) as archive:
            for name in archive.namelist():
                lower = name.lower()
                uri = f"zip://{source_text}#{name}"
                if lower.endswith((".png", ".jpg", ".jpeg", ".webp")):
                    resources[name] = uri
                    resources[os.path.basename(name)] = uri
                    continue
                if lower.endswith((".webm", ".mp4", ".mov")):
                    videos.append(
                        {
                            "uri": uri,
                            "id": os.path.basename(name),
                            "source": "playwright_trace_zip",
                            "mime_type": _browser_video_mime_type(name),
                        }
                    )
                    continue
                if not lower.endswith((".trace", ".json", ".jsonl")):
                    continue
                try:
                    text = archive.read(name).decode("utf-8")
                except UnicodeDecodeError:
                    continue
                parsed = _parse_framework_trace_export_text(text)
                records.extend(_as_iterable(parsed))
        return {"records": records, "resources": resources, "video_artifacts": videos, "metadata": metadata}

    parsed = _load_framework_trace_export_source(source_text)
    return {"records": _as_iterable(parsed), "metadata": metadata}


def _browser_source_label(source: Optional[str | os.PathLike[str]]) -> Optional[str]:
    if source is None:
        return None
    source_text = os.fspath(source)
    parsed = urlparse(source_text)
    if parsed.scheme in {"http", "https"}:
        return f"{parsed.scheme}://{parsed.netloc}{parsed.path}"
    return source_text


def _normalize_playwright_trace_export(
    trace_export: Any,
    *,
    source_label: Optional[str] = None,
) -> Dict[str, Any]:
    fixture = {
        "snapshots": [],
        "actions": [],
        "regions": [],
        "console_logs": [],
        "network_log": [],
        "storage_state": {"cookies": [], "origins": []},
        "runtime_events": [],
        "performance_entries": [],
        "video_artifacts": [],
        "prompt_injections": [],
        "perturbations": [],
        "metadata": {"source": source_label} if source_label else {},
    }
    if trace_export is None:
        return fixture

    export = trace_export
    resources: Dict[str, str] = {}
    if isinstance(export, Mapping) and any(key in export for key in ("records", "resources", "video_artifacts", "metadata")):
        wrapper = copy.deepcopy(dict(export))
        resources = {str(key): str(value) for key, value in dict(wrapper.get("resources", {})).items()}
        fixture["video_artifacts"].extend(_as_iterable(wrapper.get("video_artifacts", [])))
        fixture["metadata"].update(copy.deepcopy(dict(wrapper.get("metadata", {}))))
        export = wrapper.get("records", wrapper)

    direct = _coerce_plain_dict(export) if isinstance(export, Mapping) else {}
    fixture["snapshots"].extend(_as_iterable(direct.get("snapshots", [])))
    fixture["actions"].extend(_as_iterable(direct.get("actions", [])))
    fixture["regions"].extend(_as_iterable(direct.get("regions", [])))
    fixture["console_logs"].extend(_as_iterable(direct.get("console_logs", direct.get("console", []))))
    fixture["network_log"].extend(_as_iterable(direct.get("network_log", direct.get("network", []))))
    fixture["storage_state"] = _merge_browser_storage_states(
        fixture.get("storage_state"),
        _normalize_browser_storage_state(
            direct.get("storage_state", direct.get("storageState")),
            url=direct.get("url") or direct.get("current_url"),
            cookies=direct.get("cookies"),
            local_storage=direct.get("local_storage", direct.get("localStorage")),
            session_storage=direct.get("session_storage", direct.get("sessionStorage")),
        ),
    )
    fixture["runtime_events"].extend(
        _normalize_browser_runtime_event(item)
        for item in _as_iterable(direct.get("runtime_events", direct.get("runtime", [])))
    )
    fixture["performance_entries"].extend(
        _normalize_browser_performance_entry(item)
        for item in _as_iterable(direct.get("performance_entries", direct.get("performance", [])))
    )
    fixture["video_artifacts"].extend(_as_iterable(direct.get("videos", direct.get("video", []))))
    fixture["prompt_injections"].extend(_as_iterable(direct.get("prompt_injections", [])))
    fixture["perturbations"].extend(_as_iterable(direct.get("perturbations", [])))

    records = _playwright_trace_records(export)
    actions_by_id: Dict[str, Dict[str, Any]] = {}
    current_url: Optional[str] = None
    for index, record in enumerate(records):
        record_dict = _coerce_plain_dict(record)
        if not record_dict:
            continue
        current_url = str(record_dict.get("url") or record_dict.get("pageUrl") or current_url or "")

        action = _playwright_action_from_record(record_dict, index=index, current_url=current_url)
        if action:
            call_id = str(action.get("id"))
            if _playwright_record_type(record_dict) in {"after", "afteraction"} and call_id in actions_by_id:
                actions_by_id[call_id].update(action)
            else:
                actions_by_id[call_id] = action
            region = action.get("region")
            if isinstance(region, Mapping):
                fixture["regions"].append(region)

        snapshot = _playwright_snapshot_from_record(record_dict, index=index, resources=resources, current_url=current_url)
        if snapshot:
            fixture["snapshots"].append(snapshot)
            current_url = str(snapshot.get("url") or current_url or "")

        log = _playwright_console_log_from_record(record_dict)
        if log:
            fixture["console_logs"].append(log)

        request = _playwright_network_log_from_record(record_dict)
        if request:
            fixture["network_log"].append(request)
        fixture["storage_state"] = _merge_browser_storage_states(
            fixture.get("storage_state"),
            _browser_storage_state_from_record(record_dict),
        )
        fixture["runtime_events"].extend(_browser_runtime_events_from_record(record_dict, index=index))
        fixture["performance_entries"].extend(_browser_performance_entries_from_record(record_dict, index=index))

        fixture["video_artifacts"].extend(_playwright_video_artifacts_from_record(record_dict, resources=resources))
        fixture["perturbations"].extend(_playwright_perturbations_from_record(record_dict))

    fixture["actions"].extend(actions_by_id.values())
    fixture["video_artifacts"] = _dedupe_dicts(fixture["video_artifacts"])
    fixture["snapshots"] = _dedupe_dicts(fixture["snapshots"])
    fixture["actions"] = _dedupe_dicts(fixture["actions"])
    fixture["regions"] = _dedupe_dicts(fixture["regions"])
    fixture["console_logs"] = _dedupe_dicts(fixture["console_logs"])
    fixture["network_log"] = _dedupe_dicts(fixture["network_log"])
    fixture["runtime_events"] = _dedupe_dicts(fixture["runtime_events"])
    fixture["performance_entries"] = _dedupe_dicts(fixture["performance_entries"])
    fixture["perturbations"] = _dedupe_dicts(fixture["perturbations"])
    if any(fixture[key] for key in ("snapshots", "actions", "video_artifacts", "perturbations")):
        fixture["metadata"].setdefault("source_type", "playwright_trace")
    return fixture


def _playwright_trace_records(export: Any) -> List[Any]:
    if export is None:
        return []
    if isinstance(export, str):
        text = export.strip()
        if text.startswith(("{", "[")) or "\n" in text:
            return _playwright_trace_records(_parse_framework_trace_export_text(text))
        return []
    if hasattr(export, "model_dump"):
        return _playwright_trace_records(export.model_dump())
    if hasattr(export, "dict"):
        return _playwright_trace_records(export.dict())
    if isinstance(export, Mapping):
        data = dict(export)
        records: List[Any] = []
        for key in ("records", "events", "traceEvents", "trace_events", "actions", "snapshots"):
            if key in data:
                records.extend(_playwright_trace_records(data[key]))
        if records:
            return records
        if any(key in data for key in ("type", "method", "apiName", "snapshot", "params", "url", "selector")):
            return [data]
        for key in ("data", "payload", "result"):
            if isinstance(data.get(key), (Mapping, list, tuple)):
                nested = _playwright_trace_records(data[key])
                if nested:
                    return nested
        return []
    if isinstance(export, Iterable):
        records: List[Any] = []
        for item in export:
            records.extend(_playwright_trace_records(item))
        return records
    return []


def _playwright_record_type(record: Mapping[str, Any]) -> str:
    return str(record.get("type") or record.get("event") or record.get("kind") or "").lower().replace("_", "")


def _playwright_action_from_record(
    record: Mapping[str, Any],
    *,
    index: int,
    current_url: Optional[str],
) -> Optional[Dict[str, Any]]:
    params = _coerce_plain_dict(record.get("params") or record.get("arguments") or record.get("args"))
    method = str(
        record.get("apiName")
        or record.get("method")
        or record.get("action")
        or record.get("name")
        or params.get("method")
        or ""
    )
    record_type = _playwright_record_type(record)
    if record_type in {"after", "afteraction"}:
        call_id = str(record.get("callId") or record.get("call_id") or record.get("id") or f"playwright_action_{index + 1}")
        error = record.get("error") or record.get("errorMessage")
        return {
            "id": call_id,
            "success": not bool(error),
            "error": str(error) if error else None,
            "duration_ms": _playwright_duration_ms(record),
        }
    if not method:
        return None
    method_lower = method.lower()
    if not any(token in method_lower for token in ("click", "tap", "goto", "navigate", "fill", "press", "hover", "check", "select")):
        return None
    selector = (
        params.get("selector")
        or params.get("locator")
        or params.get("target")
        or record.get("selector")
        or record.get("locator")
    )
    url = params.get("url") or record.get("url") or record.get("pageUrl")
    call_id = str(record.get("callId") or record.get("call_id") or record.get("id") or f"playwright_action_{index + 1}")
    action: Dict[str, Any] = {
        "id": call_id,
        "action": method,
        "actions": [method],
        "current_url": current_url or record.get("pageUrl"),
        "next_url": url,
        "metadata": {
            "source": "playwright_trace",
            "api_name": method,
            "record_type": record_type,
            "start_time": record.get("startTime"),
            "end_time": record.get("endTime"),
        },
    }
    if selector:
        action["selector"] = str(selector)
        action["selectors"] = [str(selector)]
    if any(token in method_lower for token in ("click", "tap", "hover", "check", "select")):
        action["tool_names"] = ["browser_click", "playwright_click", "computer_click"]
    if any(token in method_lower for token in ("goto", "navigate")):
        action["tool_names"] = ["browser_navigate"]
    coordinates = _browser_action_coordinates({**params, **record})
    if coordinates:
        action["coordinates"] = coordinates
    region = _playwright_region_from_record(record, params=params, default_name=f"{call_id}_target")
    if region:
        action["region"] = region
    if record.get("error"):
        action["success"] = False
        action["error"] = str(record.get("error"))
    return {key: value for key, value in action.items() if value not in (None, "", [], {})}


def _playwright_region_from_record(
    record: Mapping[str, Any],
    *,
    params: Mapping[str, Any],
    default_name: str,
) -> Optional[Dict[str, Any]]:
    for source in (params, record):
        box = source.get("boundingBox") or source.get("bounding_box") or source.get("bbox") or source.get("bounds")
        if box:
            region = _normalize_browser_region({"bounds": box, "name": default_name}, default_name=default_name)
            selector = source.get("selector") or source.get("locator")
            if selector:
                region["selectors"] = [str(selector)]
            return region
    return None


def _playwright_snapshot_from_record(
    record: Mapping[str, Any],
    *,
    index: int,
    resources: Mapping[str, str],
    current_url: Optional[str],
) -> Optional[Dict[str, Any]]:
    record_type = _playwright_record_type(record)
    snapshot = _coerce_plain_dict(record.get("snapshot"))
    if record_type not in {"framesnapshot", "screencastframe", "snapshot"} and not snapshot:
        if not any(key in record for key in ("html", "dom", "screenshot_uri", "screenshot_path", "sha1")):
            return None
    source = snapshot or record
    html = source.get("html") or source.get("dom") or source.get("body")
    if isinstance(html, (list, tuple, dict)):
        html = json.dumps(html, default=str)
    url = source.get("url") or source.get("pageUrl") or record.get("url") or current_url
    sha1 = source.get("screenshotSha1") or source.get("screenshot_sha1") or source.get("sha1")
    screenshot_uri = source.get("screenshot_uri") or source.get("uri")
    if not screenshot_uri and sha1:
        screenshot_uri = resources.get(str(sha1)) or resources.get(os.path.basename(str(sha1)))
    item = {
        "id": str(source.get("id") or source.get("snapshotName") or source.get("frameId") or f"playwright_snapshot_{index + 1}"),
        "url": url,
        "dom": html,
        "screenshot_uri": screenshot_uri,
        "screenshot_path": source.get("screenshot_path") or source.get("path"),
        "metadata": {
            "source": "playwright_trace",
            "record_type": record_type,
            "page_id": record.get("pageId") or record.get("page_id"),
            "frame_id": source.get("frameId") or record.get("frameId"),
            "timestamp_ms": _as_number(record.get("timestamp") or record.get("time")),
        },
    }
    if source.get("stale") or source.get("stale_screenshot"):
        item["metadata"]["stale_screenshot"] = True
        item["metadata"]["stale"] = True
    return {key: value for key, value in item.items() if value not in (None, "", {}, [])}


def _playwright_console_log_from_record(record: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
    text = " ".join(str(record.get(key, "")) for key in ("type", "method", "event", "apiName", "name")).lower()
    if "console" not in text:
        return None
    params = _coerce_plain_dict(record.get("params") or record.get("args"))
    message = record.get("text") or record.get("message") or params.get("text") or params.get("message")
    if message is None:
        message = json.dumps(params or dict(record), default=str)
    return {
        "level": str(record.get("level") or params.get("type") or params.get("level") or "info"),
        "message": str(message),
        "source": "playwright_trace",
    }


def _playwright_network_log_from_record(record: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
    text = " ".join(str(record.get(key, "")) for key in ("type", "method", "event", "apiName", "name")).lower()
    if not any(token in text for token in ("request", "response", "resource", "network")):
        return None
    params = _coerce_plain_dict(record.get("params") or record.get("request") or record.get("response") or record.get("snapshot"))
    url = record.get("url") or params.get("url") or params.get("requestUrl")
    if not url:
        return None
    return {
        "url": str(url),
        "method": params.get("method") or record.get("method"),
        "status": params.get("status") or record.get("status"),
        "resource_type": params.get("resourceType") or record.get("resourceType"),
        "source": "playwright_trace",
    }


def _playwright_video_artifacts_from_record(
    record: Mapping[str, Any],
    *,
    resources: Mapping[str, str],
) -> List[Dict[str, Any]]:
    videos: List[Dict[str, Any]] = []
    for attachment in _as_iterable(record.get("attachments", record.get("attachment"))):
        item = _coerce_plain_dict(attachment)
        name = str(item.get("name") or item.get("path") or item.get("sha1") or "")
        content_type = str(item.get("contentType") or item.get("content_type") or "")
        if "video" not in content_type and not name.lower().endswith((".webm", ".mp4", ".mov")):
            continue
        uri = item.get("uri") or item.get("url") or resources.get(name) or resources.get(os.path.basename(name))
        videos.append(
            {
                "id": item.get("id") or os.path.basename(name) or "playwright_video",
                "uri": uri,
                "path": item.get("path") if not uri else None,
                "mime_type": content_type or _browser_video_mime_type(name),
                "source": "playwright_trace",
            }
        )
    if str(record.get("type") or "").lower() == "video":
        name = str(record.get("path") or record.get("sha1") or record.get("name") or "playwright_video")
        videos.append(
            {
                "id": record.get("id") or os.path.basename(name),
                "uri": record.get("uri") or resources.get(name) or resources.get(os.path.basename(name)),
                "path": record.get("path") if not record.get("uri") else None,
                "mime_type": record.get("mime_type") or _browser_video_mime_type(name),
                "source": "playwright_trace",
            }
        )
    return [video for video in videos if video.get("uri") or video.get("path")]


def _playwright_perturbations_from_record(record: Mapping[str, Any]) -> List[Dict[str, Any]]:
    text = _stringify_dict(record).lower()
    if "layout_shift" not in text and "layout-shift" not in text and "stale_screenshot" not in text and "stale screenshot" not in text:
        return []
    return [_normalize_browser_perturbation(record, index=0)]


def _playwright_duration_ms(record: Mapping[str, Any]) -> Optional[int]:
    start = _as_number(record.get("startTime") or record.get("start_time"))
    end = _as_number(record.get("endTime") or record.get("end_time"))
    if start is None or end is None or end < start:
        return None
    return int(end - start)


def _normalize_browser_perturbations(
    perturbations: Iterable[str | Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    return [
        _normalize_browser_perturbation(perturbation, index=index)
        for index, perturbation in enumerate(perturbations)
    ]


def _normalize_browser_perturbation(
    perturbation: str | Mapping[str, Any],
    *,
    index: int,
) -> Dict[str, Any]:
    item = copy.deepcopy(dict(perturbation)) if isinstance(perturbation, Mapping) else {"type": str(perturbation)}
    text = _stringify_dict(item).lower()
    kind = str(item.get("type") or item.get("kind") or item.get("name") or "")
    if not kind:
        if "stale" in text:
            kind = "stale_screenshot"
        elif "layout" in text and "shift" in text:
            kind = "layout_shift"
        else:
            kind = "browser_perturbation"
    kind = kind.strip().lower().replace("-", "_").replace(" ", "_")
    item["type"] = "stale_screenshot" if "stale" in kind else ("layout_shift" if "layout" in kind and "shift" in kind else kind)
    item.setdefault("id", f"{item['type']}_{index + 1}")
    if item["type"] == "layout_shift":
        score_samples = _browser_layout_shift_samples(item)
        if len(score_samples) > 1:
            item["distribution"] = _browser_score_distribution(score_samples)
        item.setdefault("score", item.get("value", item.get("layout_shift_score", item.get("cls"))))
        if item.get("score") is None and score_samples:
            item["score"] = max(score_samples)
        delta = _coerce_plain_dict(item.get("delta"))
        dx = _as_number(item.get("dx", item.get("x_shift", delta.get("x", delta.get("dx", 0)))))
        dy = _as_number(item.get("dy", item.get("y_shift", delta.get("y", delta.get("dy", 0)))))
        item["delta"] = {"x": dx or 0.0, "y": dy or 0.0}
    if "affected_regions" not in item:
        regions = item.get("regions", item.get("region", item.get("target_region")))
        if regions is not None:
            item["affected_regions"] = [str(value) for value in _as_iterable(regions)]
    return item


def _normalize_browser_mutation(
    mutation: str | Mapping[str, Any],
    *,
    index: int,
    default_url: Optional[str],
) -> Dict[str, Any]:
    item = copy.deepcopy(dict(mutation)) if isinstance(mutation, Mapping) else {"type": str(mutation)}
    text = _stringify_dict(item).lower()
    mutation_type = str(
        item.get("type")
        or item.get("kind")
        or item.get("mutation_type")
        or item.get("name")
        or ""
    )
    if not mutation_type:
        if "storage" in text:
            mutation_type = "storage_drift"
        elif "runtime" in text or "page_error" in text:
            mutation_type = "runtime_error"
        elif "overlay" in text or "modal" in text:
            mutation_type = "overlay"
        elif "selector" in text:
            mutation_type = "selector_alias"
        elif "layout" in text and "shift" in text:
            mutation_type = "layout_shift"
        elif "stale" in text:
            mutation_type = "stale_screenshot"
        else:
            mutation_type = "browser_mutation"
    mutation_type = _normalize_browser_mutation_type(mutation_type)
    item["type"] = mutation_type
    item.setdefault("id", f"{mutation_type}_{index + 1}")
    if default_url and not item.get("url"):
        item["url"] = default_url

    selector = _browser_mutation_selector(item)
    if selector:
        item["selector"] = selector
    selectors = _dedupe_strings(
        str(value)
        for value in [selector, *_as_iterable(item.get("selectors", []))]
        if str(value or "").strip()
    )
    if selectors:
        item["selectors"] = selectors
    alternate_selectors = _dedupe_strings(
        str(value)
        for value in _as_iterable(
            item.get(
                "alternate_selectors",
                item.get("selector_aliases", item.get("aliases", item.get("fallback_selectors", []))),
            )
        )
        if str(value or "").strip()
    )
    for key in ("alternate_selector", "new_selector", "replacement_selector", "fallback_selector"):
        if item.get(key):
            alternate_selectors.append(str(item[key]))
    alternate_selectors = _dedupe_strings(alternate_selectors)
    if alternate_selectors:
        item["alternate_selectors"] = alternate_selectors

    actionability = _browser_mutation_actionability(item)
    if actionability:
        item["actionability"] = actionability
    dom_patch = _browser_mutation_dom_patch(item)
    if dom_patch:
        item["dom_patch"] = dom_patch

    signals = set(_as_iterable(item.get("signals", [])))
    signals.update({"browser_mutation", mutation_type})
    if _browser_mutation_has_storage(item):
        signals.add("storage_state")
    if _browser_mutation_has_runtime(item):
        signals.add("runtime_event")
    if _browser_mutation_has_actionability(item):
        signals.add("actionability")
    if alternate_selectors:
        signals.add("selector_fallback")
    item["signals"] = sorted(_normalize_world_contract_key(signal) for signal in signals if signal)
    item["metadata"] = copy.deepcopy(_as_mapping(item.get("metadata")))
    return {key: value for key, value in item.items() if value not in (None, "", [], {})}


def _normalize_browser_mutation_type(value: Any) -> str:
    normalized = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "dom_swap": "dom_text_swap",
        "text_swap": "dom_text_swap",
        "text_replacement": "dom_text_swap",
        "dom_replacement": "dom_text_swap",
        "dom_mutation": "dom_patch",
        "selector_patch": "selector_alias",
        "stale_selector": "selector_alias",
        "selector_drift": "selector_alias",
        "disabled": "element_disabled",
        "disabled_element": "element_disabled",
        "actionability_failure": "element_disabled",
        "blocked_overlay": "overlay",
        "modal_overlay": "overlay",
        "storage": "storage_drift",
        "storage_state": "storage_drift",
        "storage_mutation": "storage_drift",
        "local_storage_drift": "storage_drift",
        "session_storage_drift": "storage_drift",
        "page_error": "runtime_error",
        "web_error": "runtime_error",
        "console_error": "runtime_error",
        "network": "network_fault",
        "network_error": "network_fault",
        "latency": "network_latency",
        "resource_latency": "network_latency",
        "layout_shift": "layout_shift",
        "stale_screenshot": "stale_screenshot",
    }
    return aliases.get(normalized, normalized or "browser_mutation")


def _browser_mutation_selector(mutation: Mapping[str, Any]) -> Optional[str]:
    for key in ("selector", "target_selector", "old_selector", "locator", "target", "element"):
        if mutation.get(key):
            return str(mutation[key])
    return None


def _browser_mutation_actionability(mutation: Mapping[str, Any]) -> Dict[str, Any]:
    checks = _coerce_plain_dict(mutation.get("actionability"))
    mutation_type = str(mutation.get("type") or "")
    if mutation_type in {"selector_alias"}:
        checks.setdefault("attached", False)
    if mutation_type in {"element_disabled"}:
        checks.setdefault("enabled", False)
    if mutation_type in {"overlay"}:
        checks.setdefault("receives_events", False)
    for key in ("attached", "visible", "enabled", "stable", "receives_events", "actionable"):
        if key in mutation:
            checks[key] = bool(mutation[key])
    return checks


def _browser_mutation_dom_patch(mutation: Mapping[str, Any]) -> Dict[str, Any]:
    patch = _coerce_plain_dict(mutation.get("dom_patch", mutation.get("patch")))
    replacements = _coerce_plain_dict(mutation.get("replace"))
    if replacements:
        patch["replace"] = {str(old): str(new) for old, new in replacements.items()}
    old_text = (
        mutation.get("old_text")
        or mutation.get("from_text")
        or mutation.get("target_text")
        or mutation.get("before_text")
    )
    new_text = (
        mutation.get("new_text")
        or mutation.get("to_text")
        or mutation.get("replacement_text")
        or mutation.get("after_text")
    )
    if old_text is not None and new_text is not None:
        replace = dict(patch.get("replace", {}))
        replace[str(old_text)] = str(new_text)
        patch["replace"] = replace
    if mutation.get("append_html") is not None:
        patch["append"] = str(mutation["append_html"])
    if mutation.get("prepend_html") is not None:
        patch["prepend"] = str(mutation["prepend_html"])
    if mutation.get("type") == "overlay" and not any(key in patch for key in ("append", "prepend", "set")):
        overlay = mutation.get("html") or mutation.get("dom") or (
            f"<div data-browser-mutation='{mutation.get('id')}' role='dialog'>"
            f"{mutation.get('message') or 'Blocking overlay'}</div>"
        )
        patch["append"] = str(overlay)
    return patch


def _browser_mutation_has_storage(mutation: Mapping[str, Any]) -> bool:
    return any(
        mutation.get(key) not in (None, "", [], {})
        for key in (
            "storage_state",
            "storageState",
            "cookies",
            "cookie",
            "local_storage",
            "localStorage",
            "session_storage",
            "sessionStorage",
        )
    ) or str(mutation.get("type") or "") == "storage_drift"


def _browser_mutation_has_runtime(mutation: Mapping[str, Any]) -> bool:
    return any(
        mutation.get(key) not in (None, "", [], {})
        for key in (
            "runtime_events",
            "runtime_event",
            "page_errors",
            "page_error",
            "web_errors",
            "web_error",
            "performance_entries",
            "performance",
            "resource_timing",
        )
    ) or str(mutation.get("type") or "") in {"runtime_error", "network_fault", "network_latency"}


def _browser_mutation_has_actionability(mutation: Mapping[str, Any]) -> bool:
    return bool(_coerce_plain_dict(mutation.get("actionability"))) or str(mutation.get("type") or "") in {
        "selector_alias",
        "element_disabled",
        "overlay",
    }


def _browser_mutation_perturbations(mutation_pack: Mapping[str, Any]) -> List[Dict[str, Any]]:
    perturbations: List[Dict[str, Any]] = []
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        if mutation_dict.get("type") not in {"layout_shift", "stale_screenshot"}:
            continue
        perturbation = copy.deepcopy(mutation_dict)
        perturbation["source"] = "browser_mutation_pack"
        perturbation["mutation_id"] = mutation_dict.get("id")
        perturbations.append(perturbation)
    return perturbations


def _apply_browser_mutations_to_snapshots(
    snapshots: List[Dict[str, Any]],
    mutation_pack: Mapping[str, Any],
) -> List[Dict[str, Any]]:
    updated = copy.deepcopy(snapshots)
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        mutation_type = str(mutation_dict.get("type") or "")
        if mutation_type not in {"dom_text_swap", "dom_patch", "selector_alias", "element_disabled", "overlay"} and not any(
            mutation_dict.get(key) not in (None, "", [], {})
            for key in ("dom", "dom_patch", "patch", "replace", "append_html", "prepend_html")
        ):
            continue
        for snapshot in updated:
            if not _browser_mutation_targets_snapshot(mutation_dict, snapshot):
                continue
            before = str(snapshot.get("dom", "") or "")
            base = str(mutation_dict.get("dom")) if mutation_dict.get("dom") is not None and mutation_type != "overlay" else before
            after = _apply_dom_patch(base, mutation_dict.get("dom_patch"))
            if after != before:
                snapshot["dom"] = after
            metadata = copy.deepcopy(dict(snapshot.get("metadata", {})))
            mutation_ids = list(_as_iterable(metadata.get("browser_mutation_ids", [])))
            if mutation_dict.get("id") not in mutation_ids:
                mutation_ids.append(mutation_dict.get("id"))
            metadata["browser_mutation_ids"] = [str(value) for value in mutation_ids if value]
            metadata["browser_mutated"] = True
            if mutation_type == "selector_alias":
                metadata["stale_selector"] = mutation_dict.get("selector")
                metadata["alternate_selectors"] = copy.deepcopy(mutation_dict.get("alternate_selectors", []))
            snapshot["metadata"] = metadata
    return updated


def _browser_mutation_targets_snapshot(mutation: Mapping[str, Any], snapshot: Mapping[str, Any]) -> bool:
    snapshot_targets = {
        str(value)
        for value in _as_iterable(
            mutation.get("snapshot_id")
            or mutation.get("snapshot")
            or mutation.get("screenshot_id")
            or mutation.get("screenshot")
        )
        if value not in (None, "")
    }
    if snapshot_targets:
        candidates = {
            str(snapshot.get("id", "")),
            str(snapshot.get("screenshot_uri", "")),
            str(snapshot.get("screenshot_path", "")),
        }
        return bool(snapshot_targets & candidates)
    mutation_url = str(mutation.get("url") or "")
    if mutation_url and str(snapshot.get("url") or "") != mutation_url:
        return False
    return True


def _browser_mutation_storage_state(
    mutation_pack: Mapping[str, Any],
    *,
    url: Optional[Any],
) -> Dict[str, Any]:
    states: List[Dict[str, Any]] = []
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        if not _browser_mutation_has_storage(mutation_dict):
            continue
        states.append(
            _normalize_browser_storage_state(
                mutation_dict.get("storage_state", mutation_dict.get("storageState")),
                url=mutation_dict.get("url") or url,
                cookies=mutation_dict.get("cookies", mutation_dict.get("cookie")),
                local_storage=mutation_dict.get("local_storage", mutation_dict.get("localStorage")),
                session_storage=mutation_dict.get("session_storage", mutation_dict.get("sessionStorage")),
            )
        )
    return _merge_browser_storage_states(*states)


def _browser_mutation_runtime_events(mutation_pack: Mapping[str, Any]) -> List[Dict[str, Any]]:
    events: List[Dict[str, Any]] = []
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        raw_events = [
            *_as_iterable(mutation_dict.get("runtime_events", mutation_dict.get("runtime_event"))),
            *_as_iterable(mutation_dict.get("page_errors", mutation_dict.get("page_error"))),
            *_as_iterable(mutation_dict.get("web_errors", mutation_dict.get("web_error"))),
        ]
        if not raw_events and str(mutation_dict.get("type") or "") in {"runtime_error", "network_fault"}:
            raw_events = [
                {
                    "type": "runtime_error" if mutation_dict.get("type") == "runtime_error" else "network_fault",
                    "level": "error" if mutation_dict.get("type") == "runtime_error" else "warning",
                    "message": mutation_dict.get("message") or mutation_dict.get("error") or mutation_dict.get("reason") or "Browser mutation runtime event.",
                }
            ]
        for raw in raw_events:
            event = _normalize_browser_runtime_event(raw)
            event.setdefault("source", "browser_mutation_pack")
            event.setdefault("mutation_id", mutation_dict.get("id"))
            event.setdefault("mutation_type", mutation_dict.get("type"))
            events.append(event)
    return _dedupe_dicts(events)


def _browser_mutation_performance_entries(mutation_pack: Mapping[str, Any]) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        raw_entries = _as_iterable(
            mutation_dict.get(
                "performance_entries",
                mutation_dict.get("performance", mutation_dict.get("resource_timing")),
            )
        )
        if not raw_entries and mutation_dict.get("type") in {"network_fault", "network_latency"}:
            duration = (
                mutation_dict.get("duration_ms")
                or mutation_dict.get("latency_ms")
                or mutation_dict.get("delay_ms")
                or mutation_dict.get("duration")
            )
            raw_entries = [
                {
                    "name": mutation_dict.get("request_url") or mutation_dict.get("url") or mutation_dict.get("resource") or "browser_mutation_resource",
                    "entry_type": "resource",
                    "duration_ms": duration or 0,
                }
            ]
        for raw in raw_entries:
            entry = _normalize_browser_performance_entry(raw)
            entry.setdefault("source", "browser_mutation_pack")
            entry.setdefault("mutation_id", mutation_dict.get("id"))
            entry.setdefault("mutation_type", mutation_dict.get("type"))
            entries.append(entry)
    return _dedupe_dicts(entries)


def _browser_mutation_network_log(mutation_pack: Mapping[str, Any]) -> List[Dict[str, Any]]:
    requests: List[Dict[str, Any]] = []
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        raw_requests = _as_iterable(mutation_dict.get("network_log", mutation_dict.get("network_request")))
        if not raw_requests and mutation_dict.get("type") in {"network_fault", "network_latency"}:
            raw_requests = [
                {
                    "url": mutation_dict.get("request_url") or mutation_dict.get("url") or mutation_dict.get("resource"),
                    "status": mutation_dict.get("status", 503 if mutation_dict.get("type") == "network_fault" else 200),
                    "latency_ms": mutation_dict.get("latency_ms", mutation_dict.get("delay_ms")),
                }
            ]
        for raw in raw_requests:
            request = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"url": str(raw)}
            request.setdefault("source", "browser_mutation_pack")
            request.setdefault("mutation_id", mutation_dict.get("id"))
            request.setdefault("mutation_type", mutation_dict.get("type"))
            requests.append({key: value for key, value in request.items() if value not in (None, "", [], {})})
    return _dedupe_dicts(requests)


def _browser_mutation_actionability_timeline(mutation_pack: Mapping[str, Any]) -> List[Dict[str, Any]]:
    checks: List[Dict[str, Any]] = []
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        actionability = _browser_mutation_actionability(mutation_dict)
        if not actionability:
            continue
        checks.append(
            {
                "id": f"{mutation_dict.get('id')}_actionability",
                "selector": mutation_dict.get("selector"),
                "mutation_id": mutation_dict.get("id"),
                "mutation_type": mutation_dict.get("type"),
                "checks": copy.deepcopy(actionability),
                "passed": all(value is not False for value in actionability.values()),
                "source": "browser_mutation_pack",
            }
        )
    return _dedupe_dicts(checks)


def _browser_mutation_action_effects(mutation_pack: Mapping[str, Any]) -> List[Dict[str, Any]]:
    effects: List[Dict[str, Any]] = []
    for mutation in _as_iterable(mutation_pack.get("mutations", [])):
        mutation_dict = _coerce_plain_dict(mutation)
        selector = mutation_dict.get("selector")
        actionability = _browser_mutation_actionability(mutation_dict)
        if selector and actionability:
            effects.append(
                _browser_mutation_action_effect(
                    mutation_dict,
                    selector=str(selector),
                    effect_id=f"{mutation_dict.get('id')}_primary",
                    actionability=actionability,
                    success_fields=False,
                )
            )
        for index, alternate_selector in enumerate(_as_iterable(mutation_dict.get("alternate_selectors", []))):
            effects.append(
                _browser_mutation_action_effect(
                    mutation_dict,
                    selector=str(alternate_selector),
                    effect_id=f"{mutation_dict.get('id')}_alternate_{index + 1}",
                    actionability={
                        "attached": True,
                        "visible": True,
                        "enabled": True,
                        "stable": True,
                        "receives_events": True,
                    },
                    success_fields=True,
                )
            )
    return [effect for effect in effects if effect]


def _browser_mutation_action_effect(
    mutation: Mapping[str, Any],
    *,
    selector: str,
    effect_id: str,
    actionability: Mapping[str, Any],
    success_fields: bool,
) -> Dict[str, Any]:
    effect: Dict[str, Any] = {
        "id": effect_id,
        "mutation_id": mutation.get("id"),
        "mutation_type": mutation.get("type"),
        "tool_names": ["browser_click", "playwright_click", "computer_click"],
        "selector": selector,
        "selectors": [selector],
        "current_url": mutation.get("current_url") or mutation.get("from_url") or mutation.get("url"),
        "actionability": copy.deepcopy(dict(actionability)),
        "metadata": {
            **copy.deepcopy(_as_mapping(mutation.get("metadata"))),
            "source": "browser_mutation_pack",
            "mutation_id": mutation.get("id"),
            "mutation_type": mutation.get("type"),
        },
    }
    if mutation.get("match_action_without_selector"):
        action = mutation.get("action") or mutation.get("expected_action") or "click"
        effect["action"] = str(action)
        effect["actions"] = [str(value) for value in _as_iterable(mutation.get("actions", action)) if str(value or "").strip()]
    if success_fields:
        for source_key, effect_key in (
            ("next_url", "next_url"),
            ("target_url", "target_url"),
            ("navigate_to", "navigate_to"),
            ("success_dom", "dom"),
            ("success_dom_patch", "dom_patch"),
            ("success_state_updates", "state_updates"),
            ("success_screenshot_uri", "screenshot_uri"),
            ("success_screenshot_path", "screenshot_path"),
            ("screenshot_diff", "screenshot_diff"),
            ("storage_state", "storage_state"),
            ("cookies", "cookies"),
            ("local_storage", "local_storage"),
            ("session_storage", "session_storage"),
            ("runtime_events", "runtime_events"),
            ("performance_entries", "performance_entries"),
        ):
            if mutation.get(source_key) not in (None, "", [], {}):
                effect[effect_key] = copy.deepcopy(mutation[source_key])
        if "state_updates" not in effect and mutation.get("state_updates") not in (None, "", [], {}):
            effect["state_updates"] = copy.deepcopy(mutation["state_updates"])
    else:
        effect["error"] = mutation.get("error") or mutation.get("reason") or "browser mutation actionability failure"
    return {key: value for key, value in effect.items() if value not in (None, "", [], {})}


def _browser_action_effect_mutation_id(effect: Optional[Mapping[str, Any]]) -> Optional[str]:
    if not effect:
        return None
    metadata = _as_mapping(effect.get("metadata"))
    value = effect.get("mutation_id") or metadata.get("mutation_id")
    return str(value) if value not in (None, "") else None


def _browser_action_effect_mutation_type(effect: Optional[Mapping[str, Any]]) -> Optional[str]:
    if not effect:
        return None
    metadata = _as_mapping(effect.get("metadata"))
    value = effect.get("mutation_type") or metadata.get("mutation_type")
    return str(value) if value not in (None, "") else None


def _browser_layout_shift_samples(source: Mapping[str, Any]) -> List[float]:
    samples: List[float] = []
    saw_series = False
    for key in ("scores", "samples", "values", "layout_shift_scores", "cls_values"):
        for value in _as_iterable(source.get(key, [])):
            score = _as_number(value)
            if score is not None:
                saw_series = True
                samples.append(score)
    distribution = _coerce_plain_dict(source.get("distribution"))
    if not saw_series:
        for key in ("scores", "samples", "values"):
            for value in _as_iterable(distribution.get(key, [])):
                score = _as_number(value)
                if score is not None:
                    saw_series = True
                    samples.append(score)
    score = _as_number(source.get("score", source.get("value", source.get("layout_shift_score", source.get("cls")))))
    if score is not None and not saw_series:
        samples.append(score)
    return samples


def _browser_layout_shift_distribution(perturbations: Iterable[Mapping[str, Any]]) -> Dict[str, Any]:
    scores: List[float] = []
    for perturbation in perturbations:
        if perturbation.get("type") != "layout_shift":
            continue
        scores.extend(_browser_layout_shift_samples(perturbation))
    if len(scores) <= 1:
        return {}
    return _browser_score_distribution(scores)


def _browser_score_distribution(values: Iterable[Any]) -> Dict[str, Any]:
    scores = sorted(float(score) for score in (_as_number(value) for value in values) if score is not None)
    if not scores:
        return {}
    count = len(scores)
    return {
        "count": count,
        "min": round(scores[0], 6),
        "max": round(scores[-1], 6),
        "mean": round(sum(scores) / count, 6),
        "p50": round(_percentile(scores, 0.50), 6),
        "p75": round(_percentile(scores, 0.75), 6),
        "p95": round(_percentile(scores, 0.95), 6),
        "p99": round(_percentile(scores, 0.99), 6),
        "scores": [round(score, 6) for score in scores],
    }


def _percentile(sorted_values: List[float], percentile: float) -> float:
    if not sorted_values:
        return 0.0
    if len(sorted_values) == 1:
        return sorted_values[0]
    position = (len(sorted_values) - 1) * percentile
    lower = int(position)
    upper = min(lower + 1, len(sorted_values) - 1)
    weight = position - lower
    return sorted_values[lower] * (1 - weight) + sorted_values[upper] * weight


def _apply_browser_perturbations_to_regions(
    regions: Dict[str, Dict[str, Any]],
    perturbations: Iterable[Mapping[str, Any]],
) -> Dict[str, Dict[str, Any]]:
    shifted = copy.deepcopy(regions)
    for perturbation in perturbations:
        if perturbation.get("type") != "layout_shift":
            continue
        delta = _coerce_plain_dict(perturbation.get("delta"))
        dx = _as_number(delta.get("x", delta.get("dx"))) or 0.0
        dy = _as_number(delta.get("y", delta.get("dy"))) or 0.0
        targets = [str(item) for item in _as_iterable(perturbation.get("affected_regions", []))]
        if not targets:
            targets = list(shifted.keys())
        for target in targets:
            region = shifted.get(target)
            if not region:
                continue
            region["x"] = float(region.get("x", 0.0)) + dx
            region["y"] = float(region.get("y", 0.0)) + dy
            region.setdefault("metadata", {})
            region["metadata"]["layout_shift"] = copy.deepcopy(dict(perturbation))
    return shifted


def _apply_browser_perturbations_to_snapshots(
    snapshots: List[Dict[str, Any]],
    perturbations: Iterable[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    updated = copy.deepcopy(snapshots)
    for perturbation in perturbations:
        if perturbation.get("type") != "stale_screenshot":
            continue
        targets = {
            str(value)
            for value in _as_iterable(
                perturbation.get("snapshot_id")
                or perturbation.get("snapshot")
                or perturbation.get("screenshot_id")
                or perturbation.get("screenshot")
            )
            if value not in (None, "")
        }
        for index, snapshot in enumerate(updated):
            candidates = {
                str(snapshot.get("id", "")),
                str(snapshot.get("screenshot_uri", "")),
                str(snapshot.get("screenshot_path", "")),
            }
            if targets and not (targets & candidates):
                continue
            if not targets and index != 0:
                continue
            metadata = copy.deepcopy(dict(snapshot.get("metadata", {})))
            metadata.update(
                {
                    "stale": True,
                    "stale_screenshot": True,
                    "stale_reason": perturbation.get("reason", "stale screenshot perturbation"),
                    "perturbation_id": perturbation.get("id"),
                }
            )
            snapshot["metadata"] = metadata
    return updated


def _browser_snapshot_perturbation_payload(
    snapshot: Mapping[str, Any],
    perturbations: Iterable[Mapping[str, Any]],
) -> Dict[str, Any]:
    metadata = _as_mapping(snapshot.get("metadata"))
    layout_shifts = [
        copy.deepcopy(dict(perturbation))
        for perturbation in perturbations
        if perturbation.get("type") == "layout_shift"
    ]
    payload: Dict[str, Any] = {}
    if metadata.get("stale") or metadata.get("stale_screenshot"):
        payload["stale_screenshot"] = True
        payload["stale_snapshot_id"] = snapshot.get("id")
    if layout_shifts:
        payload["layout_shifts"] = layout_shifts
        payload["layout_shift_score"] = max(
            [
                _as_number(shift.get("score", shift.get("value"))) or 0.0
                for shift in layout_shifts
            ]
        )
    return payload


def _normalize_browser_video_artifacts(
    videos: Iterable[str | Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for index, video in enumerate(videos):
        item = copy.deepcopy(dict(video)) if isinstance(video, Mapping) else {"uri": str(video)}
        item.setdefault("id", f"browser_video_{index + 1}")
        if "mime_type" not in item:
            item["mime_type"] = _browser_video_mime_type(str(item.get("uri") or item.get("path") or ""))
        normalized.append(item)
    return _dedupe_dicts(normalized)


def _browser_video_mime_type(path: str) -> str:
    lower = str(path).lower()
    if lower.endswith(".mp4"):
        return "video/mp4"
    if lower.endswith(".mov"):
        return "video/quicktime"
    return "video/webm"


def _dedupe_dicts(items: Iterable[Any]) -> List[Dict[str, Any]]:
    deduped: List[Dict[str, Any]] = []
    seen: set[str] = set()
    for item in items:
        data = copy.deepcopy(dict(item)) if isinstance(item, Mapping) else {"value": item}
        signature = json.dumps(data, sort_keys=True, default=str)
        if signature in seen:
            continue
        seen.add(signature)
        deduped.append(data)
    return deduped


def _normalize_browser_snapshots(
    snapshots: Optional[Iterable[Mapping[str, Any]]],
    *,
    url: str,
    dom: str,
    screenshot_uri: Optional[str],
    state: Mapping[str, Any],
) -> List[Dict[str, Any]]:
    raw_snapshots = list(snapshots or [])
    if not raw_snapshots:
        raw_snapshots = [
            {
                "id": "initial",
                "url": url,
                "dom": dom,
                "screenshot_uri": screenshot_uri,
                "state": copy.deepcopy(state),
            }
        ]
    normalized: List[Dict[str, Any]] = []
    for index, snapshot in enumerate(raw_snapshots):
        item = dict(snapshot)
        item.setdefault("id", f"snapshot_{index + 1}")
        item.setdefault("url", url)
        item.setdefault("dom", dom)
        if "screenshot_uri" not in item and "uri" in item:
            item["screenshot_uri"] = item.get("uri")
        if "screenshot_path" not in item and "path" in item:
            item["screenshot_path"] = item.get("path")
        item.setdefault("state", {})
        item.setdefault("metadata", {})
        normalized.append(item)
    return normalized


def _normalize_browser_actions(
    actions: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]],
) -> List[Dict[str, Any]]:
    if actions is None:
        return []
    raw_actions: List[Dict[str, Any]] = []
    if isinstance(actions, Mapping):
        for key, value in actions.items():
            if isinstance(value, Mapping):
                item = dict(value)
            else:
                item = {"next_url": value}
            if not any(item.get(field) for field in ("selector", "selectors", "locator", "action", "actions")):
                item["selector"] = str(key)
            item.setdefault("id", str(key))
            raw_actions.append(item)
    else:
        raw_actions = [dict(item) for item in actions]

    normalized: List[Dict[str, Any]] = []
    for index, item in enumerate(raw_actions):
        action = dict(item)
        action.setdefault("id", f"browser_action_{index + 1}")
        if "selectors" not in action:
            selectors = []
            for key in ("selector", "locator", "target", "element"):
                if action.get(key):
                    selectors.append(str(action[key]))
            if selectors:
                action["selectors"] = selectors
        if "actions" not in action and action.get("action"):
            action["actions"] = [str(action["action"])]
        if "tool_names" not in action and action.get("tool"):
            action["tool_names"] = [str(action["tool"])]
        if "state_updates" not in action and isinstance(action.get("state"), Mapping):
            action["state_updates"] = copy.deepcopy(dict(action["state"]))
        normalized.append(action)
    return normalized


def _normalize_browser_regions(
    regions: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]],
) -> Dict[str, Dict[str, Any]]:
    if regions is None:
        return {}
    raw_regions: List[Dict[str, Any]] = []
    if isinstance(regions, Mapping):
        for name, value in regions.items():
            item = dict(value) if isinstance(value, Mapping) else {"bounds": value}
            item.setdefault("name", str(name))
            raw_regions.append(item)
    else:
        raw_regions = [dict(item) for item in regions]

    normalized: Dict[str, Dict[str, Any]] = {}
    for index, item in enumerate(raw_regions):
        region = _normalize_browser_region(item, default_name=f"region_{index + 1}")
        name = str(region.get("name") or region.get("id") or f"region_{index + 1}")
        region["name"] = name
        normalized[name] = region
        if region.get("id"):
            normalized.setdefault(str(region["id"]), region)
    return normalized


def _normalize_browser_region(
    region: Mapping[str, Any],
    *,
    default_name: str,
) -> Dict[str, Any]:
    item = dict(region)
    bounds = item.get("bounds") or item.get("bbox") or item.get("box")
    if isinstance(bounds, Mapping):
        item.setdefault("x", bounds.get("x", bounds.get("left")))
        item.setdefault("y", bounds.get("y", bounds.get("top")))
        item.setdefault("width", bounds.get("width", bounds.get("w")))
        item.setdefault("height", bounds.get("height", bounds.get("h")))
    elif isinstance(bounds, (list, tuple)) and len(bounds) >= 4:
        item.setdefault("x", bounds[0])
        item.setdefault("y", bounds[1])
        item.setdefault("width", bounds[2])
        item.setdefault("height", bounds[3])
    item.setdefault("name", item.get("id") or default_name)
    if "selectors" not in item:
        selectors = []
        for key in ("selector", "locator", "target", "element"):
            if item.get(key):
                selectors.append(str(item[key]))
        if selectors:
            item["selectors"] = selectors
    for key in ("x", "y", "width", "height"):
        value = _as_number(item.get(key))
        if value is not None:
            item[key] = value
    return item


def _normalize_browser_prompt_injections(
    prompt_injections: Optional[Iterable[str | Mapping[str, Any]]],
    regions: Mapping[str, Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for index, item in enumerate(prompt_injections or []):
        surface = dict(item) if isinstance(item, Mapping) else {"content": str(item)}
        surface.setdefault("id", f"browser_prompt_injection_{index + 1}")
        surface.setdefault("surface_type", surface.get("type") or "prompt_injection")
        region = _browser_resolve_region(surface.get("region", surface.get("target_region")), regions)
        if region:
            surface["region"] = copy.deepcopy(region)
        elif isinstance(surface.get("bounds"), (Mapping, list, tuple)):
            surface["region"] = _normalize_browser_region(surface, default_name=str(surface["id"]))
        normalized.append(surface)
    return normalized


def _normalize_browser_log(item: str | Mapping[str, Any]) -> Dict[str, Any]:
    if isinstance(item, Mapping):
        log = dict(item)
        log.setdefault("level", "info")
        log.setdefault("message", "")
        return log
    return {"level": "info", "message": str(item)}


def _normalize_browser_storage_state(
    storage_state: Any,
    *,
    url: Optional[Any] = None,
    cookies: Optional[Iterable[Mapping[str, Any]] | Mapping[str, Any]] = None,
    local_storage: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]] = None,
    session_storage: Optional[Mapping[str, Any] | Iterable[Mapping[str, Any]]] = None,
) -> Dict[str, Any]:
    default_origin = _browser_origin_from_url(url)
    state = {"cookies": [], "origins": []}
    raw = _load_browser_storage_state(storage_state)
    if raw:
        state["cookies"].extend(_normalize_browser_cookies(raw.get("cookies"), url=url))
        for origin in _as_iterable(raw.get("origins", [])):
            origin_dict = _normalize_browser_storage_origin(origin, default_origin=default_origin)
            if origin_dict:
                state["origins"].append(origin_dict)
    state["cookies"].extend(_normalize_browser_cookies(cookies, url=url))
    for origin in _normalize_browser_origin_storage(local_storage, default_origin=default_origin, storage_key="localStorage"):
        state["origins"].append(origin)
    for origin in _normalize_browser_origin_storage(session_storage, default_origin=default_origin, storage_key="sessionStorage"):
        state["origins"].append(origin)
    return _merge_browser_storage_states(state)


def _load_browser_storage_state(value: Any) -> Dict[str, Any]:
    if not value:
        return {}
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    if hasattr(value, "model_dump"):
        return _load_browser_storage_state(value.model_dump())
    if hasattr(value, "dict"):
        return _load_browser_storage_state(value.dict())
    if isinstance(value, (str, os.PathLike)):
        text = os.fspath(value)
        stripped = text.strip()
        if stripped.startswith(("{", "[")):
            parsed = _parse_framework_trace_export_text(stripped)
            if isinstance(parsed, Mapping):
                return copy.deepcopy(dict(parsed))
            return {}
        if stripped.startswith("file://"):
            text = urlparse(stripped).path
        if not stripped.startswith(("http://", "https://")):
            try:
                with open(text, "r", encoding="utf-8") as handle:
                    parsed = json.load(handle)
                return copy.deepcopy(dict(parsed)) if isinstance(parsed, Mapping) else {}
            except (OSError, json.JSONDecodeError):
                return {}
    return {}


def _normalize_browser_cookies(
    cookies: Any,
    *,
    url: Optional[Any] = None,
) -> List[Dict[str, Any]]:
    if not cookies:
        return []
    default_domain = urlparse(str(url)).hostname if url else None
    if isinstance(cookies, Mapping) and not {"name", "value"}.intersection(cookies.keys()):
        return [
            _normalize_browser_cookie({"name": name, "value": value}, default_domain=default_domain)
            for name, value in cookies.items()
        ]
    return [
        cookie
        for cookie in (
            _normalize_browser_cookie(raw, default_domain=default_domain)
            for raw in _as_iterable(cookies)
        )
        if cookie
    ]


def _normalize_browser_cookie(raw: Any, *, default_domain: Optional[str]) -> Dict[str, Any]:
    item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"name": str(raw), "value": ""}
    if not item.get("name"):
        return {}
    item["name"] = str(item["name"])
    item["value"] = str(item.get("value", ""))
    if default_domain:
        item.setdefault("domain", default_domain)
    item.setdefault("path", "/")
    for key in ("httpOnly", "secure"):
        if key in item:
            item[key] = bool(item[key])
    if "sameSite" in item:
        item["sameSite"] = str(item["sameSite"])
    return {key: value for key, value in item.items() if value not in (None, {}, [])}


def _normalize_browser_origin_storage(
    storage: Any,
    *,
    default_origin: Optional[str],
    storage_key: str,
) -> List[Dict[str, Any]]:
    if not storage:
        return []
    if isinstance(storage, Mapping):
        if storage.get("origin") or storage.get("localStorage") or storage.get("sessionStorage"):
            return [_normalize_browser_storage_origin(storage, default_origin=default_origin)]
        origins = []
        for origin, values in storage.items():
            origins.append(
                _normalize_browser_storage_origin(
                    {"origin": origin, storage_key: values},
                    default_origin=default_origin,
                )
            )
        return [origin for origin in origins if origin]
    origins_by_name: Dict[str, Dict[str, Any]] = {}
    for raw in _as_iterable(storage):
        item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"name": str(raw), "value": ""}
        origin = str(item.get("origin") or default_origin or "")
        if not origin:
            continue
        origin_item = origins_by_name.setdefault(origin, {"origin": origin, storage_key: []})
        if item.get(storage_key):
            origin_item[storage_key].extend(_normalize_browser_storage_entries(item.get(storage_key)))
        else:
            entry = _normalize_browser_storage_entry(item)
            if entry:
                origin_item[storage_key].append(entry)
    return [origin for origin in origins_by_name.values() if origin.get(storage_key)]


def _normalize_browser_storage_origin(
    origin: Any,
    *,
    default_origin: Optional[str],
) -> Dict[str, Any]:
    item = copy.deepcopy(dict(origin)) if isinstance(origin, Mapping) else {"origin": str(origin)}
    origin_name = str(item.get("origin") or item.get("url") or default_origin or "")
    if not origin_name:
        return {}
    normalized: Dict[str, Any] = {"origin": origin_name}
    local = _normalize_browser_storage_entries(
        item.get("localStorage", item.get("local_storage", item.get("local")))
    )
    session = _normalize_browser_storage_entries(
        item.get("sessionStorage", item.get("session_storage", item.get("session")))
    )
    indexed_db = _as_iterable(item.get("indexedDB", item.get("indexed_db", [])))
    if local:
        normalized["localStorage"] = local
    if session:
        normalized["sessionStorage"] = session
    if indexed_db:
        normalized["indexedDB"] = [copy.deepcopy(dict(value)) if isinstance(value, Mapping) else {"value": value} for value in indexed_db]
    return normalized


def _normalize_browser_storage_entries(entries: Any) -> List[Dict[str, Any]]:
    if not entries:
        return []
    if isinstance(entries, Mapping):
        if entries.get("name") is not None:
            entries = [entries]
        else:
            entries = [{"name": name, "value": value} for name, value in entries.items()]
    normalized: List[Dict[str, Any]] = []
    for raw in _as_iterable(entries):
        entry = _normalize_browser_storage_entry(raw)
        if entry:
            normalized.append(entry)
    return normalized


def _normalize_browser_storage_entry(raw: Any) -> Dict[str, Any]:
    item = copy.deepcopy(dict(raw)) if isinstance(raw, Mapping) else {"name": str(raw), "value": ""}
    if item.get("name") is None and item.get("key") is not None:
        item["name"] = item["key"]
    if item.get("name") is None:
        return {}
    return {"name": str(item["name"]), "value": str(item.get("value", ""))}


def _merge_browser_storage_states(*states: Any) -> Dict[str, Any]:
    cookies: Dict[tuple[str, str, str], Dict[str, Any]] = {}
    origins: Dict[str, Dict[str, Any]] = {}
    for state in states:
        raw = _load_browser_storage_state(state)
        if not raw and isinstance(state, Mapping):
            raw = copy.deepcopy(dict(state))
        for cookie in _normalize_browser_cookies(raw.get("cookies", [])):
            signature = (
                str(cookie.get("name", "")),
                str(cookie.get("domain", "")),
                str(cookie.get("path", "")),
            )
            cookies[signature] = cookie
        for origin in _as_iterable(raw.get("origins", [])):
            origin_dict = _normalize_browser_storage_origin(origin, default_origin=None)
            origin_name = str(origin_dict.get("origin") or "")
            if not origin_name:
                continue
            merged = origins.setdefault(origin_name, {"origin": origin_name})
            for key in ("localStorage", "sessionStorage", "indexedDB"):
                values = _as_iterable(origin_dict.get(key, []))
                if not values:
                    continue
                if key == "indexedDB":
                    merged[key] = _dedupe_dicts([*merged.get(key, []), *values])
                    continue
                by_name = {
                    str(item.get("name")): copy.deepcopy(dict(item))
                    for item in _as_iterable(merged.get(key, []))
                    if isinstance(item, Mapping) and item.get("name") is not None
                }
                for item in values:
                    item_dict = _normalize_browser_storage_entry(item)
                    if item_dict:
                        by_name[str(item_dict["name"])] = item_dict
                merged[key] = list(by_name.values())
    return {
        "cookies": list(cookies.values()),
        "origins": [origin for origin in origins.values() if any(origin.get(key) for key in ("localStorage", "sessionStorage", "indexedDB"))],
    }


def _browser_apply_storage_effect(
    storage_state: Dict[str, Any],
    effect: Mapping[str, Any],
    *,
    url: Optional[Any],
) -> Dict[str, Any]:
    if effect.get("clear_storage"):
        storage_state.clear()
        storage_state.update({"cookies": [], "origins": []})
    updates = _normalize_browser_storage_state(
        effect.get("storage_state", effect.get("storageState")),
        url=url,
        cookies=effect.get("cookies", effect.get("cookie")),
        local_storage=effect.get("local_storage", effect.get("localStorage")),
        session_storage=effect.get("session_storage", effect.get("sessionStorage")),
    )
    if not _browser_storage_state_has_data(updates) and not effect.get("clear_storage"):
        return {}
    merged = _merge_browser_storage_states(storage_state, updates)
    storage_state.clear()
    storage_state.update(merged)
    return {"storage_state": copy.deepcopy(storage_state), "updated": copy.deepcopy(updates)}


def _browser_storage_state_has_data(storage_state: Mapping[str, Any]) -> bool:
    return bool(_as_iterable(storage_state.get("cookies", [])) or _as_iterable(storage_state.get("origins", [])))


def _browser_origin_from_url(url: Optional[Any]) -> Optional[str]:
    if not url:
        return None
    parsed = urlparse(str(url))
    if parsed.scheme and parsed.netloc:
        return f"{parsed.scheme}://{parsed.netloc}"
    return None


def _normalize_browser_runtime_event(item: str | Mapping[str, Any]) -> Dict[str, Any]:
    event = copy.deepcopy(dict(item)) if isinstance(item, Mapping) else {"message": str(item)}
    event_type = str(event.get("type") or event.get("event") or event.get("kind") or "").lower().replace("-", "_")
    level = str(event.get("level") or event.get("severity") or "").lower()
    message = event.get("message") or event.get("text") or event.get("error") or event.get("exception")
    if not event_type:
        if "page" in level and "error" in level:
            event_type = "page_error"
        elif "error" in level or event.get("error") or event.get("exception"):
            event_type = "runtime_error"
        else:
            event_type = "runtime_event"
    event["type"] = event_type
    if level:
        event["level"] = level
    if message is not None:
        event["message"] = str(message)
    return event


def _normalize_browser_performance_entry(item: Mapping[str, Any]) -> Dict[str, Any]:
    entry = copy.deepcopy(dict(item)) if isinstance(item, Mapping) else {"name": str(item)}
    entry_type = entry.get("entry_type", entry.get("entryType", entry.get("type", entry.get("initiatorType"))))
    if entry_type is not None:
        entry["entry_type"] = str(entry_type)
    duration = _as_number(entry.get("duration_ms", entry.get("duration", entry.get("time_ms", entry.get("time")))))
    if duration is not None:
        entry["duration_ms"] = duration
    start_time = _as_number(entry.get("start_time_ms", entry.get("startTime", entry.get("start_time"))))
    if start_time is not None:
        entry["start_time_ms"] = start_time
    if "name" in entry:
        entry["name"] = str(entry["name"])
    return {key: value for key, value in entry.items() if value not in (None, "", {}, [])}


def _browser_runtime_summary(
    runtime_events: Iterable[Mapping[str, Any]],
    performance_entries: Iterable[Mapping[str, Any]],
) -> Dict[str, Any]:
    events = [dict(item) for item in runtime_events]
    entries = [dict(item) for item in performance_entries]
    error_events = [
        item
        for item in events
        if "error" in str(item.get("type", "")).lower() or str(item.get("level", "")).lower() == "error"
    ]
    warning_events = [
        item
        for item in events
        if str(item.get("level", "")).lower() in {"warn", "warning"}
    ]
    durations = [
        value
        for value in (_as_number(item.get("duration_ms", item.get("duration"))) for item in entries)
        if value is not None
    ]
    return {
        "runtime_event_count": len(events),
        "error_count": len(error_events),
        "warning_count": len(warning_events),
        "performance_entry_count": len(entries),
        "max_duration_ms": max(durations) if durations else 0.0,
        "long_task_count": sum(1 for value in durations if value >= 50),
    }


def _browser_storage_state_from_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    browser_state = _coerce_plain_dict(record.get("browser_state") or record.get("state"))
    return _normalize_browser_storage_state(
        record.get("storage_state", record.get("storageState", browser_state.get("storage_state", browser_state.get("storageState")))),
        url=record.get("current_url") or record.get("url") or browser_state.get("url"),
        cookies=record.get("cookies", browser_state.get("cookies")),
        local_storage=record.get("local_storage", record.get("localStorage", browser_state.get("localStorage"))),
        session_storage=record.get("session_storage", record.get("sessionStorage", browser_state.get("sessionStorage"))),
    )


def _browser_runtime_events_from_record(record: Mapping[str, Any], *, index: int) -> List[Dict[str, Any]]:
    events = [
        _normalize_browser_runtime_event(item)
        for item in _as_iterable(record.get("runtime_events", record.get("runtime", [])))
    ]
    text = " ".join(str(record.get(key, "")) for key in ("type", "event", "kind", "method", "apiName", "name")).lower()
    if "pageerror" in text or "page_error" in text or "weberror" in text or "web_error" in text:
        event = _normalize_browser_runtime_event(
            {
                "id": record.get("id") or f"browser_runtime_event_{index + 1}",
                "type": "page_error" if "page" in text else "web_error",
                "message": record.get("message") or record.get("text") or record.get("error"),
                "source": _browser_record_source(record),
            }
        )
        events.append(event)
    elif record.get("error") or record.get("exception"):
        events.append(
            _normalize_browser_runtime_event(
                {
                    "id": record.get("id") or f"browser_runtime_event_{index + 1}",
                    "type": "runtime_error",
                    "message": record.get("error") or record.get("exception"),
                    "source": _browser_record_source(record),
                }
            )
        )
    if "serviceworker" in text or "service_worker" in text:
        events.append(
            _normalize_browser_runtime_event(
                {
                    "id": record.get("id") or f"service_worker_{index + 1}",
                    "type": "service_worker",
                    "url": record.get("url"),
                    "source": _browser_record_source(record),
                }
            )
        )
    return _dedupe_dicts(events)


def _browser_performance_entries_from_record(record: Mapping[str, Any], *, index: int) -> List[Dict[str, Any]]:
    entries = [
        _normalize_browser_performance_entry(item)
        for item in _as_iterable(record.get("performance_entries", record.get("performance", [])))
    ]
    text = " ".join(str(record.get(key, "")) for key in ("type", "event", "kind", "method", "apiName", "name")).lower()
    if any(token in text for token in ("performance", "navigation_timing", "resource_timing", "paint")):
        entry = _normalize_browser_performance_entry(
            {
                "id": record.get("id") or f"browser_performance_entry_{index + 1}",
                "name": record.get("name") or record.get("url") or record.get("apiName"),
                "entry_type": record.get("entry_type") or record.get("entryType") or record.get("type"),
                "duration_ms": record.get("duration_ms", record.get("duration", record.get("time"))),
                "start_time_ms": record.get("start_time_ms", record.get("startTime")),
                "source": _browser_record_source(record),
            }
        )
        if entry:
            entries.append(entry)
    return _dedupe_dicts(entries)


def _browser_action_selector(arguments: Mapping[str, Any]) -> Optional[str]:
    for key in ("selector", "locator", "target", "element", "test_id", "text"):
        value = arguments.get(key)
        if value:
            return str(value)
    return None


def _browser_action_effect_matches(
    effect: Mapping[str, Any],
    *,
    tool_name: str,
    arguments: Mapping[str, Any],
    action: str,
    current_url: str,
    regions: Mapping[str, Mapping[str, Any]],
) -> bool:
    tools = {str(value).lower() for value in _as_iterable(effect.get("tool_names", effect.get("tool")))}
    if tools and tool_name.lower() not in tools:
        return False

    expected_current_urls = {
        str(value)
        for value in _as_iterable(
            effect.get("current_url", effect.get("from_url", effect.get("match_url")))
        )
    }
    if expected_current_urls and current_url not in expected_current_urls:
        return False

    selector = _browser_action_selector(arguments)
    selectors = {str(value) for value in _as_iterable(effect.get("selectors", effect.get("selector")))}
    selector_match = bool(selector and selector in selectors) if selectors else False

    expected_actions = {
        _normalize_browser_action_text(value)
        for value in _as_iterable(effect.get("actions", effect.get("action")))
        if str(value)
    }
    action_text = _normalize_browser_action_text(action)
    action_match = bool(expected_actions and action_text in expected_actions)

    coordinate_match = _browser_coordinates_match(effect, arguments, regions)

    requested_url = arguments.get("url")
    expected_target_urls = {
        str(value)
        for value in _as_iterable(
            effect.get("next_url", effect.get("target_url", effect.get("navigate_to", effect.get("url"))))
        )
    }
    url_match = bool(requested_url and str(requested_url) in expected_target_urls)

    if selectors or expected_actions or _effect_has_coordinates(effect) or _effect_has_regions(effect) or expected_target_urls:
        return selector_match or action_match or coordinate_match or url_match
    return False


def _browser_coordinates_match(
    effect: Mapping[str, Any],
    arguments: Mapping[str, Any],
    regions: Mapping[str, Mapping[str, Any]],
) -> bool:
    coordinates = _browser_action_coordinates(arguments)
    if coordinates:
        expected_regions = _browser_expected_regions(effect, regions)
        if expected_regions and any(_browser_region_contains(region, coordinates) for region in expected_regions):
            return True

    expected = effect.get("coordinates")
    expected_x = effect.get("x")
    expected_y = effect.get("y")
    if isinstance(expected, Mapping):
        expected_x = expected.get("x", expected_x)
        expected_y = expected.get("y", expected_y)
    if expected_x is None or expected_y is None:
        return False
    if not coordinates:
        return False
    return coordinates.get("x") == _as_number(expected_x) and coordinates.get("y") == _as_number(expected_y)


def _effect_has_coordinates(effect: Mapping[str, Any]) -> bool:
    return effect.get("coordinates") is not None or (
        effect.get("x") is not None and effect.get("y") is not None
    )


def _effect_has_regions(effect: Mapping[str, Any]) -> bool:
    return any(
        effect.get(key) is not None
        for key in ("region", "regions", "target_region", "bounds", "bbox", "box")
    )


def _browser_action_coordinates(arguments: Mapping[str, Any]) -> Optional[Dict[str, float]]:
    actual_x = arguments.get("x")
    actual_y = arguments.get("y")
    if actual_x is None or actual_y is None:
        point = (
            arguments.get("coordinates")
            or arguments.get("coordinate")
            or arguments.get("point")
            or arguments.get("position")
        )
        if isinstance(point, Mapping):
            actual_x = point.get("x", point.get("left"))
            actual_y = point.get("y", point.get("top"))
        elif isinstance(point, (list, tuple)) and len(point) >= 2:
            actual_x = point[0]
            actual_y = point[1]
    x = _as_number(actual_x)
    y = _as_number(actual_y)
    if x is None or y is None:
        return None
    return {"x": x, "y": y}


def _browser_expected_regions(
    effect: Optional[Mapping[str, Any]],
    regions: Mapping[str, Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    if not effect:
        return []
    expected: List[Dict[str, Any]] = []
    for raw in _as_iterable(effect.get("regions", effect.get("region", effect.get("target_region")))):
        region = _browser_resolve_region(raw, regions)
        if region:
            expected.append(region)
    if not expected and any(effect.get(key) is not None for key in ("bounds", "bbox", "box")):
        expected.append(_normalize_browser_region(effect, default_name=str(effect.get("id") or "target_region")))
    return expected


def _browser_resolve_region(
    raw: Any,
    regions: Mapping[str, Mapping[str, Any]],
) -> Optional[Dict[str, Any]]:
    if raw is None:
        return None
    if isinstance(raw, str):
        region = regions.get(raw)
        if region:
            return copy.deepcopy(dict(region))
        return {"name": raw}
    if isinstance(raw, Mapping):
        if raw.get("name") in regions:
            return copy.deepcopy(dict(regions[str(raw["name"])]))
        if raw.get("id") in regions:
            return copy.deepcopy(dict(regions[str(raw["id"])]))
        return _normalize_browser_region(raw, default_name=str(raw.get("name") or raw.get("id") or "target_region"))
    if isinstance(raw, (list, tuple)) and len(raw) >= 4:
        return _normalize_browser_region({"bounds": raw}, default_name="target_region")
    return None


def _browser_observed_region(
    coordinates: Optional[Mapping[str, float]],
    regions: Mapping[str, Mapping[str, Any]],
) -> Optional[Dict[str, Any]]:
    if not coordinates:
        return None
    for region in regions.values():
        if _browser_region_contains(region, coordinates):
            return copy.deepcopy(dict(region))
    return None


def _browser_region_contains(region: Mapping[str, Any], coordinates: Mapping[str, float]) -> bool:
    x = _as_number(region.get("x"))
    y = _as_number(region.get("y"))
    width = _as_number(region.get("width"))
    height = _as_number(region.get("height"))
    actual_x = _as_number(coordinates.get("x"))
    actual_y = _as_number(coordinates.get("y"))
    if None in (x, y, width, height, actual_x, actual_y):
        return False
    return x <= actual_x <= x + width and y <= actual_y <= y + height


def _browser_prompt_injection_surfaces_for_action(
    arguments: Mapping[str, Any],
    prompt_injections: Iterable[Mapping[str, Any]],
    regions: Mapping[str, Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    selector = _browser_action_selector(arguments)
    coordinates = _browser_action_coordinates(arguments)
    touched: List[Dict[str, Any]] = []
    for surface in prompt_injections:
        selectors = {str(value) for value in _as_iterable(surface.get("selectors", surface.get("selector")))}
        selector_match = bool(selector and selector in selectors) if selectors else False
        region = _browser_resolve_region(surface.get("region", surface.get("target_region")), regions)
        region_match = bool(region and coordinates and _browser_region_contains(region, coordinates))
        if selector_match or region_match:
            touched.append(copy.deepcopy(dict(surface)))
    return touched


def _normalize_browser_screenshot_diff(
    diff: Any,
    *,
    effect_id: str,
) -> Optional[Dict[str, Any]]:
    if diff is None:
        return None
    if isinstance(diff, Mapping):
        item = copy.deepcopy(dict(diff))
    else:
        item = {"id": str(diff)}
    item.setdefault("id", f"{effect_id}_screenshot_diff" if effect_id else "screenshot_diff")
    if effect_id:
        item.setdefault("source_action", effect_id)
    if item.get("changed_regions") or item.get("regions") or item.get("semantic_summary"):
        semantic = _browser_semantic_screenshot_diff(item, item, {})
        if semantic:
            item = _merge_browser_screenshot_diff_semantics(item, semantic)
    return item


def _merge_browser_screenshot_diff(
    explicit: Optional[Dict[str, Any]],
    computed: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    if explicit and computed:
        merged = copy.deepcopy(computed)
        merged.update(copy.deepcopy(explicit))
        for key in (
            "changed_regions",
            "regions",
            "required_regions",
            "required_semantic_regions",
            "allowed_regions",
            "masked_regions",
            "mask_regions",
            "forbidden_regions",
        ):
            explicit_values = [str(value) for value in _as_iterable(explicit.get(key, []))]
            computed_values = [str(value) for value in _as_iterable(computed.get(key, []))]
            values = list(dict.fromkeys([*explicit_values, *computed_values]))
            if values:
                merged[key] = values
        if explicit.get("semantic_regions") or computed.get("semantic_regions"):
            merged["semantic_regions"] = _merge_browser_semantic_region_entries(
                computed.get("semantic_regions"),
                explicit.get("semantic_regions"),
            )
        if computed.get("semantic_summary") and "semantic_summary" not in explicit:
            merged["semantic_summary"] = copy.deepcopy(computed["semantic_summary"])
        merged.setdefault("pixel_diff", copy.deepcopy(computed.get("pixel_diff", computed)))
        return merged
    if explicit:
        semantic = _browser_semantic_screenshot_diff(explicit, explicit, {})
        return _merge_browser_screenshot_diff_semantics(explicit, semantic) if semantic else explicit
    return explicit or computed


def _compute_browser_screenshot_diff(
    before_snapshot: Mapping[str, Any],
    effect: Mapping[str, Any],
    *,
    after_uri: Any,
    after_path: Any,
    regions: Mapping[str, Mapping[str, Any]],
) -> Optional[Dict[str, Any]]:
    diff_spec = _coerce_plain_dict(effect.get("screenshot_diff", effect.get("screenshot_delta")))
    before_ref = (
        diff_spec.get("before_uri")
        or diff_spec.get("before_path")
        or diff_spec.get("before")
        or before_snapshot.get("screenshot_uri")
        or before_snapshot.get("screenshot_path")
    )
    after_ref = (
        diff_spec.get("after_uri")
        or diff_spec.get("after_path")
        or diff_spec.get("after")
        or effect.get("screenshot_uri")
        or effect.get("screenshot_path")
        or effect.get("uri")
        or effect.get("path")
        or after_uri
        or after_path
    )
    before_image = _load_browser_image_pixels(before_ref)
    after_image = _load_browser_image_pixels(after_ref)
    if not before_image or not after_image:
        return None
    threshold = _browser_pixel_threshold(diff_spec.get("threshold", diff_spec.get("pixel_threshold", 0)))
    diff = _browser_pixel_diff(
        before_image,
        after_image,
        threshold=threshold,
        regions=regions,
    )
    if not diff:
        return None
    effect_id = str(effect.get("id") or "")
    diff.setdefault("id", f"{effect_id}_pixel_diff" if effect_id else "browser_pixel_diff")
    if effect_id:
        diff.setdefault("source_action", effect_id)
    diff["before"] = str(before_ref)
    diff["after"] = str(after_ref)
    diff["source"] = "pixel_diff"
    diff["algorithm"] = "pixel_absdiff_v1"
    semantic = _browser_semantic_screenshot_diff(diff, diff_spec, regions)
    if semantic:
        diff.update(semantic)
    diff["pixel_diff"] = {
        key: copy.deepcopy(value)
        for key, value in diff.items()
        if key
        in {
            "width",
            "height",
            "compared_pixels",
            "changed_pixels",
            "changed_ratio",
            "changed_percent",
            "max_channel_delta",
            "mean_channel_delta",
            "threshold",
            "bounding_box",
            "changed_regions",
        }
    }
    return diff


def _browser_semantic_screenshot_diff(
    diff: Mapping[str, Any],
    spec: Mapping[str, Any],
    regions: Mapping[str, Mapping[str, Any]],
) -> Dict[str, Any]:
    changed_names = _browser_region_names_from_values(
        diff.get("changed_regions", diff.get("regions", []))
    )
    semantic_names = _browser_region_names_from_values(
        spec.get("semantic_regions", spec.get("required_semantic_regions", []))
    )
    required_names = _browser_region_names_from_values(
        spec.get("required_regions", spec.get("required_semantic_regions", spec.get("semantic_regions", [])))
    )
    allowed_names = _browser_region_names_from_values(
        spec.get("allowed_regions", spec.get("allow_regions", spec.get("allowed_changed_regions", [])))
    )
    masked_names = _browser_region_names_from_values(
        spec.get(
            "masked_regions",
            spec.get("mask_regions", spec.get("ignore_regions", spec.get("ignored_regions", []))),
        )
    )
    forbidden_names = _browser_region_names_from_values(
        spec.get(
            "forbidden_regions",
            spec.get("forbid_regions", spec.get("forbidden_changed_regions", [])),
        )
    )

    for name, region in regions.items():
        region_name = str(region.get("name") or region.get("id") or name)
        if _truthy(region.get("masked", region.get("mask", region.get("ignored", region.get("dynamic"))))):
            masked_names.append(region_name)
        if _truthy(region.get("allowed_change", region.get("allow_change", region.get("expected_change")))):
            allowed_names.append(region_name)
        if _truthy(region.get("forbidden_change", region.get("forbid_change", region.get("forbidden")))):
            forbidden_names.append(region_name)
        if _truthy(region.get("required_change", region.get("required"))):
            required_names.append(region_name)

    changed_names = _dedupe_names(changed_names)
    semantic_names = _dedupe_names(semantic_names)
    required_names = _dedupe_names(required_names)
    allowed_names = _dedupe_names(allowed_names)
    masked_names = _dedupe_names(masked_names)
    forbidden_names = _dedupe_names(forbidden_names)

    ordered_names = _dedupe_names(
        [
            *changed_names,
            *semantic_names,
            *required_names,
            *allowed_names,
            *masked_names,
            *forbidden_names,
        ]
    )
    if not ordered_names and not any(
        spec.get(key) is not None
        for key in (
            "semantic_regions",
            "required_regions",
            "required_semantic_regions",
            "allowed_regions",
            "masked_regions",
            "mask_regions",
            "forbidden_regions",
        )
    ):
        return {}

    masked_changed = [name for name in changed_names if name in masked_names]
    effective_changed = [name for name in changed_names if name not in masked_names]
    allowed_or_required = _dedupe_names([*allowed_names, *required_names])
    unexpected_changed = [
        name for name in effective_changed if allowed_or_required and name not in allowed_or_required
    ]
    forbidden_changed = [name for name in effective_changed if name in forbidden_names]
    missing_required = [name for name in required_names if name not in changed_names]
    semantic_entries = [
        _browser_semantic_region_entry(
            name,
            regions.get(name, {}),
            changed=name in changed_names,
            masked=name in masked_names,
            allowed=name in allowed_names or name in required_names,
            forbidden=name in forbidden_names,
            required=name in required_names,
        )
        for name in ordered_names
    ]

    return {
        "semantic_regions": semantic_entries,
        "required_regions": required_names,
        "allowed_regions": allowed_names,
        "masked_regions": masked_names,
        "forbidden_regions": forbidden_names,
        "semantic_summary": {
            "changed_regions": changed_names,
            "changed_semantic_regions": [name for name in changed_names if name in ordered_names],
            "masked_regions": masked_names,
            "masked_changed_regions": masked_changed,
            "effective_changed_regions": effective_changed,
            "required_regions": required_names,
            "missing_required_regions": missing_required,
            "allowed_regions": allowed_names,
            "unexpected_changed_regions": unexpected_changed,
            "forbidden_regions": forbidden_names,
            "forbidden_regions_changed": forbidden_changed,
            "only_allowed_regions_changed": not unexpected_changed and not forbidden_changed,
        },
    }


def _merge_browser_screenshot_diff_semantics(
    target: Mapping[str, Any],
    semantic: Mapping[str, Any],
) -> Dict[str, Any]:
    merged = copy.deepcopy(dict(target))
    for key, value in semantic.items():
        if key == "semantic_regions" and merged.get("semantic_regions"):
            merged[key] = _merge_browser_semantic_region_entries(value, merged.get(key))
        elif key == "semantic_summary" and merged.get("semantic_summary"):
            summary = copy.deepcopy(dict(value))
            summary.update(copy.deepcopy(dict(merged.get(key) or {})))
            merged[key] = summary
        else:
            merged.setdefault(key, copy.deepcopy(value))
    return merged


def _merge_browser_semantic_region_entries(*sources: Any) -> List[Dict[str, Any]]:
    merged: Dict[str, Dict[str, Any]] = {}
    order: List[str] = []
    for source in sources:
        for raw in _as_iterable(source):
            entry = dict(raw) if isinstance(raw, Mapping) else {"name": str(raw)}
            name = _browser_region_name(entry)
            if not name:
                continue
            if name not in merged:
                merged[name] = {"name": name}
                order.append(name)
            merged[name].update(copy.deepcopy(entry))
            merged[name]["name"] = name
    return [merged[name] for name in order]


def _browser_semantic_region_entry(
    name: str,
    region: Mapping[str, Any],
    *,
    changed: bool,
    masked: bool,
    allowed: bool,
    forbidden: bool,
    required: bool,
) -> Dict[str, Any]:
    entry = copy.deepcopy(dict(region)) if region else {"name": name}
    entry["name"] = str(entry.get("name") or entry.get("id") or name)
    entry["changed"] = bool(changed)
    entry["masked"] = bool(masked)
    entry["allowed"] = bool(allowed)
    entry["forbidden"] = bool(forbidden)
    entry["required"] = bool(required)
    if changed:
        entry["change_type"] = "masked" if masked else "semantic"
    return entry


def _browser_region_names_from_values(values: Any) -> List[str]:
    names: List[str] = []
    for value in _as_iterable(values):
        name = _browser_region_name(value)
        if name:
            names.append(name)
    return names


def _browser_region_name(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, Mapping):
        for key in ("name", "id", "region", "target_region", "selector", "label"):
            if value.get(key):
                return str(value[key])
        return None
    return str(value)


def _dedupe_names(values: Iterable[Any]) -> List[str]:
    return list(dict.fromkeys(str(value) for value in values if value is not None and str(value)))


def _truthy(value: Any) -> bool:
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "y", "on"}
    return bool(value)


def _browser_pixel_threshold(value: Any) -> int:
    threshold = _as_number(value)
    if threshold is None:
        return 0
    return max(0, min(255, int(threshold)))


def _load_browser_image_pixels(ref: Any) -> Optional[Dict[str, Any]]:
    data = _load_browser_image_bytes(ref)
    if not data:
        return None
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return _decode_browser_png(data)
    if data.startswith(b"P6") or data.startswith(b"P3"):
        return _decode_browser_ppm(data)
    return None


def _load_browser_image_bytes(ref: Any) -> Optional[bytes]:
    if not ref:
        return None
    if isinstance(ref, bytes):
        return ref
    text = str(ref)
    if text.startswith("data:image/"):
        _, _, payload = text.partition(",")
        if ";base64" not in text[: text.find(",") if "," in text else len(text)]:
            return None
        try:
            return base64.b64decode(payload)
        except (ValueError, TypeError):
            return None
    if text.startswith("file://"):
        text = urlparse(text).path
    if text.startswith("zip://") and "#" in text:
        archive_path, _, member = text[len("zip://") :].partition("#")
        try:
            with zipfile.ZipFile(archive_path) as archive:
                return archive.read(member)
        except (OSError, KeyError, zipfile.BadZipFile):
            return None
    if text.startswith(("http://", "https://")):
        return None
    try:
        with open(text, "rb") as handle:
            return handle.read()
    except OSError:
        return None


def _decode_browser_png(data: bytes) -> Optional[Dict[str, Any]]:
    try:
        offset = 8
        width = height = bit_depth = color_type = None
        compressed = bytearray()
        while offset + 8 <= len(data):
            length = struct.unpack(">I", data[offset : offset + 4])[0]
            chunk_type = data[offset + 4 : offset + 8]
            chunk = data[offset + 8 : offset + 8 + length]
            offset += 12 + length
            if chunk_type == b"IHDR":
                width, height, bit_depth, color_type, _, _, interlace = struct.unpack(">IIBBBBB", chunk)
                if bit_depth != 8 or interlace != 0 or color_type not in {0, 2, 6}:
                    return None
            elif chunk_type == b"IDAT":
                compressed.extend(chunk)
            elif chunk_type == b"IEND":
                break
        if width is None or height is None or bit_depth is None or color_type is None:
            return None
        channels = {0: 1, 2: 3, 6: 4}[color_type]
        row_bytes = int(width) * channels
        raw = zlib.decompress(bytes(compressed))
        rows: List[bytearray] = []
        cursor = 0
        previous = bytearray(row_bytes)
        for _ in range(int(height)):
            filter_type = raw[cursor]
            cursor += 1
            row = bytearray(raw[cursor : cursor + row_bytes])
            cursor += row_bytes
            _unfilter_png_row(row, previous, channels, filter_type)
            rows.append(row)
            previous = row
        pixels = []
        for row in rows:
            for x in range(int(width)):
                index = x * channels
                if color_type == 0:
                    gray = row[index]
                    pixels.append((gray, gray, gray, 255))
                elif color_type == 2:
                    pixels.append((row[index], row[index + 1], row[index + 2], 255))
                else:
                    pixels.append((row[index], row[index + 1], row[index + 2], row[index + 3]))
        return {"width": int(width), "height": int(height), "pixels": pixels}
    except (IndexError, KeyError, struct.error, ValueError, zlib.error):
        return None


def _unfilter_png_row(row: bytearray, previous: bytearray, channels: int, filter_type: int) -> None:
    for index, value in enumerate(row):
        left = row[index - channels] if index >= channels else 0
        up = previous[index] if previous else 0
        up_left = previous[index - channels] if previous and index >= channels else 0
        if filter_type == 0:
            continue
        if filter_type == 1:
            row[index] = (value + left) & 0xFF
        elif filter_type == 2:
            row[index] = (value + up) & 0xFF
        elif filter_type == 3:
            row[index] = (value + ((left + up) // 2)) & 0xFF
        elif filter_type == 4:
            row[index] = (value + _png_paeth(left, up, up_left)) & 0xFF
        else:
            raise ValueError("unsupported png filter")


def _png_paeth(left: int, up: int, up_left: int) -> int:
    estimate = left + up - up_left
    distances = (abs(estimate - left), abs(estimate - up), abs(estimate - up_left))
    if distances[0] <= distances[1] and distances[0] <= distances[2]:
        return left
    if distances[1] <= distances[2]:
        return up
    return up_left


def _decode_browser_ppm(data: bytes) -> Optional[Dict[str, Any]]:
    try:
        tokens: List[bytes] = []
        index = 0
        while len(tokens) < 4 and index < len(data):
            if data[index : index + 1] == b"#":
                while index < len(data) and data[index : index + 1] not in {b"\n", b"\r"}:
                    index += 1
                continue
            if data[index : index + 1].isspace():
                index += 1
                continue
            start = index
            while index < len(data) and not data[index : index + 1].isspace():
                index += 1
            tokens.append(data[start:index])
        if len(tokens) < 4:
            return None
        magic, width_raw, height_raw, max_raw = tokens
        width, height, max_value = int(width_raw), int(height_raw), int(max_raw)
        if max_value <= 0 or max_value > 255:
            return None
        while index < len(data) and data[index : index + 1].isspace():
            index += 1
        pixels = []
        if magic == b"P6":
            payload = data[index : index + width * height * 3]
            if len(payload) < width * height * 3:
                return None
            for offset in range(0, len(payload), 3):
                pixels.append((payload[offset], payload[offset + 1], payload[offset + 2], 255))
        elif magic == b"P3":
            values = [int(token) for token in data[index:].split()]
            if len(values) < width * height * 3:
                return None
            for offset in range(0, width * height * 3, 3):
                pixels.append((values[offset], values[offset + 1], values[offset + 2], 255))
        else:
            return None
        return {"width": width, "height": height, "pixels": pixels}
    except (ValueError, IndexError):
        return None


def _browser_pixel_diff(
    before: Mapping[str, Any],
    after: Mapping[str, Any],
    *,
    threshold: int,
    regions: Mapping[str, Mapping[str, Any]],
) -> Optional[Dict[str, Any]]:
    width = min(int(before.get("width", 0)), int(after.get("width", 0)))
    height = min(int(before.get("height", 0)), int(after.get("height", 0)))
    if width <= 0 or height <= 0:
        return None
    before_pixels = list(before.get("pixels", []))
    after_pixels = list(after.get("pixels", []))
    before_width = int(before.get("width", width))
    after_width = int(after.get("width", width))
    changed_pixels = 0
    channel_delta_sum = 0
    max_delta = 0
    min_x = min_y = None
    max_x = max_y = None
    for y in range(height):
        for x in range(width):
            before_pixel = before_pixels[(y * before_width) + x]
            after_pixel = after_pixels[(y * after_width) + x]
            deltas = [abs(int(a) - int(b)) for a, b in zip(before_pixel, after_pixel)]
            delta = max(deltas)
            if delta <= threshold:
                continue
            changed_pixels += 1
            channel_delta_sum += sum(deltas[:3]) / 3
            max_delta = max(max_delta, delta)
            min_x = x if min_x is None else min(min_x, x)
            min_y = y if min_y is None else min(min_y, y)
            max_x = x if max_x is None else max(max_x, x)
            max_y = y if max_y is None else max(max_y, y)
    compared = width * height
    changed_ratio = changed_pixels / compared if compared else 0.0
    bounding_box = None
    changed_regions: List[str] = []
    if min_x is not None and min_y is not None and max_x is not None and max_y is not None:
        bounding_box = {
            "x": float(min_x),
            "y": float(min_y),
            "width": float(max_x - min_x + 1),
            "height": float(max_y - min_y + 1),
        }
        changed_regions = _browser_regions_intersecting_box(bounding_box, regions)
    return {
        "width": width,
        "height": height,
        "compared_pixels": compared,
        "changed_pixels": changed_pixels,
        "changed_ratio": round(changed_ratio, 6),
        "changed_percent": round(changed_ratio * 100, 4),
        "max_channel_delta": max_delta,
        "mean_channel_delta": round(channel_delta_sum / changed_pixels, 4) if changed_pixels else 0.0,
        "threshold": threshold,
        "bounding_box": bounding_box,
        "changed_regions": changed_regions,
    }


def _browser_regions_intersecting_box(
    box: Mapping[str, Any],
    regions: Mapping[str, Mapping[str, Any]],
) -> List[str]:
    names: List[str] = []
    for name, region in regions.items():
        if _browser_boxes_intersect(box, region):
            names.append(str(region.get("name") or name))
    return list(dict.fromkeys(names))


def _browser_boxes_intersect(first: Mapping[str, Any], second: Mapping[str, Any]) -> bool:
    first_x = _as_number(first.get("x")) or 0.0
    first_y = _as_number(first.get("y")) or 0.0
    first_w = _as_number(first.get("width")) or 0.0
    first_h = _as_number(first.get("height")) or 0.0
    second_x = _as_number(second.get("x")) or 0.0
    second_y = _as_number(second.get("y")) or 0.0
    second_w = _as_number(second.get("width")) or 0.0
    second_h = _as_number(second.get("height")) or 0.0
    return (
        first_x < second_x + second_w
        and first_x + first_w > second_x
        and first_y < second_y + second_h
        and first_y + first_h > second_y
    )


def _browser_screenshot_diff_grounding(diff: Any) -> Dict[str, Any]:
    if not diff:
        return {}
    return {"screenshot_diff": copy.deepcopy(diff)}


def _as_number(value: Any) -> Optional[float]:
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None


def _browser_actionability_error(effect: Optional[Mapping[str, Any]]) -> str:
    if not effect:
        return ""
    checks = _browser_actionability_payload(effect)
    for key, value in checks.items():
        if value is False:
            return f"element failed actionability check: {key}"
    return ""


def _browser_actionability_payload(effect: Optional[Mapping[str, Any]]) -> Dict[str, Any]:
    if not effect:
        return {}
    defaults = {
        "attached": True,
        "visible": True,
        "enabled": True,
        "stable": True,
        "receives_events": True,
    }
    actionability = effect.get("actionability")
    if isinstance(actionability, Mapping):
        defaults.update(dict(actionability))
    for key in tuple(defaults.keys()):
        if key in effect:
            defaults[key] = bool(effect[key])
    if "actionable" in effect and effect.get("actionable") is False:
        defaults["actionable"] = False
    return defaults


def _normalize_browser_action_text(value: Any) -> str:
    return str(value or "").strip().lower()


def _apply_dom_patch(dom: str, patch: Any) -> str:
    if patch is None:
        return dom
    if isinstance(patch, str):
        return f"{dom}{patch}"
    if not isinstance(patch, Mapping):
        return dom

    result = str(patch.get("set", dom))
    replacements = patch.get("replace")
    if isinstance(replacements, Mapping):
        for old, new in replacements.items():
            result = result.replace(str(old), str(new))
    if patch.get("prepend") is not None:
        result = f"{patch['prepend']}{result}"
    if patch.get("append") is not None:
        result = f"{result}{patch['append']}"
    return result


def _as_iterable(value: Any) -> List[Any]:
    if value is None:
        return []
    if isinstance(value, (str, bytes)):
        return [value]
    if isinstance(value, Mapping):
        return [value]
    if hasattr(value, "__iter__"):
        return list(value)
    return [value]


def _normalize_voice_utterances(
    utterances: Iterable[str | Mapping[str, Any]],
    audio_uris: Iterable[str],
) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for index, value in enumerate(utterances):
        item = {"transcript": value} if isinstance(value, str) else dict(value)
        item.setdefault("id", f"utt_{index + 1}")
        normalized.append(item)
    offset = len(normalized)
    for index, uri in enumerate(audio_uris):
        normalized.append(
            {
                "id": f"audio_{index + 1 + offset}",
                "audio_uri": uri,
                "transcript": "",
            }
        )
    return normalized


def _normalize_voice_export(
    voice_export: Any,
    *,
    framework: str,
    source_label: Optional[str],
) -> Dict[str, Any]:
    framework_name = _normalize_voice_export_framework(
        _get_mapping_value(voice_export, "framework")
        or _get_mapping_value(voice_export, "source")
        or framework
    )
    payload: Dict[str, Any] = {
        "framework": framework_name,
        "utterances": [],
        "event_replay": [],
        "frame_replay": [],
        "waveforms": [],
        "diarization": [],
        "webrtc_stats": [],
        "perceptual_metrics": {},
        "timing_distribution": {},
        "metadata": {"framework": framework_name},
    }
    if source_label:
        payload["metadata"]["source"] = source_label

    if isinstance(voice_export, Mapping):
        export = copy.deepcopy(dict(voice_export))
        payload["metadata"].update(copy.deepcopy(dict(export.get("metadata", {}))))
        for key in ("utterances", "transcripts", "transcriptions"):
            for index, item in enumerate(_as_iterable(export.get(key))):
                utterance = _voice_utterance_from_export_record(item, key, index=index)
                if utterance:
                    payload["utterances"].append(utterance)
        for key in ("audio", "audio_artifacts", "recordings", "waveforms"):
            payload["waveforms"].extend(_normalize_voice_waveforms(_as_iterable(export.get(key)), sample_rate_hz=16000))
        for key in ("diarization", "speaker_segments", "speakers"):
            payload["diarization"].extend(_normalize_voice_diarization(export.get(key)))
        payload["webrtc_stats"].extend(_normalize_voice_webrtc_stats(export))
        payload["perceptual_metrics"] = _merge_voice_perceptual_metrics(
            export.get("perceptual_metrics"),
            export.get("audio_quality"),
            export.get("quality_profile"),
            export.get("metrics") if _looks_like_voice_quality_mapping(_as_mapping(export.get("metrics"))) else None,
        )
        payload["timing_distribution"] = _merge_voice_timing_distributions(
            payload["timing_distribution"],
            export.get("timing_distribution"),
            export.get("timing_profile"),
            export.get("timing"),
            export.get("latency_distribution"),
            export.get("latency_metrics"),
            export.get("metrics") if _looks_like_voice_timing_mapping(_as_mapping(export.get("metrics"))) else None,
        )

    for index, record in enumerate(_voice_export_records(voice_export)):
        item = _as_mapping(record)
        if not item:
            continue
        name = _voice_export_record_name(item)
        if _voice_export_record_is_frame(item, name):
            payload["frame_replay"].append(_normalize_voice_frame(item))
        event = _voice_event_from_export_record(item, name)
        if event:
            payload["event_replay"].append(event)
        utterance = _voice_utterance_from_export_record(item, name, index=index)
        if utterance:
            payload["utterances"].append(utterance)
        waveform = _voice_waveform_from_export_record(item, name, index=index)
        if waveform:
            payload["waveforms"].append(waveform)
        payload["diarization"].extend(_normalize_voice_diarization(item.get("diarization") or item.get("speaker_segments")))
        segment = _voice_diarization_segment_from_record(item, name)
        if segment:
            payload["diarization"].append(segment)
        payload["webrtc_stats"].extend(_normalize_voice_webrtc_stats(item))
        payload["perceptual_metrics"] = _merge_voice_perceptual_metrics(
            payload["perceptual_metrics"],
            _voice_perceptual_metrics_from_record(item),
        )
        payload["timing_distribution"] = _merge_voice_timing_distributions(
            payload["timing_distribution"],
            _voice_timing_distribution_from_record(item, name),
        )

    payload["utterances"] = _dedupe_voice_dicts(payload["utterances"], "id")
    payload["event_replay"] = _dedupe_voice_dicts(payload["event_replay"], "name", include_timestamp=True)
    payload["frame_replay"] = _dedupe_voice_dicts(payload["frame_replay"], "id", include_timestamp=True)
    payload["waveforms"] = _dedupe_voice_dicts(payload["waveforms"], "id")
    payload["diarization"] = _dedupe_voice_dicts(payload["diarization"], "id", include_timestamp=True)
    payload["webrtc_stats"] = _dedupe_voice_dicts(payload["webrtc_stats"], "id", include_timestamp=True)
    payload["perceptual_metrics"] = _merge_voice_perceptual_metrics(
        payload["perceptual_metrics"],
        {"segments": payload["webrtc_stats"]},
        waveforms=payload["waveforms"],
    )
    payload["timing_distribution"] = _normalize_voice_timing_distribution(payload["timing_distribution"])
    return payload


def _pipecat_frame_log_export(
    frame_log: Any,
    *,
    audio_captures: Optional[Iterable[str | Mapping[str, Any]]],
) -> Dict[str, Any]:
    export: Dict[str, Any] = {"framework": "pipecat", "frames": [], "events": []}
    if isinstance(frame_log, Mapping):
        item = copy.deepcopy(dict(frame_log))
        metadata = copy.deepcopy(dict(item.get("metadata", {})))
        metadata.setdefault("source_type", "pipecat_frame_log")
        export["metadata"] = metadata
        for key in (
            "frames",
            "frame_replay",
            "events",
            "records",
            "items",
            "messages",
            "history",
            "conversation",
            "transcripts",
            "transcriptions",
        ):
            if key in item:
                target_key = "frames" if key in {"frames", "frame_replay"} else "events"
                export[target_key].extend(copy.deepcopy(_as_iterable(item.get(key))))
        for key in ("audio_captures", "audio", "audio_artifacts", "recordings", "waveforms"):
            if key in item:
                export.setdefault("recordings", []).extend(copy.deepcopy(_as_iterable(item.get(key))))
        for key in ("diarization", "speaker_segments", "speakers"):
            if key in item:
                export[key] = copy.deepcopy(item[key])
        for key in ("webrtc_stats", "rtc_stats", "get_stats", "stats_report", "perceptual_metrics", "audio_quality", "quality_profile", "timing_distribution", "timing_profile", "timing", "latency_distribution", "latency_metrics", "metrics"):
            if key in item:
                export[key] = copy.deepcopy(item[key])
        if not export["frames"] and not export["events"] and _looks_like_voice_export_record(item):
            if _voice_export_record_is_frame(item, _voice_export_record_name(item)):
                export["frames"].append(item)
            else:
                export["events"].append(item)
    else:
        for record in _as_iterable(frame_log):
            item = copy.deepcopy(_as_mapping(record))
            if not item:
                continue
            if _voice_export_record_is_frame(item, _voice_export_record_name(item)):
                export["frames"].append(item)
            else:
                export["events"].append(item)

    if audio_captures is not None:
        export.setdefault("recordings", []).extend(copy.deepcopy(list(audio_captures)))
    return {key: value for key, value in export.items() if value not in (None, "", [], {})}


def _merge_voice_export_payloads(*payloads: Mapping[str, Any]) -> Dict[str, Any]:
    merged: Dict[str, Any] = {
        "framework": "voice",
        "utterances": [],
        "event_replay": [],
        "frame_replay": [],
        "waveforms": [],
        "diarization": [],
        "webrtc_stats": [],
        "perceptual_metrics": {},
        "timing_distribution": {},
        "metadata": {},
    }
    for payload in payloads:
        if not payload:
            continue
        merged["framework"] = str(payload.get("framework") or merged["framework"])
        merged["metadata"].update(copy.deepcopy(dict(payload.get("metadata", {}))))
        for key in ("utterances", "event_replay", "frame_replay", "waveforms", "diarization", "webrtc_stats"):
            merged[key].extend(copy.deepcopy(list(payload.get(key, []))))
        merged["perceptual_metrics"] = _merge_voice_perceptual_metrics(
            merged["perceptual_metrics"],
            payload.get("perceptual_metrics"),
        )
        merged["timing_distribution"] = _merge_voice_timing_distributions(
            merged["timing_distribution"],
            payload.get("timing_distribution"),
        )
    return merged


def _normalize_voice_export_framework(value: Any) -> str:
    normalized = str(value or "voice").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "livekit_agents": "livekit",
        "livekit_agent": "livekit",
        "lk": "livekit",
        "pipecat_ai": "pipecat",
        "pipecat_server": "pipecat",
        "traceai_voice": "traceai",
        "future_agi": "future_agi",
        "futureagi": "future_agi",
    }
    return aliases.get(normalized, normalized or "voice")


def _voice_export_records(voice_export: Any) -> List[Any]:
    if voice_export is None:
        return []
    if hasattr(voice_export, "model_dump"):
        return _voice_export_records(voice_export.model_dump())
    if hasattr(voice_export, "dict"):
        return _voice_export_records(voice_export.dict())
    if isinstance(voice_export, str):
        text = voice_export.strip()
        if text.startswith(("{", "[")) or "\n" in text:
            return _voice_export_records(_parse_framework_trace_export_text(text))
        return [{"text": voice_export}]
    if isinstance(voice_export, Mapping):
        export = copy.deepcopy(dict(voice_export))
        records: List[Any] = []
        for key in (
            "events",
            "session_events",
            "frames",
            "frame_replay",
            "records",
            "items",
            "results",
            "messages",
            "history",
            "conversation",
            "transcripts",
            "transcriptions",
        ):
            if key in export:
                records.extend(_voice_export_records(export[key]))
        for key in ("data", "result", "payload", "response", "body"):
            nested = export.get(key)
            if isinstance(nested, (Mapping, list, tuple)):
                nested_records = _voice_export_records(nested)
                if nested_records:
                    records.extend(nested_records)
        if records:
            return records
        return [export] if _looks_like_voice_export_record(export) else []
    if isinstance(voice_export, Iterable):
        records = []
        for item in voice_export:
            records.extend(_voice_export_records(item))
        return records
    return []


def _looks_like_voice_export_record(record: Mapping[str, Any]) -> bool:
    if not record:
        return False
    text = _stringify_dict(record).lower()
    return any(
        token in text
        for token in (
            "voice",
            "audio",
            "speech",
            "transcript",
            "transcription",
            "speaker",
            "diarization",
            "frame",
            "latency",
            "timing",
            "metrics",
            "webrtc",
            "rtp",
            "packetsreceived",
            "packetslost",
            "trackidentifier",
            "eou",
            "endpointing",
            "user_input_transcribed",
            "conversation_item_added",
            "agent_state_changed",
            "user_state_changed",
            "overlapping_speech",
            "interruption",
            "on_audio_data",
            "on_transcript_update",
        )
    )


def _voice_export_record_name(record: Mapping[str, Any]) -> str:
    payload = _as_mapping(record.get("payload") or record.get("data"))
    return str(
        record.get("name")
        or record.get("event")
        or record.get("type")
        or record.get("frame_type")
        or payload.get("name")
        or payload.get("event")
        or payload.get("type")
        or payload.get("frame_type")
        or "voice_event"
    )


def _voice_export_record_is_frame(record: Mapping[str, Any], name: str) -> bool:
    return bool(record.get("frame_type") or str(name).lower().endswith("frame") or "frame_type" in _as_mapping(record.get("payload")))


def _voice_event_from_export_record(record: Mapping[str, Any], name: str) -> Optional[Dict[str, Any]]:
    if not _looks_like_voice_export_record(record) and not _voice_export_record_is_frame(record, name):
        return None
    payload = copy.deepcopy(_as_mapping(record.get("payload") or record.get("data")))
    for key in (
        "transcript",
        "text",
        "speaker",
        "speaker_id",
        "role",
        "language",
        "is_final",
        "confidence",
        "old_state",
        "new_state",
        "route",
        "latency_ms",
        "duration_ms",
        "start_ms",
        "end_ms",
        "overlap_ms",
        "jitter_ms",
        "packet_loss_pct",
        "snr_db",
        "mos",
        "stage",
        "stage_name",
        "vad_ms",
        "vad_latency_ms",
        "vad_inference_duration_ms",
        "eou_delay_ms",
        "end_of_utterance_delay_ms",
        "stt_latency_ms",
        "llm_latency_ms",
        "tts_latency_ms",
        "turn_latency_ms",
        "ttft_ms",
        "time_to_first_audio_ms",
    ):
        if key in record and key not in payload:
            payload[key] = record[key]
    event_type = "voice_frame" if _voice_export_record_is_frame(record, name) else "voice"
    return {
        "type": event_type,
        "name": name,
        "payload": payload,
        "timestamp_ms": _voice_record_timestamp_ms(record),
        "metadata": {"source": "voice_export", **copy.deepcopy(dict(record.get("metadata", {})))},
    }


def _voice_utterance_from_export_record(record: Any, name: str, *, index: int) -> Optional[Dict[str, Any]]:
    item = _as_mapping(record)
    if not item:
        return None
    payload = _as_mapping(item.get("payload") or item.get("data"))
    event_text = f"{name} {_stringify_dict(item)}".lower()
    role = str(item.get("role") or payload.get("role") or "").lower()
    transcript = (
        item.get("transcript")
        or payload.get("transcript")
        or item.get("text")
        or payload.get("text")
        or item.get("text_content")
        or payload.get("text_content")
    )
    nested_item = _as_mapping(item.get("item") or payload.get("item"))
    if transcript is None and nested_item:
        role = str(nested_item.get("role") or role).lower()
        transcript = (
            nested_item.get("transcript")
            or nested_item.get("text")
            or nested_item.get("text_content")
            or _voice_text_from_content(nested_item.get("content"))
        )
    if transcript in (None, ""):
        return None
    if role and role not in {"user", "caller", "participant", "human"} and not any(
        token in event_text for token in ("transcription", "transcribed", "user_input", "user")
    ):
        return None
    if not (
        role in {"user", "caller", "participant", "human"}
        or any(token in event_text for token in ("transcription", "transcribed", "user_input", "user"))
    ):
        return None
    utterance_id = (
        item.get("id")
        or item.get("utterance_id")
        or item.get("speech_id")
        or item.get("frame_id")
        or payload.get("id")
        or payload.get("speech_id")
        or f"voice_export_utt_{index + 1}"
    )
    speaker = (
        item.get("speaker")
        or payload.get("speaker")
        or item.get("speaker_id")
        or payload.get("speaker_id")
        or item.get("user_id")
        or payload.get("user_id")
        or "user"
    )
    result = {
        "id": str(utterance_id),
        "speaker": str(speaker),
        "transcript": str(transcript),
    }
    for key in ("language", "confidence", "turn_index", "start_ms", "end_ms", "duration_ms", "latency_ms", "audio_uri", "audio_path"):
        value = item.get(key, payload.get(key))
        if value is not None:
            result[key] = value
    if item.get("is_final", payload.get("is_final")) is not None:
        result["is_final"] = bool(item.get("is_final", payload.get("is_final")))
    return result


def _voice_waveform_from_export_record(record: Mapping[str, Any], name: str, *, index: int) -> Optional[Dict[str, Any]]:
    payload = _as_mapping(record.get("payload") or record.get("data"))
    text = f"{name} {_stringify_dict(record)}".lower()
    if _looks_like_voice_webrtc_stat_record(record) and not any(
        key in record or key in payload
        for key in (
            "audio",
            "audio_data",
            "audio_uri",
            "audio_path",
            "recording_uri",
            "uri",
            "path",
            "data",
            "sample_count",
            "num_frames",
            "duration_ms",
        )
    ):
        return None
    if not any(token in text for token in ("audio", "waveform", "recording", "webrtc", "rtp", "on_user_turn_audio_data", "on_bot_turn_audio_data")):
        return None
    waveform = {
        "id": str(record.get("id") or record.get("frame_id") or payload.get("id") or f"voice_export_audio_{index + 1}"),
        "source": "voice_export",
        "speaker": record.get("speaker", payload.get("speaker", payload.get("speaker_id", payload.get("user_id")))),
    }
    for source_key, target_key in (
        ("uri", "uri"),
        ("audio_uri", "uri"),
        ("recording_uri", "uri"),
        ("url", "uri"),
        ("path", "path"),
        ("audio_path", "path"),
        ("audio", "data"),
        ("audio_data", "data"),
        ("data", "data"),
        ("sample_rate_hz", "sample_rate_hz"),
        ("sample_rate", "sample_rate_hz"),
        ("num_channels", "channels"),
        ("channels", "channels"),
        ("num_frames", "sample_count"),
        ("sample_count", "sample_count"),
        ("duration_ms", "duration_ms"),
        ("start_ms", "start_ms"),
        ("end_ms", "end_ms"),
        ("transcript", "transcript"),
        ("text", "transcript"),
    ):
        value = record.get(source_key, payload.get(source_key))
        if value is not None:
            waveform[target_key] = value
    waveform.update(_voice_quality_from_mapping(record))
    waveform.update(_voice_quality_from_mapping(payload))
    return waveform


def _voice_text_from_content(content: Any) -> Optional[str]:
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, str):
                parts.append(item)
            else:
                item_dict = _as_mapping(item)
                text = item_dict.get("text") or item_dict.get("transcript")
                if text:
                    parts.append(str(text))
        return " ".join(parts) if parts else None
    return None


def _voice_record_timestamp_ms(record: Mapping[str, Any]) -> Optional[int]:
    for key in ("timestamp_ms", "time_ms", "start_ms"):
        value = _voice_int(record.get(key))
        if value is not None:
            return value
    for key in ("timestamp", "created_at", "detected_at"):
        value = _voice_float(record.get(key))
        if value is not None:
            return int(value * 1000 if value < 10_000 else value)
    return None


def _normalize_voice_waveforms(
    waveforms: Iterable[str | Mapping[str, Any]],
    *,
    utterances: Optional[Iterable[Mapping[str, Any]]] = None,
    sample_rate_hz: int = 16000,
) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for index, value in enumerate(waveforms):
        if value in (None, ""):
            continue
        item = _normalize_voice_waveform(value, index=index, sample_rate_hz=sample_rate_hz)
        normalized.append(item)
    seen_ids = {str(item.get("id")) for item in normalized}
    for index, utterance in enumerate(utterances or []):
        utterance_id = str(utterance.get("id") or f"utt_{index + 1}")
        if utterance_id in seen_ids:
            continue
        normalized.append(_voice_waveform_from_utterance(utterance, sample_rate_hz=sample_rate_hz))
        seen_ids.add(utterance_id)
    return _dedupe_voice_dicts(normalized, "id")


def _normalize_voice_waveform(value: str | Mapping[str, Any], *, index: int, sample_rate_hz: int) -> Dict[str, Any]:
    if isinstance(value, str):
        location_key = "uri" if value.startswith(("http://", "https://", "file://", "data:")) else "path"
        item: Dict[str, Any] = {location_key: value}
    else:
        item = copy.deepcopy(dict(value))
    item.setdefault("id", f"waveform_{index + 1}")
    item["id"] = str(item["id"])
    if "sample_rate" in item and "sample_rate_hz" not in item:
        item["sample_rate_hz"] = item.pop("sample_rate")
    item.setdefault("sample_rate_hz", sample_rate_hz)
    if "num_channels" in item and "channels" not in item:
        item["channels"] = item.pop("num_channels")
    item.setdefault("channels", 1)
    if "num_frames" in item and "sample_count" not in item:
        item["sample_count"] = item.pop("num_frames")
    media_metadata = _voice_media_metadata_from_waveform(item)
    if media_metadata:
        item.update(media_metadata)
    if item.get("duration_ms") is None and item.get("start_ms") is not None and item.get("end_ms") is not None:
        item["duration_ms"] = max(0, int(item["end_ms"]) - int(item["start_ms"]))
    if item.get("sample_count") is None and item.get("duration_ms") is not None:
        item["sample_count"] = int(float(item["sample_rate_hz"]) * float(item["duration_ms"]) / 1000)
    item.update(_voice_quality_from_mapping(item))
    if item.get("uri") is None and item.get("path") is None and item.get("data") is None:
        item["data"] = _voice_synthetic_waveform_data(item)
    return item


def _voice_media_metadata_from_waveform(waveform: Mapping[str, Any]) -> Dict[str, Any]:
    path = _voice_local_audio_path(waveform)
    if path:
        metadata = _voice_wav_metadata_from_path(path)
        if metadata:
            return metadata
        data = _voice_bytes_from_path(path)
        if data:
            return _voice_pcm_metadata_from_bytes(data, waveform, media_source="pcm_file")

    uri = str(waveform.get("uri") or "")
    data_uri = _voice_bytes_from_data_uri(uri)
    if data_uri:
        metadata = _voice_wav_metadata_from_bytes(data_uri)
        if metadata:
            metadata["media_source"] = "wav_data_uri"
            return metadata
        return _voice_pcm_metadata_from_bytes(data_uri, waveform, media_source="pcm_data_uri")

    raw_data = _voice_bytes_from_payload(waveform.get("data"), waveform)
    if raw_data:
        metadata = _voice_wav_metadata_from_bytes(raw_data)
        if metadata:
            metadata["media_source"] = "wav_bytes"
            return metadata
        return _voice_pcm_metadata_from_bytes(raw_data, waveform, media_source="pcm_bytes")
    return {}


def _voice_local_audio_path(waveform: Mapping[str, Any]) -> str:
    raw = waveform.get("path")
    if raw in (None, ""):
        uri = str(waveform.get("uri") or "")
        parsed = urlparse(uri)
        if parsed.scheme != "file":
            return ""
        raw = unquote(parsed.path)
    path = os.path.expanduser(str(raw))
    return path if os.path.exists(path) and os.path.isfile(path) else ""


def _voice_wav_metadata_from_path(path: str) -> Dict[str, Any]:
    if not path.lower().endswith((".wav", ".wave")):
        return {}
    try:
        with wave.open(path, "rb") as wav_file:
            return _voice_wav_metadata(wav_file, media_source="wav_file")
    except (wave.Error, OSError, EOFError):
        return {}


def _voice_wav_metadata_from_bytes(data: bytes) -> Dict[str, Any]:
    if not data.startswith(b"RIFF"):
        return {}
    try:
        with wave.open(io.BytesIO(data), "rb") as wav_file:
            return _voice_wav_metadata(wav_file, media_source="wav_bytes")
    except (wave.Error, EOFError):
        return {}


def _voice_wav_metadata(wav_file: wave.Wave_read, *, media_source: str) -> Dict[str, Any]:
    channels = wav_file.getnchannels()
    sample_rate_hz = wav_file.getframerate()
    sample_width_bytes = wav_file.getsampwidth()
    sample_count = wav_file.getnframes()
    raw = wav_file.readframes(sample_count)
    metadata = {
        "decoded_audio": True,
        "media_source": media_source,
        "media_format": "wav",
        "sample_rate_hz": sample_rate_hz,
        "channels": channels,
        "sample_width_bytes": sample_width_bytes,
        "sample_count": sample_count,
        "duration_ms": round((sample_count / sample_rate_hz) * 1000, 4) if sample_rate_hz else 0,
    }
    metadata.update(_voice_pcm_stats(raw, sample_width_bytes=sample_width_bytes, channels=channels))
    return metadata


def _voice_pcm_metadata_from_bytes(
    data: bytes,
    waveform: Mapping[str, Any],
    *,
    media_source: str,
) -> Dict[str, Any]:
    if not _voice_pcm_hint(waveform):
        return {}
    sample_rate_hz = _voice_int(waveform.get("sample_rate_hz") or waveform.get("sample_rate") or 16000) or 16000
    channels = _voice_int(waveform.get("channels") or waveform.get("num_channels") or 1) or 1
    sample_width_bytes = (
        _voice_int(waveform.get("sample_width_bytes"))
        or _voice_int(waveform.get("sample_width"))
        or _voice_bits_to_bytes(waveform.get("bits_per_sample"))
        or 2
    )
    frame_count = int(len(data) / max(1, sample_width_bytes * channels))
    metadata = {
        "decoded_audio": True,
        "media_source": media_source,
        "media_format": str(waveform.get("media_format") or waveform.get("format") or waveform.get("encoding") or "pcm").lower(),
        "sample_rate_hz": sample_rate_hz,
        "channels": channels,
        "sample_width_bytes": sample_width_bytes,
        "sample_count": frame_count,
        "duration_ms": round((frame_count / sample_rate_hz) * 1000, 4) if sample_rate_hz else 0,
    }
    metadata.update(_voice_pcm_stats(data, sample_width_bytes=sample_width_bytes, channels=channels))
    return metadata


def _voice_pcm_hint(waveform: Mapping[str, Any]) -> bool:
    text = " ".join(
        str(waveform.get(key, ""))
        for key in ("media_format", "format", "encoding", "mime_type", "content_type")
    ).lower()
    return any(token in text for token in ("pcm", "linear16", "s16le", "raw"))


def _voice_bits_to_bytes(value: Any) -> Optional[int]:
    bits = _voice_int(value)
    if bits in (8, 16, 24, 32):
        return bits // 8
    return None


def _voice_bytes_from_path(path: str) -> bytes:
    try:
        with open(path, "rb") as handle:
            return handle.read()
    except OSError:
        return b""


def _voice_bytes_from_data_uri(value: str) -> bytes:
    if not value.startswith("data:") or "," not in value:
        return b""
    header, payload = value.split(",", 1)
    try:
        if ";base64" in header:
            return base64.b64decode(payload)
        return unquote(payload).encode("utf-8")
    except (ValueError, OSError):
        return b""


def _voice_bytes_from_payload(value: Any, waveform: Mapping[str, Any]) -> bytes:
    if isinstance(value, (bytes, bytearray)):
        return bytes(value)
    if isinstance(value, str):
        if value.startswith("data:"):
            return _voice_bytes_from_data_uri(value)
        encoding = str(waveform.get("data_encoding") or waveform.get("encoding") or "").lower()
        if "base64" in encoding:
            try:
                return base64.b64decode(value)
            except (ValueError, OSError):
                return b""
    return b""


def _voice_pcm_stats(data: bytes, *, sample_width_bytes: int, channels: int) -> Dict[str, float]:
    if not data or sample_width_bytes not in {1, 2, 3, 4}:
        return {}
    max_possible = float(128 if sample_width_bytes == 1 else (2 ** (sample_width_bytes * 8 - 1)))
    total = 0
    sum_squares = 0.0
    peak = 0.0
    clipped = 0
    frame_width = sample_width_bytes
    usable = len(data) - (len(data) % frame_width)
    for offset in range(0, usable, frame_width):
        sample = _voice_pcm_sample(data[offset : offset + frame_width], sample_width_bytes)
        magnitude = abs(float(sample))
        total += 1
        sum_squares += magnitude * magnitude
        peak = max(peak, magnitude)
        if magnitude >= max_possible * 0.999:
            clipped += 1
    if not total:
        return {}
    rms = (sum_squares / total) ** 0.5
    return {
        "rms_db": _voice_dbfs(rms, max_possible),
        "peak_db": _voice_dbfs(peak, max_possible),
        "clipping_ratio": round(clipped / total, 6),
    }


def _voice_pcm_sample(chunk: bytes, sample_width_bytes: int) -> int:
    if sample_width_bytes == 1:
        return int(chunk[0]) - 128
    if sample_width_bytes == 2:
        return struct.unpack("<h", chunk)[0]
    if sample_width_bytes == 3:
        return int.from_bytes(chunk, byteorder="little", signed=True)
    return struct.unpack("<i", chunk)[0]


def _voice_dbfs(value: float, max_possible: float) -> float:
    if value <= 0 or max_possible <= 0:
        return -120.0
    return round(20 * math.log10(value / max_possible), 4)


def _voice_waveform_from_utterance(utterance: Mapping[str, Any], *, sample_rate_hz: int) -> Dict[str, Any]:
    duration_ms = utterance.get("duration_ms")
    if duration_ms is None and utterance.get("start_ms") is not None and utterance.get("end_ms") is not None:
        duration_ms = max(0, int(utterance["end_ms"]) - int(utterance["start_ms"]))
    if duration_ms is None:
        transcript = str(utterance.get("transcript", ""))
        duration_ms = max(320, min(10_000, 180 + len(transcript.split()) * 260))
    item = {
        "id": str(utterance.get("id") or "utterance_waveform"),
        "speaker": utterance.get("speaker", "user"),
        "transcript": utterance.get("transcript", ""),
        "sample_rate_hz": utterance.get("sample_rate_hz", sample_rate_hz),
        "channels": utterance.get("channels", 1),
        "duration_ms": int(duration_ms),
        "source": "synthetic_utterance",
    }
    for key in ("audio_uri", "uri", "audio_path", "path", "audio_data", "data", "mime_type", "snr_db", "mos", "clipping_ratio", "jitter_ms", "packet_loss_pct", "rms_db", "peak_db"):
        if key in utterance:
            target = {
                "audio_uri": "uri",
                "audio_path": "path",
                "audio_data": "data",
            }.get(key, key)
            item[target] = utterance[key]
    item["sample_count"] = int(float(item["sample_rate_hz"]) * float(item["duration_ms"]) / 1000)
    item.update(_voice_quality_from_mapping(item))
    if item.get("uri") is None and item.get("path") is None and item.get("data") is None:
        item["data"] = _voice_synthetic_waveform_data(item)
    return item


def _voice_artifact_from_waveform(
    waveform: Mapping[str, Any],
    sample_rate_hz: int,
) -> Optional[SimulationArtifact]:
    return SimulationArtifact(
        type="audio",
        uri=str(waveform.get("uri")) if waveform.get("uri") is not None else None,
        path=str(waveform.get("path")) if waveform.get("path") is not None else None,
        data=waveform.get("data"),
        mime_type=str(waveform.get("mime_type", "audio/wav")),
        role=str(waveform.get("role", "environment")),
        metadata={
            "id": waveform.get("id"),
            "speaker": waveform.get("speaker", "user"),
            "transcript": waveform.get("transcript", ""),
            "sample_rate_hz": waveform.get("sample_rate_hz", sample_rate_hz),
            "channels": waveform.get("channels", 1),
            "duration_ms": waveform.get("duration_ms"),
            "sample_count": waveform.get("sample_count"),
            "source": waveform.get("source", "voice_waveform"),
            **_voice_quality_from_mapping(waveform),
        },
    )


def _voice_synthetic_waveform_data(waveform: Mapping[str, Any]) -> Dict[str, Any]:
    sample_count = int(waveform.get("sample_count") or 0)
    preview_len = max(8, min(64, sample_count or 32))
    seed = sum(ord(ch) for ch in str(waveform.get("transcript") or waveform.get("id") or "voice"))
    preview = [int((((seed + index * 37) % 2048) - 1024) * 0.8) for index in range(preview_len)]
    return {
        "synthetic": True,
        "encoding": "pcm16_preview",
        "preview_samples": preview,
        "sample_count": sample_count,
        "sample_rate_hz": waveform.get("sample_rate_hz"),
        "duration_ms": waveform.get("duration_ms"),
    }


def _normalize_voice_diarization(value: Any) -> List[Dict[str, Any]]:
    if value in (None, ""):
        return []
    if isinstance(value, Mapping):
        for key in ("segments", "speaker_segments", "diarization"):
            if key in value:
                return _normalize_voice_diarization(value[key])
        values = [value]
    else:
        values = _as_iterable(value)
    segments: List[Dict[str, Any]] = []
    for index, raw in enumerate(values):
        item = _as_mapping(raw)
        if not item:
            continue
        segment = {
            "id": str(item.get("id") or item.get("segment_id") or f"speaker_segment_{index + 1}"),
            "speaker": str(item.get("speaker") or item.get("speaker_id") or item.get("user_id") or f"speaker_{index + 1}"),
            "start_ms": _voice_int(item.get("start_ms", item.get("start"))),
            "end_ms": _voice_int(item.get("end_ms", item.get("end"))),
            "confidence": _voice_float(item.get("confidence")),
            "overlap": bool(item.get("overlap", item.get("overlapping", False))),
        }
        if segment["end_ms"] is None and segment["start_ms"] is not None and item.get("duration_ms") is not None:
            segment["end_ms"] = segment["start_ms"] + int(item["duration_ms"])
        if item.get("transcript") is not None:
            segment["transcript"] = str(item["transcript"])
        segments.append({key: value for key, value in segment.items() if value is not None})
    return segments


def _voice_diarization_segment_from_record(record: Mapping[str, Any], name: str) -> Optional[Dict[str, Any]]:
    text = f"{name} {_stringify_dict(record)}".lower()
    if not any(token in text for token in ("diarization", "speaker_segment", "speaker turn", "speaker_turn")):
        return None
    return (_normalize_voice_diarization(record) or [None])[0]


def _normalize_voice_webrtc_stats(value: Any) -> List[Dict[str, Any]]:
    stats: List[Dict[str, Any]] = []
    for index, record in enumerate(_voice_webrtc_stat_records(value)):
        normalized = _normalize_voice_webrtc_stat(record, index=index)
        if normalized:
            stats.append(normalized)
    return stats


def _voice_webrtc_stat_records(value: Any) -> List[Mapping[str, Any]]:
    if value in (None, ""):
        return []
    if hasattr(value, "model_dump"):
        return _voice_webrtc_stat_records(value.model_dump())
    if hasattr(value, "dict"):
        return _voice_webrtc_stat_records(value.dict())
    if isinstance(value, str):
        text = value.strip()
        if text.startswith(("{", "[")):
            try:
                return _voice_webrtc_stat_records(json.loads(text))
            except json.JSONDecodeError:
                return []
        return []
    if isinstance(value, Mapping):
        item = copy.deepcopy(dict(value))
        records: List[Mapping[str, Any]] = []
        if _looks_like_voice_webrtc_stat_record(item):
            records.append(item)
        for key in (
            "webrtc_stats",
            "rtc_stats",
            "get_stats",
            "getStats",
            "stats_report",
            "statsReport",
            "peer_connection_stats",
            "peerConnectionStats",
            "rtp_stats",
            "rtpStats",
            "track_stats",
            "trackStats",
            "tracks",
            "codecs",
        ):
            if key in item:
                records.extend(_voice_webrtc_stat_records(item[key]))
        if not records and item:
            nested_records: List[Mapping[str, Any]] = []
            for key, nested in item.items():
                if not isinstance(nested, Mapping):
                    continue
                nested_item = dict(nested)
                nested_item.setdefault("id", key)
                if _looks_like_voice_webrtc_stat_record(nested_item):
                    nested_records.append(nested_item)
            records.extend(nested_records)
        return records
    if isinstance(value, Iterable) and not isinstance(value, (str, bytes)):
        records = []
        for item in value:
            records.extend(_voice_webrtc_stat_records(item))
        return records
    return []


def _looks_like_voice_webrtc_stat_record(record: Mapping[str, Any]) -> bool:
    if not record:
        return False
    stat_type = str(record.get("type") or record.get("stat_type") or "").lower()
    if stat_type in {
        "inbound-rtp",
        "outbound-rtp",
        "remote-inbound-rtp",
        "remote-outbound-rtp",
        "track",
        "media-source",
        "codec",
    }:
        return True
    return any(
        key in record
        for key in (
            "packetsReceived",
            "packets_received",
            "packetsSent",
            "packets_sent",
            "packetsLost",
            "packets_lost",
            "fractionLost",
            "fraction_lost",
            "jitter",
            "jitterBufferDelay",
            "trackIdentifier",
            "track_identifier",
            "audioLevel",
            "audio_level",
            "totalAudioEnergy",
            "total_audio_energy",
            "codecId",
            "codec_id",
            "mimeType",
            "mime_type",
            "ssrc",
        )
    )


def _normalize_voice_webrtc_stat(
    record: Mapping[str, Any],
    *,
    index: int,
) -> Dict[str, Any]:
    item = copy.deepcopy(dict(record))
    payload = _as_mapping(item.get("payload") or item.get("data"))
    if payload:
        merged = copy.deepcopy(payload)
        merged.update({key: value for key, value in item.items() if key not in {"payload", "data"}})
        item = merged
    stat_type = str(item.get("type") or item.get("stat_type") or "webrtc").lower()
    result: Dict[str, Any] = {
        "id": str(item.get("id") or item.get("stats_id") or f"webrtc_stat_{index + 1}"),
        "type": stat_type,
        "source": "webrtc_stats",
    }
    kind = item.get("kind") or item.get("mediaType") or item.get("media_type")
    if kind is not None:
        result["kind"] = str(kind).lower()
    for source_key, target_key in (
        ("timestamp", "timestamp"),
        ("timestamp_ms", "timestamp_ms"),
        ("trackIdentifier", "track_id"),
        ("track_identifier", "track_id"),
        ("trackId", "track_id"),
        ("track_id", "track_id"),
        ("mid", "mid"),
        ("ssrc", "ssrc"),
        ("codecId", "codec_id"),
        ("codec_id", "codec_id"),
        ("mimeType", "mime_type"),
        ("mime_type", "mime_type"),
        ("payloadType", "payload_type"),
        ("payload_type", "payload_type"),
        ("audioLevel", "audio_level"),
        ("audio_level", "audio_level"),
        ("totalAudioEnergy", "total_audio_energy"),
        ("total_audio_energy", "total_audio_energy"),
        ("totalSamplesDuration", "total_samples_duration"),
        ("total_samples_duration", "total_samples_duration"),
        ("bytesReceived", "bytes_received"),
        ("bytes_received", "bytes_received"),
        ("bytesSent", "bytes_sent"),
        ("bytes_sent", "bytes_sent"),
        ("packetsReceived", "packets_received"),
        ("packets_received", "packets_received"),
        ("packetsSent", "packets_sent"),
        ("packets_sent", "packets_sent"),
        ("packetsLost", "packets_lost"),
        ("packets_lost", "packets_lost"),
        ("roundTripTime", "round_trip_time_seconds"),
        ("round_trip_time", "round_trip_time_seconds"),
        ("round_trip_time_seconds", "round_trip_time_seconds"),
        ("jitterBufferDelay", "jitter_buffer_delay_seconds"),
        ("jitter_buffer_delay", "jitter_buffer_delay_seconds"),
        ("concealedSamples", "concealed_samples"),
        ("concealed_samples", "concealed_samples"),
    ):
        value = item.get(source_key)
        if value is not None:
            result[target_key] = value
    jitter_ms = _voice_webrtc_jitter_ms(item)
    if jitter_ms is not None:
        result["jitter_ms"] = jitter_ms
    quality = _voice_quality_from_mapping(item)
    quality.update(_voice_quality_from_mapping(result))
    result.update(quality)
    packet_loss = _voice_webrtc_packet_loss_pct(item)
    if packet_loss is not None:
        result["packet_loss_pct"] = packet_loss
    if result.get("mime_type"):
        result["codec"] = str(result["mime_type"]).split("/")[-1].lower()
    return result


def _voice_webrtc_jitter_ms(record: Mapping[str, Any]) -> Optional[float]:
    jitter_ms = _voice_float(record.get("jitter_ms"))
    if jitter_ms is not None:
        return jitter_ms
    jitter = _voice_float(record.get("jitter"))
    if jitter is None:
        return None
    return round(jitter * 1000, 4) if jitter <= 10 else jitter


def _voice_webrtc_packet_loss_pct(record: Mapping[str, Any]) -> Optional[float]:
    for key in ("packet_loss_pct", "packet_loss_percent"):
        explicit = _voice_float(record.get(key))
        if explicit is not None:
            return explicit
    fraction_lost = _voice_float(record.get("fraction_lost", record.get("fractionLost")))
    if fraction_lost is not None:
        return round(fraction_lost * 100, 4) if fraction_lost <= 1 else fraction_lost
    packets_lost = _voice_float(record.get("packets_lost", record.get("packetsLost")))
    packets_received = _voice_float(record.get("packets_received", record.get("packetsReceived")))
    packets_sent = _voice_float(record.get("packets_sent", record.get("packetsSent")))
    denominator = None
    if packets_received is not None:
        denominator = packets_received + (packets_lost or 0.0)
    elif packets_sent is not None:
        denominator = packets_sent + (packets_lost or 0.0)
    if packets_lost is not None and denominator and denominator > 0:
        return round((packets_lost / denominator) * 100, 4)
    return None


def _merge_voice_perceptual_metrics(*values: Any, waveforms: Optional[Iterable[Mapping[str, Any]]] = None) -> Dict[str, Any]:
    overall: Dict[str, Any] = {}
    segments: List[Dict[str, Any]] = []
    for value in values:
        normalized = _normalize_voice_perceptual_metrics(value)
        overall.update(copy.deepcopy(normalized.get("overall", {})))
        segments.extend(copy.deepcopy(normalized.get("segments", [])))
    for waveform in waveforms or []:
        quality = _voice_quality_from_mapping(waveform)
        if quality:
            segments.append({"id": waveform.get("id"), "speaker": waveform.get("speaker"), **quality})
    if not overall and segments:
        numeric_keys = sorted({key for item in segments for key, value in item.items() if isinstance(value, (int, float))})
        for key in numeric_keys:
            values_for_key = [float(item[key]) for item in segments if isinstance(item.get(key), (int, float))]
            if values_for_key:
                overall[key] = round(sum(values_for_key) / len(values_for_key), 4)
    return {
        "overall": overall,
        "segments": _dedupe_voice_dicts(segments, "id", include_timestamp=True),
    }


def _normalize_voice_perceptual_metrics(value: Any) -> Dict[str, Any]:
    if value in (None, ""):
        return {"overall": {}, "segments": []}
    if isinstance(value, Mapping):
        item = copy.deepcopy(dict(value))
        overall = _voice_quality_from_mapping(item)
        if "overall" in item:
            overall.update(_voice_quality_from_mapping(_as_mapping(item.get("overall"))))
        segments: List[Dict[str, Any]] = []
        for key in ("segments", "items", "turns", "frames"):
            for index, raw in enumerate(_as_iterable(item.get(key))):
                segment = _as_mapping(raw)
                quality = _voice_quality_from_mapping(segment)
                if quality:
                    segments.append(
                        {
                            "id": segment.get("id") or segment.get("segment_id") or f"quality_segment_{index + 1}",
                            "speaker": segment.get("speaker") or segment.get("speaker_id"),
                            **quality,
                        }
                    )
        return {"overall": overall, "segments": segments}
    segments = []
    for index, raw in enumerate(_as_iterable(value)):
        segment = _as_mapping(raw)
        quality = _voice_quality_from_mapping(segment)
        if quality:
            segments.append({"id": segment.get("id") or f"quality_segment_{index + 1}", **quality})
    return {"overall": {}, "segments": segments}


def _voice_perceptual_metrics_from_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    return _merge_voice_perceptual_metrics(
        record.get("perceptual_metrics"),
        record.get("audio_quality"),
        record.get("quality_profile"),
        record.get("metrics") if _looks_like_voice_quality_mapping(_as_mapping(record.get("metrics"))) else None,
        _voice_quality_from_mapping(record),
    )


def _looks_like_voice_quality_mapping(value: Mapping[str, Any]) -> bool:
    return bool(value) and bool(_voice_quality_from_mapping(value))


def _voice_quality_from_mapping(value: Mapping[str, Any]) -> Dict[str, float]:
    if not value:
        return {}
    aliases = {
        "snr": "snr_db",
        "snr_db": "snr_db",
        "signal_to_noise_ratio_db": "snr_db",
        "mos": "mos",
        "polqa_mos": "mos",
        "p863_mos": "mos",
        "pesq": "pesq",
        "pesq_mos": "pesq",
        "stoi": "stoi",
        "clipping_ratio": "clipping_ratio",
        "clip_ratio": "clipping_ratio",
        "clipped_ratio": "clipping_ratio",
        "clipping_pct": "clipping_ratio",
        "clipping_percent": "clipping_ratio",
        "jitter_ms": "jitter_ms",
        "jitter": "jitter_ms",
        "jitter_seconds": "jitter_ms",
        "packet_loss_pct": "packet_loss_pct",
        "packet_loss_percent": "packet_loss_pct",
        "fraction_lost": "packet_loss_pct",
        "fractionLost": "packet_loss_pct",
        "rms_db": "rms_db",
        "peak_db": "peak_db",
        "noise_db": "noise_db",
        "processed_noise_db": "processed_noise_db",
    }
    result: Dict[str, float] = {}
    for raw_key, canonical in aliases.items():
        if raw_key not in value:
            continue
        raw = _voice_float(value.get(raw_key))
        if raw is None:
            continue
        if raw_key == "jitter_seconds" or (raw_key == "jitter" and raw <= 10):
            raw *= 1000
        if raw_key in {"fraction_lost", "fractionLost", "clipping_pct", "clipping_percent"} and raw <= 1:
            raw *= 100
        if canonical == "clipping_ratio" and raw_key in {"clipping_pct", "clipping_percent"}:
            raw = raw / 100
        result[canonical] = raw
    packets_lost = _voice_float(value.get("packets_lost", value.get("packetsLost")))
    packets_received = _voice_float(value.get("packets_received", value.get("packetsReceived")))
    if "packet_loss_pct" not in result and packets_lost is not None and packets_received is not None:
        denominator = packets_lost + packets_received
        if denominator > 0:
            result["packet_loss_pct"] = round((packets_lost / denominator) * 100, 4)
    return result


def _voice_int(value: Any) -> Optional[int]:
    if isinstance(value, bool) or value is None:
        return None
    try:
        return int(float(str(value)))
    except (TypeError, ValueError):
        return None


def _voice_float(value: Any) -> Optional[float]:
    if isinstance(value, bool) or value is None:
        return None
    try:
        return float(str(value))
    except (TypeError, ValueError):
        return None


def _as_mapping(value: Any) -> Dict[str, Any]:
    if hasattr(value, "model_dump"):
        return _as_mapping(value.model_dump())
    if hasattr(value, "dict"):
        return _as_mapping(value.dict())
    return copy.deepcopy(dict(value)) if isinstance(value, Mapping) else {}


def _get_mapping_value(value: Any, key: str) -> Any:
    return value.get(key) if isinstance(value, Mapping) else None


def _dedupe_voice_dicts(
    items: Iterable[Mapping[str, Any]],
    key: str,
    *,
    include_timestamp: bool = False,
) -> List[Dict[str, Any]]:
    seen: set[tuple[Any, ...]] = set()
    deduped: List[Dict[str, Any]] = []
    for item in items:
        item_dict = copy.deepcopy(dict(item))
        identity = (
            item_dict.get(key),
            item_dict.get("timestamp_ms") if include_timestamp else None,
            item_dict.get("start_ms") if include_timestamp else None,
        )
        if identity in seen:
            continue
        seen.add(identity)
        deduped.append(item_dict)
    return deduped


def _voice_artifact_from_utterance(
    utterance: Mapping[str, Any],
    sample_rate_hz: int,
) -> Optional[SimulationArtifact]:
    uri = utterance.get("audio_uri") or utterance.get("uri")
    path = utterance.get("audio_path") or utterance.get("path")
    data = utterance.get("audio_data") or utterance.get("data")
    if uri is None and path is None and data is None:
        return None
    return SimulationArtifact(
        type="audio",
        uri=str(uri) if uri is not None else None,
        path=str(path) if path is not None else None,
        data=data,
        mime_type=str(utterance.get("mime_type", "audio/wav")),
        role=str(utterance.get("role", "environment")),
        metadata={
            "id": utterance.get("id"),
            "speaker": utterance.get("speaker", "user"),
            "transcript": utterance.get("transcript", ""),
            "sample_rate_hz": utterance.get("sample_rate_hz", sample_rate_hz),
        },
    )


def _normalize_voice_event(item: Mapping[str, Any]) -> Dict[str, Any]:
    event = dict(item)
    payload = dict(event.get("payload", {}))
    for key in ("latency_ms", "duration_ms", "transcript", "speaker", "route", "status"):
        if key in event and key not in payload:
            payload[key] = event[key]
    return {
        "type": str(event.get("type", "voice")),
        "name": str(event.get("name") or event.get("event") or "voice_event"),
        "payload": payload,
        "timestamp_ms": event.get("timestamp_ms"),
        "metadata": dict(event.get("metadata", {})),
    }


def _normalize_voice_frame(item: Mapping[str, Any]) -> Dict[str, Any]:
    frame = dict(item)
    payload = dict(frame.get("payload", frame.get("data", {})) or {})
    frame_type = str(
        frame.get("frame_type")
        or frame.get("type")
        or frame.get("name")
        or frame.get("event")
        or "VoiceFrame"
    )
    name = str(frame.get("name") or frame.get("event") or frame_type)
    for key in (
        "text",
        "transcript",
        "speaker",
        "speaker_id",
        "language",
        "confidence",
        "latency_ms",
        "duration_ms",
        "start_ms",
        "end_ms",
        "overlap_ms",
        "noise_db",
        "vad_ms",
        "vad_latency_ms",
        "vad_inference_duration_ms",
        "eou_delay_ms",
        "end_of_utterance_delay_ms",
        "stt_latency_ms",
        "llm_latency_ms",
        "tts_latency_ms",
        "turn_latency_ms",
        "ttft_ms",
        "time_to_first_audio_ms",
        "sample_rate",
        "sample_rate_hz",
        "num_channels",
        "num_frames",
    ):
        if key in frame and key not in payload:
            payload[key] = frame[key]
    return {
        "id": str(frame.get("id") or frame.get("frame_id") or name),
        "frame_type": frame_type,
        "name": name,
        "category": str(frame.get("category") or _voice_frame_category(frame_type)),
        "direction": str(frame.get("direction") or frame.get("frame_direction") or ""),
        "processor": frame.get("processor"),
        "timestamp_ms": frame.get("timestamp_ms", frame.get("time_ms")),
        "start_ms": frame.get("start_ms", payload.get("start_ms")),
        "end_ms": frame.get("end_ms", payload.get("end_ms")),
        "duration_ms": frame.get("duration_ms", payload.get("duration_ms")),
        "speaker": frame.get("speaker", payload.get("speaker", payload.get("speaker_id"))),
        "payload": payload,
        "metadata": dict(frame.get("metadata", {})),
    }


def _voice_events_from_frame(
    frame: Mapping[str, Any],
    *,
    noise_profile: Mapping[str, Any],
) -> List[SimulationEvent]:
    payload = {
        **copy.deepcopy(dict(frame.get("payload", {}))),
        "id": frame.get("id"),
        "frame_type": frame.get("frame_type"),
        "category": frame.get("category"),
        "direction": frame.get("direction"),
        "processor": frame.get("processor"),
        "timestamp_ms": frame.get("timestamp_ms"),
    }
    payload.update(_voice_noise_payload(noise_profile, frame))
    frame_type = str(frame.get("frame_type") or frame.get("name") or "").lower()
    name = str(frame.get("name") or frame.get("frame_type") or "voice_frame")
    events = [
        SimulationEvent(
            type="voice_frame",
            name=name,
            payload=copy.deepcopy(payload),
            metadata={"frame_type": frame.get("frame_type"), **copy.deepcopy(dict(frame.get("metadata", {})))},
            timestamp_ms=frame.get("timestamp_ms"),
        )
    ]
    if "userstartedspeaking" in frame_type or "vad_start" in frame_type:
        events.append(SimulationEvent(type="voice", name="vad_start", payload=copy.deepcopy(payload), timestamp_ms=frame.get("timestamp_ms")))
    if "userstoppedspeaking" in frame_type or "vad_end" in frame_type:
        events.append(SimulationEvent(type="voice", name="vad_end", payload=copy.deepcopy(payload), timestamp_ms=frame.get("timestamp_ms")))
    if "transcription" in frame_type or "userinputtranscribed" in frame_type:
        events.append(SimulationEvent(type="voice", name="stt_result", payload=copy.deepcopy(payload), timestamp_ms=frame.get("timestamp_ms")))
    if "ttsstarted" in frame_type or "botstartedspeaking" in frame_type:
        events.append(SimulationEvent(type="voice", name="tts_start", payload=copy.deepcopy(payload), timestamp_ms=frame.get("timestamp_ms")))
    if "ttsaudio" in frame_type or "outputaudio" in frame_type:
        events.append(SimulationEvent(type="voice", name="tts_output", payload=copy.deepcopy(payload), timestamp_ms=frame.get("timestamp_ms")))
    if "interruption" in frame_type or "agent_false_interruption" in frame_type:
        events.append(SimulationEvent(type="voice", name="barge_in", payload=copy.deepcopy(payload), timestamp_ms=frame.get("timestamp_ms")))
    if "error" in frame_type:
        events.append(SimulationEvent(type="voice", name="voice_error", payload=copy.deepcopy(payload), timestamp_ms=frame.get("timestamp_ms")))
    return events


def _voice_frame_category(frame_type: str) -> str:
    lowered = frame_type.lower()
    if any(token in lowered for token in ("system", "interruption", "userstartedspeaking", "userstoppedspeaking", "error")):
        return "system"
    if "control" in lowered or lowered.endswith("frame") and "end" in lowered:
        return "control"
    return "data"


def _voice_frame_is_overlap(frame: Mapping[str, Any]) -> bool:
    text = _stringify_dict(frame).lower()
    return "overlap" in text or "agent_false_interruption" in text


def _voice_overlap_payload(frame: Mapping[str, Any]) -> Dict[str, Any]:
    payload = dict(frame.get("payload", {}))
    overlap_ms = payload.get("overlap_ms", frame.get("overlap_ms", frame.get("duration_ms")))
    return {
        "id": frame.get("id"),
        "frame_type": frame.get("frame_type"),
        "overlap_ms": int(overlap_ms) if overlap_ms is not None else None,
        "speaker": frame.get("speaker", payload.get("speaker")),
        "timestamp_ms": frame.get("timestamp_ms"),
        "metadata": copy.deepcopy(dict(frame.get("metadata", {}))),
    }


def _voice_timeline_entry(kind: str, item: Mapping[str, Any], *, speaker: Any = None) -> Dict[str, Any]:
    payload = dict(item.get("payload", {})) if isinstance(item.get("payload"), Mapping) else {}
    start_ms = item.get("start_ms", payload.get("start_ms", item.get("timestamp_ms")))
    end_ms = item.get("end_ms", payload.get("end_ms"))
    duration_ms = item.get("duration_ms", payload.get("duration_ms"))
    if end_ms is None and start_ms is not None and duration_ms is not None:
        end_ms = int(start_ms) + int(duration_ms)
    return {
        "kind": kind,
        "id": item.get("id"),
        "name": item.get("name", item.get("frame_type")),
        "speaker": speaker,
        "start_ms": start_ms,
        "end_ms": end_ms,
        "duration_ms": duration_ms,
    }


def _voice_noise_payload(
    noise_profile: Mapping[str, Any],
    item: Mapping[str, Any],
) -> Dict[str, Any]:
    payload = dict(item.get("payload", {})) if isinstance(item.get("payload"), Mapping) else {}
    noise_db = item.get("noise_db", payload.get("noise_db", noise_profile.get("noise_db")))
    processed_noise_db = item.get(
        "processed_noise_db",
        payload.get("processed_noise_db", noise_profile.get("processed_noise_db", noise_db)),
    )
    result: Dict[str, Any] = {}
    if noise_db is not None:
        result["noise_db"] = noise_db
    if processed_noise_db is not None:
        result["processed_noise_db"] = processed_noise_db
    if noise_profile.get("noise_cancellation") is not None:
        result["noise_cancellation"] = noise_profile.get("noise_cancellation")
    return result


def _stringify_dict(value: Any) -> str:
    try:
        return json.dumps(value, default=str)
    except Exception:
        return str(value)


def _normalize_latency_profile(
    profile: Optional[Mapping[str, Any]],
    *,
    stt_latency_ms: int,
    tts_latency_ms: int,
) -> Dict[str, List[int]]:
    profile = profile or {}
    return {
        "stt": _latency_series(profile.get("stt", profile.get("stt_latency_ms")), stt_latency_ms),
        "tts": _latency_series(profile.get("tts", profile.get("tts_latency_ms")), tts_latency_ms),
    }


def _latency_series(value: Any, default: int) -> List[int]:
    if value is None:
        return [int(default)]
    if isinstance(value, (int, float)):
        return [int(value)]
    if isinstance(value, Mapping):
        for key in ("series", "latencies", "values"):
            if key in value:
                return _latency_series(value[key], default)
        return [int(value.get("p50_ms", value.get("mean_ms", default)))]
    if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
        values = [int(item) for item in value]
        return values or [int(default)]
    return [int(default)]


def _merge_voice_timing_distribution_inputs(*values: Any) -> Dict[str, Any]:
    return _merge_voice_timing_distributions(*values)


def _merge_voice_timing_distributions(*values: Any) -> Dict[str, Any]:
    raw: Dict[str, Any] = {"kind": "voice_timing_distribution", "stages": {}, "stage_order": []}
    declared_turn_count: Optional[int] = None
    for value in values:
        normalized = _normalize_voice_timing_distribution(value)
        if not normalized.get("stages"):
            continue
        if normalized.get("turn_count") is not None:
            declared_turn_count = max(int(declared_turn_count or 0), int(normalized["turn_count"]))
        for stage in normalized.get("stage_order", []):
            if stage not in raw["stage_order"]:
                raw["stage_order"].append(stage)
        for stage, stage_payload in normalized.get("stages", {}).items():
            current = raw["stages"].setdefault(stage, {"samples_ms": [], "count": 0})
            current["samples_ms"].extend(copy.deepcopy(list(stage_payload.get("samples_ms", []))))
            current["count"] = int(current.get("count", 0)) + int(
                stage_payload.get("count") or len(stage_payload.get("samples_ms", []))
            )
            for key, value_for_key in stage_payload.items():
                if key not in {"stage", "samples_ms", "count", "min_ms", "max_ms", "mean_ms", "p50_ms", "p75_ms", "p95_ms", "p99_ms", "stddev_ms"}:
                    current[key] = copy.deepcopy(value_for_key)
    if declared_turn_count is not None:
        raw["turn_count"] = declared_turn_count
    return _normalize_voice_timing_distribution(raw)


def _normalize_voice_timing_distribution(
    value: Any,
    *,
    latency_profile: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    stages: Dict[str, Dict[str, Any]] = {}
    stage_order: List[str] = []
    metadata: Dict[str, Any] = {}
    turn_count: Optional[int] = None

    def add_stage(raw_stage: Any, raw_value: Any) -> None:
        stage = _normalize_voice_timing_stage_name(raw_stage)
        if not stage:
            return
        normalized_stage = _normalize_voice_timing_stage(raw_value, stage=stage)
        if not normalized_stage:
            return
        existing = stages.get(stage)
        if existing:
            samples = [
                *copy.deepcopy(list(existing.get("samples_ms", []))),
                *copy.deepcopy(list(normalized_stage.get("samples_ms", []))),
            ]
            declared_count = int(existing.get("count", 0)) + int(
                normalized_stage.get("count") or len(normalized_stage.get("samples_ms", []))
            )
            merged = {**existing, **normalized_stage, "samples_ms": samples, "count": declared_count}
            stages[stage] = _normalize_voice_timing_stage(merged, stage=stage)
        else:
            stages[stage] = normalized_stage
        if stage not in stage_order:
            stage_order.append(stage)

    if isinstance(value, Mapping):
        item = copy.deepcopy(dict(value))
        metadata = copy.deepcopy(_as_mapping(item.get("metadata", {})))
        turn_count = _voice_int(item.get("turn_count", item.get("turns")))
        raw_order = item.get("stage_order") or item.get("order") or item.get("expected_order")
        for raw_stage in _as_iterable(raw_order):
            stage = _normalize_voice_timing_stage_name(raw_stage)
            if stage and stage not in stage_order:
                stage_order.append(stage)

        raw_stages = item.get("stages") or item.get("stage_summaries")
        if isinstance(raw_stages, Mapping):
            for raw_stage, raw_value in raw_stages.items():
                add_stage(raw_stage, raw_value)
        elif raw_stages is not None:
            for index, raw_stage_item in enumerate(_as_iterable(raw_stages)):
                stage_item = _as_mapping(raw_stage_item)
                stage_name = (
                    stage_item.get("stage")
                    or stage_item.get("name")
                    or stage_item.get("metric")
                    or stage_item.get("type")
                    or f"stage_{index + 1}"
                )
                add_stage(stage_name, stage_item)

        for raw_key, raw_value in item.items():
            if raw_key in {"kind", "metadata", "stages", "stage_summaries", "stage_order", "order", "expected_order", "turn_count", "turns"}:
                continue
            stage = _normalize_voice_timing_stage_name(raw_key)
            if stage:
                add_stage(stage, raw_value)
    elif value not in (None, ""):
        for index, raw_stage_item in enumerate(_as_iterable(value)):
            stage_item = _as_mapping(raw_stage_item)
            if stage_item:
                add_stage(
                    stage_item.get("stage")
                    or stage_item.get("name")
                    or stage_item.get("metric")
                    or f"stage_{index + 1}",
                    stage_item,
                )

    for stage, samples in (latency_profile or {}).items():
        if stage not in stages:
            add_stage(stage, samples)

    ordered = [stage for stage in stage_order if stage in stages]
    ordered.extend(stage for stage in stages if stage not in ordered)
    sample_count = sum(int(stage.get("count", 0)) for stage in stages.values())
    return {
        "kind": "voice_timing_distribution",
        "stages": {stage: stages[stage] for stage in ordered},
        "stage_order": ordered,
        "turn_count": turn_count,
        "sample_count": sample_count,
        "metadata": metadata,
    }


def _normalize_voice_timing_stage(value: Any, *, stage: str) -> Dict[str, Any]:
    metadata = copy.deepcopy(_as_mapping(value)) if isinstance(value, Mapping) else {}
    samples = _voice_timing_samples(value)
    declared_count = _voice_int(metadata.get("count", metadata.get("sample_count", metadata.get("n"))))
    if declared_count is None:
        declared_count = len(samples)
    summary = _voice_timing_summary(samples, declared_count=declared_count, fallback=metadata)
    result = {
        "stage": stage,
        "samples_ms": samples,
        **summary,
    }
    for key in ("source", "metric", "unit", "description", "turn_indices", "speech_ids"):
        if key in metadata:
            result[key] = copy.deepcopy(metadata[key])
    return result if result.get("count", 0) > 0 else {}


def _voice_timing_samples(value: Any) -> List[int]:
    if value in (None, "") or isinstance(value, bool):
        return []
    if isinstance(value, (int, float)):
        return [max(0, int(round(float(value))))]
    if isinstance(value, Mapping):
        item = dict(value)
        for key in (
            "samples_ms",
            "samples",
            "series",
            "values",
            "latencies_ms",
            "latencies",
            "durations_ms",
            "durations",
        ):
            if key in item:
                return _voice_timing_samples(item[key])
        direct_values = []
        for key in (
            "latency_ms",
            "duration_ms",
            "delay_ms",
            "vad_ms",
            "vad_latency_ms",
            "vad_inference_duration_ms",
            "eou_delay_ms",
            "end_of_utterance_delay_ms",
            "stt_latency_ms",
            "llm_latency_ms",
            "tts_latency_ms",
            "turn_latency_ms",
            "ttft_ms",
            "time_to_first_audio_ms",
        ):
            if key in item:
                direct_values.append(item[key])
        if direct_values:
            return _voice_timing_samples(direct_values)
        return _voice_synthetic_timing_samples(item)
    if hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
        samples: List[int] = []
        for item in value:
            samples.extend(_voice_timing_samples(item))
        return samples
    parsed = _voice_float(value)
    return [max(0, int(round(parsed)))] if parsed is not None else []


def _voice_synthetic_timing_samples(item: Mapping[str, Any]) -> List[int]:
    count = _voice_int(item.get("count", item.get("sample_count", item.get("n")))) or 5
    count = max(1, min(count, 100))
    center = _voice_float(
        item.get(
            "mean_ms",
            item.get("avg_ms", item.get("p50_ms", item.get("median_ms", item.get("latency_ms")))),
        )
    )
    stddev = _voice_float(item.get("stddev_ms", item.get("std_ms", item.get("jitter_ms"))))
    minimum = _voice_float(item.get("min_ms"))
    maximum = _voice_float(item.get("max_ms"))
    p75 = _voice_float(item.get("p75_ms"))
    p95 = _voice_float(item.get("p95_ms"))
    p99 = _voice_float(item.get("p99_ms"))
    if center is None and any(value is not None for value in (minimum, maximum, p75, p95, p99)):
        candidates = [value for value in (minimum, p75, p95, p99, maximum) if value is not None]
        center = sum(candidates) / len(candidates)
    if center is None:
        return []
    if stddev is not None and stddev > 0:
        offsets = [-1.0, -0.5, 0.0, 0.5, 1.0]
        values = [center + offsets[index % len(offsets)] * stddev for index in range(count)]
    else:
        seed_values = [value for value in (minimum, center, p75, p95, p99, maximum) if value is not None]
        values = [seed_values[index % len(seed_values)] for index in range(count)] if seed_values else [center] * count
    if minimum is not None:
        values = [max(minimum, value) for value in values]
    if maximum is not None:
        values = [min(maximum, value) for value in values]
    return [max(0, int(round(value))) for value in values]


def _voice_timing_summary(
    samples: Sequence[int],
    *,
    declared_count: int,
    fallback: Mapping[str, Any],
) -> Dict[str, Any]:
    values = sorted(int(value) for value in samples if not isinstance(value, bool))
    count = max(int(declared_count), len(values))
    summary: Dict[str, Any] = {"count": count}
    if values:
        mean = sum(values) / len(values)
        variance = sum((value - mean) ** 2 for value in values) / len(values)
        summary.update(
            {
                "min_ms": min(values),
                "max_ms": max(values),
                "mean_ms": round(mean, 4),
                "p50_ms": _voice_percentile(values, 50),
                "p75_ms": _voice_percentile(values, 75),
                "p95_ms": _voice_percentile(values, 95),
                "p99_ms": _voice_percentile(values, 99),
                "stddev_ms": round(math.sqrt(variance), 4),
            }
        )
        return summary
    for key in ("min_ms", "max_ms", "mean_ms", "p50_ms", "p75_ms", "p95_ms", "p99_ms", "stddev_ms"):
        value = _voice_float(fallback.get(key))
        if value is not None:
            summary[key] = round(value, 4)
    return summary


def _voice_percentile(values: Sequence[int], percentile: float) -> float:
    if not values:
        return 0.0
    if len(values) == 1:
        return float(values[0])
    ordered = sorted(values)
    index = (len(ordered) - 1) * percentile / 100
    low = int(math.floor(index))
    high = int(math.ceil(index))
    if low == high:
        return float(ordered[low])
    lower = ordered[low] * (high - index)
    upper = ordered[high] * (index - low)
    return round(lower + upper, 4)


def _normalize_voice_timing_stage_name(value: Any) -> str:
    normalized = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    normalized = normalized.replace(".", "_")
    aliases = {
        "vad": "vad",
        "voice_activity_detection": "vad",
        "vad_latency": "vad",
        "vad_inference": "vad",
        "vad_inference_duration": "vad",
        "eou": "eou",
        "end_of_utterance": "eou",
        "end_of_utterance_delay": "eou",
        "endpointing": "eou",
        "endpointing_delay": "eou",
        "stt": "stt",
        "speech_to_text": "stt",
        "transcription": "stt",
        "transcription_latency": "stt",
        "llm": "llm",
        "model": "llm",
        "generation": "llm",
        "inference": "llm",
        "tts": "tts",
        "text_to_speech": "tts",
        "synthesis": "tts",
        "ttft": "tts",
        "time_to_first_audio": "tts",
        "turn": "turn",
        "turn_latency": "turn",
        "round_trip": "turn",
        "response_latency": "turn",
        "interruption": "interruption",
        "interrupt": "interruption",
        "barge_in": "interruption",
    }
    if normalized in aliases:
        return aliases[normalized]
    if normalized.endswith("_ms"):
        return _normalize_voice_timing_stage_name(normalized[:-3])
    if normalized.endswith("_latency"):
        return _normalize_voice_timing_stage_name(normalized[: -len("_latency")])
    return ""


def _looks_like_voice_timing_mapping(value: Mapping[str, Any]) -> bool:
    if not value:
        return False
    text = _stringify_dict(value).lower()
    return any(
        token in text
        for token in (
            "latency_ms",
            "timing",
            "duration_ms",
            "eou",
            "endpointing",
            "vad",
            "stt",
            "tts",
            "ttft",
        )
    )


def _voice_timing_distribution_from_record(record: Mapping[str, Any], name: str) -> Dict[str, Any]:
    payload = _as_mapping(record.get("payload") or record.get("data"))
    sources = [record, payload]
    for nested_key in ("metrics", "timing", "timing_distribution", "timing_profile", "latency_metrics"):
        nested = _as_mapping(record.get(nested_key) or payload.get(nested_key))
        if nested:
            sources.append(nested)

    distributions: List[Any] = []
    for source in sources:
        for key in ("timing_distribution", "timing_profile", "timing", "latency_distribution", "latency_metrics"):
            if source.get(key):
                distributions.append(source.get(key))

        explicit_stage = _normalize_voice_timing_stage_name(
            source.get("stage") or source.get("stage_name") or source.get("metric") or source.get("type") or name
        )
        inferred_stage = explicit_stage or _voice_timing_stage_from_text(f"{name} {_stringify_dict(source)}")
        stage_values: Dict[str, List[Any]] = {}

        for key, stage in (
            ("vad_ms", "vad"),
            ("vad_latency_ms", "vad"),
            ("vad_inference_duration_ms", "vad"),
            ("eou_delay_ms", "eou"),
            ("end_of_utterance_delay_ms", "eou"),
            ("endpointing_delay_ms", "eou"),
            ("stt_latency_ms", "stt"),
            ("llm_latency_ms", "llm"),
            ("model_latency_ms", "llm"),
            ("tts_latency_ms", "tts"),
            ("ttft_ms", "tts"),
            ("time_to_first_audio_ms", "tts"),
            ("turn_latency_ms", "turn"),
            ("round_trip_ms", "turn"),
            ("interruption_latency_ms", "interruption"),
        ):
            if key in source:
                stage_values.setdefault(stage, []).append(source[key])
        for key in ("latency_ms", "duration_ms", "delay_ms"):
            if key in source and inferred_stage:
                stage_values.setdefault(inferred_stage, []).append(source[key])
        if stage_values:
            distributions.append({"stages": stage_values})

    return _merge_voice_timing_distributions(*distributions)


def _voice_timing_stage_from_text(text: str) -> str:
    lowered = text.lower()
    if "end_of_utterance" in lowered or "endpoint" in lowered or "eou" in lowered:
        return "eou"
    if "vad" in lowered or "userstartedspeaking" in lowered or "userstoppedspeaking" in lowered:
        return "vad"
    if "transcription" in lowered or "transcript" in lowered or "stt" in lowered:
        return "stt"
    if "time_to_first_audio" in lowered or "ttft" in lowered or "tts" in lowered or "audio_out" in lowered:
        return "tts"
    if "llm" in lowered or "model" in lowered or "generation" in lowered:
        return "llm"
    if "interrupt" in lowered or "barge" in lowered:
        return "interruption"
    if "turn" in lowered or "round_trip" in lowered or "response_latency" in lowered:
        return "turn"
    return ""


def _normalize_voice_routes(routes: Optional[Mapping[str, Any] | Iterable[str]]) -> Dict[str, Any]:
    if routes is None:
        return {"default": {"kind": "agent", "name": "default"}}
    if isinstance(routes, Mapping):
        normalized = {}
        for name, target in routes.items():
            normalized[str(name)] = copy.deepcopy(target)
        return normalized or {"default": {"kind": "agent", "name": "default"}}
    normalized = {str(route): {"kind": "queue", "name": str(route)} for route in routes}
    return normalized or {"default": {"kind": "agent", "name": "default"}}


def _find_by_id(items: Iterable[Mapping[str, Any]], item_id: str) -> Optional[Mapping[str, Any]]:
    if not item_id:
        return None
    for item in items:
        if str(item.get("id")) == item_id:
            return item
    return None


def _normalize_image_fixture(
    image_id: str,
    value: Any,
    default_mime_type: str,
) -> Dict[str, Any]:
    if isinstance(value, SimulationArtifact):
        fixture = value.model_dump() if hasattr(value, "model_dump") else value.dict()
    elif isinstance(value, Mapping):
        fixture = dict(value)
    elif isinstance(value, str):
        location_key = "uri" if value.startswith(("http://", "https://", "file://", "data:")) else "path"
        fixture = {location_key: value}
    else:
        fixture = {"data": value}
    fixture.setdefault("id", image_id)
    fixture.setdefault("mime_type", default_mime_type)
    fixture.setdefault("metadata", {})
    return fixture


def _image_artifact_from_fixture(fixture: Mapping[str, Any]) -> SimulationArtifact:
    metadata = dict(fixture.get("metadata", {}))
    metadata.setdefault("id", fixture.get("id"))
    if "description" in fixture:
        metadata.setdefault("description", fixture.get("description"))
    if "labels" in fixture:
        metadata.setdefault("labels", fixture.get("labels"))
    return SimulationArtifact(
        type="image",
        uri=str(fixture["uri"]) if fixture.get("uri") is not None else None,
        path=str(fixture["path"]) if fixture.get("path") is not None else None,
        data=fixture.get("data"),
        mime_type=str(fixture.get("mime_type", "image/png")),
        role=str(fixture.get("role", "environment")),
        metadata=metadata,
    )


def _normalize_structured_artifact_fixture(
    artifact_id: str,
    value: Any,
    *,
    default_domain: str,
) -> Dict[str, Any]:
    if isinstance(value, SimulationArtifact):
        fixture = value.model_dump() if hasattr(value, "model_dump") else value.dict()
    elif isinstance(value, Mapping):
        fixture = copy.deepcopy(dict(value))
    else:
        fixture = {"data": value}
    fixture.setdefault("id", artifact_id)
    fixture.setdefault("domain", default_domain)
    fixture.setdefault("schema", fixture.get("domain", default_domain))
    fixture.setdefault("metadata", {})
    fixture.setdefault("data", {})
    return fixture


def _structured_artifact_from_fixture(fixture: Mapping[str, Any]) -> SimulationArtifact:
    metadata = copy.deepcopy(dict(fixture.get("metadata", {})))
    metadata.setdefault("id", fixture.get("id"))
    metadata.setdefault("kind", "structured_artifact")
    metadata.setdefault("domain", fixture.get("domain"))
    metadata.setdefault("schema", fixture.get("schema"))
    if fixture.get("description") is not None:
        metadata.setdefault("description", fixture.get("description"))
    return SimulationArtifact(
        type="json",
        data=copy.deepcopy(fixture.get("data", {})),
        mime_type=str(fixture.get("mime_type", "application/json")),
        role=str(fixture.get("role", "environment")),
        metadata=metadata,
    )


def _normalize_domain_package_fixture(
    package_id: str,
    value: Any,
    *,
    default_domain: str,
) -> Dict[str, Any]:
    if isinstance(value, SimulationArtifact):
        fixture = value.model_dump() if hasattr(value, "model_dump") else value.dict()
    elif isinstance(value, Mapping):
        fixture = copy.deepcopy(dict(value))
    else:
        fixture = {"data": value}
    fixture.setdefault("id", package_id)
    fixture.setdefault("domain", default_domain)
    package_type = (
        fixture.get("package_type")
        or fixture.get("domain_package_type")
        or fixture.get("schema")
        or fixture.get("domain", default_domain)
    )
    fixture["package_type"] = str(package_type)
    fixture.setdefault("schema", fixture["package_type"])
    fixture.setdefault("metadata", {})
    fixture.setdefault("data", {})
    metadata = copy.deepcopy(dict(fixture.get("metadata", {})))
    metadata.setdefault("kind", "domain_package")
    metadata.setdefault("id", fixture.get("id"))
    metadata.setdefault("domain", fixture.get("domain"))
    metadata.setdefault("package_type", fixture.get("package_type"))
    metadata.setdefault("schema", fixture.get("schema"))
    fixture["metadata"] = metadata
    return fixture


def _domain_package_artifact_from_fixture(fixture: Mapping[str, Any]) -> SimulationArtifact:
    metadata = copy.deepcopy(dict(fixture.get("metadata", {})))
    metadata.setdefault("id", fixture.get("id"))
    metadata.setdefault("kind", "domain_package")
    metadata.setdefault("domain", fixture.get("domain"))
    metadata.setdefault("package_type", fixture.get("package_type"))
    metadata.setdefault("schema", fixture.get("schema"))
    if fixture.get("description") is not None:
        metadata.setdefault("description", fixture.get("description"))
    data = copy.deepcopy(fixture.get("data", {}))
    if isinstance(data, Mapping):
        data = dict(data)
        data.setdefault("id", fixture.get("id"))
        data.setdefault("domain", fixture.get("domain"))
        data.setdefault("package_type", fixture.get("package_type"))
    return SimulationArtifact(
        type="json",
        data=data,
        mime_type=str(fixture.get("mime_type", "application/json")),
        role=str(fixture.get("role", "environment")),
        metadata=metadata,
    )


def _world_contract_entity(value: str | Mapping[str, Any], *, prefix: str) -> Dict[str, Any]:
    if isinstance(value, str):
        entity = {"id": value, "name": value}
    else:
        entity = copy.deepcopy(dict(value))
    entity_id = str(entity.get("id") or entity.get("name") or f"{prefix}_{abs(hash(str(entity))) % 10000}")
    entity.setdefault("id", entity_id)
    entity.setdefault("name", entity_id)
    return entity


def _world_contract_transition(value: str | Mapping[str, Any], *, index: int) -> Dict[str, Any]:
    if isinstance(value, str):
        transition = {"id": value, "name": value, "action": value}
    else:
        transition = copy.deepcopy(dict(value))
    transition_id = str(
        transition.get("id")
        or transition.get("name")
        or transition.get("action")
        or f"transition_{index}"
    )
    action = str(transition.get("action") or transition.get("name") or transition_id)
    transition.setdefault("id", transition_id)
    transition.setdefault("name", action)
    transition.setdefault("action", action)
    transition["preconditions"] = _world_contract_flat_mapping(transition.get("preconditions") or transition.get("requires"))
    transition["postconditions"] = _world_contract_flat_mapping(transition.get("postconditions") or transition.get("ensures"))
    transition["effects"] = _world_contract_patch_mapping(
        transition.get("effects")
        or transition.get("state_updates")
        or transition.get("state")
        or transition.get("to")
    )
    transition["signals"] = sorted(
        {
            _normalize_world_contract_key(signal)
            for signal in [
                *_as_iterable(transition.get("signals")),
                transition.get("actor"),
                transition.get("resource"),
                transition.get("action"),
                "transition",
            ]
            if signal
        }
    )
    transition["required"] = bool(transition.get("required", transition.get("must_run", False)))
    transition["forbidden"] = bool(transition.get("forbidden", False))
    return transition


def _world_contract_condition(
    value: str | Mapping[str, Any],
    *,
    prefix: str,
    index: int,
) -> Dict[str, Any]:
    if isinstance(value, str):
        condition = {"id": value, "name": value}
    else:
        condition = copy.deepcopy(dict(value))
    condition_id = str(condition.get("id") or condition.get("name") or f"{prefix}_{index}")
    condition.setdefault("id", condition_id)
    condition.setdefault("name", condition_id)
    condition["when"] = _world_contract_flat_mapping(condition.get("when"))
    condition["must"] = _world_contract_flat_mapping(
        condition.get("must")
        or condition.get("expect")
        or condition.get("expected")
        or condition.get("state")
    )
    condition["forbidden"] = _world_contract_flat_mapping(condition.get("forbidden"))
    condition["signals"] = sorted(
        {
            _normalize_world_contract_key(signal)
            for signal in [*_as_iterable(condition.get("signals")), prefix]
            if signal
        }
    )
    return condition


def _world_contract_patch_mapping(value: Any) -> Dict[str, Any]:
    mapping = _as_mapping(value)
    if not mapping:
        return {}
    patch: Dict[str, Any] = {}
    for path, item in mapping.items():
        if "." in str(path):
            _world_contract_set_path(patch, str(path), item)
        elif isinstance(item, Mapping):
            patch[str(path)] = _world_contract_patch_mapping(item)
        else:
            patch[str(path)] = copy.deepcopy(item)
    return patch


def _world_contract_flat_mapping(value: Any, prefix: str = "") -> Dict[str, Any]:
    mapping = _as_mapping(value)
    flattened: Dict[str, Any] = {}
    for key, item in mapping.items():
        path = f"{prefix}.{key}" if prefix else str(key)
        if isinstance(item, Mapping):
            flattened.update(_world_contract_flat_mapping(item, path))
        else:
            flattened[path] = copy.deepcopy(item)
    return flattened


def _world_contract_effects(transition: Mapping[str, Any]) -> Dict[str, Any]:
    return _world_contract_patch_mapping(transition.get("effects"))


def _world_contract_check_conditions(
    conditions: Iterable[Mapping[str, Any]],
    state: Mapping[str, Any],
    *,
    condition_type: str,
) -> List[Dict[str, Any]]:
    results: List[Dict[str, Any]] = []
    for condition in conditions:
        condition_dict = _as_mapping(condition)
        when = _as_mapping(condition_dict.get("when"))
        applies = not when or _world_contract_condition_matches(state, when)
        must = _as_mapping(condition_dict.get("must"))
        forbidden = _as_mapping(condition_dict.get("forbidden"))
        must_match = True if not must else _world_contract_condition_matches(state, must)
        forbidden_match = False if not forbidden else _world_contract_condition_matches(state, forbidden)
        passed = (not applies) or (must_match and not forbidden_match)
        result = {
            "id": condition_dict.get("id"),
            "name": condition_dict.get("name"),
            "type": condition_type,
            "applies": applies,
            "pass": passed,
            "expected": copy.deepcopy(must),
            "forbidden": copy.deepcopy(forbidden),
            "actual": {
                path: _world_contract_get_path(state, path)
                for path in sorted({*must.keys(), *forbidden.keys()})
            },
            "signals": copy.deepcopy(condition_dict.get("signals", [])),
        }
        results.append(result)
    return results


def _world_contract_condition_matches(state: Mapping[str, Any], expected: Mapping[str, Any]) -> bool:
    for path, value in expected.items():
        if _world_contract_get_path(state, str(path)) != value:
            return False
    return True


def _world_contract_get_path(value: Mapping[str, Any], path: str) -> Any:
    current: Any = value
    for part in path.split("."):
        if isinstance(current, Mapping) and part in current:
            current = current.get(part)
        else:
            return None
    return current


def _world_contract_set_path(target: Dict[str, Any], path: str, value: Any) -> None:
    current: Dict[str, Any] = target
    parts = path.split(".")
    for part in parts[:-1]:
        existing = current.get(part)
        if not isinstance(existing, dict):
            existing = {}
            current[part] = existing
        current = existing
    current[parts[-1]] = copy.deepcopy(value)


def _world_contract_find_transition(
    transitions: Iterable[Mapping[str, Any]],
    transition_id: str,
) -> Optional[Dict[str, Any]]:
    query = str(transition_id or "").strip().lower()
    if not query:
        return None
    for transition in transitions:
        transition_dict = _as_mapping(transition)
        candidates = {
            str(transition_dict.get("id") or "").lower(),
            str(transition_dict.get("name") or "").lower(),
            str(transition_dict.get("action") or "").lower(),
        }
        if query in candidates:
            return copy.deepcopy(transition_dict)
    return None


def _world_contract_find_condition(
    conditions: Iterable[Mapping[str, Any]],
    condition_id: str,
) -> Optional[Dict[str, Any]]:
    query = str(condition_id or "").strip().lower()
    if not query:
        return None
    for condition in conditions:
        condition_dict = _as_mapping(condition)
        if query in {str(condition_dict.get("id") or "").lower(), str(condition_dict.get("name") or "").lower()}:
            return copy.deepcopy(condition_dict)
    return None


def _world_contract_find_condition_result(
    results: Iterable[Mapping[str, Any]],
    condition_id: str,
) -> Optional[Dict[str, Any]]:
    query = str(condition_id or "").strip().lower()
    if not query:
        return None
    for result in results:
        result_dict = _as_mapping(result)
        if query in {str(result_dict.get("id") or "").lower(), str(result_dict.get("name") or "").lower()}:
            return copy.deepcopy(result_dict)
    return None


def _normalize_world_contract_key(value: Any) -> str:
    normalized = str(value or "").strip().lower().replace("-", "_").replace(" ", "_").replace(".", "_")
    aliases = {
        "world_contract": "contract",
        "world_contract_status": "contract",
        "list_world_transitions": "transition",
        "apply_world_transition": "transition",
        "inspect_world_invariant": "invariant",
        "actors": "actor",
        "actor": "actor",
        "resources": "resource",
        "resource": "resource",
        "transitions": "transition",
        "transition": "transition",
        "transition_log": "transition_log",
        "completed_transition": "completed_transition",
        "required_transition": "required_transition",
        "forbidden_transition": "forbidden_transition",
        "invariants": "invariant",
        "invariant": "invariant",
        "invariant_violation": "invariant_violation",
        "success": "success",
        "success_condition": "success_condition",
        "success_conditions": "success_condition",
        "policy_gate": "policy",
        "policy_gates": "policy",
        "policy": "policy",
        "adversarial_surface": "adversarial_surface",
        "adversarial_surfaces": "adversarial_surface",
        "violation": "violation",
        "state_update": "state",
        "state": "state",
        "milestone": "milestone",
        "tool": "tool",
        "browser": "browser",
        "voice": "voice",
        "memory": "memory",
    }
    return aliases.get(normalized, normalized)


def _as_mapping(value: Any) -> Dict[str, Any]:
    if value is None:
        return {}
    if isinstance(value, Mapping):
        return copy.deepcopy(dict(value))
    return {}


def _deep_merge(target: Dict[str, Any], updates: Mapping[str, Any]) -> None:
    for key, value in updates.items():
        if isinstance(value, Mapping) and isinstance(target.get(key), dict):
            _deep_merge(target[key], value)
        else:
            target[key] = copy.deepcopy(value)
